fn process_file(dir: &str, name: &str) {
    let path = Path::new(dir).join(name);
    let data = fs::read(&path).unwrap();

    let bf_off_bits = read_u32(&data, 10) as usize;
    let dib_size = read_u32(&data, 14) as usize;
    let width = read_i32(&data, 18) as usize;
    let height_raw = read_i32(&data, 22);
    let bpp = read_u16(&data, 28) as usize;
    let compression = read_u32(&data, 30) as usize;
    let colors_used = read_u32(&data, 32) as usize;

    let bottom_up = height_raw > 0;
    let height = height_raw.unsigned_abs() as usize;

    println!("== {}", name);

    if compression != 0 && compression != 3 {
        println!("error: unsupported compression {}", compression);
        return;
    }

    let pixels = decode_pixels(
        &data, bf_off_bits, dib_size, width, height, bpp, compression, colors_used, bottom_up,
    );

    let mut ink = vec![false; width * height];
    let mut ink_count = 0usize;
    for y in 0..height {
        for x in 0..width {
            let idx = y * width + x;
            let (r, g, b) = pixels[idx];
            if (299 * r as u32 + 587 * g as u32 + 114 * b as u32) / 1000 < 128 {
                ink[idx] = true;
                ink_count += 1;
            }
        }
    }

    println!(
        "size {}x{} bpp {} header {} {} ink {}",
        width,
        height,
        bpp,
        dib_size,
        if bottom_up { "bottom-up" } else { "top-down" },
        ink_count
    );

    let mut visited = vec![false; width * height];
    let mut components: Vec<(usize, usize, usize, usize, usize, usize, usize)> = Vec::new();

    for y in 0..height {
        for x in 0..width {
            let idx = y * width + x;
            if ink[idx] && !visited[idx] {
                let mut queue = VecDeque::new();
                queue.push_back((x, y));
                visited[idx] = true;
                let mut min_x = x;
                let mut min_y = y;
                let mut max_x = x;
                let mut max_y = y;
                let mut count = 0usize;

                while let Some((cx, cy)) = queue.pop_front() {
                    count += 1;
                    if cx < min_x {
                        min_x = cx;
                    }
                    if cx > max_x {
                        max_x = cx;
                    }
                    if cy < min_y {
                        min_y = cy;
                    }
                    if cy > max_y {
                        max_y = cy;
                    }

                    for dy in -1i64..=1 {
                        for dx in -1i64..=1 {
                            if dx == 0 && dy == 0 {
                                continue;
                            }
                            let nx = cx as i64 + dx;
                            let ny = cy as i64 + dy;
                            if nx >= 0 && nx < width as i64 && ny >= 0 && ny < height as i64 {
                                let nidx = ny as usize * width + nx as usize;
                                if ink[nidx] && !visited[nidx] {
                                    visited[nidx] = true;
                                    queue.push_back((nx as usize, ny as usize));
                                }
                            }
                        }
                    }
                }

                components.push((x, y, min_x, min_y, max_x, max_y, count));
            }
        }
    }

    println!("components {}", components.len());
    for (fx, fy, minx, miny, maxx, maxy, count) in &components {
        println!(
            "{},{}, bbox {},{}-{},{}, pixels {}",
            fx, fy, minx, miny, maxx, maxy, count
        );
    }
}

fn decode_pixels(
    data: &[u8],
    bf_off_bits: usize,
    dib_size: usize,
    width: usize,
    height: usize,
    bpp: usize,
    compression: usize,
    colors_used: usize,
    bottom_up: bool,
) -> Vec<(u8, u8, u8)> {
    let mut pixels = vec![(0u8, 0u8, 0u8); width * height];

    let palette_start = 14 + dib_size;
    let palette_entries = if colors_used > 0 {
        colors_used
    } else {
        1usize << bpp
    };
    let mut palette: Vec<(u8, u8, u8)> = Vec::with_capacity(palette_entries);
    if bpp <= 8 {
        for i in 0..palette_entries {
            let off = palette_start + i * 4;
            let b = data[off];
            let g = data[off + 1];
            let r = data[off + 2];
            palette.push((r, g, b));
        }
    }

    let (r_mask, g_mask, b_mask) = if compression == 3 {
        let mask_offset = 14 + 40;
        (
            read_u32(data, mask_offset),
            read_u32(data, mask_offset + 4),
            read_u32(data, mask_offset + 8),
        )
    } else {
        (0u32, 0u32, 0u32)
    };

    let row_bytes = match bpp {
        1 => ((width + 7) / 8 + 3) & !3,
        4 => ((width + 1) / 2 + 3) & !3,
        8 => (width + 3) & !3,
        24 => (width * 3 + 3) & !3,
        32 => width * 4,
        _ => 0,
    };

    for y in 0..height {
        let stored_y = if bottom_up { height - 1 - y } else { y };
        let row_offset = bf_off_bits + stored_y * row_bytes;

        for x in 0..width {
            let (r, g, b) = match bpp {
                1 => {
                    let byte_idx = row_offset + x / 8;
                    let bit = 7 - (x % 8);
                    let idx = ((data[byte_idx] >> bit) & 1) as usize;
                    palette[idx]
                }
                4 => {
                    let byte_idx = row_offset + x / 2;
                    let nibble = if x % 2 == 0 {
                        (data[byte_idx] >> 4) & 0xF
                    } else {
                        data[byte_idx] & 0xF
                    };
                    palette[nibble as usize]
                }
                8 => {
                    let idx = data[row_offset + x] as usize;
                    palette[idx]
                }
                24 => {
                    let off = row_offset + x * 3;
                    (data[off + 2], data[off + 1], data[off])
                }
                32 => {
                    if compression == 0 {
                        let off = row_offset + x * 4;
                        (data[off + 2], data[off + 1], data[off])
                    } else {
                        let off = row_offset + x * 4;
                        let pixel = read_u32(data, off);
                        let r = extract_channel(pixel, r_mask);
                        let g = extract_channel(pixel, g_mask);
                        let b = extract_channel(pixel, b_mask);
                        (r, g, b)
                    }
                }
                _ => (0, 0, 0),
            };

            pixels[y * width + x] = (r, g, b);
        }
    }

    pixels
}

fn extract_channel(pixel: u32, mask: u32) -> u8 {
    if mask == 0 {
        return 0;
    }
    let s = mask.trailing_zeros();
    let v = (pixel & mask) >> s;
    let n = mask.count_ones();
    let m = (1u32 << n) - 1;
    ((v * 255 + m / 2) / m) as u8
}

