import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        List<String> lines = Files.readAllLines(Path.of(dir, "queries.txt"));

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;

            String[] parts = line.trim().split(" ");
            String name = parts[0];
            String type = parts[1];

            String normName = name.toLowerCase();
            if (normName.endsWith(".")) normName = normName.substring(0, normName.length() - 1);
            if (normName.isEmpty()) normName = ".";

            byte[] query = buildQuery(name, type);
            int id = ((query[0] & 0xFF) << 8) | (query[1] & 0xFF);

            byte[] response = sendUdp(query, port, id);

            int flags = ((response[2] & 0xFF) << 8) | (response[3] & 0xFF);
            if ((flags & 0x0200) != 0) {
                response = sendTcp(query, port);
            }

            parseAndPrint(normName, type, response);
        }
    }

    static byte[] buildQuery(String name, String type) {
        Random rand = new Random();
        int id = rand.nextInt(65536);

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        baos.write((id >> 8) & 0xFF);
        baos.write(id & 0xFF);
        baos.write(0x01);
        baos.write(0x00);
        baos.write(0x00); baos.write(0x01);
        baos.write(0x00); baos.write(0x00);
        baos.write(0x00); baos.write(0x00);
        baos.write(0x00); baos.write(0x00);

        String qname = name;
        if (qname.endsWith(".")) qname = qname.substring(0, qname.length() - 1);
        if (!qname.isEmpty()) {
            String[] labels = qname.split("\\.");
            for (String label : labels) {
                baos.write(label.length());
                for (byte b : label.getBytes(StandardCharsets.US_ASCII)) {
                    baos.write(b);
                }
            }
        }
        baos.write(0);

        int qtype = typeToNumber(type);
        baos.write((qtype >> 8) & 0xFF);
        baos.write(qtype & 0xFF);

        baos.write(0x00);
        baos.write(0x01);

        return baos.toByteArray();
    }

    static int typeToNumber(String type) {
        switch (type) {
            case "A": return 1;
            case "CNAME": return 5;
            case "MX": return 15;
            case "TXT": return 16;
            case "AAAA": return 28;
            default: return 0;
        }
    }

    static byte[] sendUdp(byte[] query, int port, int expectedId) throws Exception {
        DatagramSocket sock = new DatagramSocket();
        sock.setSoTimeout(5000);
        DatagramPacket out = new DatagramPacket(query, query.length,
                InetAddress.getByName("127.0.0.1"), port);
        sock.send(out);

        byte[] buf = new byte[65535];
        while (true) {
            DatagramPacket in = new DatagramPacket(buf, buf.length);
            sock.receive(in);
            byte[] data = Arrays.copyOf(in.getData(), in.getLength());
            if (data.length >= 12) {
                int respId = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
                int flags = ((data[2] & 0xFF) << 8) | (data[3] & 0xFF);
                int qr = (flags >> 15) & 1;
                if (qr == 1 && respId == expectedId) {
                    sock.close();
                    return data;
                }
            }
        }
    }

    static byte[] sendTcp(byte[] query, int port) throws Exception {
        Socket sock = new Socket("127.0.0.1", port);
        sock.setSoTimeout(5000);

        DataOutputStream dos = new DataOutputStream(sock.getOutputStream());
        dos.writeShort(query.length);
        dos.write(query);
        dos.flush();

        DataInputStream dis = new DataInputStream(sock.getInputStream());
        int len = dis.readUnsignedShort();
        byte[] response = new byte[len];
        dis.readFully(response);

        sock.close();
        return response;
    }

    static void parseAndPrint(String normName, String type, byte[] msg) {
        int flags = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
        int rcode = flags & 0x0F;
        int qdcount = ((msg[4] & 0xFF) << 8) | (msg[5] & 0xFF);
        int ancount = ((msg[6] & 0xFF) << 8) | (msg[7] & 0xFF);

        System.out.println(normName + " " + type + " " + rcodeToString(rcode));

        int offset = 12;
        for (int i = 0; i < qdcount; i++) {
            offset = skipName(msg, offset);
            offset += 4;
        }

        for (int i = 0; i < ancount; i++) {
            offset = parseRecord(msg, offset);
        }
    }

    static int skipName(byte[] msg, int offset) {
        while (offset < msg.length) {
            int len = msg[offset] & 0xFF;
            if (len == 0) {
                offset++;
                break;
            }
            if ((len & 0xC0) == 0xC0) {
                offset += 2;
                break;
            }
            offset += 1 + len;
        }
        return offset;
    }

    static String readName(byte[] msg, int offset) {
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        boolean jumped = false;

        while (offset < msg.length) {
            int len = msg[offset] & 0xFF;
            if (len == 0) {
                offset++;
                break;
            }
            if ((len & 0xC0) == 0xC0) {
                int ptr = ((len & 0x3F) << 8) | (msg[offset + 1] & 0xFF);
                if (!jumped) {
                    jumped = true;
                }
                offset = ptr;
                continue;
            }
            if (!first) sb.append('.');
            first = false;
            for (int i = 0; i < len; i++) {
                sb.append((char) (msg[offset + 1 + i] & 0xFF));
            }
            offset += 1 + len;
        }

        String result = sb.toString().toLowerCase();
        if (result.isEmpty()) result = ".";
        return result;
    }

    static int parseRecord(byte[] msg, int offset) {
        String owner = readName(msg, offset);
        offset = skipName(msg, offset);

        int rtype = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
        long ttl = ((long) (msg[offset + 4] & 0xFF) << 24)
                 | ((long) (msg[offset + 5] & 0xFF) << 16)
                 | ((long) (msg[offset + 6] & 0xFF) << 8)
                 | (msg[offset + 7] & 0xFF);
        int rdlength = ((msg[offset + 8] & 0xFF) << 8) | (msg[offset + 9] & 0xFF);
        offset += 10;

        int rdataStart = offset;
        int rdataEnd = offset + rdlength;

        String data = formatRdata(msg, rdataStart, rdataEnd, rtype);
        String typeName = numberToType(rtype);
        System.out.println("  " + owner + " " + ttl + " " + typeName + " " + data);

        return rdataEnd;
    }

    static String formatRdata(byte[] msg, int start, int end, int rtype) {
        switch (rtype) {
            case 1: return formatA(msg, start);
            case 28: return formatAAAA(msg, start);
            case 5: return readName(msg, start);
            case 15: return formatMX(msg, start, end);
            case 16: return formatTXT(msg, start, end);
            default: return formatUnknown(msg, start, end);
        }
    }

    static String formatA(byte[] msg, int offset) {
        return (msg[offset] & 0xFF) + "." + (msg[offset + 1] & 0xFF) + "."
             + (msg[offset + 2] & 0xFF) + "." + (msg[offset + 3] & 0xFF);
    }

    static String formatAAAA(byte[] msg, int offset) {
        int[] groups = new int[8];
        for (int i = 0; i < 8; i++) {
            groups[i] = ((msg[offset + i * 2] & 0xFF) << 8) | (msg[offset + i * 2 + 1] & 0xFF);
        }

        int bestStart = -1, bestLen = 0;
        int i = 0;
        while (i < 8) {
            if (groups[i] == 0) {
                int j = i;
                while (j < 8 && groups[j] == 0) j++;
                int runLen = j - i;
                if (runLen >= 2 && runLen > bestLen) {
                    bestStart = i;
                    bestLen = runLen;
                }
                i = j;
            } else {
                i++;
            }
        }

        StringBuilder sb = new StringBuilder();
        if (bestStart == -1) {
            for (i = 0; i < 8; i++) {
                if (i > 0) sb.append(':');
                sb.append(Integer.toHexString(groups[i]));
            }
        } else {
            for (i = 0; i < 8; i++) {
                if (i == bestStart) {
                    sb.append("::");
                    i += bestLen - 1;
                } else {
                    if (sb.length() > 0 && sb.charAt(sb.length() - 1) != ':') {
                        sb.append(':');
                    }
                    sb.append(Integer.toHexString(groups[i]));
                }
            }
        }
        return sb.toString();
    }

    static String formatMX(byte[] msg, int start, int end) {
        int pref = ((msg[start] & 0xFF) << 8) | (msg[start + 1] & 0xFF);
        String exchange = readName(msg, start + 2);
        return pref + " " + exchange;
    }

    static String formatTXT(byte[] msg, int start, int end) {
        StringBuilder sb = new StringBuilder();
        int offset = start;
        boolean first = true;
        while (offset < end) {
            if (!first) sb.append(' ');
            first = false;
            int len = msg[offset] & 0xFF;
            offset++;
            sb.append('"');
            for (int i = 0; i < len; i++) {
                int b = msg[offset + i] & 0xFF;
                if (b == '"') sb.append("\\\"");
                else if (b == '\\') sb.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) sb.append((char) b);
                else sb.append(String.format("\\%03d", b));
            }
            offset += len;
            sb.append('"');
        }
        return sb.toString();
    }

    static String formatUnknown(byte[] msg, int start, int end) {
        int len = end - start;
        if (len == 0) return "\\# 0";
        StringBuilder sb = new StringBuilder();
        sb.append("\\# ").append(len).append(" ");
        for (int i = start; i < end; i++) {
            sb.append(String.format("%02x", msg[i] & 0xFF));
        }
        return sb.toString();
    }

    static String numberToType(int n) {
        switch (n) {
            case 1: return "A";
            case 5: return "CNAME";
            case 15: return "MX";
            case 16: return "TXT";
            case 28: return "AAAA";
            default: return "TYPE" + n;
        }
    }

    static String rcodeToString(int rcode) {
        switch (rcode) {
            case 0: return "NOERROR";
            case 1: return "FORMERR";
            case 2: return "SERVFAIL";
            case 3: return "NXDOMAIN";
            case 4: return "NOTIMP";
            case 5: return "REFUSED";
            default: return "RCODE" + rcode;
        }
    }
}

import * as dgram from 'dgram';
import * as net from 'net';
import * as fs from 'fs';
import * as path from 'path';

const TYPE_NAMES: Record<number, string> = {
  1: 'A', 5: 'CNAME', 15: 'MX', 16: 'TXT', 28: 'AAAA'
};

const TYPE_CODES: Record<string, number> = {
  'A': 1, 'CNAME': 5, 'MX': 15, 'TXT': 16, 'AAAA': 28
};

const RCODE_NAMES: Record<number, string> = {
  0: 'NOERROR', 1: 'FORMERR', 2: 'SERVFAIL', 3: 'NXDOMAIN', 4: 'NOTIMP', 5: 'REFUSED'
};

function rcodeName(code: number): string {
  return RCODE_NAMES[code] ?? `RCODE${code}`;
}

function typeName(code: number): string {
  return TYPE_NAMES[code] ?? `TYPE${code}`;
}

function normalizeName(name: string): string {
  let lower = name.toLowerCase();
  if (lower.endsWith('.')) lower = lower.slice(0, -1);
  if (lower === '') lower = '.';
  return lower;
}

function encodeQueryName(name: string): number[] {
  const trimmed = name.endsWith('.') ? name.slice(0, -1) : name;
  if (trimmed === '') return [0];
  const labels = trimmed.split('.');
  const result: number[] = [];
  for (const label of labels) {
    result.push(label.length);
    for (let i = 0; i < label.length; i++) {
      result.push(label.charCodeAt(i) & 0xFF);
    }
  }
  result.push(0);
  return result;
}

function buildQuery(id: number, name: string, typeCode: number): Buffer {
  const qname = encodeQueryName(name);
  const msg = Buffer.alloc(12 + qname.length + 4);
  msg.writeUInt16BE(id, 0);
  msg.writeUInt16BE(0x0100, 2);
  msg.writeUInt16BE(1, 4);
  msg.writeUInt16BE(0, 6);
  msg.writeUInt16BE(0, 8);
  msg.writeUInt16BE(0, 10);
  let offset = 12;
  for (const b of qname) {
    msg[offset++] = b;
  }
  msg.writeUInt16BE(typeCode, offset); offset += 2;
  msg.writeUInt16BE(1, offset);
  return msg;
}

function decodeName(buf: Buffer, offset: number): { name: string; newOffset: number } {
  const labels: string[] = [];
  let pos = offset;
  let returnOffset = -1;
  const visited = new Set<number>();

  while (pos < buf.length) {
    if (visited.has(pos)) break;
    visited.add(pos);

    const len = buf[pos];
    if (len === 0) {
      if (returnOffset === -1) returnOffset = pos + 1;
      break;
    }
    if ((len & 0xC0) === 0xC0) {
      if (returnOffset === -1) returnOffset = pos + 2;
      const pointer = ((len & 0x3F) << 8) | buf[pos + 1];
      pos = pointer;
      continue;
    }
    const label = buf.slice(pos + 1, pos + 1 + len).toString('ascii').toLowerCase();
    labels.push(label);
    pos += 1 + len;
  }

  if (returnOffset === -1) returnOffset = pos + 1;
  const name = labels.join('.');
  return { name: name || '.', newOffset: returnOffset };
}

function skipName(buf: Buffer, offset: number): number {
  let pos = offset;
  while (pos < buf.length) {
    const len = buf[pos];
    if (len === 0) { return pos + 1; }
    if ((len & 0xC0) === 0xC0) { return pos + 2; }
    pos += 1 + len;
  }
  return pos;
}

function formatIPv4(buf: Buffer, offset: number): string {
  return `${buf[offset]}.${buf[offset + 1]}.${buf[offset + 2]}.${buf[offset + 3]}`;
}

function formatIPv6(buf: Buffer, offset: number): string {
  const groups: string[] = [];
  for (let i = 0; i < 8; i++) {
    groups.push(buf.readUInt16BE(offset + i * 2).toString(16));
  }

  let bestStart = -1, bestLen = 0;
  let curStart = -1, curLen = 0;
  for (let i = 0; i < 8; i++) {
    if (groups[i] === '0') {
      if (curStart === -1) curStart = i;
      curLen++;
    } else {
      if (curLen >= 2 && curLen > bestLen) {
        bestStart = curStart;
        bestLen = curLen;
      }
      curStart = -1;
      curLen = 0;
    }
  }
  if (curLen >= 2 && curLen > bestLen) {
    bestStart = curStart;
    bestLen = curLen;
  }

  if (bestLen < 2) {
    return groups.join(':');
  }

  const before = groups.slice(0, bestStart).join(':');
  const after = groups.slice(bestStart + bestLen).join(':');
  return before + '::' + after;
}

function formatTxt(buf: Buffer, offset: number, rdlength: number): string {
  let pos = offset;
  const end = offset + rdlength;
  const parts: string[] = [];
  while (pos < end) {
    const len = buf[pos];
    pos++;
    let escaped = '"';
    for (let i = 0; i < len; i++) {
      const b = buf[pos + i];
      if (b === 0x22) { escaped += '\\"'; }
      else if (b === 0x5C) { escaped += '\\\\'; }
      else if (b >= 0x20 && b <= 0x7E) { escaped += String.fromCharCode(b); }
      else { escaped += '\\' + b.toString().padStart(3, '0'); }
    }
    escaped += '"';
    parts.push(escaped);
    pos += len;
  }
  return parts.join(' ');
}

interface Answer {
  owner: string;
  ttl: number;
  type: number;
  data: string;
}

interface ParsedResponse {
  id: number;
  qr: boolean;
  tc: boolean;
  rcode: number;
  answers: Answer[];
}

function parseResponse(buf: Buffer): ParsedResponse {
  const id = buf.readUInt16BE(0);
  const flags = buf.readUInt16BE(2);
  const qr = (flags & 0x8000) !== 0;
  const tc = (flags & 0x0200) !== 0;
  const rcode = flags & 0x000F;
  const qdcount = buf.readUInt16BE(4);
  const ancount = buf.readUInt16BE(6);

  let offset = 12;
  for (let i = 0; i < qdcount; i++) {
    offset = skipName(buf, offset);
    offset += 4;
  }

  const answers: Answer[] = [];

  for (let i = 0; i < ancount; i++) {
    const { name: owner, newOffset } = decodeName(buf, offset);
    offset = newOffset;
    const type = buf.readUInt16BE(offset); offset += 2;
    offset += 2; // CLASS
    const ttl = buf.readUInt32BE(offset); offset += 4;
    const rdlength = buf.readUInt16BE(offset); offset += 2;

    let data = '';
    if (type === 1) {
      data = formatIPv4(buf, offset);
    } else if (type === 28) {
      data = formatIPv6(buf, offset);
    } else if (type === 5) {
      const { name } = decodeName(buf, offset);
      data = name;
    } else if (type === 15) {
      const pref = buf.readUInt16BE(offset);
      const { name } = decodeName(buf, offset + 2);
      data = `${pref} ${name}`;
    } else if (type === 16) {
      data = formatTxt(buf, offset, rdlength);
    } else {
      if (rdlength === 0) {
        data = '\\# 0';
      } else {
        const hex = buf.slice(offset, offset + rdlength).toString('hex');
        data = `\\# ${rdlength} ${hex}`;
      }
    }

    answers.push({ owner, ttl, type, data });
    offset += rdlength;
  }

  return { id, qr, tc, rcode, answers };
}

function udpQuery(msg: Buffer, port: number): Promise<Buffer> {
  return new Promise((resolve) => {
    const socket = dgram.createSocket('udp4');
    const id = msg.readUInt16BE(0);

    socket.on('message', (response) => {
      if (response.length >= 12) {
        const respId = response.readUInt16BE(0);
        const flags = response.readUInt16BE(2);
        const qr = (flags & 0x8000) !== 0;
        if (respId === id && qr) {
          socket.close();
          resolve(response);
        }
      }
    });

    socket.send(msg, 0, msg.length, port, '127.0.0.1');
  });
}

function tcpQuery(msg: Buffer, port: number): Promise<Buffer> {
  return new Promise((resolve) => {
    const socket = net.createConnection({ host: '127.0.0.1', port });
    let buffer = Buffer.alloc(0);

    socket.on('connect', () => {
      const lenBuf = Buffer.alloc(2);
      lenBuf.writeUInt16BE(msg.length, 0);
      socket.write(Buffer.concat([lenBuf, msg]));
    });

    socket.on('data', (data) => {
      buffer = Buffer.concat([buffer, data]);
      if (buffer.length >= 2) {
        const msgLen = buffer.readUInt16BE(0);
        if (buffer.length >= 2 + msgLen) {
          const response = buffer.subarray(2, 2 + msgLen);
          socket.destroy();
          resolve(response);
        }
      }
    });
  });
}

async function main() {
  const dir = process.argv[2];
  const port = parseInt(process.argv[3]);

  const queriesPath = path.join(dir, 'queries.txt');
  const content = fs.readFileSync(queriesPath, 'utf-8');
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed === '') continue;

    const spaceIdx = trimmed.indexOf(' ');
    if (spaceIdx === -1) continue;

    const name = trimmed.substring(0, spaceIdx);
    const typeStr = trimmed.substring(spaceIdx + 1).trim();
    const typeCode = TYPE_CODES[typeStr.toUpperCase()];
    if (!typeCode) continue;

    const id = Math.floor(Math.random() * 65536);
    const query = buildQuery(id, name, typeCode);

    let response = await udpQuery(query, port);
    let parsed = parseResponse(response);

    if (parsed.tc) {
      response = await tcpQuery(query, port);
      parsed = parseResponse(response);
    }

    const outputName = normalizeName(name);
    console.log(`${outputName} ${typeStr.toUpperCase()} ${rcodeName(parsed.rcode)}`);

    for (const ans of parsed.answers) {
      console.log(`  ${ans.owner} ${ans.ttl} ${typeName(ans.type)} ${ans.data}`);
    }
  }
}

main().then(() => process.exit(0));

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::time::{SystemTime, UNIX_EPOCH};

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let port: u16 = args[2].parse().unwrap();

    let content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();
    let addr = format!("127.0.0.1:{}", port);

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let parts: Vec<&str> = trimmed.splitn(2, ' ').collect();
        if parts.len() < 2 {
            continue;
        }
        let name = parts[0];
        let qtype_str = parts[1];

        let qtype: u16 = match qtype_str {
            "A" => 1,
            "AAAA" => 28,
            "MX" => 15,
            "TXT" => 16,
            "CNAME" => 5,
            _ => continue,
        };

        let id = rand_id();
        let query = build_query(id, name, qtype);

        let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
        socket.connect(&addr).unwrap();
        socket.send(&query).unwrap();

        let mut buf = vec![0u8; 65535];
        let mut response = Vec::new();
        loop {
            let n = socket.recv(&mut buf).unwrap();
            if n >= 12 {
                let resp_id = u16::from_be_bytes([buf[0], buf[1]]);
                let flags = u16::from_be_bytes([buf[2], buf[3]]);
                let qr = (flags >> 15) & 1;
                if qr == 1 && resp_id == id {
                    response = buf[..n].to_vec();
                    break;
                }
            }
        }

        let flags = u16::from_be_bytes([response[2], response[3]]);
        let tc = (flags >> 9) & 1;

        if tc == 1 {
            let mut stream = TcpStream::connect(&addr).unwrap();
            let len_bytes = (query.len() as u16).to_be_bytes();
            stream.write_all(&len_bytes).unwrap();
            stream.write_all(&query).unwrap();
            stream.flush().unwrap();

            let mut len_buf = [0u8; 2];
            stream.read_exact(&mut len_buf).unwrap();
            let resp_len = u16::from_be_bytes(len_buf) as usize;
            let mut resp_buf = vec![0u8; resp_len];
            let mut total_read = 0;
            while total_read < resp_len {
                let n = stream.read(&mut resp_buf[total_read..]).unwrap();
                if n == 0 {
                    break;
                }
                total_read += n;
            }
            response = resp_buf;
        }

        parse_and_print(&response, name, qtype_str);
    }
}

fn rand_id() -> u16 {
    let t = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .subsec_nanos();
    ((t ^ (t >> 16)) & 0xFFFF) as u16
}

fn build_query(id: u16, name: &str, qtype: u16) -> Vec<u8> {
    let mut msg = Vec::new();
    msg.extend_from_slice(&id.to_be_bytes());
    msg.extend_from_slice(&0x0100u16.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());

    let name_trimmed = name.trim_end_matches('.');
    if !name_trimmed.is_empty() {
        for label in name_trimmed.split('.') {
            msg.push(label.len() as u8);
            msg.extend_from_slice(label.as_bytes());
        }
    }
    msg.push(0);

    msg.extend_from_slice(&qtype.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());
    msg
}

fn skip_name(msg: &[u8], start: usize) -> usize {
    let mut pos = start;
    loop {
        if pos >= msg.len() {
            return pos;
        }
        let byte = msg[pos];
        if byte == 0 {
            return pos + 1;
        }
        if byte & 0xC0 == 0xC0 {
            return pos + 2;
        }
        let len = byte as usize;
        pos += 1 + len;
    }
}

fn parse_name(msg: &[u8], start: usize) -> (String, usize) {
    let mut labels: Vec<String> = Vec::new();
    let mut pos = start;
    let mut jumped = false;
    let mut end_pos = start;
    let mut iterations = 0;

    loop {
        iterations += 1;
        if iterations > 128 {
            break;
        }
        if pos >= msg.len() {
            break;
        }
        let byte = msg[pos];
        if byte == 0 {
            if !jumped {
                end_pos = pos + 1;
            }
            break;
        }
        if byte & 0xC0 == 0xC0 {
            let ptr = ((byte as usize & 0x3F) << 8) | msg[pos + 1] as usize;
            if !jumped {
                end_pos = pos + 2;
            }
            pos = ptr;
            jumped = true;
        } else {
            let len = byte as usize;
            pos += 1;
            if pos + len > msg.len() {
                break;
            }
            let label = String::from_utf8_lossy(&msg[pos..pos + len]).to_lowercase();
            labels.push(label);
            pos += len;
            if !jumped {
                end_pos = pos;
            }
        }
    }

    if labels.is_empty() {
        (String::from("."), end_pos)
    } else {
        (labels.join("."), end_pos)
    }
}

fn format_a(data: &[u8]) -> String {
    format!("{}.{}.{}.{}", data[0], data[1], data[2], data[3])
}

fn format_aaaa(data: &[u8]) -> String {
    let mut groups: Vec<u16> = Vec::new();
    for i in 0..8 {
        groups.push(u16::from_be_bytes([data[i * 2], data[i * 2 + 1]]));
    }

    let mut best_start = usize::MAX;
    let mut best_len = 0usize;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let start = i;
            while i < 8 && groups[i] == 0 {
                i += 1;
            }
            let len = i - start;
            if len >= 2 && len > best_len {
                best_start = start;
                best_len = len;
            }
        } else {
            i += 1;
        }
    }

    let mut result = String::new();
    let mut i = 0;
    while i < 8 {
        if i == best_start {
            result.push_str("::");
            i += best_len;
        } else {
            if !result.is_empty() && !result.ends_with(':') {
                result.push(':');
            }
            result.push_str(&format!("{:x}", groups[i]));
            i += 1;
        }
    }
    result
}

fn format_mx(msg: &[u8], rdata_start: usize, rdata: &[u8]) -> String {
    let preference = u16::from_be_bytes([rdata[0], rdata[1]]);
    let (exchange, _) = parse_name(msg, rdata_start + 2);
    format!("{} {}", preference, exchange)
}

fn format_txt(data: &[u8]) -> String {
    let mut parts: Vec<String> = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        let len = data[pos] as usize;
        pos += 1;
        if pos + len > data.len() {
            break;
        }
        let s = &data[pos..pos + len];
        pos += len;
        let mut quoted = String::from("\"");
        for &b in s {
            match b {
                b'"' => quoted.push_str("\\\""),
                b'\\' => quoted.push_str("\\\\"),
                0x20..=0x7E => quoted.push(b as char),
                _ => quoted.push_str(&format!("\\{:03}", b)),
            }
        }
        quoted.push('"');
        parts.push(quoted);
    }
    parts.join(" ")
}

fn parse_and_print(msg: &[u8], query_name: &str, qtype_str: &str) {
    let flags = u16::from_be_bytes([msg[2], msg[3]]);
    let rcode = (flags & 0x0F) as u8;
    let qdcount = u16::from_be_bytes([msg[4], msg[5]]) as usize;
    let ancount = u16::from_be_bytes([msg[6], msg[7]]) as usize;

    let mut pos = 12;
    for _ in 0..qdcount {
        pos = skip_name(msg, pos);
        pos += 4;
    }

    let name_lower = query_name.to_lowercase();
    let name_display = name_lower.trim_end_matches('.');
    let name_display = if name_display.is_empty() { "." } else { name_display };

    let rcode_str = match rcode {
        0 => "NOERROR",
        1 => "FORMERR",
        2 => "SERVFAIL",
        3 => "NXDOMAIN",
        4 => "NOTIMP",
        5 => "REFUSED",
        _ => {
            println!("{} {} RCODE{}", name_display, qtype_str, rcode);
            // still print answer records
            parse_answers(msg, pos, ancount);
            return;
        }
    };
    println!("{} {} {}", name_display, qtype_str, rcode_str);
    parse_answers(msg, pos, ancount);
}

fn parse_answers(msg: &[u8], mut pos: usize, ancount: usize) {
    for _ in 0..ancount {
        if pos + 10 > msg.len() {
            break;
        }
        let (owner, new_pos) = parse_name(msg, pos);
        pos = new_pos;
        if pos + 10 > msg.len() {
            break;
        }
        let rtype = u16::from_be_bytes([msg[pos], msg[pos + 1]]);
        pos += 2;
        pos += 2; // class
        let ttl = u32::from_be_bytes([msg[pos], msg[pos + 1], msg[pos + 2], msg[pos + 3]]);
        pos += 4;
        let rdlength = u16::from_be_bytes([msg[pos], msg[pos + 1]]) as usize;
        pos += 2;

        let rdata_start = pos;
        let rdata = if pos + rdlength <= msg.len() {
            &msg[pos..pos + rdlength]
        } else {
            &msg[pos..]
        };

        let type_name = match rtype {
            1 => "A",
            5 => "CNAME",
            15 => "MX",
            16 => "TXT",
            28 => "AAAA",
            _ => "",
        };

        let data_str = match rtype {
            1 => format_a(rdata),
            5 => {
                let (target, _) = parse_name(msg, rdata_start);
                target
            }
            15 => format_mx(msg, rdata_start, rdata),
            16 => format_txt(rdata),
            28 => format_aaaa(rdata),
            _ => {
                if rdlength == 0 {
                    String::from("\\# 0")
                } else {
                    let hex: String = rdata.iter().map(|b| format!("{:02x}", b)).collect();
                    format!("\\# {} {}", rdlength, hex)
                }
            }
        };

        let type_display = if type_name.is_empty() {
            format!("TYPE{}", rtype)
        } else {
            type_name.to_string()
        };

        println!("  {} {} {} {}", owner, ttl, type_display, data_str);
        pos = rdata_start + rdlength;
    }
}

import * as fs from 'fs';
import * as path from 'path';

function parseDecimal(s: string): { value: bigint; scale: number } {
    let negative = false;
    let i = 0;
    if (s[0] === '-') {
        negative = true;
        i = 1;
    }
    let intPart = '';
    let fracPart = '';
    let hasDot = false;
    for (; i < s.length; i++) {
        if (s[i] === '.') {
            hasDot = true;
        } else {
            if (hasDot) fracPart += s[i];
            else intPart += s[i];
        }
    }
    let digits = intPart + fracPart;
    let value = BigInt(digits === '' ? '0' : digits);
    if (negative) value = -value;
    return { value, scale: fracPart.length };
}

function pow10(n: number): bigint {
    return 10n ** BigInt(n);
}

function roundDiv(numerator: bigint, denominator: bigint): bigint {
    if (denominator === 1n) return numerator;
    let q = numerator / denominator;
    let r = numerator - q * denominator;
    let absR = r < 0n ? -r : r;
    let twoAbsR = absR * 2n;

    if (twoAbsR > denominator) {
        if (numerator > 0n) q += 1n;
        else if (numerator < 0n) q -= 1n;
    } else if (twoAbsR === denominator) {
        if (q % 2n !== 0n) {
            if (numerator > 0n) q += 1n;
            else if (numerator < 0n) q -= 1n;
        }
    }
    return q;
}

function roundToMinor(value: bigint, scale: number, mu: number): bigint {
    if (scale <= mu) {
        return value * pow10(mu - scale);
    } else {
        return roundDiv(value, pow10(scale - mu));
    }
}

function formatMoney(minorUnits: bigint, mu: number): string {
    if (minorUnits === 0n) {
        if (mu === 0) return '0';
        return '0.' + '0'.repeat(mu);
    }

    let negative = minorUnits < 0n;
    let abs = negative ? -minorUnits : minorUnits;

    let intStr: string;
    let fracStr: string;
    if (mu === 0) {
        intStr = abs.toString();
        fracStr = '';
    } else {
        let p = pow10(mu);
        intStr = (abs / p).toString();
        fracStr = (abs % p).toString().padStart(mu, '0');
    }

    let withCommas = '';
    let count = 0;
    for (let i = intStr.length - 1; i >= 0; i--) {
        withCommas = intStr[i] + withCommas;
        count++;
        if (count % 3 === 0 && i > 0) {
            withCommas = ',' + withCommas;
        }
    }

    let result = '';
    if (negative) result = '-';
    result += withCommas;
    if (mu > 0) {
        result += '.' + fracStr;
    }
    return result;
}

const dir = process.argv[2];
const content = fs.readFileSync(path.join(dir, 'ledger.txt'), 'utf-8');
let lines = content.split('\n');
if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
}

const currencies = new Map<string, number>();
const accounts = new Map<string, { currency: string; balance: bigint; limit: bigint }>();
const rejections: string[] = [];

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const trimmed = line.trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const fields = trimmed.split(/\s+/);
    const cmd = fields[0];
    const ln = lineNum + 1;
    let rejected = false;

    if (cmd === 'currency') {
        currencies.set(fields[1], parseInt(fields[2]));
    } else if (cmd === 'open') {
        const name = fields[1];
        const code = fields[2];
        const limitStr = fields.length > 3 ? fields[3] : '0';

        if (accounts.has(name)) {
            rejections.push(`line ${ln}: REJECT account exists ${name}`);
            continue;
        }

        const mu = currencies.get(code)!;
        const limitDec = parseDecimal(limitStr);
        const limit = roundToMinor(limitDec.value, limitDec.scale, mu);

        accounts.set(name, { currency: code, balance: 0n, limit });
    } else if (cmd === 'deposit') {
        const name = fields[1];
        const amountStr = fields[2];

        if (!accounts.has(name)) {
            rejections.push(`line ${ln}: REJECT unknown account ${name}`);
            continue;
        }

        const acc = accounts.get(name)!;
        const mu = currencies.get(acc.currency)!;
        const amountDec = parseDecimal(amountStr);
        const amount = roundToMinor(amountDec.value, amountDec.scale, mu);

        if (amount <= 0n) {
            rejections.push(`line ${ln}: REJECT non-positive amount`);
            continue;
        }

        acc.balance += amount;
    } else if (cmd === 'withdraw') {
        const name = fields[1];
        const amountStr = fields[2];

        if (!accounts.has(name)) {
            rejections.push(`line ${ln}: REJECT unknown account ${name}`);
            continue;
        }

        const acc = accounts.get(name)!;
        const mu = currencies.get(acc.currency)!;
        const amountDec = parseDecimal(amountStr);
        const amount = roundToMinor(amountDec.value, amountDec.scale, mu);

        if (amount <= 0n) {
            rejections.push(`line ${ln}: REJECT non-positive amount`);
            continue;
        }

        if (acc.balance - amount < -acc.limit) {
            rejections.push(`line ${ln}: REJECT insufficient funds ${name}`);
            continue;
        }

        acc.balance -= amount;
    } else if (cmd === 'transfer') {
        const fromName = fields[1];
        const toName = fields[2];
        const amountStr = fields[3];

        if (!accounts.has(fromName)) {
            rejections.push(`line ${ln}: REJECT unknown account ${fromName}`);
            continue;
        }
        if (!accounts.has(toName)) {
            rejections.push(`line ${ln}: REJECT unknown account ${toName}`);
            continue;
        }

        const from = accounts.get(fromName)!;
        const to = accounts.get(toName)!;

        if (from.currency !== to.currency) {
            rejections.push(`line ${ln}: REJECT currency mismatch`);
            continue;
        }

        const mu = currencies.get(from.currency)!;
        const amountDec = parseDecimal(amountStr);
        const amount = roundToMinor(amountDec.value, amountDec.scale, mu);

        if (amount <= 0n) {
            rejections.push(`line ${ln}: REJECT non-positive amount`);
            continue;
        }

        if (from.balance - amount < -from.limit) {
            rejections.push(`line ${ln}: REJECT insufficient funds ${fromName}`);
            continue;
        }

        from.balance -= amount;
        to.balance += amount;
    } else if (cmd === 'convert') {
        const fromName = fields[1];
        const toName = fields[2];
        const amountStr = fields[3];
        const rateStr = fields[4];

        if (!accounts.has(fromName)) {
            rejections.push(`line ${ln}: REJECT unknown account ${fromName}`);
            continue;
        }
        if (!accounts.has(toName)) {
            rejections.push(`line ${ln}: REJECT unknown account ${toName}`);
            continue;
        }

        const from = accounts.get(fromName)!;
        const to = accounts.get(toName)!;

        const fromMu = currencies.get(from.currency)!;
        const toMu = currencies.get(to.currency)!;

        const amountDec = parseDecimal(amountStr);
        const amount = roundToMinor(amountDec.value, amountDec.scale, fromMu);

        if (amount <= 0n) {
            rejections.push(`line ${ln}: REJECT non-positive amount`);
            continue;
        }

        if (from.balance - amount < -from.limit) {
            rejections.push(`line ${ln}: REJECT insufficient funds ${fromName}`);
            continue;
        }

        const rateDec = parseDecimal(rateStr);
        const numerator = amount * rateDec.value * pow10(toMu);
        const denominator = pow10(fromMu + rateDec.scale);
        const converted = roundDiv(numerator, denominator);

        from.balance -= amount;
        to.balance += converted;
    } else if (cmd === 'interest') {
        const name = fields[1];
        const rateStr = fields[2];

        if (!accounts.has(name)) {
            rejections.push(`line ${ln}: REJECT unknown account ${name}`);
            continue;
        }

        const acc = accounts.get(name)!;
        const rateDec = parseDecimal(rateStr);

        const numerator = acc.balance * rateDec.value;
        const denominator = pow10(rateDec.scale);
        const interest = roundDiv(numerator, denominator);

        acc.balance += interest;
    } else if (cmd === 'split') {
        const fromName = fields[1];
        const amountStr = fields[2];

        const targets: { name: string; weight: bigint }[] = [];
        for (let i = 3; i < fields.length; i++) {
            const colonIdx = fields[i].indexOf(':');
            const tName = fields[i].substring(0, colonIdx);
            const tWeight = BigInt(fields[i].substring(colonIdx + 1));
            targets.push({ name: tName, weight: tWeight });
        }

        const allNames = [fromName, ...targets.map(t => t.name)];
        for (const name of allNames) {
            if (!accounts.has(name)) {
                rejections.push(`line ${ln}: REJECT unknown account ${name}`);
                rejected = true;
                break;
            }
        }
        if (rejected) continue;

        const from = accounts.get(fromName)!;
        const fromCurrency = from.currency;

        for (const t of targets) {
            const tAcc = accounts.get(t.name)!;
            if (tAcc.currency !== fromCurrency) {
                rejections.push(`line ${ln}: REJECT currency mismatch`);
                rejected = true;
                break;
            }
        }
        if (rejected) continue;

        const mu = currencies.get(fromCurrency)!;
        const amountDec = parseDecimal(amountStr);
        const A = roundToMinor(amountDec.value, amountDec.scale, mu);

        if (A <= 0n) {
            rejections.push(`line ${ln}: REJECT non-positive amount`);
            continue;
        }

        if (from.balance - A < -from.limit) {
            rejections.push(`line ${ln}: REJECT insufficient funds ${fromName}`);
            continue;
        }

        let W = 0n;
        for (const t of targets) W += t.weight;

        const shares: bigint[] = [];
        const remainders: bigint[] = [];
        let totalAllocated = 0n;

        for (const t of targets) {
            const product = A * t.weight;
            const share = product / W;
            const remainder = product % W;
            shares.push(share);
            remainders.push(remainder);
            totalAllocated += share;
        }

        let leftover = A - totalAllocated;

        const indices = Array.from({ length: targets.length }, (_, i) => i);
        indices.sort((a, b) => {
            if (remainders[b] > remainders[a]) return 1;
            if (remainders[b] < remainders[a]) return -1;
            return a - b;
        });

        for (let i = 0; i < Number(leftover) && i < indices.length; i++) {
            shares[indices[i]] += 1n;
        }

        from.balance -= A;
        for (let i = 0; i < targets.length; i++) {
            const tAcc = accounts.get(targets[i].name)!;
            tAcc.balance += shares[i];
        }
    }
}

const output: string[] = [];

for (const r of rejections) {
    output.push(r);
}

output.push('');

const sortedAccounts = [...accounts.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
});

for (const [name, acc] of sortedAccounts) {
    const mu = currencies.get(acc.currency)!;
    output.push(`${name} ${acc.currency} ${formatMoney(acc.balance, mu)}`);
}

output.push('');

const currencyTotals = new Map<string, { total: bigint; count: number }>();
for (const [, acc] of accounts) {
    const code = acc.currency;
    if (!currencyTotals.has(code)) {
        currencyTotals.set(code, { total: 0n, count: 0 });
    }
    const entry = currencyTotals.get(code)!;
    entry.total += acc.balance;
    entry.count++;
}

const sortedCurrencies = [...currencyTotals.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
});

for (const [code, { total, count }] of sortedCurrencies) {
    const mu = currencies.get(code)!;
    output.push(`total ${code} ${formatMoney(total, mu)} (${count} accounts)`);
}

console.log(output.join('\n'));

import Foundation
import Darwin

// MARK: - Helpers

func readU16(_ d: [UInt8], _ o: Int) -> Int {
    return Int(d[o]) << 8 | Int(d[o + 1])
}

func readU32(_ d: [UInt8], _ o: Int) -> UInt32 {
    return UInt32(d[o]) << 24 | UInt32(d[o+1]) << 16 | UInt32(d[o+2]) << 8 | UInt32(d[o+3])
}

func parseName(_ msg: [UInt8], _ start: Int) -> (name: String, next: Int) {
    var labels: [String] = []
    var off = start
    var next = -1
    var jumped = false
    var jumps = 0
    while off < msg.count {
        let len = Int(msg[off])
        if len == 0 {
            if !jumped { next = off + 1 }
            break
        }
        if len & 0xC0 == 0xC0 {
            if !jumped { next = off + 2; jumped = true }
            let ptr = (Int(msg[off] & 0x3F) << 8) | Int(msg[off + 1])
            off = ptr
            jumps += 1
            if jumps > 128 { break }
            continue
        }
        if off + 1 + len > msg.count { break }
        let lb = Array(msg[(off+1)..<(off+1+len)])
        labels.append(String(bytes: lb, encoding: .ascii) ?? "")
        off += 1 + len
        if !jumped { next = off }
    }
    if next == -1 { next = off }
    if labels.isEmpty { return (".", next) }
    return (labels.joined(separator: ".").lowercased(), next)
}

func formatIPv6(_ b: [UInt8]) -> String {
    var g: [UInt16] = []
    for i in 0..<8 { g.append(UInt16(b[i*2]) << 8 | UInt16(b[i*2+1])) }
    var bs = -1, bl = 0
    var i = 0
    while i < 8 {
        if g[i] == 0 {
            var j = i
            while j < 8 && g[j] == 0 { j += 1 }
            if j - i >= 2 && j - i > bl { bs = i; bl = j - i }
            i = j
        } else { i += 1 }
    }
    if bs == -1 {
        return g.map { String($0, radix: 16) }.joined(separator: ":")
    }
    var pre: [String] = []
    for k in 0..<bs { pre.append(String(g[k], radix: 16)) }
    var suf: [String] = []
    for k in (bs+bl)..<8 { suf.append(String(g[k], radix: 16)) }
    if pre.isEmpty && suf.isEmpty { return "::" }
    if pre.isEmpty { return "::" + suf.joined(separator: ":") }
    if suf.isEmpty { return pre.joined(separator: ":") + "::" }
    return pre.joined(separator: ":") + "::" + suf.joined(separator: ":")
}

func parseTXT(_ d: [UInt8]) -> String {
    var off = 0
    var strs: [String] = []
    while off < d.count {
        let len = Int(d[off]); off += 1
        if off + len > d.count { break }
        var s = "\""
        for j in 0..<len {
            let b = d[off + j]
            if b == 0x22 { s += "\\\"" }
            else if b == 0x5C { s += "\\\\" }
            else if b >= 0x20 && b <= 0x7E { s.append(Character(UnicodeScalar(b))) }
            else { s += "\\\(String(format: "%03d", Int(b)))" }
        }
        s += "\""
        strs.append(s)
        off += len
    }
    return strs.joined(separator: " ")
}

func formatUnknown(_ d: [UInt8]) -> String {
    if d.isEmpty { return "\\# 0" }
    return "\\# \(d.count) " + d.map { String(format: "%02x", $0) }.joined()
}

func typeName(_ t: Int) -> String {
    switch t {
    case 1: return "A"; case 5: return "CNAME"; case 15: return "MX"
    case 16: return "TXT"; case 28: return "AAAA"
    default: return "TYPE\(t)"
    }
}

func rcodeName(_ r: Int) -> String {
    switch r {
    case 0: return "NOERROR"; case 1: return "FORMERR"; case 2: return "SERVFAIL"
    case 3: return "NXDOMAIN"; case 4: return "NOTIMP"; case 5: return "REFUSED"
    default: return "RCODE\(r)"
    }
}

func qtypeVal(_ t: String) -> UInt16 {
    switch t {
    case "A": return 1; case "AAAA": return 28; case "MX": return 15
    case "TXT": return 16; case "CNAME": return 5; default: return 0
    }
}

// MARK: - Build query

func buildQuery(id: UInt16, name: String, qtype: UInt16) -> [UInt8] {
    var m: [UInt8] = []
    m.append(UInt8(id >> 8)); m.append(UInt8(id & 0xFF))
    m.append(0x01); m.append(0x00)
    m.append(0x00); m.append(0x01)
    m.append(0x00); m.append(0x00)
    m.append(0x00); m.append(0x00)
    m.append(0x00); m.append(0x00)
    var cn = name
    if cn.hasSuffix(".") { cn = String(cn.dropLast()) }
    if cn.isEmpty {
        m.append(0)
    } else {
        for part in cn.components(separatedBy: ".") {
            let b = Array(part.utf8)
            m.append(UInt8(b.count))
            m.append(contentsOf: b)
        }
        m.append(0)
    }
    m.append(UInt8(qtype >> 8)); m.append(UInt8(qtype & 0xFF))
    m.append(0x00); m.append(0x01)
    return m
}

// MARK: - Parse response

struct Answer { let owner: String; let ttl: UInt32; let type: Int; let data: String }
struct DNSResp { let rcode: Int; let answers: [Answer] }

func parseResponse(_ msg: [UInt8]) -> DNSResp {
    let flags = readU16(msg, 2)
    let rcode = flags & 0xF
    let qd = readU16(msg, 4)
    let an = readU16(msg, 6)
    var off = 12
    for _ in 0..<qd {
        let (_, nx) = parseName(msg, off); off = nx + 4
    }
    var answers: [Answer] = []
    for _ in 0..<an {
        let (owner, nx) = parseName(msg, off); off = nx
        let rtype = readU16(msg, off); off += 2
        off += 2 // class
        let ttl = readU32(msg, off); off += 4
        let rdl = readU16(msg, off); off += 2
        let rds = off
        let rdata = Array(msg[off..<(off+rdl)])
        var ds = ""
        switch rtype {
        case 1:
            ds = "\(rdata[0]).\(rdata[1]).\(rdata[2]).\(rdata[3])"
        case 28:
            ds = formatIPv6(rdata)
        case 5:
            ds = parseName(msg, rds).name
        case 15:
            let pref = readU16(rdata, 0)
            let nm = parseName(msg, rds + 2).name
            ds = "\(pref) \(nm)"
        case 16:
            ds = parseTXT(rdata)
        default:
            ds = formatUnknown(rdata)
        }
        answers.append(Answer(owner: owner, ttl: ttl, type: rtype, data: ds))
        off += rdl
    }
    return DNSResp(rcode: rcode, answers: answers)
}

// MARK: - Networking

func readExact(_ fd: Int32, _ n: Int) -> [UInt8] {
    var buf = [UInt8](repeating: 0, count: n)
    var got = 0
    while got < n {
        let r = recv(fd, &buf[got], n - got, 0)
        if r <= 0 { break }
        got += r
    }
    return Array(buf[0..<got])
}

func tcpQuery(_ query: [UInt8], _ port: UInt16) -> [UInt8] {
    let fd = socket(AF_INET, SOCK_STREAM, 0)
    var addr = sockaddr_in()
    addr.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")
    withUnsafePointer(to: &addr) { p in
        p.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            _ = connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    var pkt = [UInt8(query.count >> 8), UInt8(query.count & 0xFF)]
    pkt.append(contentsOf: query)
    var sent = 0
    while sent < pkt.count {
        let n = pkt.withUnsafeBytes { send(fd, $0.baseAddress!.advanced(by: sent), pkt.count - sent, 0) }
        if n <= 0 { break }
        sent += n
    }
    let lb = readExact(fd, 2)
    let rl = Int(lb[0]) << 8 | Int(lb[1])
    let resp = readExact(fd, rl)
    close(fd)
    return resp
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dir = args[1]
let port = UInt16(args[2])!

let content = try! String(contentsOfFile: (dir as NSString).appendingPathComponent("queries.txt"), encoding: .utf8)
let lines = content.components(separatedBy: "\n")

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.isEmpty { continue }
    let parts = trimmed.split(separator: " ", maxSplits: 1)
    guard parts.count == 2 else { continue }
    let name = String(parts[0])
    let typeStr = String(parts[1])
    let qtype = qtypeVal(typeStr)
    let id = UInt16.random(in: UInt16.min...UInt16.max)
    let query = buildQuery(id: id, name: name, qtype: qtype)

    // UDP
    let ufd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
    var addr = sockaddr_in()
    addr.sin_len = UInt8(MemoryLayout<sockaddr_in>.size)
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")
    query.withUnsafeBytes { buf in
        withUnsafePointer(to: &addr) { ap in
            ap.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                _ = sendto(ufd, buf.baseAddress!, buf.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
    }
    var rbuf = [UInt8](repeating: 0, count: 65535)
    var resp: [UInt8] = []
    while true {
        let n = recvfrom(ufd, &rbuf, rbuf.count, 0, nil, nil)
        if n <= 0 { continue }
        let m = Array(rbuf[0..<n])
        if m.count < 12 { continue }
        let rid = readU16(m, 0)
        let fl = readU16(m, 2)
        if (fl >> 15) & 1 == 1 && rid == Int(id) { resp = m; break }
    }
    let tc = (readU16(resp, 2) >> 9) & 1
    if tc == 1 {
        close(ufd)
        resp = tcpQuery(query, port)
    } else {
        close(ufd)
    }

    let r = parseResponse(resp)
    var dn = name.lowercased()
    if dn.hasSuffix(".") { dn = String(dn.dropLast()) }
    if dn.isEmpty { dn = "." }
    print("\(dn) \(typeStr) \(rcodeName(r.rcode))")
    for a in r.answers {
        print("  \(a.owner) \(a.ttl) \(typeName(a.type)) \(a.data)")
    }
}
exit(0)

import json
import sys
import os


def deep_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if a is None or b is None:
        return a is None and b is None
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(deep_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(deep_equal(a[k], b[k]) for k in a)
    return False


def is_integer(x):
    if isinstance(x, bool):
        return False
    if isinstance(x, int):
        return True
    if isinstance(x, float):
        return x == int(x)
    return False


def is_number(x):
    if isinstance(x, bool):
        return False
    return isinstance(x, (int, float))


def type_name(x):
    if x is None:
        return "null"
    if isinstance(x, bool):
        return "boolean"
    if isinstance(x, (int, float)):
        return "number"
    if isinstance(x, str):
        return "string"
    if isinstance(x, list):
        return "array"
    if isinstance(x, dict):
        return "object"
    return "unknown"


def format_pointer(tokens):
    result = "#"
    for t in tokens:
        t = str(t)
        t = t.replace("~", "~0").replace("/", "~1")
        result += "/" + t
    return result


def resolve_ref(ref_str, root_schema):
    if ref_str == "#":
        return root_schema, []
    pointer = ref_str[1:]  # Remove "#"
    raw_tokens = pointer[1:].split("/")
    current = root_schema
    schema_tokens = []
    for t in raw_tokens:
        t = t.replace("~1", "/").replace("~0", "~")
        schema_tokens.append(t)
        current = current[t]
    return current, schema_tokens


def validate(instance, schema, inst_tokens, schema_tokens, errors, root_schema):
    if schema is True:
        return
    if schema is False:
        errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens)))
        return

    # type
    if "type" in schema:
        type_val = schema["type"]
        if isinstance(type_val, str):
            type_names = [type_val]
        else:
            type_names = type_val
        inst_type = type_name(instance)
        matched = False
        for tn in type_names:
            if tn == inst_type:
                matched = True
                break
            if tn == "integer" and inst_type == "number" and is_integer(instance):
                matched = True
                break
        if not matched:
            errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["type"])))

    # enum
    if "enum" in schema:
        if not any(deep_equal(instance, v) for v in schema["enum"]):
            errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["enum"])))

    # const
    if "const" in schema:
        if not deep_equal(instance, schema["const"]):
            errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["const"])))

    # Number keywords
    if is_number(instance):
        if "minimum" in schema:
            if not (instance >= schema["minimum"]):
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["minimum"])))
        if "maximum" in schema:
            if not (instance <= schema["maximum"]):
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["maximum"])))
        if "exclusiveMinimum" in schema:
            if not (instance > schema["exclusiveMinimum"]):
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["exclusiveMinimum"])))
        if "exclusiveMaximum" in schema:
            if not (instance < schema["exclusiveMaximum"]):
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["exclusiveMaximum"])))

    # String keywords
    if isinstance(instance, str):
        if "minLength" in schema:
            if len(instance) < schema["minLength"]:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["minLength"])))
        if "maxLength" in schema:
            if len(instance) > schema["maxLength"]:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["maxLength"])))

    # Array keywords
    if isinstance(instance, list):
        if "minItems" in schema:
            if len(instance) < schema["minItems"]:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["minItems"])))
        if "maxItems" in schema:
            if len(instance) > schema["maxItems"]:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["maxItems"])))
        if "uniqueItems" in schema and schema["uniqueItems"] is True:
            found_dup = False
            for i in range(len(instance)):
                for j in range(i + 1, len(instance)):
                    if deep_equal(instance[i], instance[j]):
                        found_dup = True
                        break
                if found_dup:
                    break
            if found_dup:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["uniqueItems"])))

        # prefixItems
        prefix_len = 0
        if "prefixItems" in schema:
            prefix_items = schema["prefixItems"]
            prefix_len = len(prefix_items)
            for i in range(min(len(instance), prefix_len)):
                validate(instance[i], prefix_items[i], inst_tokens + [str(i)],
                         schema_tokens + ["prefixItems", str(i)], errors, root_schema)

        # items
        if "items" in schema:
            items_schema = schema["items"]
            start = prefix_len if "prefixItems" in schema else 0
            for i in range(start, len(instance)):
                validate(instance[i], items_schema, inst_tokens + [str(i)],
                         schema_tokens + ["items"], errors, root_schema)

    # Object keywords
    if isinstance(instance, dict):
        if "minProperties" in schema:
            if len(instance) < schema["minProperties"]:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["minProperties"])))
        if "maxProperties" in schema:
            if len(instance) > schema["maxProperties"]:
                errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["maxProperties"])))

        if "required" in schema:
            for j, name in enumerate(schema["required"]):
                if name not in instance:
                    errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["required", str(j)])))

        # properties
        prop_names = set()
        if "properties" in schema:
            props = schema["properties"]
            prop_names = set(props.keys())
            for name, sub_schema in props.items():
                if name in instance:
                    validate(instance[name], sub_schema, inst_tokens + [name],
                             schema_tokens + ["properties", name], errors, root_schema)

        # additionalProperties
        if "additionalProperties" in schema:
            add_schema = schema["additionalProperties"]
            for name in instance:
                if name not in prop_names:
                    validate(instance[name], add_schema, inst_tokens + [name],
                             schema_tokens + ["additionalProperties"], errors, root_schema)

    # Applicators
    if "allOf" in schema:
        for i, sub_schema in enumerate(schema["allOf"]):
            validate(instance, sub_schema, inst_tokens, schema_tokens + ["allOf", str(i)],
                     errors, root_schema)

    if "anyOf" in schema:
        any_accepted = False
        for sub_schema in schema["anyOf"]:
            temp_errors = set()
            validate(instance, sub_schema, inst_tokens, [], temp_errors, root_schema)
            if not temp_errors:
                any_accepted = True
                break
        if not any_accepted:
            errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["anyOf"])))

    if "oneOf" in schema:
        accept_count = 0
        for sub_schema in schema["oneOf"]:
            temp_errors = set()
            validate(instance, sub_schema, inst_tokens, [], temp_errors, root_schema)
            if not temp_errors:
                accept_count += 1
        if accept_count != 1:
            errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["oneOf"])))

    if "not" in schema:
        temp_errors = set()
        validate(instance, schema["not"], inst_tokens, [], temp_errors, root_schema)
        if not temp_errors:
            errors.add((format_pointer(inst_tokens), format_pointer(schema_tokens + ["not"])))

    if "if" in schema:
        temp_errors = set()
        validate(instance, schema["if"], inst_tokens, [], temp_errors, root_schema)
        if_accepted = not temp_errors
        if if_accepted and "then" in schema:
            validate(instance, schema["then"], inst_tokens, schema_tokens + ["then"],
                     errors, root_schema)
        elif not if_accepted and "else" in schema:
            validate(instance, schema["else"], inst_tokens, schema_tokens + ["else"],
                     errors, root_schema)

    # $ref
    if "$ref" in schema:
        ref_schema, ref_tokens = resolve_ref(schema["$ref"], root_schema)
        validate(instance, ref_schema, inst_tokens, ref_tokens, errors, root_schema)


def main():
    directory = sys.argv[1]

    with open(os.path.join(directory, "schema.json"), "r", encoding="utf-8") as f:
        schema = json.load(f)

    with open(os.path.join(directory, "instances.json"), "r", encoding="utf-8") as f:
        instances = json.load(f)

    valid_count = 0
    invalid_count = 0

    for n, instance in enumerate(instances):
        errors = set()
        validate(instance, schema, [], [], errors, schema)

        if not errors:
            print(f"{n}: valid")
            valid_count += 1
        else:
            sorted_errors = sorted(errors, key=lambda x: (x[0], x[1]))
            print(f"{n}: invalid ({len(sorted_errors)})")
            for inst_loc, schema_loc in sorted_errors:
                print(f"  {inst_loc} {schema_loc}")
            invalid_count += 1

    print(f"valid={valid_count} invalid={invalid_count}")


if __name__ == "__main__":
    main()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <time.h>

#define MAX_MSG 65535
#define MAX_NAME 2048

static uint16_t type_from_str(const char *s) {
    if (!strcmp(s, "A")) return 1;
    if (!strcmp(s, "AAAA")) return 28;
    if (!strcmp(s, "MX")) return 15;
    if (!strcmp(s, "TXT")) return 16;
    if (!strcmp(s, "CNAME")) return 5;
    return 0;
}

static const char *type_to_str(uint16_t t) {
    switch (t) {
        case 1: return "A";
        case 5: return "CNAME";
        case 15: return "MX";
        case 16: return "TXT";
        case 28: return "AAAA";
    }
    return NULL;
}

static const char *rcode_str(uint16_t r) {
    switch (r) {
        case 0: return "NOERROR";
        case 1: return "FORMERR";
        case 2: return "SERVFAIL";
        case 3: return "NXDOMAIN";
        case 4: return "NOTIMP";
        case 5: return "REFUSED";
    }
    return NULL;
}

static int build_query(uint8_t *buf, uint16_t id, const char *name, uint16_t qtype) {
    int p = 0;
    buf[p++] = id >> 8; buf[p++] = id & 0xFF;
    buf[p++] = 0x01; buf[p++] = 0x00;
    buf[p++] = 0; buf[p++] = 1;
    buf[p++] = 0; buf[p++] = 0;
    buf[p++] = 0; buf[p++] = 0;
    buf[p++] = 0; buf[p++] = 0;

    const char *s = name;
    while (*s) {
        const char *dot = strchr(s, '.');
        if (!dot) dot = s + strlen(s);
        int len = dot - s;
        if (len > 0) {
            buf[p++] = (uint8_t)len;
            memcpy(buf + p, s, len);
            p += len;
        }
        s = dot;
        if (*s == '.') s++;
    }
    buf[p++] = 0;

    buf[p++] = qtype >> 8; buf[p++] = qtype & 0xFF;
    buf[p++] = 0; buf[p++] = 1;
    return p;
}

static int parse_name(uint8_t *msg, int msglen, int off, char *out, int outsz) {
    int op = 0, ret = -1, jumps = 0;
    while (off >= 0 && off < msglen) {
        uint8_t b = msg[off];
        if (b == 0) {
            if (ret < 0) ret = off + 1;
            break;
        }
        if ((b & 0xC0) == 0xC0) {
            if (off + 1 >= msglen) return -1;
            if (ret < 0) ret = off + 2;
            off = ((b & 0x3F) << 8) | msg[off + 1];
            if (++jumps > 128) return -1;
        } else {
            off++;
            if (off + b > msglen) return -1;
            if (op > 0) {
                if (op + 1 >= outsz) return -1;
                out[op++] = '.';
            }
            if (op + b >= outsz) return -1;
            for (int i = 0; i < b; i++)
                out[op++] = tolower(msg[off + i]);
            off += b;
        }
    }
    out[op] = '\0';
    return ret;
}

static void fmt_aaaa(uint8_t *d, char *out) {
    uint16_t g[8];
    for (int i = 0; i < 8; i++) g[i] = (uint16_t)((d[i*2] << 8) | d[i*2+1]);

    int bs = -1, bl = 0, cs = -1, cl = 0;
    for (int i = 0; i < 8; i++) {
        if (g[i] == 0) {
            if (cs < 0) cs = i;
            cl++;
        } else {
            if (cl >= 2 && cl > bl) { bs = cs; bl = cl; }
            cs = -1; cl = 0;
        }
    }
    if (cl >= 2 && cl > bl) { bs = cs; bl = cl; }

    char *p = out;
    if (bs < 0) {
        for (int i = 0; i < 8; i++) {
            if (i) *p++ = ':';
            p += sprintf(p, "%x", g[i]);
        }
    } else {
        for (int i = 0; i < bs; i++) {
            if (i) *p++ = ':';
            p += sprintf(p, "%x", g[i]);
        }
        *p++ = ':'; *p++ = ':';
        for (int i = bs + bl; i < 8; i++) {
            if (i > bs + bl) *p++ = ':';
            p += sprintf(p, "%x", g[i]);
        }
    }
    *p = '\0';
}

static int read_exact(int fd, uint8_t *buf, int n) {
    int t = 0;
    while (t < n) {
        int r = read(fd, buf + t, n - t);
        if (r <= 0) return -1;
        t += r;
    }
    return t;
}

static int write_all(int fd, uint8_t *buf, int n) {
    int t = 0;
    while (t < n) {
        int w = write(fd, buf + t, n - t);
        if (w <= 0) return -1;
        t += w;
    }
    return t;
}

int main(int argc, char **argv) {
    if (argc != 3) return 1;
    const char *dir = argv[1];
    int port = atoi(argv[2]);

    char path[4096];
    snprintf(path, sizeof(path), "%s/queries.txt", dir);
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    srand(time(NULL) ^ getpid());

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        int len = strlen(line);
        while (len > 0 && isspace((unsigned char)line[len-1])) line[--len] = '\0';
        if (len == 0) continue;

        char *sp = strchr(line, ' ');
        if (!sp) continue;
        *sp = '\0';
        char *name = line;
        char *tstr = sp + 1;

        char qname[MAX_NAME];
        strcpy(qname, name);
        int ql = strlen(qname);
        if (ql > 0 && qname[ql-1] == '.') qname[--ql] = '\0';

        uint16_t qtype = type_from_str(tstr);

        uint8_t query[MAX_MSG];
        uint16_t id = (uint16_t)(rand() & 0xFFFF);
        int qlen = build_query(query, id, qname, qtype);

        int fd = socket(AF_INET, SOCK_DGRAM, 0);
        sendto(fd, query, qlen, 0, (struct sockaddr*)&addr, sizeof(addr));

        uint8_t resp[MAX_MSG];
        int rlen;
        while (1) {
            rlen = recv(fd, resp, sizeof(resp), 0);
            if (rlen < 12) continue;
            uint16_t rid = (resp[0] << 8) | resp[1];
            uint16_t fl = (resp[2] << 8) | resp[3];
            if ((fl & 0x8000) && rid == id) break;
        }
        close(fd);

        uint16_t flags = (resp[2] << 8) | resp[3];
        if (flags & 0x0200) {
            int tfd = socket(AF_INET, SOCK_STREAM, 0);
            connect(tfd, (struct sockaddr*)&addr, sizeof(addr));
            uint8_t tbuf[MAX_MSG + 2];
            tbuf[0] = qlen >> 8; tbuf[1] = qlen & 0xFF;
            memcpy(tbuf + 2, query, qlen);
            write_all(tfd, tbuf, qlen + 2);
            uint8_t lb[2];
            read_exact(tfd, lb, 2);
            int tlen = (lb[0] << 8) | lb[1];
            rlen = read_exact(tfd, resp, tlen);
            close(tfd);
        }

        uint16_t rflags = (resp[2] << 8) | resp[3];
        uint16_t rcode = rflags & 0xF;
        uint16_t qd = (resp[4] << 8) | resp[5];
        uint16_t an = (resp[6] << 8) | resp[7];

        char oname[MAX_NAME];
        int i;
        for (i = 0; name[i]; i++) oname[i] = tolower(name[i]);
        oname[i] = '\0';
        int ol = strlen(oname);
        if (ol > 0 && oname[ol-1] == '.') oname[--ol] = '\0';
        if (ol == 0) strcpy(oname, ".");

        printf("%s %s ", oname, tstr);
        const char *rs = rcode_str(rcode);
        if (rs) printf("%s\n", rs);
        else printf("RCODE%u\n", rcode);

        int off = 12;
        for (int qi = 0; qi < qd && off >= 0; qi++) {
            char tmp[MAX_NAME];
            off = parse_name(resp, rlen, off, tmp, sizeof(tmp));
            if (off < 0) break;
            off += 4;
        }

        for (int ai = 0; ai < an && off >= 0; ai++) {
            char owner[MAX_NAME];
            off = parse_name(resp, rlen, off, owner, sizeof(owner));
            if (off < 0) break;
            if (off + 10 > rlen) break;

            uint16_t rtype = (resp[off] << 8) | resp[off+1];
            uint32_t ttl = ((uint32_t)resp[off+4] << 24) | ((uint32_t)resp[off+5] << 16) |
                           ((uint32_t)resp[off+6] << 8) | (uint32_t)resp[off+7];
            uint16_t rdlen = (resp[off+8] << 8) | resp[off+9];
            off += 10;
            if (off + rdlen > rlen) break;

            printf("  %s %u ", owner[0] ? owner : ".", ttl);

            const char *tn = type_to_str(rtype);
            if (tn) printf("%s ", tn);
            else printf("TYPE%u ", rtype);

            uint8_t *rd = resp + off;

            if (rtype == 1) {
                if (rdlen >= 4)
                    printf("%d.%d.%d.%d", rd[0], rd[1], rd[2], rd[3]);
            } else if (rtype == 28) {
                if (rdlen >= 16) {
                    char abuf[64];
                    fmt_aaaa(rd, abuf);
                    printf("%s", abuf);
                }
            } else if (rtype == 5) {
                char target[MAX_NAME];
                parse_name(resp, rlen, off, target, sizeof(target));
                printf("%s", target[0] ? target : ".");
            } else if (rtype == 15) {
                if (rdlen >= 2) {
                    uint16_t pref = (rd[0] << 8) | rd[1];
                    char exch[MAX_NAME];
                    parse_name(resp, rlen, off + 2, exch, sizeof(exch));
                    printf("%u %s", pref, exch[0] ? exch : ".");
                }
            } else if (rtype == 16) {
                int pos = 0, first = 1;
                while (pos < rdlen) {
                    int sl = rd[pos++];
                    if (pos + sl > rdlen) break;
                    if (!first) printf(" ");
                    first = 0;
                    printf("\"");
                    for (int j = 0; j < sl; j++) {
                        uint8_t c = rd[pos + j];
                        if (c == '"' || c == '\\') printf("\\%c", c);
                        else if (c >= 0x20 && c <= 0x7E) printf("%c", c);
                        else printf("\\%03d", c);
                    }
                    printf("\"");
                    pos += sl;
                }
            } else {
                printf("\\# %u", rdlen);
                if (rdlen > 0) {
                    printf(" ");
                    for (int j = 0; j < rdlen; j++)
                        printf("%02x", rd[j]);
                }
            }
            printf("\n");
            off += rdlen;
        }
    }

    fclose(f);
    return 0;
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static Object rootSchema;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String schemaStr = new String(Files.readAllBytes(Path.of(dir, "schema.json")), StandardCharsets.UTF_8);
        String instancesStr = new String(Files.readAllBytes(Path.of(dir, "instances.json")), StandardCharsets.UTF_8);

        rootSchema = new JsonParser(schemaStr).parse();
        @SuppressWarnings("unchecked")
        List<Object> instances = (List<Object>) new JsonParser(instancesStr).parse();

        int validCount = 0, invalidCount = 0;

        for (int i = 0; i < instances.size(); i++) {
            Set<String> errors = new HashSet<>();
            validate(instances.get(i), rootSchema, "#", "#", errors);

            if (errors.isEmpty()) {
                System.out.println(i + ": valid");
                validCount++;
            } else {
                List<String> sorted = new ArrayList<>(errors);
                sorted.sort((a, b) -> {
                    String[] pa = a.split("\t", 2);
                    String[] pb = b.split("\t", 2);
                    int cmp = compareUtf8(pa[0], pb[0]);
                    if (cmp != 0) return cmp;
                    return compareUtf8(pa[1], pb[1]);
                });
                System.out.println(i + ": invalid (" + sorted.size() + ")");
                for (String e : sorted) {
                    String[] parts = e.split("\t", 2);
                    System.out.println("  " + parts[0] + " " + parts[1]);
                }
                invalidCount++;
            }
        }
        System.out.println("valid=" + validCount + " invalid=" + invalidCount);
    }

    static int compareUtf8(String a, String b) {
        byte[] ba = a.getBytes(StandardCharsets.UTF_8);
        byte[] bb = b.getBytes(StandardCharsets.UTF_8);
        int len = Math.min(ba.length, bb.length);
        for (int i = 0; i < len; i++) {
            int diff = (ba[i] & 0xFF) - (bb[i] & 0xFF);
            if (diff != 0) return diff;
        }
        return ba.length - bb.length;
    }

    @SuppressWarnings("unchecked")
    static void validate(Object instance, Object schema, String instanceLoc, String schemaLoc, Set<String> errors) {
        if (schema instanceof Boolean) {
            if (!(Boolean) schema) {
                errors.add(instanceLoc + "\t" + schemaLoc);
            }
            return;
        }

        Map<String, Object> s = (Map<String, Object>) schema;

        // type
        if (s.containsKey("type")) {
            if (!checkType(instance, s.get("type"))) {
                errors.add(instanceLoc + "\t" + schemaLoc + "/type");
            }
        }

        // enum
        if (s.containsKey("enum")) {
            List<Object> enumVals = (List<Object>) s.get("enum");
            boolean found = false;
            for (Object ev : enumVals) {
                if (deepEqual(instance, ev)) { found = true; break; }
            }
            if (!found) errors.add(instanceLoc + "\t" + schemaLoc + "/enum");
        }

        // const
        if (s.containsKey("const")) {
            if (!deepEqual(instance, s.get("const"))) {
                errors.add(instanceLoc + "\t" + schemaLoc + "/const");
            }
        }

        // Number keywords
        if (instance instanceof Double) {
            double val = (Double) instance;
            if (s.containsKey("minimum") && val < toDouble(s.get("minimum")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/minimum");
            if (s.containsKey("maximum") && val > toDouble(s.get("maximum")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/maximum");
            if (s.containsKey("exclusiveMinimum") && val <= toDouble(s.get("exclusiveMinimum")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/exclusiveMinimum");
            if (s.containsKey("exclusiveMaximum") && val >= toDouble(s.get("exclusiveMaximum")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/exclusiveMaximum");
        }

        // String keywords
        if (instance instanceof String) {
            String str = (String) instance;
            int len = str.codePointCount(0, str.length());
            if (s.containsKey("minLength") && len < toInt(s.get("minLength")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/minLength");
            if (s.containsKey("maxLength") && len > toInt(s.get("maxLength")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/maxLength");
        }

        // Array keywords
        if (instance instanceof List) {
            List<Object> arr = (List<Object>) instance;
            if (s.containsKey("minItems") && arr.size() < toInt(s.get("minItems")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/minItems");
            if (s.containsKey("maxItems") && arr.size() > toInt(s.get("maxItems")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/maxItems");
            if (s.containsKey("uniqueItems") && Boolean.TRUE.equals(s.get("uniqueItems"))) {
                boolean unique = true;
                outer:
                for (int i = 0; i < arr.size(); i++) {
                    for (int j = i + 1; j < arr.size(); j++) {
                        if (deepEqual(arr.get(i), arr.get(j))) { unique = false; break outer; }
                    }
                }
                if (!unique) errors.add(instanceLoc + "\t" + schemaLoc + "/uniqueItems");
            }

            int prefixLen = 0;
            if (s.containsKey("prefixItems")) {
                List<Object> prefix = (List<Object>) s.get("prefixItems");
                prefixLen = prefix.size();
                for (int i = 0; i < Math.min(prefixLen, arr.size()); i++) {
                    validate(arr.get(i), prefix.get(i),
                        instanceLoc + "/" + i,
                        schemaLoc + "/prefixItems/" + i, errors);
                }
            }

            if (s.containsKey("items")) {
                Object itemsSchema = s.get("items");
                for (int i = prefixLen; i < arr.size(); i++) {
                    validate(arr.get(i), itemsSchema,
                        instanceLoc + "/" + i,
                        schemaLoc + "/items", errors);
                }
            }
        }

        // Object keywords
        if (instance instanceof Map) {
            Map<String, Object> obj = (Map<String, Object>) instance;

            if (s.containsKey("minProperties") && obj.size() < toInt(s.get("minProperties")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/minProperties");
            if (s.containsKey("maxProperties") && obj.size() > toInt(s.get("maxProperties")))
                errors.add(instanceLoc + "\t" + schemaLoc + "/maxProperties");

            if (s.containsKey("required")) {
                List<Object> req = (List<Object>) s.get("required");
                for (int j = 0; j < req.size(); j++) {
                    String name = (String) req.get(j);
                    if (!obj.containsKey(name)) {
                        errors.add(instanceLoc + "\t" + schemaLoc + "/required/" + j);
                    }
                }
            }

            Set<String> propNames = new HashSet<>();
            if (s.containsKey("properties")) {
                Map<String, Object> props = (Map<String, Object>) s.get("properties");
                propNames.addAll(props.keySet());
                for (Map.Entry<String, Object> e : props.entrySet()) {
                    if (obj.containsKey(e.getKey())) {
                        validate(obj.get(e.getKey()), e.getValue(),
                            instanceLoc + "/" + escapeToken(e.getKey()),
                            schemaLoc + "/properties/" + escapeToken(e.getKey()), errors);
                    }
                }
            }

            if (s.containsKey("additionalProperties")) {
                Object addSchema = s.get("additionalProperties");
                for (Map.Entry<String, Object> e : obj.entrySet()) {
                    if (!propNames.contains(e.getKey())) {
                        validate(e.getValue(), addSchema,
                            instanceLoc + "/" + escapeToken(e.getKey()),
                            schemaLoc + "/additionalProperties", errors);
                    }
                }
            }
        }

        // Applicators
        if (s.containsKey("allOf")) {
            List<Object> allOf = (List<Object>) s.get("allOf");
            for (int i = 0; i < allOf.size(); i++) {
                validate(instance, allOf.get(i), instanceLoc,
                    schemaLoc + "/allOf/" + i, errors);
            }
        }

        if (s.containsKey("anyOf")) {
            List<Object> anyOf = (List<Object>) s.get("anyOf");
            boolean anyAccepted = false;
            for (Object sub : anyOf) {
                Set<String> temp = new HashSet<>();
                validate(instance, sub, instanceLoc, "", temp);
                if (temp.isEmpty()) { anyAccepted = true; break; }
            }
            if (!anyAccepted) {
                errors.add(instanceLoc + "\t" + schemaLoc + "/anyOf");
            }
        }

        if (s.containsKey("oneOf")) {
            List<Object> oneOf = (List<Object>) s.get("oneOf");
            int count = 0;
            for (Object sub : oneOf) {
                Set<String> temp = new HashSet<>();
                validate(instance, sub, instanceLoc, "", temp);
                if (temp.isEmpty()) { count++; if (count > 1) break; }
            }
            if (count != 1) {
                errors.add(instanceLoc + "\t" + schemaLoc + "/oneOf");
            }
        }

        if (s.containsKey("not")) {
            Set<String> temp = new HashSet<>();
            validate(instance, s.get("not"), instanceLoc, "", temp);
            if (temp.isEmpty()) {
                errors.add(instanceLoc + "\t" + schemaLoc + "/not");
            }
        }

        if (s.containsKey("if")) {
            Set<String> temp = new HashSet<>();
            validate(instance, s.get("if"), instanceLoc, "", temp);
            if (temp.isEmpty()) {
                if (s.containsKey("then")) {
                    validate(instance, s.get("then"), instanceLoc, schemaLoc + "/then", errors);
                }
            } else {
                if (s.containsKey("else")) {
                    validate(instance, s.get("else"), instanceLoc, schemaLoc + "/else", errors);
                }
            }
        }

        // $ref
        if (s.containsKey("$ref")) {
            String ref = (String) s.get("$ref");
            Object target = resolveRef(ref);
            validate(instance, target, instanceLoc, ref, errors);
        }
    }

    @SuppressWarnings("unchecked")
    static Object resolveRef(String ref) {
        if (ref.equals("#")) return rootSchema;
        String encodedName = ref.substring("#/$defs/".length());
        String name = decodePointerToken(encodedName);
        Map<String, Object> defs = (Map<String, Object>) ((Map<String, Object>) rootSchema).get("$defs");
        return defs.get(name);
    }

    static String decodePointerToken(String token) {
        return token.replace("~1", "/").replace("~0", "~");
    }

    static String escapeToken(String token) {
        return token.replace("~", "~0").replace("/", "~1");
    }

    @SuppressWarnings("unchecked")
    static boolean checkType(Object instance, Object typeVal) {
        if (typeVal instanceof String) {
            return matchesType(instance, (String) typeVal);
        }
        List<Object> types = (List<Object>) typeVal;
        for (Object t : types) {
            if (matchesType(instance, (String) t)) return true;
        }
        return false;
    }

    static boolean matchesType(Object instance, String type) {
        switch (type) {
            case "null": return instance == null;
            case "boolean": return instance instanceof Boolean;
            case "number": return instance instanceof Double;
            case "string": return instance instanceof String;
            case "array": return instance instanceof List;
            case "object": return instance instanceof Map;
            case "integer": return instance instanceof Double && isInteger((Double) instance);
        }
        return false;
    }

    static boolean isInteger(double d) {
        return d == Math.floor(d);
    }

    static double toDouble(Object o) { return (Double) o; }
    static int toInt(Object o) { return (int) (double) (Double) o; }

    static boolean deepEqual(Object a, Object b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        if (a instanceof Boolean && b instanceof Boolean) return a.equals(b);
        if (a instanceof Double && b instanceof Double) return ((Double) a).doubleValue() == ((Double) b).doubleValue();
        if (a instanceof String && b instanceof String) return a.equals(b);
        if (a instanceof List && b instanceof List) {
            List<?> la = (List<?>) a, lb = (List<?>) b;
            if (la.size() != lb.size()) return false;
            for (int i = 0; i < la.size(); i++)
                if (!deepEqual(la.get(i), lb.get(i))) return false;
            return true;
        }
        if (a instanceof Map && b instanceof Map) {
            Map<?, ?> ma = (Map<?, ?>) a, mb = (Map<?, ?>) b;
            if (ma.size() != mb.size()) return false;
            for (Map.Entry<?, ?> e : ma.entrySet()) {
                if (!mb.containsKey(e.getKey())) return false;
                if (!deepEqual(e.getValue(), mb.get(e.getKey()))) return false;
            }
            return true;
        }
        return false;
    }

    // JSON Parser
    static class JsonParser {
        String input;
        int pos;

        JsonParser(String input) { this.input = input; pos = 0; }

        Object parse() {
            skipWhitespace();
            Object val = parseValue();
            skipWhitespace();
            return val;
        }

        void skipWhitespace() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        Object parseValue() {
            skipWhitespace();
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') { pos += 4; return Boolean.TRUE; }
            if (c == 'f') { pos += 5; return Boolean.FALSE; }
            if (c == 'n') { pos += 4; return null; }
            return parseNumber();
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // skip {
            skipWhitespace();
            if (input.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                pos++; // skip :
                Object val = parseValue();
                map.put(key, val);
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') { pos++; }
                else break;
            }
            pos++; // skip }
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // skip [
            skipWhitespace();
            if (input.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                list.add(parseValue());
                skipWhitespace();
                if (pos < input.length() && input.charAt(pos) == ',') { pos++; }
                else break;
            }
            pos++; // skip ]
            return list;
        }

        String parseString() {
            pos++; // skip opening "
            StringBuilder sb = new StringBuilder();
            while (input.charAt(pos) != '"') {
                char c = input.charAt(pos);
                if (c == '\\') {
                    pos++;
                    char esc = input.charAt(pos);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            int cp = Integer.parseInt(input.substring(pos + 1, pos + 5), 16);
                            pos += 4;
                            sb.append((char) cp);
                            break;
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            pos++; // skip closing "
            return sb.toString();
        }

        Double parseNumber() {
            int start = pos;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            while (pos < input.length() && Character.isDigit(input.charAt(pos))) pos++;
            if (pos < input.length() && input.charAt(pos) == '.') {
                pos++;
                while (pos < input.length() && Character.isDigit(input.charAt(pos))) pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                while (pos < input.length() && Character.isDigit(input.charAt(pos))) pos++;
            }
            return Double.parseDouble(input.substring(start, pos));
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

function main() {
    const dir = process.argv[2];
    const schema = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf-8'));
    const instances = JSON.parse(fs.readFileSync(path.join(dir, 'instances.json'), 'utf-8'));

    const results: string[] = [];
    let validCount = 0;
    let invalidCount = 0;

    for (let i = 0; i < instances.length; i++) {
        const errors = validate(instances[i], schema, '#', '#', schema);
        if (errors.size === 0) {
            results.push(`${i}: valid`);
            validCount++;
        } else {
            const sorted = [...errors].sort((a, b) => {
                const tabA = a.indexOf('\t');
                const tabB = b.indexOf('\t');
                const ia = a.substring(0, tabA);
                const sa = a.substring(tabA + 1);
                const ib = b.substring(0, tabB);
                const sb = b.substring(tabB + 1);
                const c = compareCodePoints(ia, ib);
                if (c !== 0) return c;
                return compareCodePoints(sa, sb);
            });
            results.push(`${i}: invalid (${sorted.length})`);
            for (const e of sorted) {
                const tabIdx = e.indexOf('\t');
                results.push(`  ${e.substring(0, tabIdx)} ${e.substring(tabIdx + 1)}`);
            }
            invalidCount++;
        }
    }

    results.push(`valid=${validCount} invalid=${invalidCount}`);
    process.stdout.write(results.join('\n') + '\n');
}

function compareCodePoints(a: string, b: string): number {
    let i = 0, j = 0;
    while (i < a.length && j < b.length) {
        const ca = a.codePointAt(i)!;
        const cb = b.codePointAt(j)!;
        if (ca !== cb) return ca < cb ? -1 : 1;
        i += ca > 0xFFFF ? 2 : 1;
        j += cb > 0xFFFF ? 2 : 1;
    }
    if (i < a.length) return 1;
    if (j < b.length) return -1;
    return 0;
}

function validate(instance: any, schema: any, instancePath: string, schemaPath: string, rootSchema: any): Set<string> {
    const errors = new Set<string>();

    if (schema === true) return errors;
    if (schema === false) {
        errors.add(`${instancePath}\t${schemaPath}`);
        return errors;
    }

    const instanceType = getType(instance);

    // type
    if ('type' in schema) {
        const types: string[] = Array.isArray(schema.type) ? schema.type : [schema.type];
        let matched = false;
        for (const t of types) {
            if (t === 'integer') {
                if (instanceType === 'number' && Number.isInteger(instance)) { matched = true; break; }
            } else if (t === instanceType) {
                matched = true; break;
            }
        }
        if (!matched) {
            errors.add(`${instancePath}\t${schemaPath}/type`);
        }
    }

    // enum
    if ('enum' in schema) {
        let found = false;
        for (const v of schema.enum) {
            if (deepEqual(instance, v)) { found = true; break; }
        }
        if (!found) {
            errors.add(`${instancePath}\t${schemaPath}/enum`);
        }
    }

    // const
    if ('const' in schema) {
        if (!deepEqual(instance, schema.const)) {
            errors.add(`${instancePath}\t${schemaPath}/const`);
        }
    }

    // Number keywords
    if (instanceType === 'number') {
        if ('minimum' in schema && instance < schema.minimum) {
            errors.add(`${instancePath}\t${schemaPath}/minimum`);
        }
        if ('maximum' in schema && instance > schema.maximum) {
            errors.add(`${instancePath}\t${schemaPath}/maximum`);
        }
        if ('exclusiveMinimum' in schema && instance <= schema.exclusiveMinimum) {
            errors.add(`${instancePath}\t${schemaPath}/exclusiveMinimum`);
        }
        if ('exclusiveMaximum' in schema && instance >= schema.exclusiveMaximum) {
            errors.add(`${instancePath}\t${schemaPath}/exclusiveMaximum`);
        }
    }

    // String keywords
    if (instanceType === 'string') {
        const len = stringLength(instance);
        if ('minLength' in schema && len < schema.minLength) {
            errors.add(`${instancePath}\t${schemaPath}/minLength`);
        }
        if ('maxLength' in schema && len > schema.maxLength) {
            errors.add(`${instancePath}\t${schemaPath}/maxLength`);
        }
    }

    // Array keywords
    if (instanceType === 'array') {
        if ('minItems' in schema && instance.length < schema.minItems) {
            errors.add(`${instancePath}\t${schemaPath}/minItems`);
        }
        if ('maxItems' in schema && instance.length > schema.maxItems) {
            errors.add(`${instancePath}\t${schemaPath}/maxItems`);
        }
        if (schema.uniqueItems === true) {
            let hasDup = false;
            for (let i = 0; i < instance.length && !hasDup; i++) {
                for (let j = i + 1; j < instance.length && !hasDup; j++) {
                    if (deepEqual(instance[i], instance[j])) hasDup = true;
                }
            }
            if (hasDup) {
                errors.add(`${instancePath}\t${schemaPath}/uniqueItems`);
            }
        }

        let prefixLen = 0;
        if ('prefixItems' in schema) {
            prefixLen = schema.prefixItems.length;
            for (let i = 0; i < Math.min(instance.length, schema.prefixItems.length); i++) {
                const subErrors = validate(instance[i], schema.prefixItems[i],
                    `${instancePath}/${i}`, `${schemaPath}/prefixItems/${i}`, rootSchema);
                for (const e of subErrors) errors.add(e);
            }
        }

        if ('items' in schema) {
            for (let i = prefixLen; i < instance.length; i++) {
                const subErrors = validate(instance[i], schema.items,
                    `${instancePath}/${i}`, `${schemaPath}/items`, rootSchema);
                for (const e of subErrors) errors.add(e);
            }
        }
    }

    // Object keywords
    if (instanceType === 'object') {
        const keys = Object.keys(instance);

        if ('minProperties' in schema && keys.length < schema.minProperties) {
            errors.add(`${instancePath}\t${schemaPath}/minProperties`);
        }
        if ('maxProperties' in schema && keys.length > schema.maxProperties) {
            errors.add(`${instancePath}\t${schemaPath}/maxProperties`);
        }

        const propKeys = new Set<string>();
        if ('properties' in schema) {
            for (const key of Object.keys(schema.properties)) {
                propKeys.add(key);
                if (Object.prototype.hasOwnProperty.call(instance, key)) {
                    const subErrors = validate(instance[key], schema.properties[key],
                        `${instancePath}/${escapePointer(key)}`, `${schemaPath}/properties/${escapePointer(key)}`, rootSchema);
                    for (const e of subErrors) errors.add(e);
                }
            }
        }

        if ('required' in schema) {
            for (let j = 0; j < schema.required.length; j++) {
                if (!Object.prototype.hasOwnProperty.call(instance, schema.required[j])) {
                    errors.add(`${instancePath}\t${schemaPath}/required/${j}`);
                }
            }
        }

        if ('additionalProperties' in schema) {
            for (const key of keys) {
                if (!propKeys.has(key)) {
                    const subErrors = validate(instance[key], schema.additionalProperties,
                        `${instancePath}/${escapePointer(key)}`, `${schemaPath}/additionalProperties`, rootSchema);
                    for (const e of subErrors) errors.add(e);
                }
            }
        }
    }

    // Applicators
    if ('allOf' in schema) {
        for (let i = 0; i < schema.allOf.length; i++) {
            const subErrors = validate(instance, schema.allOf[i],
                instancePath, `${schemaPath}/allOf/${i}`, rootSchema);
            for (const e of subErrors) errors.add(e);
        }
    }

    if ('anyOf' in schema) {
        let anyValid = false;
        for (let i = 0; i < schema.anyOf.length; i++) {
            const subErrors = validate(instance, schema.anyOf[i],
                instancePath, `${schemaPath}/anyOf/${i}`, rootSchema);
            if (subErrors.size === 0) { anyValid = true; break; }
        }
        if (!anyValid) {
            errors.add(`${instancePath}\t${schemaPath}/anyOf`);
        }
    }

    if ('oneOf' in schema) {
        let count = 0;
        for (let i = 0; i < schema.oneOf.length; i++) {
            const subErrors = validate(instance, schema.oneOf[i],
                instancePath, `${schemaPath}/oneOf/${i}`, rootSchema);
            if (subErrors.size === 0) count++;
        }
        if (count !== 1) {
            errors.add(`${instancePath}\t${schemaPath}/oneOf`);
        }
    }

    if ('not' in schema) {
        const subErrors = validate(instance, schema.not,
            instancePath, `${schemaPath}/not`, rootSchema);
        if (subErrors.size === 0) {
            errors.add(`${instancePath}\t${schemaPath}/not`);
        }
    }

    if ('if' in schema) {
        const ifErrors = validate(instance, schema.if,
            instancePath, `${schemaPath}/if`, rootSchema);
        if (ifErrors.size === 0) {
            if ('then' in schema) {
                const subErrors = validate(instance, schema.then,
                    instancePath, `${schemaPath}/then`, rootSchema);
                for (const e of subErrors) errors.add(e);
            }
        } else {
            if ('else' in schema) {
                const subErrors = validate(instance, schema.else,
                    instancePath, `${schemaPath}/else`, rootSchema);
                for (const e of subErrors) errors.add(e);
            }
        }
    }

    // $ref
    if ('$ref' in schema) {
        const [refSchema, refPath] = resolveRef(schema.$ref, rootSchema);
        const subErrors = validate(instance, refSchema, instancePath, refPath, rootSchema);
        for (const e of subErrors) errors.add(e);
    }

    return errors;
}

function getType(value: any): string {
    if (value === null) return 'null';
    if (Array.isArray(value)) return 'array';
    if (typeof value === 'boolean') return 'boolean';
    if (typeof value === 'number') return 'number';
    if (typeof value === 'string') return 'string';
    if (typeof value === 'object') return 'object';
    return 'unknown';
}

function stringLength(s: string): number {
    let count = 0;
    for (const _ of s) count++;
    return count;
}

function deepEqual(a: any, b: any): boolean {
    const ta = getType(a);
    const tb = getType(b);
    if (ta !== tb) return false;

    switch (ta) {
        case 'null': return true;
        case 'boolean': return a === b;
        case 'number': return a === b;
        case 'string': return a === b;
        case 'array':
            if (a.length !== b.length) return false;
            for (let i = 0; i < a.length; i++) {
                if (!deepEqual(a[i], b[i])) return false;
            }
            return true;
        case 'object': {
            const ka = Object.keys(a).sort();
            const kb = Object.keys(b).sort();
            if (ka.length !== kb.length) return false;
            for (let i = 0; i < ka.length; i++) {
                if (ka[i] !== kb[i]) return false;
                if (!deepEqual(a[ka[i]], b[ka[i]])) return false;
            }
            return true;
        }
    }
    return false;
}

function escapePointer(s: string): string {
    return s.replace(/~/g, '~0').replace(/\//g, '~1');
}

function resolveRef(ref: string, rootSchema: any): [any, string] {
    if (ref === '#') return [rootSchema, '#'];
    const prefix = '#/$defs/';
    if (ref.startsWith(prefix)) {
        const encodedName = ref.slice(prefix.length);
        const name = decodePointerToken(encodedName);
        return [rootSchema.$defs[name], ref];
    }
    throw new Error(`Unknown $ref: ${ref}`);
}

function decodePointerToken(token: string): string {
    return token.replace(/~1/g, '/').replace(/~0/g, '~');
}

main();

import sys
import json
import base64
import hmac
import hashlib
import os


def is_valid_base64url(s):
    if not s:
        return False
    for c in s:
        if c not in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_":
            return False
    if len(s) % 4 == 1:
        return False
    return True


def b64url_decode(s):
    padding = 4 - len(s) % 4
    if padding != 4:
        s += "=" * padding
    return base64.urlsafe_b64decode(s)


def check_token(token, keys, now, leeway, issuer, audience):
    # Rule 1: MALFORMED
    parts = token.split(".")
    if len(parts) != 3:
        return "MALFORMED"

    header_seg, payload_seg, sig_seg = parts

    for seg in parts:
        if not is_valid_base64url(seg):
            return "MALFORMED"

    try:
        header_bytes = b64url_decode(header_seg)
        payload_bytes = b64url_decode(payload_seg)
    except Exception:
        return "MALFORMED"

    try:
        header = json.loads(header_bytes.decode("utf-8"))
    except Exception:
        return "MALFORMED"
    if not isinstance(header, dict):
        return "MALFORMED"

    try:
        payload = json.loads(payload_bytes.decode("utf-8"))
    except Exception:
        return "MALFORMED"
    if not isinstance(payload, dict):
        return "MALFORMED"

    # Rule 2: UNSUPPORTED_ALG
    alg = header.get("alg")
    if not isinstance(alg, str) or alg not in ("HS256", "HS384", "HS512"):
        return "UNSUPPORTED_ALG"

    # Rule 3: UNKNOWN_KEY
    kid = header.get("kid")
    if not isinstance(kid, str) or kid not in keys:
        return "UNKNOWN_KEY"

    key = keys[kid]

    # Rule 4: ALG_MISMATCH
    if key["alg"] != alg:
        return "ALG_MISMATCH"

    # Rule 5: BAD_SIGNATURE
    try:
        secret = b64url_decode(key["k"])
        sig_bytes = b64url_decode(sig_seg)
    except Exception:
        return "BAD_SIGNATURE"

    signing_input = (header_seg + "." + payload_seg).encode("ascii")
    hash_func = {"HS256": hashlib.sha256, "HS384": hashlib.sha384, "HS512": hashlib.sha512}[alg]
    expected_sig = hmac.new(secret, signing_input, hash_func).digest()

    if sig_bytes != expected_sig:
        return "BAD_SIGNATURE"

    # Rule 6: EXPIRED
    if "exp" in payload:
        exp = payload["exp"]
        if now >= exp + leeway:
            return "EXPIRED"

    # Rule 7: NOT_YET_VALID
    if "nbf" in payload:
        nbf = payload["nbf"]
        if now + leeway < nbf:
            return "NOT_YET_VALID"

    # Rule 8: BAD_ISSUER
    iss = payload.get("iss")
    if not isinstance(iss, str) or iss != issuer:
        return "BAD_ISSUER"

    # Rule 9: BAD_AUDIENCE
    aud = payload.get("aud")
    if isinstance(aud, str):
        if aud != audience:
            return "BAD_AUDIENCE"
    elif isinstance(aud, list):
        if audience not in aud:
            return "BAD_AUDIENCE"
    else:
        return "BAD_AUDIENCE"

    # VALID
    sub = payload["sub"]
    scope = payload.get("scope", "")
    if isinstance(scope, str):
        scopes = sorted(set(s for s in scope.split(" ") if s))
    else:
        scopes = []
    scopes_str = ",".join(scopes)

    return f"VALID sub={sub} scope={scopes_str}"


def main():
    directory = sys.argv[1]

    with open(os.path.join(directory, "config.json"), "r", encoding="utf-8") as f:
        config = json.load(f)

    now = config["now"]
    leeway = config["leeway"]
    issuer = config["issuer"]
    audience = config["audience"]
    keys = {k["kid"]: k for k in config["keys"]}

    with open(os.path.join(directory, "tokens.txt"), "r", encoding="utf-8") as f:
        content = f.read()

    lines = content.split("\n")

    tokens = []
    for line in lines:
        trimmed = line.strip(" \t")
        if trimmed:
            tokens.append(trimmed)

    valid_count = 0
    invalid_count = 0
    results = []

    for n, token in enumerate(tokens, 1):
        result = check_token(token, keys, now, leeway, issuer, audience)
        if result.startswith("VALID"):
            valid_count += 1
        else:
            invalid_count += 1
        results.append((n, result))

    for n, result in results:
        print(f"{n}: {result}")

    print()
    print(f"valid={valid_count} invalid={invalid_count}")


if __name__ == "__main__":
    main()

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>

/* ============== JSON Value ============== */
typedef enum { JNULL, JBOOL, JNUM, JSTR, JARR, JOBJ } JType;

typedef struct JV {
    JType type;
    union {
        int bval;
        double nval;
        char *sval;
        struct { struct JV **items; int n; } arr;
        struct { char **keys; struct JV **vals; int n; } obj;
    };
} JV;

/* ============== Parser ============== */
static const char *inp;
static int ipos;

static void skip_ws(void) {
    while (inp[ipos]==' '||inp[ipos]=='\t'||inp[ipos]=='\n'||inp[ipos]=='\r') ipos++;
}

static JV *parse_value(void);

static unsigned int parse_hex4(void) {
    unsigned int v=0;
    for(int i=0;i<4;i++){
        char c=inp[ipos++]; v<<=4;
        if(c>='0'&&c<='9')v|=c-'0';
        else if(c>='a'&&c<='f')v|=c-'a'+10;
        else if(c>='A'&&c<='F')v|=c-'A'+10;
    }
    return v;
}

static char *parse_string(void) {
    int cap=64,len=0;
    char *buf=malloc(cap);
    while(inp[ipos]!='"'){
        if(len+4>=cap){cap*=2;buf=realloc(buf,cap);}
        if(inp[ipos]=='\\'){
            ipos++;
            switch(inp[ipos++]){
                case '"':buf[len++]='"';break;
                case '\\':buf[len++]='\\';break;
                case '/':buf[len++]='/';break;
                case 'b':buf[len++]='\b';break;
                case 'f':buf[len++]='\f';break;
                case 'n':buf[len++]='\n';break;
                case 'r':buf[len++]='\r';break;
                case 't':buf[len++]='\t';break;
                case 'u':{
                    unsigned int cp=parse_hex4();
                    if(cp>=0xD800&&cp<=0xDBFF){
                        ipos+=2;
                        unsigned int lo=parse_hex4();
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    if(cp<0x80){buf[len++]=cp;}
                    else if(cp<0x800){buf[len++]=0xC0|(cp>>6);buf[len++]=0x80|(cp&0x3F);}
                    else if(cp<0x10000){buf[len++]=0xE0|(cp>>12);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    else{buf[len++]=0xF0|(cp>>18);buf[len++]=0x80|((cp>>12)&0x3F);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    break;
                }
            }
        } else {
            buf[len++]=inp[ipos++];
        }
    }
    ipos++;
    buf[len]='\0';
    return buf;
}

static JV *new_jv(JType t){JV*v=calloc(1,sizeof(JV));v->type=t;return v;}

static JV *parse_value(void){
    skip_ws();
    char c=inp[ipos];
    if(c=='"'){ipos++;JV*v=new_jv(JSTR);v->sval=parse_string();return v;}
    if(c=='{'){
        ipos++;JV*v=new_jv(JOBJ);
        int cap=8;v->obj.keys=malloc(cap*sizeof(char*));v->obj.vals=malloc(cap*sizeof(JV*));v->obj.n=0;
        skip_ws();
        if(inp[ipos]=='}'){ipos++;return v;}
        while(1){
            skip_ws();ipos++;
            char *key=parse_string();
            skip_ws();ipos++;
            JV *val=parse_value();
            if(v->obj.n>=cap){cap*=2;v->obj.keys=realloc(v->obj.keys,cap*sizeof(char*));v->obj.vals=realloc(v->obj.vals,cap*sizeof(JV*));}
            v->obj.keys[v->obj.n]=key;v->obj.vals[v->obj.n]=val;v->obj.n++;
            skip_ws();
            if(inp[ipos]==','){ipos++;continue;}
            ipos++;break;
        }
        return v;
    }
    if(c=='['){
        ipos++;JV*v=new_jv(JARR);
        int cap=8;v->arr.items=malloc(cap*sizeof(JV*));v->arr.n=0;
        skip_ws();
        if(inp[ipos]==']'){ipos++;return v;}
        while(1){
            JV *item=parse_value();
            if(v->arr.n>=cap){cap*=2;v->arr.items=realloc(v->arr.items,cap*sizeof(JV*));}
            v->arr.items[v->arr.n++]=item;
            skip_ws();
            if(inp[ipos]==','){ipos++;continue;}
            ipos++;break;
        }
        return v;
    }
    if(c=='t'){ipos+=4;JV*v=new_jv(JBOOL);v->bval=1;return v;}
    if(c=='f'){ipos+=5;JV*v=new_jv(JBOOL);v->bval=0;return v;}
    if(c=='n'){ipos+=4;return new_jv(JNULL);}
    /* number */
    int start=ipos;
    while(inp[ipos]&&inp[ipos]!=','&&inp[ipos]!='}'&&inp[ipos]!=']'&&inp[ipos]!=' '&&inp[ipos]!='\t'&&inp[ipos]!='\n'&&inp[ipos]!='\r')ipos++;
    int len=ipos-start;
    char *tmp=malloc(len+1);memcpy(tmp,inp+start,len);tmp[len]='\0';
    JV*v=new_jv(JNUM);v->nval=strtod(tmp,NULL);free(tmp);
    return v;
}

static JV *parse_json(const char *s){inp=s;ipos=0;return parse_value();}

/* ============== Utilities ============== */
static JV *obj_get(JV *obj,const char *key){
    if(!obj||obj->type!=JOBJ)return NULL;
    for(int i=0;i<obj->obj.n;i++)
        if(strcmp(obj->obj.keys[i],key)==0)return obj->obj.vals[i];
    return NULL;
}

static int str_cp_len(const char *s){
    int len=0;while(*s){if((*s&0xC0)!=0x80)len++;s++;}return len;
}

static int deep_eq(JV *a,JV *b){
    if(a->type!=b->type)return 0;
    switch(a->type){
        case JNULL:return 1;
        case JBOOL:return a->bval==b->bval;
        case JNUM:return a->nval==b->nval;
        case JSTR:return strcmp(a->sval,b->sval)==0;
        case JARR:
            if(a->arr.n!=b->arr.n)return 0;
            for(int i=0;i<a->arr.n;i++)if(!deep_eq(a->arr.items[i],b->arr.items[i]))return 0;
            return 1;
        case JOBJ:
            if(a->obj.n!=b->obj.n)return 0;
            for(int i=0;i<a->obj.n;i++){
                JV *bv=obj_get(b,a->obj.keys[i]);
                if(!bv||!deep_eq(a->obj.vals[i],bv))return 0;
            }
            return 1;
    }
    return 0;
}

static int is_int(double d){return d==floor(d);}

static int type_matches(JV *inst,const char *tname){
    if(strcmp(tname,"null")==0)return inst->type==JNULL;
    if(strcmp(tname,"boolean")==0)return inst->type==JBOOL;
    if(strcmp(tname,"number")==0)return inst->type==JNUM;
    if(strcmp(tname,"string")==0)return inst->type==JSTR;
    if(strcmp(tname,"array")==0)return inst->type==JARR;
    if(strcmp(tname,"object")==0)return inst->type==JOBJ;
    if(strcmp(tname,"integer")==0)return inst->type==JNUM&&is_int(inst->nval);
    return 0;
}

/* ============== Pointer building ============== */
static char *esc_token(const char *s){
    int len=0;
    for(const char *p=s;*p;p++)len+=(*p=='~'||*p=='/')?2:1;
    char *out=malloc(len+1);int j=0;
    for(const char *p=s;*p;p++){
        if(*p=='~'){out[j++]='~';out[j++]='0';}
        else if(*p=='/'){out[j++]='~';out[j++]='1';}
        else out[j++]=*p;
    }
    out[j]='\0';return out;
}

static char *append_ptr(const char *base,const char *token){
    char *et=esc_token(token);
    int blen=strlen(base),tlen=strlen(et);
    char *out=malloc(blen+1+tlen+1);
    memcpy(out,base,blen);out[blen]='/';memcpy(out+blen+1,et,tlen+1);
    free(et);return out;
}

static char *append_ptr_int(const char *base,int idx){
    char num[32];sprintf(num,"%d",idx);
    return append_ptr(base,num);
}

/* ============== Error Set ============== */
typedef struct{char*inst;char*sch;}Err;
typedef struct{Err*data;int n,cap;}ErrSet;

static void errset_init(ErrSet*es){es->data=NULL;es->n=0;es->cap=0;}
static void errset_add(ErrSet*es,const char*inst,const char*sch){
    if(es->n>=es->cap){es->cap=es->cap?es->cap*2:16;es->data=realloc(es->data,es->cap*sizeof(Err));}
    es->data[es->n].inst=strdup(inst);es->data[es->n].sch=strdup(sch);es->n++;
}
static int err_cmp(const void*a,const void*b){
    Err*ea=(Err*)a,*eb=(Err*)b;
    int c=strcmp(ea->inst,eb->inst);
    if(c)return c;return strcmp(ea->sch,eb->sch);
}
static void errset_sort_dedup(ErrSet*es){
    if(es->n<=1)return;
    qsort(es->data,es->n,sizeof(Err),err_cmp);
    int w=1;
    for(int i=1;i<es->n;i++){
        if(strcmp(es->data[i].inst,es->data[w-1].inst)!=0||strcmp(es->data[i].sch,es->data[w-1].sch)!=0)
            es->data[w++]=es->data[i];
    }
    es->n=w;
}
static void errset_free(ErrSet*es){
    for(int i=0;i<es->n;i++){free(es->data[i].inst);free(es->data[i].sch);}
    free(es->data);
}

/* ============== Validator ============== */
static void validate(JV*inst,JV*schema,const char*il,const char*sl,JV*root,ErrSet*es);

static int schema_accepts(JV*inst,JV*schema,const char*il,const char*sl,JV*root){
    ErrSet tmp;errset_init(&tmp);
    validate(inst,schema,il,sl,root,&tmp);
    int ok=(tmp.n==0);
    errset_free(&tmp);
    return ok;
}

static JV *resolve_ref(const char*ref,JV*root,const char**out_loc){
    if(strcmp(ref,"#")==0){*out_loc="#";return root;}
    if(strncmp(ref,"#/$defs/",8)==0){
        const char *token=ref+8;
        int tlen=strlen(token);
        char *name=malloc(tlen+1);int j=0;
        for(int i=0;i<tlen;i++){
            if(token[i]=='~'&&i+1<tlen){
                if(token[i+1]=='1'){name[j++]='/';i++;}
                else if(token[i+1]=='0'){name[j++]='~';i++;}
                else name[j++]=token[i];
            }else name[j++]=token[i];
        }
        name[j]='\0';
        JV *defs=obj_get(root,"$defs");
        if(!defs||defs->type!=JOBJ){free(name);return NULL;}
        JV *target=obj_get(defs,name);
        char *et=esc_token(name);
        char *loc=malloc(strlen(et)+9);
        strcpy(loc,"#/$defs/");strcat(loc,et);
        free(et);free(name);
        *out_loc=loc;
        return target;
    }
    return NULL;
}

static void validate(JV*inst,JV*schema,const char*il,const char*sl,JV*root,ErrSet*es){
    if(!schema)return;
    if(schema->type==JBOOL){
        if(!schema->bval)errset_add(es,il,sl);
        return;
    }
    if(schema->type!=JOBJ)return;

    JV *kw;

    /* $ref */
    kw=obj_get(schema,"$ref");
    if(kw&&kw->type==JSTR){
        const char *ref_loc;
        JV *target=resolve_ref(kw->sval,root,&ref_loc);
        if(target)validate(inst,target,il,ref_loc,root,es);
    }

    /* type */
    kw=obj_get(schema,"type");
    if(kw){
        int ok=0;
        if(kw->type==JSTR)ok=type_matches(inst,kw->sval);
        else if(kw->type==JARR){
            for(int i=0;i<kw->arr.n;i++)
                if(type_matches(inst,kw->arr.items[i]->sval)){ok=1;break;}
        }
        if(!ok){char*loc=append_ptr(sl,"type");errset_add(es,il,loc);free(loc);}
    }

    /* enum */
    kw=obj_get(schema,"enum");
    if(kw&&kw->type==JARR){
        int ok=0;
        for(int i=0;i<kw->arr.n;i++)if(deep_eq(inst,kw->arr.items[i])){ok=1;break;}
        if(!ok){char*loc=append_ptr(sl,"enum");errset_add(es,il,loc);free(loc);}
    }

    /* const */
    kw=obj_get(schema,"const");
    if(kw){
        if(!deep_eq(inst,kw)){char*loc=append_ptr(sl,"const");errset_add(es,il,loc);free(loc);}
    }

    /* Number keywords */
    if(inst->type==JNUM){
        double val=inst->nval;
        kw=obj_get(schema,"minimum");
        if(kw&&kw->type==JNUM&&!(val>=kw->nval)){char*loc=append_ptr(sl,"minimum");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"maximum");
        if(kw&&kw->type==JNUM&&!(val<=kw->nval)){char*loc=append_ptr(sl,"maximum");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"exclusiveMinimum");
        if(kw&&kw->type==JNUM&&!(val>kw->nval)){char*loc=append_ptr(sl,"exclusiveMinimum");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"exclusiveMaximum");
        if(kw&&kw->type==JNUM&&!(val<kw->nval)){char*loc=append_ptr(sl,"exclusiveMaximum");errset_add(es,il,loc);free(loc);}
    }

    /* String keywords */
    if(inst->type==JSTR){
        int len=str_cp_len(inst->sval);
        kw=obj_get(schema,"minLength");
        if(kw&&kw->type==JNUM&&len<(int)kw->nval){char*loc=append_ptr(sl,"minLength");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"maxLength");
        if(kw&&kw->type==JNUM&&len>(int)kw->nval){char*loc=append_ptr(sl,"maxLength");errset_add(es,il,loc);free(loc);}
    }

    /* Array keywords */
    if(inst->type==JARR){
        kw=obj_get(schema,"minItems");
        if(kw&&kw->type==JNUM&&inst->arr.n<(int)kw->nval){char*loc=append_ptr(sl,"minItems");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"maxItems");
        if(kw&&kw->type==JNUM&&inst->arr.n>(int)kw->nval){char*loc=append_ptr(sl,"maxItems");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"uniqueItems");
        if(kw&&kw->type==JBOOL&&kw->bval){
            int dup=0;
            for(int i=0;i<inst->arr.n&&!dup;i++)
                for(int j=i+1;j<inst->arr.n&&!dup;j++)
                    if(deep_eq(inst->arr.items[i],inst->arr.items[j]))dup=1;
            if(dup){char*loc=append_ptr(sl,"uniqueItems");errset_add(es,il,loc);free(loc);}
        }
        /* prefixItems */
        kw=obj_get(schema,"prefixItems");
        int prefix_len=0;
        if(kw&&kw->type==JARR){
            prefix_len=kw->arr.n;
            for(int i=0;i<prefix_len&&i<inst->arr.n;i++){
                char*child_il=append_ptr_int(il,i);
                char*pi_base=append_ptr(sl,"prefixItems");
                char*child_sl=append_ptr_int(pi_base,i);free(pi_base);
                validate(inst->arr.items[i],kw->arr.items[i],child_il,child_sl,root,es);
                free(child_il);free(child_sl);
            }
        }
        /* items */
        kw=obj_get(schema,"items");
        if(kw){
            char*items_sl=append_ptr(sl,"items");
            for(int i=prefix_len;i<inst->arr.n;i++){
                char*child_il=append_ptr_int(il,i);
                validate(inst->arr.items[i],kw,child_il,items_sl,root,es);
                free(child_il);
            }
            free(items_sl);
        }
    }

    /* Object keywords */
    if(inst->type==JOBJ){
        kw=obj_get(schema,"minProperties");
        if(kw&&kw->type==JNUM&&inst->obj.n<(int)kw->nval){char*loc=append_ptr(sl,"minProperties");errset_add(es,il,loc);free(loc);}
        kw=obj_get(schema,"maxProperties");
        if(kw&&kw->type==JNUM&&inst->obj.n>(int)kw->nval){char*loc=append_ptr(sl,"maxProperties");errset_add(es,il,loc);free(loc);}

        /* required */
        kw=obj_get(schema,"required");
        if(kw&&kw->type==JARR){
            for(int i=0;i<kw->arr.n;i++){
                if(!obj_get(inst,kw->arr.items[i]->sval)){
                    char*r_base=append_ptr(sl,"required");
                    char*loc=append_ptr_int(r_base,i);free(r_base);
                    errset_add(es,il,loc);free(loc);
                }
            }
        }

        /* properties */
        JV *props=obj_get(schema,"properties");
        if(props&&props->type==JOBJ){
            char*props_sl=append_ptr(sl,"properties");
            for(int i=0;i<props->obj.n;i++){
                const char*key=props->obj.keys[i];
                JV *child=obj_get(inst,key);
                if(child){
                    char*child_il=append_ptr(il,key);
                    char*child_sl=append_ptr(props_sl,key);
                    validate(child,props->obj.vals[i],child_il,child_sl,root,es);
                    free(child_il);free(child_sl);
                }
            }
            free(props_sl);
        }

        /* additionalProperties */
        kw=obj_get(schema,"additionalProperties");
        if(kw){
            char*ap_sl=append_ptr(sl,"additionalProperties");
            for(int i=0;i<inst->obj.n;i++){
                const char*key=inst->obj.keys[i];
                if(!props||!obj_get(props,key)){
                    char*child_il=append_ptr(il,key);
                    validate(inst->obj.vals[i],kw,child_il,ap_sl,root,es);
                    free(child_il);
                }
            }
            free(ap_sl);
        }
    }

    /* allOf */
    kw=obj_get(schema,"allOf");
    if(kw&&kw->type==JARR){
        char*ao_sl=append_ptr(sl,"allOf");
        for(int i=0;i<kw->arr.n;i++){
            char*child_sl=append_ptr_int(ao_sl,i);
            validate(inst,kw->arr.items[i],il,child_sl,root,es);
            free(child_sl);
        }
        free(ao_sl);
    }

    /* anyOf */
    kw=obj_get(schema,"anyOf");
    if(kw&&kw->type==JARR){
        int any_ok=0;
        for(int i=0;i<kw->arr.n;i++){
            if(schema_accepts(inst,kw->arr.items[i],il,sl,root)){any_ok=1;break;}
        }
        if(!any_ok){char*loc=append_ptr(sl,"anyOf");errset_add(es,il,loc);free(loc);}
    }

    /* oneOf */
    kw=obj_get(schema,"oneOf");
    if(kw&&kw->type==JARR){
        int count=0;
        for(int i=0;i<kw->arr.n;i++)
            if(schema_accepts(inst,kw->arr.items[i],il,sl,root))count++;
        if(count!=1){char*loc=append_ptr(sl,"oneOf");errset_add(es,il,loc);free(loc);}
    }

    /* not */
    kw=obj_get(schema,"not");
    if(kw){
        char*not_sl=append_ptr(sl,"not");
        if(schema_accepts(inst,kw,il,not_sl,root))errset_add(es,il,not_sl);
        free(not_sl);
    }

    /* if/then/else */
    kw=obj_get(schema,"if");
    if(kw){
        char*if_sl=append_ptr(sl,"if");
        int if_ok=schema_accepts(inst,kw,il,if_sl,root);
        free(if_sl);
        if(if_ok){
            JV*tk=obj_get(schema,"then");
            if(tk){char*tsl=append_ptr(sl,"then");validate(inst,tk,il,tsl,root,es);free(tsl);}
        }else{
            JV*ek=obj_get(schema,"else");
            if(ek){char*esl=append_ptr(sl,"else");validate(inst,ek,il,esl,root,es);free(esl);}
        }
    }
}

