import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Main {

    static class JsonParser {
        private final String json;
        private int pos;

        JsonParser(String json) {
            this.json = json;
            this.pos = 0;
        }

        Object parse() {
            skipWhitespace();
            Object result = parseValue();
            skipWhitespace();
            if (pos < json.length()) {
                throw new RuntimeException("Trailing content");
            }
            return result;
        }

        Object parseValue() {
            if (pos >= json.length()) throw new RuntimeException("Unexpected end");
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') {
                if (json.startsWith("null", pos)) { pos += 4; return null; }
                throw new RuntimeException("Invalid token");
            }
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("Unexpected character: " + c);
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // skip '{'
            skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWhitespace();
                if (pos >= json.length() || json.charAt(pos) != '"')
                    throw new RuntimeException("Expected string key");
                String key = parseString();
                skipWhitespace();
                if (pos >= json.length() || json.charAt(pos) != ':')
                    throw new RuntimeException("Expected ':'");
                pos++;
                skipWhitespace();
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') { pos++; }
                else { break; }
            }
            if (pos >= json.length() || json.charAt(pos) != '}')
                throw new RuntimeException("Expected '}'");
            pos++;
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // skip '['
            skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWhitespace();
                list.add(parseValue());
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') { pos++; }
                else { break; }
            }
            if (pos >= json.length() || json.charAt(pos) != ']')
                throw new RuntimeException("Expected ']'");
            pos++;
            return list;
        }

        String parseString() {
            pos++; // skip opening '"'
            StringBuilder sb = new StringBuilder();
            while (pos < json.length()) {
                char c = json.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    if (pos >= json.length()) throw new RuntimeException("Unexpected end in string");
                    char esc = json.charAt(pos);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 >= json.length()) throw new RuntimeException("Invalid unicode escape");
                            String hex = json.substring(pos + 1, pos + 5);
                            sb.append((char) Integer.parseInt(hex, 16));
                            pos += 4;
                            break;
                        default: sb.append(esc);
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            throw new RuntimeException("Unterminated string");
        }

        Double parseNumber() {
            int start = pos;
            if (pos < json.length() && json.charAt(pos) == '-') pos++;
            if (pos >= json.length() || !Character.isDigit(json.charAt(pos)))
                throw new RuntimeException("Invalid number");
            while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            if (pos < json.length() && json.charAt(pos) == '.') {
                pos++;
                if (pos >= json.length() || !Character.isDigit(json.charAt(pos)))
                    throw new RuntimeException("Invalid number");
                while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            }
            if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
                pos++;
                if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
                if (pos >= json.length() || !Character.isDigit(json.charAt(pos)))
                    throw new RuntimeException("Invalid number");
                while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            }
            return Double.parseDouble(json.substring(start, pos));
        }

        Boolean parseBoolean() {
            if (json.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
            else if (json.startsWith("false", pos)) { pos += 5; return Boolean.FALSE; }
            throw new RuntimeException("Invalid boolean");
        }

        void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }
    }

    static boolean isValidBase64url(String s) {
        if (s.length() % 4 == 1) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                  (c >= '0' && c <= '9') || c == '-' || c == '_')) {
                return false;
            }
        }
        return true;
    }

    static byte[] base64urlDecode(String s) {
        int pad = (4 - s.length() % 4) % 4;
        StringBuilder sb = new StringBuilder(s);
        for (int i = 0; i < pad; i++) sb.append('=');
        String std = sb.toString().replace('-', '+').replace('_', '/');
        return Base64.getDecoder().decode(std);
    }

    static byte[] hmac(String alg, byte[] key, byte[] data) throws Exception {
        String macAlg;
        switch (alg) {
            case "HS256": macAlg = "HmacSHA256"; break;
            case "HS384": macAlg = "HmacSHA384"; break;
            case "HS512": macAlg = "HmacSHA512"; break;
            default: throw new IllegalArgumentException(alg);
        }
        Mac mac = Mac.getInstance(macAlg);
        mac.init(new SecretKeySpec(key, macAlg));
        return mac.doFinal(data);
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dir = args[0];

        String configStr = Files.readString(Path.of(dir, "config.json"), StandardCharsets.UTF_8);
        Map<String, Object> config = (Map<String, Object>) new JsonParser(configStr).parse();

        double now = ((Number) config.get("now")).doubleValue();
        double leeway = ((Number) config.get("leeway")).doubleValue();
        String issuer = (String) config.get("issuer");
        String audience = (String) config.get("audience");

        List<Object> keysList = (List<Object>) config.get("keys");
        Map<String, Map<String, Object>> keyMap = new HashMap<>();
        for (Object k : keysList) {
            Map<String, Object> key = (Map<String, Object>) k;
            keyMap.put((String) key.get("kid"), key);
        }

        String tokensStr = Files.readString(Path.of(dir, "tokens.txt"), StandardCharsets.UTF_8);
        String[] lines = tokensStr.split("\n", -1);

        List<String> tokens = new ArrayList<>();
        for (String line : lines) {
            String trimmed = line.trim();
            if (!trimmed.isEmpty()) tokens.add(trimmed);
        }

        int valid = 0, invalid = 0;
        List<String> results = new ArrayList<>();

        for (int i = 0; i < tokens.size(); i++) {
            String token = tokens.get(i);
            int n = i + 1;
            String result = verify(token, now, leeway, issuer, audience, keyMap);
            results.add(n + ": " + result);
            if (result.startsWith("VALID")) valid++; else invalid++;
        }

        for (String r : results) System.out.println(r);
        System.out.println();
        System.out.println("valid=" + valid + " invalid=" + invalid);
    }

