func loadJSON(_ path: String) -> JSONValue {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    var str = String(data: data, encoding: .utf8)!
    if str.hasPrefix("\u{FEFF}") { str = String(str.dropFirst()) }
    var parser = JSONParser(Array(str.utf8))
    return parser.parse()
}

let schema = loadJSON(dir + "/schema.json")
let instances = loadJSON(dir + "/instances.json")

guard case .array(let instArr) = instances else { exit(1) }

