var invalidCount = 0

for (i, inst) in instArr.enumerated() {
    let errors = validate(instance: inst, schema: schema, iPath: "#", sPath: "#", root: schema)
    if errors.isEmpty {
        print("\(i): valid")
        validCount += 1
    } else {
        print("\(i): invalid (\(errors.count))")
        let sorted = errors.sorted { a, b in
            let ai = Array(a.inst.utf8)
            let bi = Array(b.inst.utf8)
            if ai != bi { return ai.lexicographicallyPrecedes(bi) }
            let as_ = Array(a.sch.utf8)
            let bs = Array(b.sch.utf8)
            return as_.lexicographicallyPrecedes(bs)
        }
        for e in sorted {
            print("  \(e.inst) \(e.sch)")
        }
    }
}

