#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <CommonCrypto/CommonHMAC.h>

/* ============ JSON Parser ============ */

typedef enum { JSON_NULL, JSON_BOOL, JSON_NUMBER, JSON_STRING, JSON_ARRAY, JSON_OBJECT } json_type;

typedef struct json_value {
    json_type type;
    int boolean;
    double number;
    char *string;
    struct json_value **items;
    int count;
    char **keys;
} json_value;

static json_value *json_new(json_type t) {
    json_value *v = (json_value*)calloc(1, sizeof(json_value));
    v->type = t;
    return v;
}

static void skip_ws(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') (*p)++;
}

static json_value *parse_value(const char **p);

static unsigned int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

static char *parse_string_raw(const char **p) {
    (*p)++; /* skip opening " */
    const char *start = *p;
    const char *q = start;
    while (*q != '"') {
        if (*q == '\\') q++;
        q++;
    }
    int raw_len = (int)(q - start);
    *p = q + 1; /* skip closing " */

    int has_escape = 0;
    for (int i = 0; i < raw_len; i++) {
        if (start[i] == '\\') { has_escape = 1; break; }
    }

    if (!has_escape) {
        char *s = (char*)malloc(raw_len + 1);
        memcpy(s, start, raw_len);
        s[raw_len] = '\0';
        return s;
    }

    char *s = (char*)malloc(raw_len * 3 + 1);
    int si = 0;
    q = start;
    while (q < start + raw_len) {
        if (*q == '\\') {
            q++;
            switch (*q) {
                case '"': s[si++] = '"'; q++; break;
                case '\\': s[si++] = '\\'; q++; break;
                case '/': s[si++] = '/'; q++; break;
                case 'b': s[si++] = '\b'; q++; break;
                case 'f': s[si++] = '\f'; q++; break;
                case 'n': s[si++] = '\n'; q++; break;
                case 'r': s[si++] = '\r'; q++; break;
                case 't': s[si++] = '\t'; q++; break;
                case 'u': {
                    q++;
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) cp = (cp << 4) | hex_val(*q++);
                    if (cp >= 0xD800 && cp <= 0xDBFF && q[0] == '\\' && q[1] == 'u') {
                        q += 2;
                        unsigned int lo = 0;
                        for (int i = 0; i < 4; i++) lo = (lo << 4) | hex_val(*q++);
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    if (cp < 0x80) {
                        s[si++] = (char)cp;
                    } else if (cp < 0x800) {
                        s[si++] = (char)(0xC0 | (cp >> 6));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    } else if (cp < 0x10000) {
                        s[si++] = (char)(0xE0 | (cp >> 12));
                        s[si++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        s[si++] = (char)(0xF0 | (cp >> 18));
                        s[si++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                        s[si++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: s[si++] = *q; q++; break;
            }
        } else {
            s[si++] = *q++;
        }
    }
    s[si] = '\0';
    return s;
}

static json_value *parse_value(const char **p) {
    skip_ws(p);
    if (**p == '"') {
        json_value *v = json_new(JSON_STRING);
        v->string = parse_string_raw(p);
        return v;
    } else if (**p == '{') {
        json_value *v = json_new(JSON_OBJECT);
        (*p)++;
        skip_ws(p);
        if (**p == '}') { (*p)++; return v; }
        int cap = 8;
        v->keys = (char**)malloc(cap * sizeof(char*));
        v->items = (json_value**)malloc(cap * sizeof(json_value*));
        while (1) {
            skip_ws(p);
            char *key = parse_string_raw(p);
            skip_ws(p);
            (*p)++; /* skip : */
            json_value *val = parse_value(p);
            if (v->count >= cap) {
                cap *= 2;
                v->keys = (char**)realloc(v->keys, cap * sizeof(char*));
                v->items = (json_value**)realloc(v->items, cap * sizeof(json_value*));
            }
            v->keys[v->count] = key;
            v->items[v->count] = val;
            v->count++;
            skip_ws(p);
            if (**p == ',') { (*p)++; continue; }
            if (**p == '}') { (*p)++; break; }
            break;
        }
        return v;
    } else if (**p == '[') {
        json_value *v = json_new(JSON_ARRAY);
        (*p)++;
        skip_ws(p);
        if (**p == ']') { (*p)++; return v; }
        int cap = 8;
        v->items = (json_value**)malloc(cap * sizeof(json_value*));
        while (1) {
            json_value *val = parse_value(p);
            if (v->count >= cap) {
                cap *= 2;
                v->items = (json_value**)realloc(v->items, cap * sizeof(json_value*));
            }
            v->items[v->count++] = val;
            skip_ws(p);
            if (**p == ',') { (*p)++; continue; }
            if (**p == ']') { (*p)++; break; }
            break;
        }
        return v;
    } else if (**p == 't') {
        *p += 4;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 1;
        return v;
    } else if (**p == 'f') {
        *p += 5;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 0;
        return v;
    } else if (**p == 'n') {
        *p += 4;
        return json_new(JSON_NULL);
    } else {
        json_value *v = json_new(JSON_NUMBER);
        char *end;
        v->number = strtod(*p, &end);
        *p = end;
        return v;
    }
}

static json_value *json_get(json_value *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->keys[i], key) == 0) return obj->items[i];
    }
    return NULL;
}

/* ============ Base64url ============ */

static int b64_val(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}

static int is_valid_b64url(const char *s, int len) {
    if (len == 0) return 0;
    if (len % 4 == 1) return 0;
    for (int i = 0; i < len; i++) {
        if (b64_val(s[i]) < 0) return 0;
    }
    return 1;
}

static unsigned char *b64url_decode(const char *s, int len, int *out_len) {
    int full = len / 4;
    int rem = len % 4;
    int dlen = full * 3 + (rem == 2 ? 1 : rem == 3 ? 2 : 0);
    unsigned char *out = (unsigned char*)malloc(dlen > 0 ? dlen : 1);
    int oi = 0, i = 0;
    for (; i + 3 < len; i += 4) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]), c = b64_val(s[i+2]), d = b64_val(s[i+3]);
        out[oi++] = (a << 2) | (b >> 4);
        out[oi++] = ((b & 0xF) << 4) | (c >> 2);
        out[oi++] = ((c & 0x3) << 6) | d;
    }
    if (rem == 2) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]);
        out[oi++] = (a << 2) | (b >> 4);
    } else if (rem == 3) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]), c = b64_val(s[i+2]);
        out[oi++] = (a << 2) | (b >> 4);
        out[oi++] = ((b & 0xF) << 4) | (c >> 2);
    }
    *out_len = oi;
    return out;
}

/* ============ File reading ============ */

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char*)malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    if (out_len) *out_len = (int)sz;
    return buf;
}

