enum PropType {
    Str { min_length: usize },
    ArrayOfIntegers { min_items: usize },
}

struct ToolDef {
    name: &'static str,
    properties: Vec<(&'static str, PropType)>,
    required: Vec<&'static str>,
}

fn get_tool_defs() -> Vec<ToolDef> {
    vec![
        ToolDef {
            name: "kv_set",
            properties: vec![
                ("key", PropType::Str { min_length: 1 }),
                ("value", PropType::Str { min_length: 0 }),
            ],
            required: vec!["key", "value"],
        },
        ToolDef {
            name: "kv_get",
            properties: vec![
                ("key", PropType::Str { min_length: 1 }),
            ],
            required: vec!["key"],
        },
        ToolDef {
            name: "kv_list",
            properties: vec![
                ("prefix", PropType::Str { min_length: 0 }),
            ],
            required: vec![],
        },
        ToolDef {
            name: "sum",
            properties: vec![
                ("numbers", PropType::ArrayOfIntegers { min_items: 1 }),
            ],
            required: vec!["numbers"],
        },
        ToolDef {
            name: "text_stats",
            properties: vec![
                ("text", PropType::Str { min_length: 0 }),
            ],
            required: vec!["text"],
        },
    ]
}

fn validate_arguments(tool: &ToolDef, args: &JsonValue) -> Result<(), String> {
    // Check for unknown arguments
    let mut unknown: Vec<&str> = Vec::new();
    if let JsonValue::Obj(pairs) = args {
        for (k, _) in pairs {
            let known = tool.properties.iter().any(|(name, _)| *name == k.as_str());
            if !known {
                unknown.push(k.as_str());
            }
        }
    }
    if !unknown.is_empty() {
        unknown.sort();
        return Err(format!("unknown argument: {}", unknown[0]));
    }

    // Check each property in schema order
    for (name, ptype) in &tool.properties {
        let val = args.get(name);
        let is_required = tool.required.iter().any(|r| r == name);

        match val {
            None => {
                if *is_required {
                    return Err(format!("missing required argument: {}", name));
                }
            }
            Some(v) => {
                match ptype {
                    PropType::Str { min_length } => {
                        if let JsonValue::Str(s) = v {
                            if *min_length > 0 && s.is_empty() {
                                return Err(format!("argument {} must not be empty", name));
                            }
                        } else {
                            return Err(format!("argument {} must be a string", name));
                        }
                    }
                    PropType::ArrayOfIntegers { min_items } => {
                        if let JsonValue::Arr(arr) = v {
                            for item in arr {
                                if !item.is_int() {
                                    return Err(format!("argument {} must be an array of integers", name));
                                }
                            }
                            if *min_items > 0 && arr.is_empty() {
                                return Err(format!("argument {} must not be empty", name));
                            }
                        } else {
                            return Err(format!("argument {} must be an array of integers", name));
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

fn execute_tool(name: &str, args: &JsonValue, store: &mut HashMap<String, String>) -> JsonValue {
    match name {
        "kv_set" => {
            let key = args.get("key").unwrap().as_str().unwrap();
            let value = args.get("value").unwrap().as_str().unwrap();
            let existed = store.contains_key(key);
            store.insert(key.to_string(), value.to_string());
            if existed {
                make_tool_success(&format!("updated {}", key))
            } else {
                make_tool_success(&format!("created {}", key))
            }
        }
        "kv_get" => {
            let key = args.get("key").unwrap().as_str().unwrap();
            match store.get(key) {
                Some(val) => make_tool_success(val),
                None => make_tool_error(&format!("key not found: {}", key)),
            }
        }
        "kv_list" => {
            let prefix = args.get("prefix").and_then(|v| v.as_str()).unwrap_or("");
            let mut keys: Vec<&String> = store.keys().filter(|k| k.starts_with(prefix)).collect();
            keys.sort();
            let keys_arr: Vec<JsonValue> = keys.into_iter().map(|k| jstr(k)).collect();
            let count = keys_arr.len() as i64;
            let structured = jobj(vec![
                ("keys", JsonValue::Arr(keys_arr)),
                ("count", jnum(count)),
            ]);
            make_tool_success_structured(structured)
        }
        "sum" => {
            let numbers = args.get("numbers").unwrap().as_arr().unwrap();
            let mut sum: i64 = 0;
            for n in numbers {
                sum += n.as_i64().unwrap();
            }
            let count = numbers.len() as i64;
            let structured = jobj(vec![
                ("sum", jnum(sum)),
                ("count", jnum(count)),
            ]);
            make_tool_success_structured(structured)
        }
        "text_stats" => {
            let text = args.get("text").unwrap().as_str().unwrap();
            let words = count_words(text);
            let codepoints = text.chars().count() as i64;
            let utf8_bytes = text.len() as i64;
            let structured = jobj(vec![
                ("words", jnum(words as i64)),
                ("codepoints", jnum(codepoints)),
                ("utf8_bytes", jnum(utf8_bytes)),
            ]);
            make_tool_success_structured(structured)
        }
        _ => unreachable!(),
    }
}

fn count_words(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for c in text.chars() {
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            in_word = false;
        } else {
            if !in_word { count += 1; }
            in_word = true;
        }
    }
    count
}

fn is_valid_id(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Str(_) | JsonValue::Num(_, true))
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut store: HashMap<String, String> = HashMap::new();
    let mut initialized = false;

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        let line = line.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }

        // Rule 1: parse
        let parsed = {
            let mut p = Parser::new(line);
            p.parse_top()
        };
        let msg = match parsed {
            Some(v) => v,
            None => {
                let resp = make_error(JsonValue::Null, -32700, "Parse error");
                writeln!(out, "{}", serialize(&resp)).unwrap();
                continue;
            }
        };

        // Rule 2: must be object
        let obj = match &msg {
            JsonValue::Obj(o) => o,
            _ => {
                let resp = make_error(JsonValue::Null, -32600, "Invalid Request");
                writeln!(out, "{}", serialize(&resp)).unwrap();
                continue;
            }
        };

        // Rule 3: response from client (no method, has result or error)
        let has_method = obj.iter().any(|(k, _)| k == "method");
        let has_result = obj.iter().any(|(k, _)| k == "result");
        let has_error = obj.iter().any(|(k, _)| k == "error");
        if !has_method && (has_result || has_error) {
            continue;
        }

        // Rule 4: invalid request check
        let jsonrpc_ok = obj.iter().any(|(k, v)| k == "jsonrpc" && v.as_str() == Some("2.0"));
        let method_val = obj.iter().find(|(k, _)| k == "method").map(|(_, v)| v);
        let method_ok = method_val.map_or(false, |v| v.as_str().is_some());
        let id_val = obj.iter().find(|(k, _)| k == "id").map(|(_, v)| v);
        let id_present = id_val.is_some();
        let id_valid = id_val.map_or(false, |v| is_valid_id(v));

        if !jsonrpc_ok || !method_ok || (id_present && !id_valid) {
            let resp_id = if id_valid { id_val.unwrap().clone() } else { JsonValue::Null };
            let resp = make_error(resp_id, -32600, "Invalid Request");
            writeln!(out, "{}", serialize(&resp)).unwrap();
            continue;
        }

        // Rule 5: notification
        if !id_present {
            continue;
        }

        // Rule 6: request
        let resp_id = id_val.unwrap().clone();
        let method = method_val.unwrap().as_str().unwrap();
        let params = msg.get("params");

        // Check params type
        if let Some(p) = params {
            if !matches!(p, JsonValue::Obj(_)) {
                let resp = make_error(resp_id, -32602, "Invalid params");
                writeln!(out, "{}", serialize(&resp)).unwrap();
                continue;
            }
        }

        // Check method exists
        if method != "initialize" && method != "ping" && method != "tools/list" && method != "tools/call" {
            let resp = make_error(resp_id, -32601, "Method not found");
            writeln!(out, "{}", serialize(&resp)).unwrap();
            continue;
        }

        // Check initialized
        if !initialized && method != "initialize" && method != "ping" {
            let resp = make_error(resp_id, -32002, "Server not initialized");
            writeln!(out, "{}", serialize(&resp)).unwrap();
            continue;
        }

        // Dispatch
        let resp = match method {
            "initialize" => {
                if initialized {
                    make_error(resp_id, -32600, "Already initialized")
                } else {
                    let pv = params.and_then(|p| p.get("protocolVersion")).and_then(|v| v.as_str());
                    match pv {
                        None => make_error(resp_id, -32602, "Invalid params"),
                        Some(version) => {
                            initialized = true;
                            let echo_version = match version {
                                "2025-06-18" | "2025-03-26" | "2024-11-05" => version,
                                _ => "2025-06-18",
                            };
                            let result = jobj(vec![
                                ("protocolVersion", jstr(echo_version)),
                                ("capabilities", jobj(vec![
                                    ("tools", jobj(vec![("listChanged", jbool(false))])),
                                ])),
                                ("serverInfo", jobj(vec![
                                    ("name", jstr("cb2-kv")),
                                    ("title", jstr("CB2 key-value server")),
                                    ("version", jstr("1.4.2")),
                                ])),
                            ]);
                            make_result(resp_id, result)
                        }
                    }
                }
            }
            "ping" => {
                make_result(resp_id, jobj(vec![]))
            }
            "tools/list" => {
                make_result(resp_id, build_tools_list())
            }
            "tools/call" => {
                let name = params.and_then(|p| p.get("name")).and_then(|v| v.as_str());
                let name = match name {
                    Some(n) => n,
                    None => {
                        let resp = make_error(resp_id, -32602, "Invalid params");
                        writeln!(out, "{}", serialize(&resp)).unwrap();
                        continue;
                    }
                };

                let tool_defs = get_tool_defs();
                let tool = tool_defs.iter().find(|t| t.name == name);
                let tool = match tool {
                    Some(t) => t,
                    None => {
                        let resp = make_error(resp_id, -32602, &format!("Unknown tool: {}", name));
                        writeln!(out, "{}", serialize(&resp)).unwrap();
                        continue;
                    }
                };

                let args = params.and_then(|p| p.get("arguments"));
                let args_val;
                let args = match args {
                    None => { args_val = JsonValue::Obj(vec![]); &args_val }
                    Some(a) => {
                        if !matches!(a, JsonValue::Obj(_)) {
                            let result = make_tool_error("arguments must be an object");
                            let resp = make_result(resp_id, result);
                            writeln!(out, "{}", serialize(&resp)).unwrap();
                            continue;
                        }
                        a
                    }
                };

                match validate_arguments(tool, args) {
                    Err(msg) => {
                        let result = make_tool_error(&msg);
                        let resp = make_result(resp_id, result);
                        writeln!(out, "{}", serialize(&resp)).unwrap();
                        continue;
                    }
                    Ok(()) => {}
                }

                let result = execute_tool(name, args, &mut store);
                make_result(resp_id, result)
            }
            _ => unreachable!(),
        };

        writeln!(out, "{}", serialize(&resp)).unwrap();
    }

    out.flush().unwrap();
    std::process::exit(0);
}

use std::collections::HashMap;
use std::fmt::Write as _;
use std::io::{self, BufRead, Write};

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Num(f64, bool),
    Str(String),
    Arr(Vec<JsonValue>),
    Obj(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get<'a>(&'a self, key: &str) -> Option<&'a JsonValue> {
        if let JsonValue::Obj(ref obj) = self {
            for (k, v) in obj {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let JsonValue::Str(s) = self { Some(s) } else { None }
    }
    fn as_arr(&self) -> Option<&Vec<JsonValue>> {
        if let JsonValue::Arr(a) = self { Some(a) } else { None }
    }
    fn is_int(&self) -> bool {
        matches!(self, JsonValue::Num(_, true))
    }
    fn as_i64(&self) -> Option<i64> {
        if let JsonValue::Num(v, true) = self { Some(*v as i64) } else { None }
    }
}

struct Parser<'a> {
    s: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Parser { s, pos: 0 } }

    fn skip_ws(&mut self) {
        let b = self.s.as_bytes();
        while self.pos < b.len() {
            match b[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        self.s.as_bytes().get(self.pos).copied()
    }

    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) { self.pos += 1; true } else { false }
    }

    fn parse_top(&mut self) -> Option<JsonValue> {
        let v = self.parse_value()?;
        self.skip_ws();
        if self.pos != self.s.len() { return None; }
        Some(v)
    }

    fn parse_value(&mut self) -> Option<JsonValue> {
        self.skip_ws();
        match self.peek()? {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string().map(JsonValue::Str),
            b't' => { if self.s[self.pos..].starts_with("true") { self.pos += 4; Some(JsonValue::Bool(true)) } else { None } }
            b'f' => { if self.s[self.pos..].starts_with("false") { self.pos += 5; Some(JsonValue::Bool(false)) } else { None } }
            b'n' => { if self.s[self.pos..].starts_with("null") { self.pos += 4; Some(JsonValue::Null) } else { None } }
            b'-' | b'0'..=b'9' => self.parse_number(),
            _ => None,
        }
    }

    fn parse_object(&mut self) -> Option<JsonValue> {
        if !self.eat(b'{') { return None; }
        let mut obj = Vec::new();
        self.skip_ws();
        if self.eat(b'}') { return Some(JsonValue::Obj(obj)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if !self.eat(b':') { return None; }
            let val = self.parse_value()?;
            obj.push((key, val));
            self.skip_ws();
            if self.eat(b'}') { return Some(JsonValue::Obj(obj)); }
            if !self.eat(b',') { return None; }
        }
    }

    fn parse_array(&mut self) -> Option<JsonValue> {
        if !self.eat(b'[') { return None; }
        let mut arr = Vec::new();
        self.skip_ws();
        if self.eat(b']') { return Some(JsonValue::Arr(arr)); }
        loop {
            let val = self.parse_value()?;
            arr.push(val);
            self.skip_ws();
            if self.eat(b']') { return Some(JsonValue::Arr(arr)); }
            if !self.eat(b',') { return None; }
        }
    }

    fn parse_string(&mut self) -> Option<String> {
        if !self.eat(b'"') { return None; }
        let mut bytes: Vec<u8> = Vec::new();
        loop {
            let c = *self.s.as_bytes().get(self.pos)?;
            self.pos += 1;
            match c {
                b'"' => return String::from_utf8(bytes).ok(),
                b'\\' => {
                    let esc = *self.s.as_bytes().get(self.pos)?;
                    self.pos += 1;
                    match esc {
                        b'"' => bytes.push(b'"'),
                        b'\\' => bytes.push(b'\\'),
                        b'/' => bytes.push(b'/'),
                        b'b' => bytes.push(0x08),
                        b'f' => bytes.push(0x0C),
                        b'n' => bytes.push(b'\n'),
                        b'r' => bytes.push(b'\r'),
                        b't' => bytes.push(b'\t'),
                        b'u' => {
                            let cp = self.parse_hex4()?;
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                if self.peek() != Some(b'\\') { return None; }
                                self.pos += 1;
                                if self.peek() != Some(b'u') { return None; }
                                self.pos += 1;
                                let cp2 = self.parse_hex4()?;
                                if cp2 < 0xDC00 || cp2 > 0xDFFF { return None; }
                                let combined = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                let ch = char::from_u32(combined)?;
                                let mut buf = [0u8; 4];
                                bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            } else if cp >= 0xDC00 && cp <= 0xDFFF {
                                return None;
                            } else {
                                let ch = char::from_u32(cp)?;
                                let mut buf = [0u8; 4];
                                bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            }
                        }
                        _ => return None,
                    }
                }
                0x00..=0x1F => return None,
                _ => bytes.push(c),
            }
        }
    }

    fn parse_hex4(&mut self) -> Option<u32> {
        let b = self.s.as_bytes();
        if self.pos + 4 > b.len() { return None; }
        let mut val = 0u32;
        for i in 0..4 {
            let d = match b[self.pos + i] {
                b'0'..=b'9' => (b[self.pos + i] - b'0') as u32,
                b'a'..=b'f' => (b[self.pos + i] - b'a' + 10) as u32,
                b'A'..=b'F' => (b[self.pos + i] - b'A' + 10) as u32,
                _ => return None,
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Some(val)
    }

    fn parse_number(&mut self) -> Option<JsonValue> {
        let start = self.pos;
        let b = self.s.as_bytes();
        let mut is_int = true;
        if self.peek() == Some(b'-') { self.pos += 1; }
        match self.peek()? {
            b'0' => self.pos += 1,
            b'1'..=b'9' => {
                while self.pos < b.len() && b[self.pos].is_ascii_digit() { self.pos += 1; }
            }
            _ => return None,
        }
        if self.pos < b.len() && b[self.pos] == b'.' {
            is_int = false;
            self.pos += 1;
            if self.pos >= b.len() || !b[self.pos].is_ascii_digit() { return None; }
            while self.pos < b.len() && b[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < b.len() && (b[self.pos] == b'e' || b[self.pos] == b'E') {
            is_int = false;
            self.pos += 1;
            if self.pos < b.len() && (b[self.pos] == b'+' || b[self.pos] == b'-') { self.pos += 1; }
            if self.pos >= b.len() || !b[self.pos].is_ascii_digit() { return None; }
            while self.pos < b.len() && b[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let num_str = &self.s[start..self.pos];
        let value: f64 = num_str.parse().ok()?;
        Some(JsonValue::Num(value, is_int))
    }
}

fn jstr(s: &str) -> JsonValue { JsonValue::Str(s.to_string()) }
fn jnum(v: i64) -> JsonValue { JsonValue::Num(v as f64, true) }
fn jbool(b: bool) -> JsonValue { JsonValue::Bool(b) }
fn jobj(pairs: Vec<(&str, JsonValue)>) -> JsonValue {
    JsonValue::Obj(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}
fn jarr(items: Vec<JsonValue>) -> JsonValue { JsonValue::Arr(items) }

fn serialize(v: &JsonValue) -> String {
    let mut s = String::new();
    write_json(v, &mut s);
    s
}

fn write_json(v: &JsonValue, out: &mut String) {
    match v {
        JsonValue::Null => out.push_str("null"),
        JsonValue::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JsonValue::Num(val, is_int) => {
            if *is_int {
                write!(out, "{}", *val as i64).unwrap();
            } else {
                write!(out, "{}", val).unwrap();
            }
        }
        JsonValue::Str(s) => write_json_str(s, out),
        JsonValue::Arr(arr) => {
            out.push('[');
            for (i, item) in arr.iter().enumerate() {
                if i > 0 { out.push(','); }
                write_json(item, out);
            }
            out.push(']');
        }
        JsonValue::Obj(obj) => {
            out.push('{');
            for (i, (k, val)) in obj.iter().enumerate() {
                if i > 0 { out.push(','); }
                write_json_str(k, out);
                out.push(':');
                write_json(val, out);
            }
            out.push('}');
        }
    }
}

fn write_json_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => { write!(out, "\\u{:04x}", c as u32).unwrap(); }
            c => out.push(c),
        }
    }
    out.push('"');
}

fn make_error(id: JsonValue, code: i64, message: &str) -> JsonValue {
    jobj(vec![
        ("jsonrpc", jstr("2.0")),
        ("id", id),
        ("error", jobj(vec![
            ("code", jnum(code)),
            ("message", jstr(message)),
        ])),
    ])
}

fn make_result(id: JsonValue, result: JsonValue) -> JsonValue {
    jobj(vec![
        ("jsonrpc", jstr("2.0")),
        ("id", id),
        ("result", result),
    ])
}

fn make_tool_success(text: &str) -> JsonValue {
    jobj(vec![
        ("content", jarr(vec![jobj(vec![
            ("type", jstr("text")),
            ("text", jstr(text)),
        ])])),
        ("isError", jbool(false)),
    ])
}

fn make_tool_success_structured(structured: JsonValue) -> JsonValue {
    let text = serialize(&structured);
    jobj(vec![
        ("content", jarr(vec![jobj(vec![
            ("type", jstr("text")),
            ("text", jstr(&text)),
        ])])),
        ("structuredContent", structured),
        ("isError", jbool(false)),
    ])
}

fn make_tool_error(message: &str) -> JsonValue {
    jobj(vec![
        ("content", jarr(vec![jobj(vec![
            ("type", jstr("text")),
            ("text", jstr(message)),
        ])])),
        ("isError", jbool(true)),
    ])
}

