enum PropType {
    Str { min_length: usize },
    ArrayOfIntegers { min_items: usize },
}

struct ToolDef {
    name: &'static str,
    properties: Vec<(&'static str, PropType)>,
    required: Vec<&'static str>,
}

fn get_tool_defs() -> Vec<ToolDef> {
    vec![
        ToolDef {
            name: "kv_set",
            properties: vec![
                ("key", PropType::Str { min_length: 1 }),
                ("value", PropType::Str { min_length: 0 }),
            ],
            required: vec!["key", "value"],
        },
        ToolDef {
            name: "kv_get",
            properties: vec![
                ("key", PropType::Str { min_length: 1 }),
            ],
            required: vec!["key"],
        },
        ToolDef {
            name: "kv_list",
            properties: vec![
                ("prefix", PropType::Str { min_length: 0 }),
            ],
            required: vec![],
        },
        ToolDef {
            name: "sum",
            properties: vec![
                ("numbers", PropType::ArrayOfIntegers { min_items: 1 }),
            ],
            required: vec!["numbers"],
        },
        ToolDef {
            name: "text_stats",
            properties: vec![
                ("text", PropType::Str { min_length: 0 }),
            ],
            required: vec!["text"],
        },
    ]
}

fn validate_arguments(tool: &ToolDef, args: &JsonValue) -> Result<(), String> {
    // Check for unknown arguments
    let mut unknown: Vec<&str> = Vec::new();
    if let JsonValue::Obj(pairs) = args {
        for (k, _) in pairs {
            let known = tool.properties.iter().any(|(name, _)| *name == k.as_str());
            if !known {
                unknown.push(k.as_str());
            }
        }
    }
    if !unknown.is_empty() {
        unknown.sort();
        return Err(format!("unknown argument: {}", unknown[0]));
    }

    // Check each property in schema order
    for (name, ptype) in &tool.properties {
        let val = args.get(name);
        let is_required = tool.required.iter().any(|r| r == name);

        match val {
            None => {
                if is_required {
                    return Err(format!("missing required argument: {}", name));
                }
            }
            Some(v) => {
                match ptype {
                    PropType::Str { min_length } => {
                        if let JsonValue::Str(s) = v {
                            if *min_length > 0 && s.is_empty() {
                                return Err(format!("argument {} must not be empty", name));
                            }
                        } else {
                            return Err(format!("argument {} must be a string", name));
                        }
                    }
                    PropType::ArrayOfIntegers { min_items } => {
                        if let JsonValue::Arr(arr) = v {
                            for item in arr {
                                if !item.is_int() {
                                    return Err(format!("argument {} must be an array of integers", name));
                                }
                            }
                            if *min_items > 0 && arr.is_empty() {
                                return Err(format!("argument {} must not be empty", name));
                            }
                        } else {
                            return Err(format!("argument {} must be an array of integers", name));
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

fn execute_tool(name: &str, args: &JsonValue, store: &mut HashMap<String, String>) -> JsonValue {
    match name {
        "kv_set" => {
            let key = args.get("key").unwrap().as_str().unwrap();
            let value = args.get("value").unwrap().as_str().unwrap();
            let existed = store.contains_key(key);
            store.insert(key.to_string(), value.to_string());
            if existed {
                make_tool_success(&format!("updated {}", key))
            } else {
                make_tool_success(&format!("created {}", key))
            }
        }
        "kv_get" => {
            let key = args.get("key").unwrap().as_str().unwrap();
            match store.get(key) {
                Some(val) => make_tool_success(val),
                None => make_tool_error(&format!("key not found: {}", key)),
            }
        }
        "kv_list" => {
            let prefix = args.get("prefix").and_then(|v| v.as_str()).unwrap_or("");
            let mut keys: Vec<&String> = store.keys().filter(|k| k.starts_with(prefix)).collect();
            keys.sort();
            let keys_arr: Vec<JsonValue> = keys.into_iter().map(|k| jstr(k)).collect();
            let count = keys_arr.len() as i64;
            let structured = jobj(vec![
                ("keys", JsonValue::Arr(keys_arr)),
                ("count", jnum(count)),
            ]);
            make_tool_success_structured(structured)
        }
        "sum" => {
            let numbers = args.get("numbers").unwrap().as_arr().unwrap();
            let mut sum: i64 = 0;
            for n in numbers {
                sum += n.as_i64().unwrap();
            }
            let count = numbers.len() as i64;
            let structured = jobj(vec![
                ("sum", jnum(sum)),
                ("count", jnum(count)),
            ]);
            make_tool_success_structured(structured)
        }
        "text_stats" => {
            let text = args.get("text").unwrap().as_str().unwrap();
            let words = count_words(text);
            let codepoints = text.chars().count() as i64;
            let utf8_bytes = text.len() as i64;
            let structured = jobj(vec![
                ("words", jnum(words as i64)),
                ("codepoints", jnum(codepoints)),
                ("utf8_bytes", jnum(utf8_bytes)),
            ]);
            make_tool_success_structured(structured)
        }
        _ => unreachable!(),
    }
}

fn count_words(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for c in text.chars() {
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            in_word = false;
        } else {
            if !in_word { count += 1; }
            in_word = true;
        }
    }
    count
}

fn is_valid_id(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Str(_) | JsonValue::Num(_, true))
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut store: HashMap<String, String> = HashMap::new();
    let mut initialized = false;

    for line in stdin.lock().lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        let line = line.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }

        // Rule 1: parse
        let parsed = {
            let mut p = Parser::new(line);
            p.parse_top()
        };
        let msg = match parsed {
            Some(v) => v,
            None => {
                let resp = make_error(JsonValue::Null, -32700, "Parse error");
                writeln!(out, "{}", serialize(&resp)).unwrap();
                continue;
            }
        };

        // Rule 2: must be object
        let obj = match &msg {
            JsonValue::Obj(o) => o,
            _ => {
                let resp = make_error(JsonValue::Null, -32600, "Invalid Request");
                writeln!(out, "{}", serialize(&resp)).unwrap();
                continue;
            }
        };

        // Rule 3: response from client (no method, has result or error)
        let has_method = obj.iter().any(|(k, _)| k == "method");
        let has_result = obj.iter().any(|(k, _)| k == "result");
        let has_error = obj.iter().any(|(k, _)| k == "error");
        if !has_method && (has_result || has_error) {
            continue;
        }

        // Rule 4: invalid request check
        let jsonrpc_ok = obj.iter().any(|(k, v)| k == "jsonrpc" && v.as_str() == Some("2.0"));
        let method_val = obj.iter().find(|(k, _)| k == "method").map(|(_, v)| v);
        let method_ok = method_val.map_or(false, |v| v.as_str().is_some());
        let id_val = obj.iter().find(|(k, _)| k == "id").map(|(_, v)| v);
        let id_present = id_val.is_some();
        let id_valid = id_val.map_or(false, |v| is_valid_id(v));

        if !jsonrpc_ok || !method_ok || (id_present && !id_valid) {
            let resp_id = if id_valid { id_val.unwrap().clone() } else { JsonValue::Null };
            let resp = make_error(resp_id, -32600, "Invalid Request");
            writeln!(out, "{}", serialize(&resp)).unwrap();
            continue;
        }

        // Rule 5: notification
        if !id_present {
            continue;
        }

        // Rule 6: request
        let resp_id = id_val.unwrap().clone();
        let method = method_val.unwrap().as_str().unwrap();
        let params = msg.get("params");

        // Check params type
        if let Some(p) = params {
            if !matches!(p, JsonValue::Obj(_)) {
                let resp = make_error(resp_id, -32602, "Invalid params");
                writeln!(out, "{}", serialize(&resp)).unwrap();
                continue;
            }
        }

        // Check method exists
        if method != "initialize" && method != "ping" && method != "tools/list" && method != "tools/call" {
            let resp = make_error(resp_id, -32601, "Method not found");
            writeln!(out, "{}", serialize(&resp)).unwrap();
            continue;
        }

        // Check initialized
        if !initialized && method != "initialize" && method != "ping" {
            let resp = make_error(resp_id, -32002, "Server not initialized");
            writeln!(out, "{}", serialize(&resp)).unwrap();
            continue;
        }

        // Dispatch
        let resp = match method {
            "initialize" => {
                if initialized {
                    make_error(resp_id, -32600, "Already initialized")
                } else {
                    let pv = params.and_then(|p| p.get("protocolVersion")).and_then(|v| v.as_str());
                    match pv {
                        None => make_error(resp_id, -32602, "Invalid params"),
                        Some(version) => {
                            initialized = true;
                            let echo_version = match version {
                                "2025-06-18" | "2025-03-26" | "2024-11-05" => version,
                                _ => "2025-06-18",
                            };
                            let result = jobj(vec![
                                ("protocolVersion", jstr(echo_version)),
                                ("capabilities", jobj(vec![
                                    ("tools", jobj(vec![("listChanged", jbool(false))])),
                                ])),
                                ("serverInfo", jobj(vec![
                                    ("name", jstr("cb2-kv")),
                                    ("title", jstr("CB2 key-value server")),
                                    ("version", jstr("1.4.2")),
                                ])),
                            ]);
                            make_result(resp_id, result)
                        }
                    }
                }
            }
            "ping" => {
                make_result(resp_id, jobj(vec![]))
            }
            "tools/list" => {
                make_result(resp_id, build_tools_list())
            }
            "tools/call" => {
                let name = params.and_then(|p| p.get("name")).and_then(|v| v.as_str());
                let name = match name {
                    Some(n) => n,
                    None => {
                        let resp = make_error(resp_id, -32602, "Invalid params");
                        writeln!(out, "{}", serialize(&resp)).unwrap();
                        continue;
                    }
                };

                let tool_defs = get_tool_defs();
                let tool = tool_defs.iter().find(|t| t.name == name);
                let tool = match tool {
                    Some(t) => t,
                    None => {
                        let resp = make_error(resp_id, -32602, &format!("Unknown tool: {}", name));
                        writeln!(out, "{}", serialize(&resp)).unwrap();
                        continue;
                    }
                };

                let args = params.and_then(|p| p.get("arguments"));
                let args_val;
                let args = match args {
                    None => { args_val = JsonValue::Obj(vec![]); &args_val }
                    Some(a) => {
                        if !matches!(a, JsonValue::Obj(_)) {
                            let result = make_tool_error("arguments must be an object");
                            let resp = make_result(resp_id, result);
                            writeln!(out, "{}", serialize(&resp)).unwrap();
                            continue;
                        }
                        a
                    }
                };

                match validate_arguments(tool, args) {
                    Err(msg) => {
                        let result = make_tool_error(&msg);
                        let resp = make_result(resp_id, result);
                        writeln!(out, "{}", serialize(&resp)).unwrap();
                        continue;
                    }
                    Ok(()) => {}
                }

                let result = execute_tool(name, args, &mut store);
                make_result(resp_id, result)
            }
            _ => unreachable!(),
        };

        writeln!(out, "{}", serialize(&resp)).unwrap();
    }

    out.flush().unwrap();
    std::process::exit(0);
}

import Foundation

// MARK: - JSON Value
enum JSONValue {
    case null
    case bool(Bool)
    case int(Int64)
    case double(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser
final class JSONParser {
    let chars: [Character]
    var pos = 0

    init(_ s: String) { chars = Array(s) }

    func parse() -> JSONValue? {
        skipWS()
        guard let v = parseValue() else { return nil }
        skipWS()
        guard pos >= chars.count else { return nil }
        return v
    }

    private func skipWS() {
        while pos < chars.count {
            let c = chars[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 } else { break }
        }
    }

    private func parseValue() -> JSONValue? {
        guard pos < chars.count else { return nil }
        switch chars[pos] {
        case "n": return matchLit("null") ? .null : nil
        case "t": return matchLit("true") ? .bool(true) : nil
        case "f": return matchLit("false") ? .bool(false) : nil
        case "\"": return parseStr().map { JSONValue.string($0) }
        case "[": return parseArr()
        case "{": return parseObj()
        default:
            if chars[pos] == "-" || (chars[pos] >= "0" && chars[pos] <= "9") { return parseNum() }
            return nil
        }
    }

    private func matchLit(_ s: String) -> Bool {
        let a = Array(s)
        guard pos + a.count <= chars.count else { return false }
        for i in 0..<a.count { if chars[pos+i] != a[i] { return false } }
        pos += a.count
        return true
    }

    private func parseStr() -> String? {
        guard pos < chars.count && chars[pos] == "\"" else { return nil }
        pos += 1
        var r = ""
        while pos < chars.count {
            let c = chars[pos]
            if c == "\"" { pos += 1; return r }
            if c == "\\" {
                pos += 1
                guard pos < chars.count else { return nil }
                let e = chars[pos]
                switch e {
                case "\"": r.append("\""); pos += 1
                case "\\": r.append("\\"); pos += 1
                case "/": r.append("/"); pos += 1
                case "b": r.append("\u{08}"); pos += 1
                case "f": r.append("\u{0C}"); pos += 1
                case "n": r.append("\n"); pos += 1
                case "r": r.append("\r"); pos += 1
                case "t": r.append("\t"); pos += 1
                case "u":
                    pos += 1
                    guard let hi = parseHex4() else { return nil }
                    if hi >= 0xD800 && hi <= 0xDBFF {
                        guard pos < chars.count && chars[pos] == "\\" else { return nil }
                        pos += 1
                        guard pos < chars.count && chars[pos] == "u" else { return nil }
                        pos += 1
                        guard let lo = parseHex4() else { return nil }
                        guard lo >= 0xDC00 && lo <= 0xDFFF else { return nil }
                        let sc = UInt32(0x10000 + (UInt32(hi)-0xD800)*0x400 + UInt32(lo)-0xDC00)
                        guard let u = Unicode.Scalar(sc) else { return nil }
                        r.unicodeScalars.append(u)
                    } else if hi >= 0xDC00 && hi <= 0xDFFF {
                        return nil
                    } else {
                        guard let u = Unicode.Scalar(UInt32(hi)) else { return nil }
                        r.unicodeScalars.append(u)
                    }
                default: return nil
                }
            } else {
                r.append(c); pos += 1
            }
        }
        return nil
    }

    private func parseHex4() -> UInt16? {
        guard pos + 4 <= chars.count else { return nil }
        var v: UInt16 = 0
        for i in 0..<4 {
            let c = chars[pos+i]
            let d: UInt16
            if c >= "0" && c <= "9" { d = UInt16(c.asciiValue! - 48) }
            else if c >= "a" && c <= "f" { d = UInt16(c.asciiValue! - 97 + 10) }
            else if c >= "A" && c <= "F" { d = UInt16(c.asciiValue! - 65 + 10) }
            else { return nil }
            v = v &* 16 &+ d
        }
        pos += 4
        return v
    }

    private func parseNum() -> JSONValue? {
        let start = pos
        var isDbl = false
        if pos < chars.count && chars[pos] == "-" { pos += 1 }
        guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
        if chars[pos] == "0" { pos += 1 }
        else { while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 } }
        if pos < chars.count && chars[pos] == "." {
            isDbl = true; pos += 1
            guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        if pos < chars.count && (chars[pos] == "e" || chars[pos] == "E") {
            isDbl = true; pos += 1
            if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-") { pos += 1 }
            guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        let s = String(chars[start..<pos])
        if isDbl { return Double(s).map { JSONValue.double($0) } }
        else { return Int64(s).map { JSONValue.int($0) } ?? Double(s).map { JSONValue.double($0) } }
    }

    private func parseArr() -> JSONValue? {
        pos += 1; skipWS()
        var items: [JSONValue] = []
        if pos < chars.count && chars[pos] == "]" { pos += 1; return .array(items) }
        while true {
            skipWS()
            guard let v = parseValue() else { return nil }
            items.append(v); skipWS()
            guard pos < chars.count else { return nil }
            if chars[pos] == "]" { pos += 1; return .array(items) }
            guard chars[pos] == "," else { return nil }
            pos += 1
        }
    }

    private func parseObj() -> JSONValue? {
        pos += 1; skipWS()
        var pairs: [(String, JSONValue)] = []
        if pos < chars.count && chars[pos] == "}" { pos += 1; return .object(pairs) }
        while true {
            skipWS()
            guard pos < chars.count && chars[pos] == "\"" else { return nil }
            guard let k = parseStr() else { return nil }
            skipWS()
            guard pos < chars.count && chars[pos] == ":" else { return nil }
            pos += 1; skipWS()
            guard let v = parseValue() else { return nil }
            pairs.append((k, v)); skipWS()
            guard pos < chars.count else { return nil }
            if chars[pos] == "}" { pos += 1; return .object(pairs) }
            guard chars[pos] == "," else { return nil }
            pos += 1
        }
    }
}

// MARK: - JSON Serializer
func ser(_ v: JSONValue) -> String {
    switch v {
    case .null: return "null"
    case .bool(true): return "true"
    case .bool(false): return "false"
    case .int(let i): return String(i)
    case .double(let d):
        if d == d.rounded() && abs(d) < 1e15 { return String(Int64(d)) }
        return String(d)
    case .string(let s): return serStr(s)
    case .array(let a): return "[" + a.map{ser($0)}.joined(separator: ",") + "]"
    case .object(let p): return "{" + p.map{ serStr($0.0) + ":" + ser($0.1) }.joined(separator: ",") + "}"
    }
}

func serStr(_ s: String) -> String {
    var r = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if c.value < 0x20 { r += String(format: "\\u%04x", c.value) }
            else { r.unicodeScalars.append(c) }
        }
    }
    r += "\""
    return r
}

// MARK: - Helpers
func gv(_ obj: JSONValue, _ key: String) -> JSONValue? {
    guard case .object(let p) = obj else { return nil }
    for (k,v) in p { if k == key { return v } }
    return nil
}

func isValidId(_ v: JSONValue?) -> Bool {
    guard let v = v else { return false }
    switch v { case .string, .int: return true; default: return false }
}

func makeErr(id: JSONValue?, code: Int, msg: String) -> String {
    ser(.object([("jsonrpc",.string("2.0")),("id",id ?? .null),("error",.object([("code",.int(Int64(code))),("message",.string(msg))]))]))
}

func makeRes(id: JSONValue?, result: JSONValue) -> String {
    ser(.object([("jsonrpc",.string("2.0")),("id",id ?? .null),("result",result)]))
}

// MARK: - Server State
var initialized = false
