// MARK: - Tool result helpers
func toolOk(_ text: String) -> JSONValue {
    .object([("content",.array([.object([("type",.string("text")),("text",.string(text))])])),("isError",.bool(false))])
}
func toolOkStructured(_ structured: JSONValue) -> JSONValue {
    let txt = ser(structured)
    return .object([("content",.array([.object([("type",.string("text")),("text",.string(txt))])])),("structuredContent",structured),("isError",.bool(false))])
}
func toolFail(_ msg: String) -> JSONValue {
    .object([("content",.array([.object([("type",.string("text")),("text",.string(msg))])])),("isError",.bool(true))])
}

// MARK: - Tool schemas
struct PropInfo { let name: String; let type: String; let minCheck: Bool }
struct ToolDef { let props: [PropInfo]; let required: [String] }

let toolDefs: [String: ToolDef] = [
    "kv_set": ToolDef(props: [PropInfo(name:"key",type:"string",minCheck:true),PropInfo(name:"value",type:"string",minCheck:false)], required:["key","value"]),
    "kv_get": ToolDef(props: [PropInfo(name:"key",type:"string",minCheck:true)], required:["key"]),
    "kv_list": ToolDef(props: [PropInfo(name:"prefix",type:"string",minCheck:false)], required:[]),
    "sum": ToolDef(props: [PropInfo(name:"numbers",type:"array",minCheck:true)], required:["numbers"]),
    "text_stats": ToolDef(props: [PropInfo(name:"text",type:"string",minCheck:false)], required:["text"]),
]

// MARK: - Process line
func processLine(_ line: String) -> String? {
    let trimmed = line.trimmingCharacters(in: CharacterSet(charactersIn: " \t\r\n"))
    if trimmed.isEmpty { return nil }

    guard let json = JSONParser(line).parse() else {
        return makeErr(id: nil, code: -32700, msg: "Parse error")
    }

    guard case .object = json else {
        return makeErr(id: nil, code: -32600, msg: "Invalid Request")
    }

    let hasMethod = gv(json, "method") != nil
    let hasResult = gv(json, "result") != nil
    let hasError = gv(json, "error") != nil
    if !hasMethod && (hasResult || hasError) { return nil }

    let jsonrpcVal = gv(json, "jsonrpc")
    let methodVal = gv(json, "method")
    let idVal = gv(json, "id")
    let hasId = idVal != nil
    let idValid = hasId && isValidId(idVal)

    let jsonrpcOk: Bool
    if case .string(let s) = jsonrpcVal ?? .null { jsonrpcOk = (s == "2.0") } else { jsonrpcOk = false }
    let methodOk: Bool
    if case .string = methodVal ?? .null { methodOk = true } else { methodOk = false }
    let idOk = !hasId || idValid

    if !jsonrpcOk || !methodOk || !idOk {
        return makeErr(id: (hasId && idValid) ? idVal : nil, code: -32600, msg: "Invalid Request")
    }

    if !hasId { return nil }

    guard case .string(let method) = methodVal! else { return nil }

    let validMethods: Set<String> = ["initialize","ping","tools/list","tools/call"]
    if !validMethods.contains(method) {
        return makeErr(id: idVal, code: -32601, msg: "Method not found")
    }

    let paramsVal = gv(json, "params")
    if let p = paramsVal {
        guard case .object = p else {
            return makeErr(id: idVal, code: -32602, msg: "Invalid params")
        }
    }

    if !initialized && method != "initialize" && method != "ping" {
        return makeErr(id: idVal, code: -32002, msg: "Server not initialized")
    }

    switch method {
    case "initialize": return handleInit(id: idVal, params: paramsVal)
    case "ping": return makeRes(id: idVal, result: .object([]))
    case "tools/list": return makeRes(id: idVal, result: toolsList())
    case "tools/call": return handleCall(id: idVal, params: paramsVal)
    default: return makeErr(id: idVal, code: -32601, msg: "Method not found")
    }
}

func handleInit(id: JSONValue?, params: JSONValue?) -> String {
    if initialized { return makeErr(id: id, code: -32600, msg: "Already initialized") }
    guard case .object = params ?? .null else {
        return makeErr(id: id, code: -32602, msg: "Invalid params")
    }
    let pv = gv(params!, "protocolVersion")
    guard case .string(let ver) = pv ?? .null else {
        return makeErr(id: id, code: -32602, msg: "Invalid params")
    }
    let supported: Set<String> = ["2025-06-18","2025-03-26","2024-11-05"]
    let rv = supported.contains(ver) ? ver : "2025-06-18"
    initialized = true
    let result = JSONValue.object([
        ("protocolVersion", .string(rv)),
        ("capabilities", .object([("tools", .object([("listChanged", .bool(false))]))])),
        ("serverInfo", .object([("name",.string("cb2-kv")),("title",.string("CB2 key-value server")),("version",.string("1.4.2"))]))
    ])
    return makeRes(id: id, result: result)
}

