func handleCall(id: JSONValue?, params: JSONValue?) -> String {
    let nameVal = gv(params ?? .object([]), "name")
    guard case .string(let toolName) = nameVal ?? .null else {
        return makeErr(id: id, code: -32602, msg: "Invalid params")
    }
    guard let def = toolDefs[toolName] else {
        return makeErr(id: id, code: -32602, msg: "Unknown tool: \(toolName)")
    }

    let argsVal = gv(params ?? .object([]), "arguments")
    var args: [(String, JSONValue)] = []
    if let av = argsVal {
        guard case .object(let pairs) = av else {
            return makeRes(id: id, result: toolFail("arguments must be an object"))
        }
        args = pairs
    }

    let validProps = Set(def.props.map { $0.name })
    let unknown = args.filter { !validProps.contains($0.0) }.map { $0.0 }
    if !unknown.isEmpty {
        let sorted = unknown.sorted { $0.unicodeScalars.lexicographicallyPrecedes($1.unicodeScalars) }
        return makeRes(id: id, result: toolFail("unknown argument: \(sorted[0])"))
    }

    var argMap: [String: JSONValue] = [:]
    for (k,v) in args { argMap[k] = v }

    for prop in def.props {
        if let val = argMap[prop.name] {
            switch prop.type {
            case "string":
                guard case .string(let s) = val else {
                    return makeRes(id: id, result: toolFail("argument \(prop.name) must be a string"))
                }
                if prop.minCheck && s.isEmpty {
                    return makeRes(id: id, result: toolFail("argument \(prop.name) must not be empty"))
                }
            case "array":
                guard case .array(let arr) = val else {
                    return makeRes(id: id, result: toolFail("argument \(prop.name) must be an array of integers"))
                }
                for item in arr {
                    guard case .int = item else {
                        return makeRes(id: id, result: toolFail("argument \(prop.name) must be an array of integers"))
                    }
                }
                if prop.minCheck && arr.isEmpty {
                    return makeRes(id: id, result: toolFail("argument \(prop.name) must not be empty"))
                }
            default: break
            }
        } else {
            if def.required.contains(prop.name) {
                return makeRes(id: id, result: toolFail("missing required argument: \(prop.name)"))
            }
        }
    }

    switch toolName {
    case "kv_set":
        guard case .string(let key) = argMap["key"]!, case .string(let val) = argMap["value"]! else {
            return makeRes(id: id, result: toolFail("internal error"))
        }
        let existed = kvStore[key] != nil
        kvStore[key] = val
        return makeRes(id: id, result: toolOk(existed ? "updated \(key)" : "created \(key)"))
    case "kv_get":
        guard case .string(let key) = argMap["key"]! else {
            return makeRes(id: id, result: toolFail("internal error"))
        }
        guard let val = kvStore[key] else {
            return makeRes(id: id, result: toolFail("key not found: \(key)"))
        }
        return makeRes(id: id, result: toolOk(val))
    case "kv_list":
        var prefix = ""
        if let pv = argMap["prefix"], case .string(let s) = pv { prefix = s }
        let keys = kvStore.keys.filter { $0.hasPrefix(prefix) }
            .sorted { $0.unicodeScalars.lexicographicallyPrecedes($1.unicodeScalars) }
        let structured = JSONValue.object([
            ("keys", .array(keys.map { .string($0) })),
            ("count", .int(Int64(keys.count)))
        ])
        return makeRes(id: id, result: toolOkStructured(structured))
    case "sum":
        guard case .array(let arr) = argMap["numbers"]! else {
            return makeRes(id: id, result: toolFail("internal error"))
        }
        var total: Int64 = 0
        for item in arr { if case .int(let n) = item { total += n } }
        let structured = JSONValue.object([
            ("sum", .int(total)),
            ("count", .int(Int64(arr.count)))
        ])
        return makeRes(id: id, result: toolOkStructured(structured))
    case "text_stats":
        guard case .string(let text) = argMap["text"]! else {
            return makeRes(id: id, result: toolFail("internal error"))
        }
        let w = countWords(text)
        let cp = text.unicodeScalars.count
        let ub = text.utf8.count
        let structured = JSONValue.object([
            ("words", .int(Int64(w))),
            ("codepoints", .int(Int64(cp))),
            ("utf8_bytes", .int(Int64(ub)))
        ])
        return makeRes(id: id, result: toolOkStructured(structured))
    default:
        return makeErr(id: id, code: -32601, msg: "Method not found")
    }
}

func countWords(_ text: String) -> Int {
    var count = 0
    var inWord = false
    for sc in text.unicodeScalars {
        if sc == " " || sc == "\t" || sc == "\n" || sc == "\r" {
            inWord = false
        } else {
            if !inWord { count += 1; inWord = true }
        }
    }
    return count
}

