"\"inputSchema\":{\"type\":\"object\",\"properties\":{\"numbers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"minItems\":1}},"
"\"required\":[\"numbers\"],\"additionalProperties\":false},"
