int main(void) {
    char *line=NULL;size_t bufsize=0;ssize_t nread;
    while((nread=getline(&line,&bufsize,stdin))!=-1){
        while(nread>0&&(line[nread-1]=='\n'||line[nread-1]=='\r'))nread--;
        /* Check empty/whitespace */
        int all_ws=1;
        for(ssize_t i=0;i<nread;i++){if(line[i]!=' '&&line[i]!='\t'&&line[i]!='\r'){all_ws=0;break;}}
        if(all_ws)continue;

        jval *msg=parse_json(line,(size_t)nread);
        if(!msg){send_error_id_null(-32700,"Parse error");continue;}

        /* Rule 2: not an object */
        if(msg->type!=JV_OBJECT){send_error_id_null(-32600,"Invalid Request");jval_free(msg);continue;}

        /* Rule 3: response from client */
        jval *method=obj_get(msg,"method");
        jval *result_m=obj_get(msg,"result");
        jval *error_m=obj_get(msg,"error");
        if(!method&&(result_m||error_m)){jval_free(msg);continue;}

        /* Rule 4: invalid request check */
        jval *jsonrpc=obj_get(msg,"jsonrpc");
        jval *id=obj_get(msg,"id");
        int has_id=obj_has(msg,"id");
        int valid_id=0;
        if(has_id){valid_id=(id->type==JV_STRING||id->type==JV_INT);}

        int invalid=0;
        if(!jsonrpc||jsonrpc->type!=JV_STRING||strcmp(jsonrpc->str_val,"2.0")!=0)invalid=1;
        if(!method||method->type!=JV_STRING)invalid=1;
        if(has_id&&!valid_id)invalid=1;

        if(invalid){
            printf("{\"jsonrpc\":\"2.0\",\"id\":");
            if(has_id&&valid_id)write_id(id);else printf("null");
            printf(",\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}\n");
            jval_free(msg);continue;
        }

        /* Rule 5: notification */
        if(!has_id){jval_free(msg);continue;}

        /* Rule 6: request */
        const char *mname=method->str_val;
        jval *params=obj_get(msg,"params");

        /* 6a: method not found */
        int known=(strcmp(mname,"initialize")==0||strcmp(mname,"ping")==0||strcmp(mname,"tools/list")==0||strcmp(mname,"tools/call")==0);
        if(!known){send_error(id,-32601,"Method not found");jval_free(msg);continue;}

        /* 6b: params not object */
        if(obj_has(msg,"params")&&(!params||params->type!=JV_OBJECT)){send_error(id,-32602,"Invalid params");jval_free(msg);continue;}

        /* 6c: not initialized */
        if(!g_initialized&&strcmp(mname,"initialize")!=0&&strcmp(mname,"ping")!=0){
            send_error(id,-32002,"Server not initialized");jval_free(msg);continue;
        }

        /* 6d: dispatch */
        if(strcmp(mname,"initialize")==0){
            if(g_initialized){send_error(id,-32600,"Already initialized");jval_free(msg);continue;}
            if(!params){send_error(id,-32602,"Invalid params");jval_free(msg);continue;}
            jval *pv=obj_get(params,"protocolVersion");
            if(!pv||pv->type!=JV_STRING){send_error(id,-32602,"Invalid params");jval_free(msg);continue;}
            const char *ver=pv->str_val;
            if(strcmp(ver,"2025-06-18")!=0&&strcmp(ver,"2025-03-26")!=0&&strcmp(ver,"2024-11-05")!=0)ver="2025-06-18";
            g_initialized=1;
            printf("{\"jsonrpc\":\"2.0\",\"id\":");write_id(id);
            printf(",\"result\":{\"protocolVersion\":\"%s\",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}\n",ver);
        } else if(strcmp(mname,"ping")==0){
            printf("{\"jsonrpc\":\"2.0\",\"id\":");write_id(id);
            printf(",\"result\":{}}\n");
        } else if(strcmp(mname,"tools/list")==0){
            printf("{\"jsonrpc\":\"2.0\",\"id\":");write_id(id);
            printf(",\"result\":%s\n",TOOLS_LIST_RESULT);
        } else if(strcmp(mname,"tools/call")==0){
            handle_tools_call(msg,id);
        }

        jval_free(msg);
    }
    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>

/* ============ Dynamic string ============ */
typedef struct { char *d; size_t len, cap; } Str;
static void str_init(Str *s){s->d=NULL;s->len=s->cap=0;}
static void str_free(Str *s){free(s->d);s->d=NULL;s->len=s->cap=0;}
static void str_res(Str *s,size_t n){if(n>=s->cap){s->cap=n+1>s->len*2+1?n+1:s->len*2+1;s->d=realloc(s->d,s->cap);}}
static void str_app(Str *s,const char *d,size_t n){str_res(s,s->len+n+1);memcpy(s->d+s->len,d,n);s->len+=n;s->d[s->len]=0;}
static void str_appc(Str *s,char c){str_app(s,&c,1);}
static void str_apps(Str *s,const char *d){str_app(s,d,strlen(d));}

/* ============ Dynamic byte buffer ============ */
typedef struct { unsigned char *d; size_t len, cap; } Buf;
static void buf_init(Buf *b){b->d=NULL;b->len=b->cap=0;}
static void buf_free(Buf *b){free(b->d);b->d=NULL;b->len=b->cap=0;}
static void buf_res(Buf *b,size_t n){if(n>=b->cap){b->cap=n+1>b->len*2+1?n+1:b->len*2+1;b->d=realloc(b->d,b->cap);}}
static void buf_app(Buf *b,const unsigned char *d,size_t n){buf_res(b,b->len+n);memcpy(b->d+b->len,d,n);b->len+=n;}
static void buf_appc(Buf *b,unsigned char c){buf_app(b,&c,1);}

/* ============ CRC-32 ============ */
static unsigned crc_tab[256];
static void crc_init(void){for(unsigned i=0;i<256;i++){unsigned c=i;for(int k=0;k<8;k++)c=(c&1)?(0xEDB88320u^(c>>1)):(c>>1);crc_tab[i]=c;}}
static unsigned crc32_calc(const unsigned char *d,size_t n){unsigned c=0xFFFFFFFFu;for(size_t i=0;i<n;i++)c=crc_tab[(c^d[i])&0xFF]^(c>>8);return c^0xFFFFFFFFu;}

/* ============ Base64 ============ */
static int b64v(char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;if(c=='/')return 63;return -1;}
static void b64_dec(const char *src,size_t sl,Buf *out){int val=0,bits=0;for(size_t i=0;i<sl;i++){if(src[i]=='=')break;int v=b64v(src[i]);if(v<0)continue;val=(val<<6)|v;bits+=6;if(bits>=8){bits-=8;buf_appc(out,(unsigned char)((val>>bits)&0xFF));}}}

/* ============ Hex ============ */
static int hexv(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}

/* ============ QP decode ============ */
static void qp_dec(const char *src,size_t sl,Buf *out,int le){
    Str tmp;str_init(&tmp);
    size_t pos=0;
    while(pos<sl){
        size_t eol=pos;
        while(eol<sl){
            if(le==2&&eol+1<sl&&src[eol]=='\r'&&src[eol+1]=='\n')break;
            if(le==1&&src[eol]=='\n')break;
            eol++;
        }
        size_t tend=eol;
        while(tend>pos&&(src[tend-1]==' '||src[tend-1]=='\t'))tend--;
        if(tend>pos&&src[tend-1]=='='){
            str_app(&tmp,src+pos,tend-1-pos);
            pos=(eol<sl)?eol+le:sl;
        } else {
            str_app(&tmp,src+pos,tend-pos);
            if(eol<sl){str_app(&tmp,src+eol,le);pos=eol+le;}
            else pos=sl;
        }
    }
    for(size_t i=0;i<tmp.len;){
        if(tmp.d[i]=='='&&i+2<tmp.len){
            int h1=hexv(tmp.d[i+1]),h2=hexv(tmp.d[i+2]);
            if(h1>=0&&h2>=0){buf_appc(out,(unsigned char)(h1*16+h2));i+=3;continue;}
        }
        buf_appc(out,(unsigned char)tmp.d[i]);i++;
    }
    str_free(&tmp);
}

/* ============ Charset decode ============ */
static const unsigned cp1252_80_9f[]={
    0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
    0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
    0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
    0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
};

static int ci_cmp(const char*a,const char*b){while(*a&&*b){if(tolower((unsigned char)*a)!=tolower((unsigned char)*b))return tolower((unsigned char)*a)-tolower((unsigned char)*b);a++;b++;}return tolower((unsigned char)*a)-tolower((unsigned char)*b);}

typedef struct { unsigned *cps; size_t len; } CodePoints;
static void cp_init(CodePoints *c){c->cps=NULL;c->len=0;}
static void cp_free(CodePoints *c){free(c->cps);}

static void cp_append(CodePoints *c,unsigned cp){
    c->cps=realloc(c->cps,(c->len+1)*sizeof(unsigned));
    c->cps[c->len++]=cp;
}

static void decode_charset(const unsigned char *data,size_t len,const char *charset,CodePoints *out){
    cp_init(out);
    if(!ci_cmp(charset,"utf-8")){
        size_t i=0;
        while(i<len){
            unsigned cp;int n;
            unsigned char b=data[i];
            if(b<0x80){cp=b;n=1;}
            else if((b&0xE0)==0xC0){cp=b&0x1F;n=2;}
            else if((b&0xF0)==0xE0){cp=b&0x0F;n=3;}
            else if((b&0xF8)==0xF0){cp=b&0x07;n=4;}
            else {cp=b;n=1;}
            for(int j=1;j<n&&i+j<len;j++) cp=(cp<<6)|(data[i+j]&0x3F);
            cp_append(out,cp);
            i+=n;
        }
    } else if(!ci_cmp(charset,"windows-1252")){
        for(size_t i=0;i<len;i++){
            unsigned char b=data[i];
            if(b>=0x80&&b<=0x9F) cp_append(out,cp1252_80_9f[b-0x80]);
            else cp_append(out,b);
        }
    } else {
        /* us-ascii, iso-8859-1, and anything else: byte -> code point */
        for(size_t i=0;i<len;i++) cp_append(out,data[i]);
    }
}

/* ============ UTF-8 encode a code point ============ */
static void utf8_enc(Str *s,unsigned cp){
    if(cp<0x80){char c=cp;str_app(s,&c,1);}
    else if(cp<0x800){char c[2]={(char)(0xC0|(cp>>6)),(char)(0x80|(cp&0x3F))};str_app(s,c,2);}
    else if(cp<0x10000){char c[3]={(char)(0xE0|(cp>>12)),(char)(0x80|((cp>>6)&0x3F)),(char)(0x80|(cp&0x3F))};str_app(s,c,3);}
    else {char c[4]={(char)(0xF0|(cp>>18)),(char)(0x80|((cp>>12)&0x3F)),(char)(0x80|((cp>>6)&0x3F)),(char)(0x80|(cp&0x3F))};str_app(s,c,4);}
}

/* ============ Quoted string output ============ */
static void write_quoted(Str *out,const unsigned *cps,size_t len){
    str_appc(out,'"');
    for(size_t i=0;i<len;i++){
        unsigned cp=cps[i];
        if(cp=='\\') str_apps(out,"\\\\");
        else if(cp=='"') str_apps(out,"\\\"");
        else if(cp=='\n') str_apps(out,"\\n");
        else if(cp=='\t') str_apps(out,"\\t");
        else if(cp<0x20||(cp>=0x7F&&cp<=0x9F)){
            char buf[8];sprintf(buf,"\\u%04x",cp);str_apps(out,buf);
        } else {
            utf8_enc(out,cp);
        }
    }
    str_appc(out,'"');
}

/* ============ Headers ============ */
typedef struct { char *name; char *value; } Header;
typedef struct { Header *h; int n; } HeaderList;

static void hl_init(HeaderList *hl){hl->h=NULL;hl->n=0;}
static void hl_free(HeaderList *hl){for(int i=0;i<hl->n;i++){free(hl->h[i].name);free(hl->h[i].value);}free(hl->h);}

static void hl_add(HeaderList *hl,const char *name,const char *value){
    hl->h=realloc(hl->h,(hl->n+1)*sizeof(Header));
    hl->h[hl->n].name=strdup(name);
    hl->h[hl->n].value=strdup(value);
    hl->n++;
}

static const char *hl_get(const HeaderList *hl,const char *name){
    for(int i=0;i<hl->n;i++) if(ci_cmp(hl->h[i].name,name)==0) return hl->h[i].value;
    return NULL;
}

/* ============ Parameters ============ */
typedef struct { char *name; char *value; } Param;
typedef struct { Param *p; int n; } ParamList;

static void pl_init(ParamList *pl){pl->p=NULL;pl->n=0;}
static void pl_free(ParamList *pl){for(int i=0;i<pl->n;i++){free(pl->p[i].name);free(pl->p[i].value);}free(pl->p);}
static void pl_add(ParamList *pl,const char *name,const char *value){
    pl->p=realloc(pl->p,(pl->n+1)*sizeof(Param));
    pl->p[pl->n].name=strdup(name);
    pl->p[pl->n].value=strdup(value);
    pl->n++;
}
static const char *pl_get(const ParamList *pl,const char *name){
    for(int i=0;i<pl->n;i++) if(ci_cmp(pl->p[i].name,name)==0) return pl->p[i].value;
    return NULL;
}

/* ============ Parse parameter list from a value string ============ */
static void parse_params(const char *s,ParamList *pl){
    while(*s){
        while(*s==' '||*s=='\t')s++;
        if(*s!=';')break;
        s++;
        while(*s==' '||*s=='\t')s++;
        /* read attr name */
        size_t ns=0;char name[256];
        while(*s&&*s!='='&&*s!=' '&&*s!='\t'&&*s!=';'){if(ns<255)name[ns++]=*s;s++;}
        name[ns]=0;
        /* lowercase name */
        for(size_t i=0;i<ns;i++) name[i]=tolower((unsigned char)name[i]);
        while(*s==' '||*s=='\t')s++;
        if(*s!='=')break;
        s++;
        while(*s==' '||*s=='\t')s++;
        /* read value */
        Str val;str_init(&val);
        if(*s=='"'){
            s++;
            while(*s&&*s!='"'){
                if(*s=='\\'&&s[1]){s++;str_appc(&val,*s);s++;}
                else{str_appc(&val,*s);s++;}
            }
            if(*s=='"')s++;
        } else {
            while(*s&&*s!=';'&&*s!=' '&&*s!='\t'){str_appc(&val,*s);s++;}
        }
        pl_add(pl,name,val.d?val.d:"");
        str_free(&val);
    }
}

/* ============ RFC 2231 decoding ============ */
static void percent_decode(const char *src,size_t slen,Buf *out){
    for(size_t i=0;i<slen;){
        if(src[i]=='%'&&i+2<slen){
            int h1=hexv(src[i+1]),h2=hexv(src[i+2]);
            if(h1>=0&&h2>=0){buf_appc(out,(unsigned char)(h1*16+h2));i+=3;continue;}
        }
        buf_appc(out,(unsigned char)src[i]);i++;
    }
}

/* Returns decoded string or NULL if not RFC 2231 */
static char *rfc2231_decode(const ParamList *pl,const char *attr,const char **out_charset){
    /* Check for single form: attr* */
    char sname[512];
    snprintf(sname,sizeof(sname),"%s*",attr);
    const char *sv=pl_get(pl,sname);
    if(sv){
        /* percent-encoded, starts with charset'lang'value */
        const char *p=sv;
        const char *q1=strchr(p,'\'');
        if(!q1)return NULL;
        const char *q2=strchr(q1+1,'\'');
        if(!q2)return NULL;
        size_t clen=q1-p;
        char *cs=malloc(clen+1);
        memcpy(cs,p,clen);cs[clen]=0;
        *out_charset=cs; /* caller must free */
        Buf b;buf_init(&b);
        percent_decode(q2+1,strlen(q2+1),&b);
        char *result=malloc(b.len+1);
        memcpy(result,b.d,b.len);result[b.len]=0;
        buf_free(&b);
        return result;
    }
    /* Check for continuation segments: attr*0, attr*1, ..., attr*0*, attr*1*, ... */
    /* Collect all segments */
    struct { int idx; int pct; char *val; } segs[256];
    int nsegs=0;
    for(int i=0;i<256;i++){
        char sn[512];
        snprintf(sn,sizeof(sn),"%s*%d",attr,i);
        const char *v=pl_get(pl,sn);
        if(v){segs[nsegs].idx=i;segs[nsegs].pct=0;segs[nsegs].val=strdup(v);nsegs++;}
        snprintf(sn,sizeof(sn),"%s*%d*",attr,i);
        v=pl_get(pl,sn);
        if(v){segs[nsegs].idx=i;segs[nsegs].pct=1;segs[nsegs].val=strdup(v);nsegs++;}
    }
    if(nsegs==0)return NULL;
    /* Sort by idx */
    for(int i=0;i<nsegs-1;i++)for(int j=i+1;j<nsegs;j++){
        if(segs[j].idx<segs[i].idx){
            struct {int idx;int pct;char*val;}t=segs[i];segs[i]=segs[j];segs[j]=t;
        }
    }
    /* Find charset from first percent-encoded segment */
    const char *charset=NULL;
    char *cs_alloc=NULL;
    for(int i=0;i<nsegs;i++){
        if(segs[i].pct){
            const char *p=segs[i].val;
            const char *q1=strchr(p,'\'');
            const char *q2=q1?strchr(q1+1,'\''):NULL;
            if(q1&&q2){
                size_t clen=q1-p;
                cs_alloc=malloc(clen+1);
                memcpy(cs_alloc,p,clen);cs_alloc[clen]=0;
                charset=cs_alloc;
            }
            break;
        }
    }
    if(!charset){charset="us-ascii";}
    *out_charset=cs_alloc; /* may be NULL meaning us-ascii */
    /* Concatenate bytes */
    Buf b;buf_init(&b);
    for(int i=0;i<nsegs;i++){
        if(segs[i].pct){
            const char *p=segs[i].val;
            if(i==0||segs[i].idx==0){
                /* strip charset'lang' prefix if this is the first pct segment */
                const char *q1=strchr(p,'\'');
                const char *q2=q1?strchr(q1+1,'\''):NULL;
                if(q2) p=q2+1;
            }
            percent_decode(p,strlen(p),&b);
        } else {
            buf_app(&b,(unsigned char*)segs[i].val,strlen(segs[i].val));
        }
    }
    char *result=malloc(b.len+1);
    memcpy(result,b.d,b.len);result[b.len]=0;
    buf_free(&b);
    for(int i=0;i<nsegs;i++)free(segs[i].val);
    return result;
}

/* ============ Encoded-word decoding ============ */
static void decode_encoded_words(const char *src,Str *out){
    size_t slen=strlen(src);
    size_t pos=0;
    while(pos<slen){
        /* Find next encoded-word */
        const char *start=strstr(src+pos,"=?");
        if(!start){str_app(out,src+pos,slen-pos);break;}
        /* Output text before it */
        str_app(out,src+pos,start-(src+pos));
        /* Try to parse encoded-word at start */
        const char *p=start+2;
        /* charset: one or more chars other than ?, space, tab */
        const char *cs_start=p;
        while(*p&&*p!='?'&&*p!=' '&&*p!='\t')p++;
        if(*p!='?'||p==cs_start){/* not a valid encoded-word, output "=?" and continue */
            str_appc(out,'=');str_appc(out,'?');pos=start+2;continue;
        }
        size_t cs_len=p-cs_start;
        char *cs=malloc(cs_len+1);memcpy(cs,cs_start,cs_len);cs[cs_len]=0;
        p++; /* skip ? */
        /* encoding */
        if(*p!='B'&&*p!='b'&&*p!='Q'&&*p!='q'){
            str_appc(out,'=');str_appc(out,'?');pos=start+2;free(cs);continue;
        }
        char enc=*p;p++;
        if(*p!='?'){str_appc(out,'=');str_appc(out,'?');pos=start+2;free(cs);continue;}
        p++; /* skip ? */
        /* encoded-text: zero or more chars other than ?, space, tab */
        const char *et_start=p;
        while(*p&&*p!='?'&&*p!=' '&&*p!='\t')p++;
        if(*p!='?'){str_appc(out,'=');str_appc(out,'?');pos=start+2;free(cs);continue;}
        size_t et_len=p-et_start;
        p++; /* skip ? */
        if(*p!='='){str_appc(out,'=');str_appc(out,'?');pos=start+2;free(cs);continue;}
        p++; /* skip = */
        /* Valid encoded-word found from start to p */
        /* Collect this and subsequent adjacent encoded-words with same charset */
        /* For now, collect all adjacent same-charset encoded-words */
        Buf bytes;buf_init(&bytes);
        /* Decode this word */
        if(enc=='B'||enc=='b'){
            b64_dec(et_start,et_len,&bytes);
        } else {
            /* Q encoding */
            for(size_t i=0;i<et_len;){
                if(et_start[i]=='_'){buf_appc(&bytes,0x20);i++;}
                else if(et_start[i]=='='&&i+2<et_len){
                    int h1=hexv(et_start[i+1]),h2=hexv(et_start[i+2]);
                    if(h1>=0&&h2>=0){buf_appc(&bytes,(unsigned char)(h1*16+h2));i+=3;continue;}
                    buf_appc(&bytes,'=');i++;
                } else {buf_appc(&bytes,(unsigned char)et_start[i]);i++;}
            }
        }
        /* Strip *language from charset for comparison */
        char *cs_cmp=strdup(cs);
        char *star=strchr(cs_cmp,'*');
        if(star)*star=0;
        /* Look for adjacent encoded-words with same charset */
        const char *after=p;
        while(1){
            const char *gap=after;
            while(*gap==' '||*gap=='\t')gap++;
            if(*gap=='='&&gap[1]=='?'){
                /* Try to parse next encoded-word */
                const char *p2=gap+2;
                const char *cs2s=p2;
                while(*p2&&*p2!='?'&&*p2!=' '&&*p2!='\t')p2++;
                if(*p2!='?'||p2==cs2s){break;}
                size_t cs2_len=p2-cs2s;
                char *cs2=malloc(cs2_len+1);memcpy(cs2,cs2s,cs2_len);cs2[cs2_len]=0;
                p2++;
                if(*p2!='B'&&*p2!='b'&&*p2!='Q'&&*p2!='q'){free(cs2);break;}
                char enc2=*p2;p2++;
                if(*p2!='?'){free(cs2);break;}
                p2++;
                const char *et2=p2;
                while(*p2&&*p2!='?'&&*p2!=' '&&*p2!='\t')p2++;
                if(*p2!='?'){free(cs2);break;}
                size_t et2_len=p2-et2;p2++;
                if(*p2!='='){free(cs2);break;}
                p2++;
                /* Check charset match */
                char *cs2_cmp=strdup(cs2);
                char *star2=strchr(cs2_cmp,'*');
                if(star2)*star2=0;
                if(ci_cmp(cs_cmp,cs2_cmp)!=0){free(cs2);free(cs2_cmp);free(cs2_cmp);break;}
                free(cs2_cmp);
                /* Decode */
                if(enc2=='B'||enc2=='b'){
                    b64_dec(et2,et2_len,&bytes);
                } else {
                    for(size_t i=0;i<et2_len;){
                        if(et2[i]=='_'){buf_appc(&bytes,0x20);i++;}
                        else if(et2[i]=='='&&i+2<et2_len){
                            int h1=hexv(et2[i+1]),h2=hexv(et2[i+2]);
                            if(h1>=0&&h2>=0){buf_appc(&bytes,(unsigned char)(h1*16+h2));i+=3;continue;}
                            buf_appc(&bytes,'=');i++;
                        } else {buf_appc(&bytes,(unsigned char)et2[i]);i++;}
                    }
                }
                free(cs2);
                after=p2;
            } else break;
        }
        /* Decode bytes with charset */
        CodePoints cps;
        decode_charset(bytes.d,bytes.len,cs,&cps);
        /* Replace CRLF and lone CR with LF */
        /* Actually for encoded words, we just output the decoded code points */
        /* The CRLF replacement is for body text, not headers */
        for(size_t i=0;i<cps.len;i++) utf8_enc(out,cps.cps[i]);
        cp_free(&cps);
        buf_free(&bytes);
        free(cs_cmp);
        free(cs);
        pos=after;
    }
}

/* ============ Entity structure ============ */
typedef struct Entity {
    HeaderList headers;
    unsigned char *body;
    size_t body_len;
    char type[256],subtype[256];
    ParamList ct_params;
    char disp[256];
    ParamList cd_params;
    char cte[256];
    struct Entity *parts;
    int num_parts;
} Entity;

/* ============ Parse headers from data ============ */
/* Returns pointer to start of body, sets body_len */
static const char *parse_headers(const char *data,size_t len,HeaderList *hl,int le){
    hl_init(hl);
    size_t pos=0;
    Str cur_name;str_init(&cur_name);
    Str cur_val;str_init(&cur_val);
    int in_header=1;
    while(pos<len&&in_header){
        /* Find end of line */
        size_t eol=pos;
        while(eol<len){
            if(le==2&&eol+1<len&&data[eol]=='\r'&&data[eol+1]=='\n')break;
            if(le==1&&data[eol]=='\n')break;
            eol++;
        }
        size_t line_len=eol-pos;
        /* Check for blank line */
        if(line_len==0){
            /* End of headers */
            if(cur_name.len>0){
                /* trim trailing spaces/tabs from value */
                while(cur_val.len>0&&(cur_val.d[cur_val.len-1]==' '||cur_val.d[cur_val.len-1]=='\t'))
                    cur_val.len--;
                if(cur_val.d)cur_val.d[cur_val.len]=0;
                hl_add(hl,cur_name.d,cur_val.d?cur_val.d:"");
            }
            str_free(&cur_name);str_free(&cur_val);
            pos=eol+le;
            in_header=0;
            break;
        }
        /* Check for continuation (starts with space or tab) */
        if(pos<len&&(data[pos]==' '||data[pos]=='\t')){
            /* Continuation line: append to current value */
            /* The space/tab stays */
            str_appc(&cur_val,' ');
            str_app(&cur_val,data+pos+1,line_len-1);
            pos=eol+le;
            continue;
        }
        /* New header */
        if(cur_name.len>0){
            while(cur_val.len>0&&(cur_val.d[cur_val.len-1]==' '||cur_val.d[cur_val.len-1]=='\t'))
                cur_val.len--;
            if(cur_val.d)cur_val.d[cur_val.len]=0;
            hl_add(hl,cur_name.d,cur_val.d?cur_val.d:"");
        }
        str_free(&cur_name);str_free(&cur_val);
        str_init(&cur_name);str_init(&cur_val);
        /* Parse Name: value */
        size_t colon=pos;
        while(colon<eol&&data[colon]!=':')colon++;
        if(colon<eol){
            /* name */
            for(size_t i=pos;i<colon;i++) str_appc(&cur_name,(char)tolower((unsigned char)data[i]));
            /* value: skip leading spaces/tabs after colon */
            size_t vs=colon+1;
            while(vs<eol&&(data[vs]==' '||data[vs]=='\t'))vs++;
            str_app(&cur_val,data+vs,eol-vs);
        } else {
            /* No colon - treat whole line as name with empty value */
            str_app(&cur_name,data+pos,line_len);
        }
        pos=eol+le;
    }
    if(in_header&&cur_name.len>0){
        while(cur_val.len>0&&(cur_val.d[cur_val.len-1]==' '||cur_val.d[cur_val.len-1]=='\t'))
            cur_val.len--;
        if(cur_val.d)cur_val.d[cur_val.len]=0;
        hl_add(hl,cur_name.d,cur_val.d?cur_val.d:"");
    }
    str_free(&cur_name);str_free(&cur_val);
    return data+pos;
}

/* ============ Find delimiter lines in body ============ */
typedef struct { size_t line_start; size_t line_end; int is_close; } Delim;

static int find_delims(const char *body,size_t blen,const char *boundary,int le,Delim **out,int *nout){
    Delim *delims=NULL;int ndelims=0;
    size_t bl=strlen(boundary);
    size_t pos=0;
    while(pos<=blen){
        size_t eol=pos;
        while(eol<blen){
            if(le==2&&eol+1<blen&&body[eol]=='\r'&&body[eol+1]=='\n')break;
            if(le==1&&body[eol]=='\n')break;
            eol++;
        }
        /* Check if this line is a delimiter */
        /* Line content is body[pos..eol] */
        size_t llen=eol-pos;
        int is_close=0,is_delim=0;
        if(llen>=bl+2&&memcmp(body+pos,"--",2)==0&&memcmp(body+pos+2,boundary,bl)==0){
            /* Check what follows */
            size_t after=2+bl;
            if(after<llen&&body[pos+after]=='-'){
                /* --B-- */
                after++;
                is_close=1;
                /* Check rest is only spaces/tabs */
                is_delim=1;
                for(size_t i=after;i<llen;i++){
                    if(body[pos+i]!=' '&&body[pos+i]!='\t'){is_delim=0;break;}
                }
            } else {
                /* --B followed by only spaces/tabs */
                is_delim=1;
                for(size_t i=after;i<llen;i++){
                    if(body[pos+i]!=' '&&body[pos+i]!='\t'){is_delim=0;break;}
                }
            }
        }
        if(is_delim){
            delims=realloc(delims,(ndelims+1)*sizeof(Delim));
            delims[ndelims].line_start=pos;
            delims[ndelims].line_end=eol;
            delims[ndelims].is_close=is_close;
            ndelims++;
            if(is_close)break;
        }
        if(eol>=blen)break;
        pos=eol+le;
    }
    *out=delims;*nout=ndelims;
    return ndelims;
}

/* ============ Parse entity ============ */
static void parse_entity(Entity *ent,const char *data,size_t len,int le){
    hl_init(&ent->headers);
    ent->body=NULL;ent->body_len=0;
    ent->type[0]=0;ent->subtype[0]=0;
    pl_init(&ent->ct_params);
    ent->disp[0]=0;
    pl_init(&ent->cd_params);
    ent->cte[0]=0;
    ent->parts=NULL;ent->num_parts=0;

    /* Parse headers */
    const char *body_start=parse_headers(data,len,&ent->headers,le);
    size_t body_off=body_start-data;
    ent->body=(unsigned char*)(data+body_off);
    ent->body_len=len-body_off;

    /* Content-Type */
    const char *ct=hl_get(&ent->headers,"content-type");
    if(ct){
        /* Parse type/subtype */
        const char *p=ct;
        while(*p==' '||*p=='\t')p++;
        /* read type */
        size_t i=0;
        while(*p&&*p!='/'&&*p!=' '&&*p!='\t'&&*p!=';'){if(i<255)ent->type[i++]=*p;p++;}
        ent->type[i]=0;
        for(size_t j=0;j<i;j++)ent->type[j]=tolower((unsigned char)ent->type[j]);
        while(*p==' '||*p=='\t')p++;
        if(*p=='/'){
            p++;
            while(*p==' '||*p=='\t')p++;
            i=0;
            while(*p&&*p!=' '&&*p!='\t'&&*p!=';'){if(i<255)ent->subtype[i++]=*p;p++;}
            ent->subtype[i]=0;
            for(size_t j=0;j<i;j++)ent->subtype[j]=tolower((unsigned char)ent->subtype[j]);
        }
        /* Parse params */
        while(*p&&*p!=';')p++;
        if(*p==';')parse_params(p,&ent->ct_params);
    } else {
        strcpy(ent->type,"text");
        strcpy(ent->subtype,"plain");
    }

    /* Content-Disposition */
    const char *cd=hl_get(&ent->headers,"content-disposition");
    if(cd){
        const char *p=cd;
        while(*p==' '||*p=='\t')p++;
        size_t i=0;
        while(*p&&*p!=' '&&*p!='\t'&&*p!=';'){if(i<255)ent->disp[i++]=*p;p++;}
        ent->disp[i]=0;
        for(size_t j=0;j<i;j++)ent->disp[j]=tolower((unsigned char)ent->disp[j]);
        while(*p&&*p!=';')p++;
        if(*p==';')parse_params(p,&ent->cd_params);
    }

    /* Content-Transfer-Encoding */
    const char *cte=hl_get(&ent->headers,"content-transfer-encoding");
    if(cte){
        while(*cte==' '||*cte=='\t')cte++;
        size_t i=0;
        while(*cte&&*cte!=' '&&*cte!='\t'){if(i<255)ent->cte[i++]=tolower((unsigned char)*cte);cte++;}
        ent->cte[i]=0;
    } else {
        strcpy(ent->cte,"7bit");
    }

    /* Multipart? */
    if(ci_cmp(ent->type,"multipart")==0){
        const char *boundary=pl_get(&ent->ct_params,"boundary");
        if(boundary){
            Delim *delims=NULL;int ndelims=0;
            find_delims((const char*)ent->body,ent->body_len,boundary,le,&delims,&ndelims);
            if(ndelims>=2){
                /* Parts are between consecutive delimiters */
                int nparts=0;
                for(int i=0;i<ndelims-1;i++){
                    if(delims[i].is_close)break;
                    nparts++;
                }
                ent->parts=calloc(nparts,sizeof(Entity));
                ent->num_parts=nparts;
                int pi=0;
                for(int i=0;i<ndelims-1;i++){
                    if(delims[i].is_close)break;
                    /* Part content: from after delims[i] line break to before delims[i+1] line break */
                    size_t part_start=delims[i].line_end;
                    if(part_start<ent->body_len){
                        if(le==2&&part_start+1<ent->body_len&&ent->body[part_start]=='\r'&&ent->body[part_start+1]=='\n')
                            part_start+=2;
                        else if(le==1&&ent->body[part_start]=='\n')
                            part_start+=1;
                    }
                    /* End: before the line break preceding delims[i+1] */
                    size_t part_end=delims[i+1].line_start;
                    /* Remove the line break before the next delimiter */
                    if(part_end>0){
                        if(le==2&&part_end>=2&&ent->body[part_end-2]=='\r'&&ent->body[part_end-1]=='\n')
                            part_end-=2;
                        else if(le==1&&part_end>=1&&ent->body[part_end-1]=='\n')
                            part_end-=1;
                    }
                    if(part_end<part_start)part_end=part_start;
                    parse_entity(&ent->parts[pi],(const char*)ent->body+part_start,part_end-part_start,le);
                    pi++;
                }
            }
            free(delims);
        }
    }
}

/* ============ Transfer decode ============ */
static void transfer_decode(Entity *ent,Buf *out,int le){
    if(ci_cmp(ent->cte,"base64")==0){
        b64_dec((const char*)ent->body,ent->body_len,out);
    } else if(ci_cmp(ent->cte,"quoted-printable")==0){
        qp_dec((const char*)ent->body,ent->body_len,out,le);
    } else {
        buf_app(out,ent->body,ent->body_len);
    }
}

/* ============ Get charset for a text part ============ */
static void get_charset(Entity *ent,char *cs,size_t cs_sz){
    const char *c=pl_get(&ent->ct_params,"charset");
    if(c){
        size_t i=0;
        while(*c&&i<cs_sz-1){cs[i++]=tolower((unsigned char)*c);c++;}
        cs[i]=0;
    } else {
        strcpy(cs,"us-ascii");
    }
}

/* ============ Get filename ============ */
static void get_filename(Entity *ent,Str *out){
    /* Priority: CD filename RFC2231, CD filename, CT name RFC2231, CT name */
    const char *result=NULL;
    char *alloc=NULL;
    const char *charset=NULL;
    char *cs_alloc=NULL;

    /* Try CD filename* (RFC 2231) */
    alloc=rfc2231_decode(&ent->cd_params,"filename",&cs_alloc);
    if(alloc){
        charset=cs_alloc?cs_alloc:"us-ascii";
        result=alloc;
        goto do_decode;
    }
    /* Try CD filename (plain) */
    result=pl_get(&ent->cd_params,"filename");
    if(result){
        /* Decode encoded-words */
        decode_encoded_words(result,out);
        return;
    }
    /* Try CT name RFC2231 */
    alloc=rfc2231_decode(&ent->ct_params,"name",&cs_alloc);
    if(alloc){
        charset=cs_alloc?cs_alloc:"us-ascii";
        result=alloc;
        goto do_decode;
    }
    /* Try CT name (plain) */
    result=pl_get(&ent->ct_params,"name");
    if(result){
        decode_encoded_words(result,out);
        return;
    }
    return;

do_decode:
    /* Decode bytes with charset */
    CodePoints cps;
    decode_charset((unsigned char*)result,strlen(result),charset,&cps);
    for(size_t i=0;i<cps.len;i++) utf8_enc(out,cps.cps[i]);
    cp_free(&cps);
    free(alloc);free(cs_alloc);
}

/* ============ Decode text body ============ */
static void decode_text(Entity *ent,int le,CodePoints *out){
    Buf raw;buf_init(&raw);
    transfer_decode(ent,&raw,le);
    char cs[256];get_charset(ent,cs,sizeof(cs));
    decode_charset(raw.d,raw.len,cs,out);
    buf_free(&raw);
    /* Replace CRLF and lone CR with LF */
    size_t w=0;
    for(size_t i=0;i<out->len;i++){
        if(out->cps[i]==0x0D){
            if(i+1<out->len&&out->cps[i+1]==0x0A) i++; /* skip the LF */
            out->cps[w++]=0x0A;
        } else {
            out->cps[w++]=out->cps[i];
        }
    }
    out->len=w;
}

/* ============ Output ============ */
static void print_entity(Entity *ent,int indent,int le){
    /* Indent */
    for(int i=0;i<indent*2;i++) putchar(' ');

    if(ci_cmp(ent->type,"multipart")==0){
        printf("multipart/%s parts=%d\n",ent->subtype,ent->num_parts);
        for(int i=0;i<ent->num_parts;i++){
            print_entity(&ent->parts[i],indent+1,le);
        }
    } else {
        int is_text=(ci_cmp(ent->type,"text")==0&&ci_cmp(ent->disp,"attachment")!=0);
        if(is_text){
            char cs[256];get_charset(ent,cs,sizeof(cs));
            CodePoints cps;
            decode_text(ent,le,&cps);
            printf("text/%s charset=%s cte=%s chars=%zu\n",ent->subtype,cs,ent->cte,cps.len);
            for(int i=0;i<(indent+1)*2;i++) putchar(' ');
            Str qs;str_init(&qs);
            write_quoted(&qs,cps.cps,cps.len);
            printf("%s\n",qs.d?qs.d:"\"\"");
            str_free(&qs);
            cp_free(&cps);
        } else {
            Buf raw;buf_init(&raw);
            transfer_decode(ent,&raw,le);
            unsigned crc=crc32_calc(raw.d,raw.len);
            Str fname;str_init(&fname);
            get_filename(ent,&fname);
            const char *disp_out=ent->disp[0]?ent->disp:"-";
            printf("%s/%s cte=%s disposition=%s name=",ent->type,ent->subtype,ent->cte,disp_out);
            if(fname.len>0){
                /* fname is already UTF-8 encoded string, need to make it a quoted string */
                /* Actually we need to convert back to code points for quoting */
                /* Let's re-decode as UTF-8 */
                CodePoints cps;
                decode_charset((unsigned char*)fname.d,fname.len,"utf-8",&cps);
                Str qs;str_init(&qs);
                write_quoted(&qs,cps.cps,cps.len);
                printf("%s",qs.d?qs.d:"\"\"");
                str_free(&qs);
                cp_free(&cps);
            } else {
                printf("-");
            }
            printf(" size=%zu crc32=%08x\n",raw.len,crc);
            str_free(&fname);
            buf_free(&raw);
        }
    }
}

/* ============ Free entity ============ */
static void free_entity(Entity *ent){
    hl_free(&ent->headers);
    pl_free(&ent->ct_params);
    pl_free(&ent->cd_params);
    for(int i=0;i<ent->num_parts;i++) free_entity(&ent->parts[i]);
    free(ent->parts);
}

/* ============ Main ============ */
static int cmp_str(const void *a,const void *b){
    return strcmp(*(const char**)a,*(const char**)b);
}

int main(int argc,char *argv[]){
    crc_init();
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}

    DIR *dir=opendir(argv[1]);
    if(!dir){perror("opendir");return 1;}

    /* Collect .eml files */
    char **files=NULL;int nf=0;
    struct dirent *de;
    while((de=readdir(dir))){
        size_t l=strlen(de->d_name);
        if(l>4&&strcmp(de->d_name+l-4,".eml")==0){
            files=realloc(files,(nf+1)*sizeof(char*));
            files[nf++]=strdup(de->d_name);
        }
    }
    closedir(dir);
    qsort(files,nf,sizeof(char*),cmp_str);

    for(int fi=0;fi<nf;fi++){
        /* Read file */
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE *f=fopen(path,"rb");
        if(!f)continue;
        fseek(f,0,SEEK_END);
        long fsz=ftell(f);
        fseek(f,0,SEEK_SET);
        char *data=malloc(fsz+1);
        size_t rd=fread(data,1,fsz,f);
        fclose(f);
        data[rd]=0;

        /* Detect line ending */
        int le=1;
        for(size_t i=0;i+1<rd;i++){
            if(data[i]=='\r'&&data[i+1]=='\n'){le=2;break;}
        }

        /* Parse */
        Entity msg;
        parse_entity(&msg,data,rd,le);

        /* Output */
        printf("== %s\n",files[fi]);

        /* From */
        const char *from=hl_get(&msg.headers,"from");
        if(from){
            Str s;str_init(&s);
            decode_encoded_words(from,&s);
            /* Convert to code points for quoting */
            CodePoints cps;
            decode_charset((unsigned char*)s.d,s.len,"utf-8",&cps);
            Str qs;str_init(&qs);
            write_quoted(&qs,cps.cps,cps.len);
            printf("From: %s\n",qs.d?qs.d:"\"\"");
            str_free(&qs);cp_free(&cps);str_free(&s);
        } else {
            printf("From: -\n");
        }

        /* Subject */
        const char *subj=hl_get(&msg.headers,"subject");
        if(subj){
            Str s;str_init(&s);
            decode_encoded_words(subj,&s);
            CodePoints cps;
            decode_charset((unsigned char*)s.d,s.len,"utf-8",&cps);
            Str qs;str_init(&qs);
            write_quoted(&qs,cps.cps,cps.len);
            printf("Subject: %s\n",qs.d?qs.d:"\"\"");
            str_free(&qs);cp_free(&cps);str_free(&s);
        } else {
            printf("Subject: -\n");
        }

        /* Tree */
        print_entity(&msg,0,le);

        if(fi<nf-1) printf("\n");

        free_entity(&msg);
        free(data);
        free(files[fi]);
    }
    free(files);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

// ===== TYPES =====
type Val = bigint | boolean | string | Val[] | FuncVal | null;

interface UserFunc {
  kind: 'user';
  params: string[];
  body: Stmt[];
  scope: Scope;
}

interface BuiltinFunc {
  kind: 'builtin';
  name: string;
  arity: number; // -1 for variadic
  fn: (args: Val[], line: number) => Val;
}

type FuncVal = UserFunc | BuiltinFunc;

class Scope {
  vars: Map<string, Val> = new Map();
  parent: Scope | null;
  constructor(parent: Scope | null = null) { this.parent = parent; }
  get(name: string): Val | undefined {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) return s.vars.get(name)!; s = s.parent; }
    return undefined;
  }
  has(name: string): boolean {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) return true; s = s.parent; }
    return false;
  }
  set(name: string, val: Val): boolean {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) { s.vars.set(name, val); return true; } s = s.parent; }
    return false;
  }
  declare(name: string, val: Val): void { this.vars.set(name, val); }
}

// ===== LEXER =====
enum TT {
  INT, STR, IDENT,
  LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
  AND, OR, NOT, TRUE, FALSE, NIL,
  EQ, NEQ, LTE, GTE, LT, GT, ASSIGN,
  PLUS, MINUS, STAR, SLASH, PERCENT,
  LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE,
  COMMA, SEMI, EOF
}

interface Token { type: TT; str: string; intVal?: bigint; line: number; }

const KW: Record<string, TT> = {
  let: TT.LET, fn: TT.FN, if: TT.IF, else: TT.ELSE, while: TT.WHILE,
  for: TT.FOR, in: TT.IN, return: TT.RETURN, break: TT.BREAK,
  continue: TT.CONTINUE, and: TT.AND, or: TT.OR, not: TT.NOT,
  true: TT.TRUE, false: TT.FALSE, nil: TT.NIL
};

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0, line = 1;
  while (pos < src.length) {
    const c = src[pos];
    if (c === ' ' || c === '\t' || c === '\r') { pos++; continue; }
    if (c === '\n') { pos++; line++; continue; }
    if (c === '#') { while (pos < src.length && src[pos] !== '\n') pos++; continue; }
    if (c >= '0' && c <= '9') {
      let s = pos;
      while (pos < src.length && src[pos] >= '0' && src[pos] <= '9') pos++;
      tokens.push({ type: TT.INT, str: src.slice(s, pos), intVal: BigInt(src.slice(s, pos)), line });
      continue;
    }
    if (c === '"') {
      pos++; let s = '';
      while (pos < src.length && src[pos] !== '"') {
        if (src[pos] === '\\') {
          pos++;
          if (src[pos] === 'n') s += '\n';
          else if (src[pos] === 't') s += '\t';
          else if (src[pos] === '"') s += '"';
          else if (src[pos] === '\\') s += '\\';
          else s += src[pos];
          pos++;
        } else { s += src[pos]; pos++; }
      }
      pos++;
      tokens.push({ type: TT.STR, str: s, line });
      continue;
    }
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c === '_') {
      let s = pos;
      while (pos < src.length && ((src[pos] >= 'A' && src[pos] <= 'Z') || (src[pos] >= 'a' && src[pos] <= 'z') || (src[pos] >= '0' && src[pos] <= '9') || src[pos] === '_')) pos++;
      const w = src.slice(s, pos);
      tokens.push({ type: KW[w] ?? TT.IDENT, str: w, line });
      continue;
    }
    const two = src.slice(pos, pos + 2);
    if (two === '==') { tokens.push({ type: TT.EQ, str: '==', line }); pos += 2; continue; }
    if (two === '!=') { tokens.push({ type: TT.NEQ, str: '!=', line }); pos += 2; continue; }
    if (two === '<=') { tokens.push({ type: TT.LTE, str: '<=', line }); pos += 2; continue; }
    if (two === '>=') { tokens.push({ type: TT.GTE, str: '>=', line }); pos += 2; continue; }
    let tt: TT;
    switch (c) {
      case '<': tt = TT.LT; break; case '>': tt = TT.GT; break;
      case '=': tt = TT.ASSIGN; break; case '+': tt = TT.PLUS; break;
      case '-': tt = TT.MINUS; break; case '*': tt = TT.STAR; break;
      case '/': tt = TT.SLASH; break; case '%': tt = TT.PERCENT; break;
      case '(': tt = TT.LPAREN; break; case ')': tt = TT.RPAREN; break;
      case '[': tt = TT.LBRACKET; break; case ']': tt = TT.RBRACKET; break;
      case '{': tt = TT.LBRACE; break; case '}': tt = TT.RBRACE; break;
      case ',': tt = TT.COMMA; break; case ';': tt = TT.SEMI; break;
      default: throw new Error(`Unexpected char '${c}' at line ${line}`);
    }
    tokens.push({ type: tt, str: c, line }); pos++;
  }
  tokens.push({ type: TT.EOF, str: '', line });
  return tokens;
}

// ===== AST =====
type Expr =
  | { kind: 'int'; value: bigint; line: number }
  | { kind: 'str'; value: string; line: number }
  | { kind: 'bool'; value: boolean; line: number }
  | { kind: 'nil'; line: number }
  | { kind: 'ident'; name: string; line: number }
  | { kind: 'list'; elements: Expr[]; line: number }
  | { kind: 'fn'; params: string[]; body: Stmt[]; line: number }
  | { kind: 'binary'; op: string; left: Expr; right: Expr; line: number }
  | { kind: 'neg'; operand: Expr; line: number }
  | { kind: 'not'; operand: Expr; line: number }
  | { kind: 'call'; callee: Expr; args: Expr[]; line: number }
  | { kind: 'index'; obj: Expr; index: Expr; line: number };

type ElseBranch = { kind: 'block'; body: Stmt[] } | { kind: 'if'; stmt: Stmt };

type Stmt =
  | { kind: 'let'; name: string; expr: Expr; line: number }
  | { kind: 'fnDecl'; name: string; params: string[]; body: Stmt[]; line: number }
  | { kind: 'if'; cond: Expr; then: Stmt[]; elseBranch: ElseBranch | null; line: number }
  | { kind: 'while'; cond: Expr; body: Stmt[]; line: number }
  | { kind: 'for'; varName: string; iterable: Expr; body: Stmt[]; line: number }
  | { kind: 'return'; expr: Expr | null; line: number }
  | { kind: 'break'; line: number }
  | { kind: 'continue'; line: number }
  | { kind: 'assign'; name: string; expr: Expr; line: number }
  | { kind: 'indexAssign'; obj: Expr; index: Expr; value: Expr; line: number }
  | { kind: 'expr'; expr: Expr; line: number };

// ===== PARSER =====
class Parser {
  tokens: Token[]; pos = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  peek(): Token { return this.tokens[this.pos]; }
  advance(): Token { return this.tokens[this.pos++]; }
  expect(type: TT): Token {
    const t = this.advance();
    if (t.type !== type) throw new Error(`Expected ${type} but got ${t.type} at line ${t.line}`);
    return t;
  }
  match(type: TT): boolean {
    if (this.peek().type === type) { this.pos++; return true; }
    return false;
  }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek().type !== TT.EOF) stmts.push(this.parseStmt());
    return stmts;
  }

  parseStmt(): Stmt {
    const t = this.peek();
    switch (t.type) {
      case TT.LET: return this.parseLet();
      case TT.FN: return this.parseFnDecl();
      case TT.IF: return this.parseIf();
      case TT.WHILE: return this.parseWhile();
      case TT.FOR: return this.parseFor();
      case TT.RETURN: return this.parseReturn();
      case TT.BREAK: this.advance(); this.expect(TT.SEMI); return { kind: 'break', line: t.line };
      case TT.CONTINUE: this.advance(); this.expect(TT.SEMI); return { kind: 'continue', line: t.line };
      case TT.IDENT: {
        // Could be assignment or expression statement
        if (this.tokens[this.pos + 1]?.type === TT.ASSIGN) {
          const name = this.advance().str; this.advance(); // skip =
          const expr = this.parseExpr(); this.expect(TT.SEMI);
          return { kind: 'assign', name, expr, line: t.line };
        }
        if (this.tokens[this.pos + 1]?.type === TT.LBRACKET) {
          // Could be index assignment: IDENT "[" expr "]" "=" expr ";"
          // We need to parse postfix first, then check for =
          const expr = this.parseExpr();
          if (this.peek().type === TT.ASSIGN) {
            // expr should be an index expression
            this.advance(); // skip =
            const value = this.parseExpr(); this.expect(TT.SEMI);
            if (expr.kind !== 'index') throw new Error('Invalid index assignment target');
            return { kind: 'indexAssign', obj: expr.obj, index: expr.index, value, line: expr.line };
          }
          this.expect(TT.SEMI);
          return { kind: 'expr', expr, line: t.line };
        }
        const expr = this.parseExpr(); this.expect(TT.SEMI);
        return { kind: 'expr', expr, line: t.line };
      }
      default: {
        // Could be a postfix expression statement (e.g., function call)
        const expr = this.parseExpr(); this.expect(TT.SEMI);
        return { kind: 'expr', expr, line: t.line };
      }
    }
  }

  parseLet(): Stmt {
    const t = this.advance(); // let
    const name = this.expect(TT.IDENT).str;
    this.expect(TT.ASSIGN);
    const expr = this.parseExpr();
    this.expect(TT.SEMI);
    return { kind: 'let', name, expr, line: t.line };
  }

  parseFnDecl(): Stmt {
    const t = this.advance(); // fn
    const name = this.expect(TT.IDENT).str;
    this.expect(TT.LPAREN);
    const params = this.parseParams();
    this.expect(TT.RPAREN);
    const body = this.parseBlock();
    return { kind: 'fnDecl', name, params, body, line: t.line };
  }

  parseIf(): Stmt {
    const t = this.advance(); // if
    const cond = this.parseExpr();
    const then = this.parseBlock();
    let elseBranch: ElseBranch | null = null;
    if (this.peek().type === TT.ELSE) {
      this.advance();
      if (this.peek().type === TT.IF) {
        elseBranch = { kind: 'if', stmt: this.parseIf() };
      } else {
        elseBranch = { kind: 'block', body: this.parseBlock() };
      }
    }
    return { kind: 'if', cond, then, elseBranch, line: t.line };
  }

  parseWhile(): Stmt {
    const t = this.advance(); // while
    const cond = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'while', cond, body, line: t.line };
  }

  parseFor(): Stmt {
    const t = this.advance(); // for
    const varName = this.expect(TT.IDENT).str;
    this.expect(TT.IN);
    const iterable = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'for', varName, iterable, body, line: t.line };
  }

  parseReturn(): Stmt {
    const t = this.advance(); // return
    let expr: Expr | null = null;
    if (this.peek().type !== TT.SEMI) expr = this.parseExpr();
    this.expect(TT.SEMI);
    return { kind: 'return', expr, line: t.line };
  }

  parseBlock(): Stmt[] {
    this.expect(TT.LBRACE);
    const stmts: Stmt[] = [];
    while (this.peek().type !== TT.RBRACE) stmts.push(this.parseStmt());
    this.expect(TT.RBRACE);
    return stmts;
  }

  parseParams(): string[] {
    const params: string[] = [];
    if (this.peek().type === TT.RPAREN) return params;
    params.push(this.expect(TT.IDENT).str);
    while (this.match(TT.COMMA)) params.push(this.expect(TT.IDENT).str);
    return params;
  }

  // Expression parsing with precedence
  parseExpr(): Expr { return this.parseOr(); }

  parseOr(): Expr {
    let left = this.parseAnd();
    while (this.peek().type === TT.OR) {
      const t = this.advance();
      const right = this.parseAnd();
      left = { kind: 'binary', op: 'or', left, right, line: t.line };
    }
    return left;
  }

  parseAnd(): Expr {
    let left = this.parseNot();
    while (this.peek().type === TT.AND) {
      const t = this.advance();
      const right = this.parseNot();
      left = { kind: 'binary', op: 'and', left, right, line: t.line };
    }
    return left;
  }

  parseNot(): Expr {
    if (this.peek().type === TT.NOT) {
      const t = this.advance();
      const operand = this.parseNot();
      return { kind: 'not', operand, line: t.line };
    }
    return this.parseComparison();
  }

  parseComparison(): Expr {
    let left = this.parseAdd();
    while (this.peek().type === TT.EQ || this.peek().type === TT.NEQ ||
           this.peek().type === TT.LT || this.peek().type === TT.LTE ||
           this.peek().type === TT.GT || this.peek().type === TT.GTE) {
      const t = this.advance();
      const right = this.parseAdd();
      left = { kind: 'binary', op: t.str, left, right, line: t.line };
    }
    return left;
  }

  parseAdd(): Expr {
    let left = this.parseMul();
    while (this.peek().type === TT.PLUS || this.peek().type === TT.MINUS) {
      const t = this.advance();
      const right = this.parseMul();
      left = { kind: 'binary', op: t.str, left, right, line: t.line };
    }
    return left;
  }

  parseMul(): Expr {
    let left = this.parseUnary();
    while (this.peek().type === TT.STAR || this.peek().type === TT.SLASH || this.peek().type === TT.PERCENT) {
      const t = this.advance();
      const right = this.parseUnary();
      left = { kind: 'binary', op: t.str, left, right, line: t.line };
    }
    return left;
  }

  parseUnary(): Expr {
    if (this.peek().type === TT.MINUS) {
      const t = this.advance();
      const operand = this.parseUnary();
      return { kind: 'neg', operand, line: t.line };
    }
    return this.parsePostfix();
  }

  parsePostfix(): Expr {
    let expr = this.parsePrimary();
    while (true) {
      if (this.peek().type === TT.LPAREN) {
        const t = this.advance();
        const args: Expr[] = [];
        if (this.peek().type !== TT.RPAREN) {
          args.push(this.parseExpr());
          while (this.match(TT.COMMA)) args.push(this.parseExpr());
        }
        this.expect(TT.RPAREN);
        expr = { kind: 'call', callee: expr, args, line: t.line };
      } else if (this.peek().type === TT.LBRACKET) {
        const t = this.advance();
        const index = this.parseExpr();
        this.expect(TT.RBRACKET);
        expr = { kind: 'index', obj: expr, index, line: t.line };
      } else break;
    }
    return expr;
  }

  parsePrimary(): Expr {
    const t = this.peek();
    switch (t.type) {
      case TT.INT: this.advance(); return { kind: 'int', value: t.intVal!, line: t.line };
      case TT.STR: this.advance(); return { kind: 'str', value: t.str, line: t.line };
      case TT.TRUE: this.advance(); return { kind: 'bool', value: true, line: t.line };
      case TT.FALSE: this.advance(); return { kind: 'bool', value: false, line: t.line };
      case TT.NIL: this.advance(); return { kind: 'nil', line: t.line };
      case TT.IDENT: this.advance(); return { kind: 'ident', name: t.str, line: t.line };
      case TT.LPAREN: {
        this.advance();
        const expr = this.parseExpr();
        this.expect(TT.RPAREN);
        return expr;
      }
      case TT.LBRACKET: {
        this.advance();
        const elements: Expr[] = [];
        if (this.peek().type !== TT.RBRACKET) {
          elements.push(this.parseExpr());
          while (this.match(TT.COMMA)) elements.push(this.parseExpr());
        }
        this.expect(TT.RBRACKET);
        return { kind: 'list', elements, line: t.line };
      }
      case TT.FN: {
        this.advance();
        this.expect(TT.LPAREN);
        const params = this.parseParams();
        this.expect(TT.RPAREN);
        const body = this.parseBlock();
        return { kind: 'fn', params, body, line: t.line };
      }
      default:
        throw new Error(`Unexpected token ${t.type} at line ${t.line}`);
    }
  }
}

// ===== RUNTIME =====
const INT_MIN = -(1n << 63n);
const INT_MAX = (1n << 63n) - 1n;

class RuntimeError {
  constructor(public line: number, public msg: string) {}
}
class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { constructor(public value: Val) {} }

function typeOf(v: Val): string {
  if (v === null) return 'nil';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'string') return 'string';
  if (Array.isArray(v)) return 'list';
  return 'function';
}

function truthy(v: Val): boolean {
  if (v === null) return false;
  if (typeof v === 'boolean') return v;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'string') return v !== '';
  if (Array.isArray(v)) return v.length > 0;
  return true;
}

function checkInt(v: bigint, line: number): bigint {
  if (v < INT_MIN || v > INT_MAX) throw new RuntimeError(line, 'integer overflow');
  return v;
}

function valuesEqual(a: Val, b: Val): boolean {
  const ta = typeOf(a), tb = typeOf(b);
  if (ta !== tb) return false;
  if (ta === 'nil') return true;
  if (ta === 'int') return (a as bigint) === (b as bigint);
  if (ta === 'bool') return (a as boolean) === (b as boolean);
  if (ta === 'string') return (a as string) === (b as string);
  if (ta === 'list') {
    const aa = a as Val[], bb = b as Val[];
    if (aa.length !== bb.length) return false;
    for (let i = 0; i < aa.length; i++) if (!valuesEqual(aa[i], bb[i])) return false;
    return true;
  }
  return a === b;
}

function displayVal(v: Val, inList: boolean, ancestors: Set<Val[]>): string {
  if (v === null) return 'nil';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'string') {
    if (!inList) return v;
    let s = '"';
    for (const ch of v) {
      if (ch === '\\') s += '\\\\';
      else if (ch === '"') s += '\\"';
      else if (ch === '\n') s += '\\n';
      else if (ch === '\t') s += '\\t';
      else s += ch;
    }
    return s + '"';
  }
  if (Array.isArray(v)) {
    if (ancestors.has(v)) return '[...]';
    ancestors.add(v);
    const parts = v.map(e => displayVal(e, true, ancestors));
    ancestors.delete(v);
    return '[' + parts.join(', ') + ']';
  }
  return '<fn>';
}

function displayStr(v: Val): string {
  return displayVal(v, false, new Set());
}

// ===== INTERPRETER =====
class Interpreter {
  output: string[] = [];
  globalScope: Scope;

  constructor() {
    this.globalScope = new Scope(this.makeBuiltinScope());
  }

  makeBuiltinScope(): Scope {
    const s = new Scope(null);
    s.declare('print', { kind: 'builtin', name: 'print', arity: -1, fn: (args, line) => {
      const parts = args.map(a => displayVal(a, false, new Set()));
      this.output.push(parts.join(' ') + '\n');
      return null;
    }} as BuiltinFunc);
    s.declare('str', { kind: 'builtin', name: 'str', arity: 1, fn: (args, line) => {
      return displayStr(args[0]);
    }} as BuiltinFunc);
    s.declare('type', { kind: 'builtin', name: 'type', arity: 1, fn: (args, line) => {
      return typeOf(args[0]);
    }} as BuiltinFunc);
    s.declare('len', { kind: 'builtin', name: 'len', arity: 1, fn: (args, line) => {
      const v = args[0];
      if (typeof v === 'string') return BigInt(v.length);
      if (Array.isArray(v)) return BigInt(v.length);
      throw new RuntimeError(line, 'bad argument to len');
    }} as BuiltinFunc);
    s.declare('push', { kind: 'builtin', name: 'push', arity: 2, fn: (args, line) => {
      const lst = args[0];
      if (!Array.isArray(lst)) throw new RuntimeError(line, 'bad argument to push');
      lst.push(args[1]);
      return null;
    }} as BuiltinFunc);
    s.declare('pop', { kind: 'builtin', name: 'pop', arity: 1, fn: (args, line) => {
      const lst = args[0];
      if (!Array.isArray(lst) || lst.length === 0) throw new RuntimeError(line, 'bad argument to pop');
      return lst.pop()!;
    }} as BuiltinFunc);
    s.declare('range', { kind: 'builtin', name: 'range', arity: 2, fn: (args, line) => {
      const a = args[0], b = args[1];
      if (typeof a !== 'bigint' || typeof b !== 'bigint') throw new RuntimeError(line, 'bad argument to range');
      const result: Val[] = [];
      for (let i = a; i < b; i++) result.push(i);
      return result;
    }} as BuiltinFunc);
    s.declare('slice', { kind: 'builtin', name: 'slice', arity: 3, fn: (args, line) => {
      const x = args[0], a = args[1], b = args[2];
      if (typeof a !== 'bigint' || typeof b !== 'bigint') throw new RuntimeError(line, 'bad argument to slice');
      if (typeof x === 'string') {
        const ai = Number(a), bi = Number(b);
        if (ai < 0 || bi > x.length || ai > bi) throw new RuntimeError(line, 'bad argument to slice');
        return x.slice(ai, bi);
      }
      if (Array.isArray(x)) {
        const ai = Number(a), bi = Number(b);
        if (ai < 0 || bi > x.length || ai > bi) throw new RuntimeError(line, 'bad argument to slice');
        return x.slice(ai, bi);
      }
      throw new RuntimeError(line, 'bad argument to slice');
    }} as BuiltinFunc);
    return s;
  }

  run(stmts: Stmt[], scope: Scope): void {
    for (const stmt of stmts) this.execStmt(stmt, scope);
  }

  execStmt(stmt: Stmt, scope: Scope): void {
    switch (stmt.kind) {
      case 'let': {
        const val = this.eval(stmt.expr, scope);
        scope.declare(stmt.name, val);
        break;
      }
      case 'fnDecl': {
        const fn: UserFunc = { kind: 'user', params: stmt.params, body: stmt.body, scope };
        scope.declare(stmt.name, fn);
        break;
      }
      case 'if': {
        if (truthy(this.eval(stmt.cond, scope))) {
          const s = new Scope(scope);
          this.run(stmt.then, s);
        } else if (stmt.elseBranch) {
          if (stmt.elseBranch.kind === 'block') {
            const s = new Scope(scope);
            this.run(stmt.elseBranch.body, s);
          } else {
            this.execStmt(stmt.elseBranch.stmt, scope);
          }
        }
        break;
      }
      case 'while': {
        while (truthy(this.eval(stmt.cond, scope))) {
          const s = new Scope(scope);
          try {
            this.run(stmt.body, s);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) continue;
            throw e;
          }
        }
        break;
      }
      case 'for': {
        const list = this.eval(stmt.iterable, scope);
        if (!Array.isArray(list)) throw new RuntimeError(stmt.line, `cannot iterate ${typeOf(list)}`);
        let i = 0;
        while (i < list.length) {
          const s = new Scope(scope);
          s.declare(stmt.varName, list[i]);
          try {
            this.run(stmt.body, s);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { i++; continue; }
            throw e;
          }
          i++;
        }
        break;
      }
      case 'return': {
        const val = stmt.expr ? this.eval(stmt.expr, scope) : null;
        throw new ReturnSignal(val);
      }
      case 'break': throw new BreakSignal();
      case 'continue': throw new ContinueSignal();
      case 'assign': {
        const val = this.eval(stmt.expr, scope);
        if (!scope.set(stmt.name, val)) throw new RuntimeError(stmt.line, `undefined variable ${stmt.name}`);
        break;
      }
      case 'indexAssign': {
        const obj = this.eval(stmt.obj, scope);
        const idx = this.eval(stmt.index, scope);
        const val = this.eval(stmt.value, scope);
        if (!Array.isArray(obj)) throw new RuntimeError(stmt.line, `cannot assign into ${typeOf(obj)}`);
        if (typeof idx !== 'bigint') throw new RuntimeError(stmt.line, `cannot index list with ${typeOf(idx)}`);
        const i = Number(idx);
        if (i < 0 || i >= obj.length) throw new RuntimeError(stmt.line, `index ${idx} out of range for length ${obj.length}`);
        obj[i] = val;
        break;
      }
      case 'expr': {
        this.eval(stmt.expr, scope);
        break;
      }
    }
  }

  eval(expr: Expr, scope: Scope): Val {
    switch (expr.kind) {
      case 'int': return expr.value;
      case 'str': return expr.value;
      case 'bool': return expr.value;
      case 'nil': return null;
      case 'ident': {
        const v = scope.get(expr.name);
        if (v === undefined) throw new RuntimeError(expr.line, `undefined variable ${expr.name}`);
        return v;
      }
      case 'list': {
        return expr.elements.map(e => this.eval(e, scope));
      }
      case 'fn': {
        return { kind: 'user', params: expr.params, body: expr.body, scope } as UserFunc;
      }
      case 'not': {
        return !truthy(this.eval(expr.operand, scope));
      }
      case 'neg': {
        const v = this.eval(expr.operand, scope);
        if (typeof v !== 'bigint') throw new RuntimeError(expr.line, `cannot apply - to ${typeOf(v)}`);
        return checkInt(-v, expr.line);
      }
      case 'binary': return this.evalBinary(expr, scope);
      case 'call': return this.evalCall(expr, scope);
      case 'index': return this.evalIndex(expr, scope);
    }
  }

  evalBinary(expr: { op: string; left: Expr; right: Expr; line: number }, scope: Scope): Val {
    const op = expr.op;
    if (op === 'and') {
      const l = this.eval(expr.left, scope);
      if (!truthy(l)) return l;
      return this.eval(expr.right, scope);
    }
    if (op === 'or') {
      const l = this.eval(expr.left, scope);
      if (truthy(l)) return l;
      return this.eval(expr.right, scope);
    }
    const l = this.eval(expr.left, scope);
    const r = this.eval(expr.right, scope);

    if (op === '==') return valuesEqual(l, r);
    if (op === '!=') return !valuesEqual(l, r);

    if (op === '+' ) {
      if (typeof l === 'bigint' && typeof r === 'bigint') return checkInt(l + r, expr.line);
      if (typeof l === 'string' && typeof r === 'string') return l + r;
      if (Array.isArray(l) && Array.isArray(r)) return [...l, ...r];
      throw new RuntimeError(expr.line, `cannot apply + to ${typeOf(l)} and ${typeOf(r)}`);
    }
    if (op === '-' || op === '*' || op === '/' || op === '%') {
      if (typeof l !== 'bigint' || typeof r !== 'bigint')
        throw new RuntimeError(expr.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
      if ((op === '/' || op === '%') && r === 0n)
        throw new RuntimeError(expr.line, 'division by zero');
      let res: bigint;
      if (op === '-') res = l - r;
      else if (op === '*') res = l * r;
      else if (op === '/') res = l / r;
      else res = l % r;
      return checkInt(res, expr.line);
    }
    if (op === '<' || op === '<=' || op === '>' || op === '>=') {
      if (typeof l === 'bigint' && typeof r === 'bigint') {
        if (op === '<') return l < r;
        if (op === '<=') return l <= r;
        if (op === '>') return l > r;
        return l >= r;
      }
      if (typeof l === 'string' && typeof r === 'string') {
        if (op === '<') return l < r;
        if (op === '<=') return l <= r;
        if (op === '>') return l > r;
        return l >= r;
      }
      throw new RuntimeError(expr.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
    }
    throw new RuntimeError(expr.line, `unknown operator ${op}`);
  }

  evalCall(expr: { callee: Expr; args: Expr[]; line: number }, scope: Scope): Val {
    const callee = this.eval(expr.callee, scope);
    const args = expr.args.map(a => this.eval(a, scope));

    if (callee === null || typeof callee !== 'object' || !('kind' in callee)) {
      throw new RuntimeError(expr.line, `cannot call ${typeOf(callee)}`);
    }
    const fn = callee as FuncVal;

    if (fn.kind === 'builtin') {
      if (fn.arity >= 0 && args.length !== fn.arity) {
        throw new RuntimeError(expr.line, `expected ${fn.arity} arguments, got ${args.length}`);
      }
      return fn.fn(args, expr.line);
    }

    // user function
    if (args.length !== fn.params.length) {
      throw new RuntimeError(expr.line, `expected ${fn.params.length} arguments, got ${args.length}`);
    }
    const callScope = new Scope(fn.scope);
    for (let i = 0; i < fn.params.length; i++) {
      callScope.declare(fn.params[i], args[i]);
    }
    try {
      this.run(fn.body, callScope);
    } catch (e) {
      if (e instanceof ReturnSignal) return e.value;
      throw e;
    }
    return null;
  }

  evalIndex(expr: { obj: Expr; index: Expr; line: number }, scope: Scope): Val {
    const obj = this.eval(expr.obj, scope);
    const idx = this.eval(expr.index, scope);
    if ((!Array.isArray(obj) && typeof obj !== 'string') || typeof idx !== 'bigint') {
      throw new RuntimeError(expr.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
    }
    const i = Number(idx);
    const len = Array.isArray(obj) ? obj.length : (obj as string).length;
    if (i < 0 || i >= len) {
      throw new RuntimeError(expr.line, `index ${idx} out of range for length ${len}`);
    }
    if (Array.isArray(obj)) return obj[i];
    return (obj as string)[i];
  }
}

// ===== MAIN =====
const dir = process.argv[2];
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = lex(src);
const parser = new Parser(tokens);
const program = parser.parseProgram();
const interp = new Interpreter();

try {
  interp.run(program, interp.globalScope);
} catch (e) {
  if (e instanceof RuntimeError) {
    process.stdout.write(interp.output.join(''));
    process.stdout.write(`error at line ${e.line}: ${e.msg}\n`);
    process.exit(0);
  }
  if (e instanceof BreakSignal || e instanceof ContinueSignal || e instanceof ReturnSignal) {
    // shouldn't happen at top level
  }
  throw e;
}

process.stdout.write(interp.output.join(''));
process.exit(0);

import * as fs from 'fs';
import * as path from 'path';

function crc32(data: Buffer): number {
    const table: number[] = new Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) {
            if (c & 1) c = 0xEDB88320 ^ (c >>> 1);
            else c = c >>> 1;
        }
        table[i] = c;
    }
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc = table[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function splitIntoLines(content: Buffer): Buffer[] {
    if (content.length === 0) return [];
    const lines: Buffer[] = [];
    let start = 0;
    for (let i = 0; i < content.length; i++) {
        if (content[i] === 0x0A) {
            lines.push(content.subarray(start, i + 1));
            start = i + 1;
        }
    }
    if (start < content.length) {
        lines.push(content.subarray(start));
    }
    return lines;
}

interface Hunk {
    a: number;
    b: number;
    c: number;
    d: number;
    oldLines: Buffer[];
    newLines: Buffer[];
}

interface Section {
    filePath: string;
    kind: 'create' | 'delete' | 'modify';
    hunks: Hunk[];
}

interface HunkResult {
    status: 'applied' | 'rejected' | 'malformed';
    position?: number;
    offset?: number;
}

function parseDiff(diffContent: Buffer): Section[] {
    const sections: Section[] = [];
    const diffLines = splitIntoLines(diffContent);

    let i = 0;
    while (i < diffLines.length) {
        const lineStr = diffLines[i].toString('utf-8');

        if (lineStr.startsWith('diff --git a/')) {
            const match = lineStr.match(/^diff --git a\/(.+) b\/(.+)\n?$/);
            if (!match) { i++; continue; }
            const filePath = match[1];

            i++;
            let kind: 'create' | 'delete' | 'modify' = 'modify';

            while (i < diffLines.length) {
                const h = diffLines[i].toString('utf-8');
                if (h.startsWith('new file mode ')) {
                    kind = 'create';
                    i++;
                } else if (h.startsWith('deleted file mode ')) {
                    kind = 'delete';
                    i++;
                } else if (h.startsWith('index ')) {
                    i++;
                } else if (h.startsWith('--- ') || h.startsWith('+++ ')) {
                    i++;
                } else if (h.startsWith('@@ ')) {
                    break;
                } else if (h.startsWith('diff --git ')) {
                    break;
                } else {
                    i++;
                }
            }

            const hunks: Hunk[] = [];
            while (i < diffLines.length) {
                const h = diffLines[i].toString('utf-8');
                if (h.startsWith('diff --git ')) break;
                if (!h.startsWith('@@ ')) { i++; continue; }

                const hunkMatch = h.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
                if (!hunkMatch) { i++; continue; }

                const a = parseInt(hunkMatch[1]);
                const b = hunkMatch[2] !== undefined ? parseInt(hunkMatch[2]) : 1;
                const c = parseInt(hunkMatch[3]);
                const d = hunkMatch[4] !== undefined ? parseInt(hunkMatch[4]) : 1;

                i++;

                const bodyEntries: { marker: string; content: Buffer }[] = [];

                while (i < diffLines.length) {
                    const bl = diffLines[i];
                    const blStr = bl.toString('utf-8');
                    if (blStr.startsWith('@@ ') || blStr.startsWith('diff --git ')) break;

                    if (bl.length === 0) { i++; continue; }

                    const marker = blStr[0];
                    const content = bl.subarray(1);

                    if (marker === '\\') {
                        if (bodyEntries.length > 0) {
                            const prev = bodyEntries[bodyEntries.length - 1];
                            if (prev.content.length > 0 && prev.content[prev.content.length - 1] === 0x0A) {
                                bodyEntries[bodyEntries.length - 1] = {
                                    marker: prev.marker,
                                    content: prev.content.subarray(0, prev.content.length - 1)
                                };
                            }
                        }
                    } else if (marker === ' ' || marker === '-' || marker === '+') {
                        bodyEntries.push({ marker, content });
                    }
                    i++;
                }

                const oldLines: Buffer[] = [];
                const newLines: Buffer[] = [];
                for (const entry of bodyEntries) {
                    if (entry.marker === ' ' || entry.marker === '-') {
                        oldLines.push(entry.content);
                    }
                    if (entry.marker === ' ' || entry.marker === '+') {
                        newLines.push(entry.content);
                    }
                }

                hunks.push({ a, b, c, d, oldLines, newLines });
            }

            sections.push({ filePath, kind, hunks });
        } else {
            i++;
        }
    }

    return sections;
}

function linesMatch(lines: Buffer[], oldLines: Buffer[], startIdx: number): boolean {
    for (let i = 0; i < oldLines.length; i++) {
        if (startIdx + i >= lines.length) return false;
        if (!lines[startIdx + i].equals(oldLines[i])) return false;
    }
    return true;
}

function formatOffset(k: number): string {
    if (k > 0) return `+${k}`;
    if (k < 0) return `${k}`;
    return '0';
}

function applyHunk(lines: Buffer[], hunk: Hunk, delta: number): { lines: Buffer[]; delta: number; result: HunkResult } {
    const { a, b, d, oldLines, newLines } = hunk;

    if (oldLines.length !== b || newLines.length !== d) {
        return { lines, delta, result: { status: 'malformed' } };
    }

    const P = a + delta;

    if (b === 0) {
        if (P >= 0 && P <= lines.length) {
            const newContent = [...lines.slice(0, P), ...newLines, ...lines.slice(P)];
            return { lines: newContent, delta: delta + d, result: { status: 'applied', position: P, offset: 0 } };
        } else {
            return { lines, delta, result: { status: 'rejected' } };
        }
    }

    const lineCount = lines.length;
    if (lineCount < b) {
        return { lines, delta, result: { status: 'rejected' } };
    }

    const minP = 1;
    const maxP = lineCount - b + 1;

    let found = -1;
    for (let k = 0; ; k++) {
        const p1 = P - k;
        if (p1 >= minP && p1 <= maxP) {
            if (linesMatch(lines, oldLines, p1 - 1)) {
                found = p1;
                break;
            }
        }

        if (k > 0) {
            const p2 = P + k;
            if (p2 >= minP && p2 <= maxP) {
                if (linesMatch(lines, oldLines, p2 - 1)) {
                    found = p2;
                    break;
                }
            }
        }

        if (P - k < minP && P + k > maxP) break;
    }

    if (found === -1) {
        return { lines, delta, result: { status: 'rejected' } };
    }

    const offset = found - P;
    const newContent = [...lines.slice(0, found - 1), ...newLines, ...lines.slice(found - 1 + b)];
    return { lines: newContent, delta: delta + d - b, result: { status: 'applied', position: found, offset } };
}

function main() {
    const args = process.argv.slice(2);
    const dir = args[0];

    const diffPath = path.join(dir, 'changes.diff');
    const treeDir = path.join(dir, 'tree');

    const diffContent = fs.readFileSync(diffPath);
    const sections = parseDiff(diffContent);

    sections.sort((a, b) => {
        const bufA = Buffer.from(a.filePath, 'utf-8');
        const bufB = Buffer.from(b.filePath, 'utf-8');
        return Buffer.compare(bufA, bufB);
    });

    const output: string[] = [];

    for (const section of sections) {
        const filePath = section.filePath;
        const treeFilePath = path.join(treeDir, filePath);

        if (section.kind === 'create') {
            if (fs.existsSync(treeFilePath)) {
                output.push(`${filePath}: create`);
                output.push(`  error: already exists`);
                continue;
            }
        } else {
            if (!fs.existsSync(treeFilePath)) {
                output.push(`${filePath}: ${section.kind}`);
                output.push(`  error: not found`);
                continue;
            }
        }

        let lines: Buffer[];
        if (section.kind === 'create') {
            lines = [];
        } else {
            const fileContent = fs.readFileSync(treeFilePath);
            lines = splitIntoLines(fileContent);
        }

        let delta = 0;
        const hunkResults: HunkResult[] = [];

        for (const hunk of section.hunks) {
            const result = applyHunk(lines, hunk, delta);
            lines = result.lines;
            delta = result.delta;
            hunkResults.push(result.result);
        }

        output.push(`${filePath}: ${section.kind}`);
        for (let i = 0; i < hunkResults.length; i++) {
            const hr = hunkResults[i];
            if (hr.status === 'applied') {
                output.push(`  hunk ${i + 1}: applied at ${hr.position} (offset ${formatOffset(hr.offset!)})`);
            } else if (hr.status === 'rejected') {
                output.push(`  hunk ${i + 1}: rejected`);
            } else {
                output.push(`  hunk ${i + 1}: malformed`);
            }
        }

        if (section.kind === 'delete') {
            const allApplied = hunkResults.every(hr => hr.status === 'applied');
            if (allApplied && lines.length === 0) {
                output.push(`  result: deleted`);
            } else {
                const content = Buffer.concat(lines);
                const crc = crc32(content);
                output.push(`  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`);
            }
        } else {
            const content = Buffer.concat(lines);
            const crc = crc32(content);
            output.push(`  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`);
        }
    }

    console.log(output.join('\n'));
}

main();

import Foundation

// MARK: - Tokens & Lexer

enum TK {
    case int, str, ident, kw
    case plus, minus, star, slash, pct
    case assign, eqeq, neq, lt, le, gt, ge
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semi, eof
}

struct Token {
    var kind: TK
    var text: String
    var line: Int
}

let kws: Set<String> = ["let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil"]

func tokenize(_ src: String) -> [Token] {
    let b = Array(src.utf8)
    var toks: [Token] = []
    var i = 0, line = 1
    let n = b.count
    while i < n {
        let c = b[i]
        if c == 32 || c == 9 || c == 13 { i += 1; continue }
        if c == 10 { line += 1; i += 1; continue }
        if c == 35 { while i < n && b[i] != 10 { i += 1 }; continue }
        if c >= 48 && c <= 57 {
            let s = i
            while i < n && b[i] >= 48 && b[i] <= 57 { i += 1 }
            toks.append(Token(kind: .int, text: String(decoding: b[s..<i], as: UTF8.self), line: line))
            continue
        }
        if c == 34 {
            i += 1; var s = ""
            while i < n && b[i] != 34 {
                if b[i] == 92 { i += 1; if i < n {
                    switch b[i] { case 110: s.append("\n"); case 116: s.append("\t"); case 34: s.append("\""); case 92: s.append("\\"); default: s.append(Character(UnicodeScalar(b[i]))) }
                    i += 1 }
                } else { s.append(Character(UnicodeScalar(b[i]))); i += 1 }
            }
            i += 1
            toks.append(Token(kind: .str, text: s, line: line)); continue
        }
        if (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 {
            let s = i
            while i < n && ((b[i] >= 65 && b[i] <= 90) || (b[i] >= 97 && b[i] <= 122) || (b[i] >= 48 && b[i] <= 57) || b[i] == 95) { i += 1 }
            let w = String(decoding: b[s..<i], as: UTF8.self)
            toks.append(Token(kind: kws.contains(w) ? .kw : .ident, text: w, line: line)); continue
        }
        if i + 1 < n {
            let c2 = b[i+1]
            if c == 61 && c2 == 61 { toks.append(Token(kind: .eqeq, text: "==", line: line)); i += 2; continue }
            if c == 33 && c2 == 61 { toks.append(Token(kind: .neq, text: "!=", line: line)); i += 2; continue }
            if c == 60 && c2 == 61 { toks.append(Token(kind: .le, text: "<=", line: line)); i += 2; continue }
            if c == 62 && c2 == 61 { toks.append(Token(kind: .ge, text: ">=", line: line)); i += 2; continue }
        }
        switch c {
        case 43: toks.append(Token(kind: .plus, text: "+", line: line))
        case 45: toks.append(Token(kind: .minus, text: "-", line: line))
        case 42: toks.append(Token(kind: .star, text: "*", line: line))
        case 47: toks.append(Token(kind: .slash, text: "/", line: line))
        case 37: toks.append(Token(kind: .pct, text: "%", line: line))
        case 61: toks.append(Token(kind: .assign, text: "=", line: line))
        case 60: toks.append(Token(kind: .lt, text: "<", line: line))
        case 62: toks.append(Token(kind: .gt, text: ">", line: line))
        case 40: toks.append(Token(kind: .lparen, text: "(", line: line))
        case 41: toks.append(Token(kind: .rparen, text: ")", line: line))
        case 91: toks.append(Token(kind: .lbracket, text: "[", line: line))
        case 93: toks.append(Token(kind: .rbracket, text: "]", line: line))
        case 123: toks.append(Token(kind: .lbrace, text: "{", line: line))
        case 125: toks.append(Token(kind: .rbrace, text: "}", line: line))
        case 44: toks.append(Token(kind: .comma, text: ",", line: line))
        case 59: toks.append(Token(kind: .semi, text: ";", line: line))
        default: break
        }
        i += 1
    }
    toks.append(Token(kind: .eof, text: "", line: line))
    return toks
}

// MARK: - AST

indirect enum Expr {
    case intLit(Int64, Int)
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binary(op: String, l: Expr, r: Expr, line: Int)
    case unary(op: String, e: Expr, line: Int)
    case andE(l: Expr, r: Expr, line: Int)
    case orE(l: Expr, r: Expr, line: Int)
    case notE(e: Expr, line: Int)
    case call(callee: Expr, args: [Expr], line: Int)
    case index(obj: Expr, idx: Expr, line: Int)
    case listLit([Expr], Int)
    case fnExpr(params: [String], body: [Stmt], line: Int)
}

enum ElseClause {
    case block([Stmt])
    case ifStmt(Stmt)
}

indirect enum Stmt {
    case letStmt(String, Expr, Int)
    case fnStmt(String, [String], [Stmt], Int)
    case ifStmt(Expr, [Stmt], ElseClause?, Int)
    case whileStmt(Expr, [Stmt], Int)
    case forStmt(String, Expr, [Stmt], Int)
    case returnStmt(Expr?, Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assignStmt(String, Expr, Int)
    case indexAssign(Expr, Expr, Expr, Int)
    case exprStmt(Expr, Int)
}

// MARK: - Parser

final class Parser {
    var toks: [Token]
    var pos = 0
    init(_ t: [Token]) { toks = t }

    func peek() -> Token { toks[pos] }
    func advance() -> Token { let t = toks[pos]; pos += 1; return t }
    func check(_ k: TK) -> Bool { toks[pos].kind == k }
    func checkKw(_ s: String) -> Bool { toks[pos].kind == .kw && toks[pos].text == s }
    func expect(_ k: TK) -> Token { let t = toks[pos]; pos += 1; return t }
    func expectKw(_ s: String) -> Token { let t = toks[pos]; pos += 1; return t }

    func parseProgram() -> [Stmt] {
        var stmts: [Stmt] = []
        while !check(.eof) { stmts.append(parseStmt()) }
        return stmts
    }

    func parseBlock() -> [Stmt] {
        expect(.lbrace)
        var stmts: [Stmt] = []
        while !check(.rbrace) && !check(.eof) { stmts.append(parseStmt()) }
        expect(.rbrace)
        return stmts
    }

    func parseStmt() -> Stmt {
        let t = peek()
        if checkKw("let") { return parseLet() }
        if checkKw("fn") {
            if toks[pos+1].kind == .ident { return parseFnStmt() }
            return parseExprStmt()
        }
        if checkKw("if") { return parseIf() }
        if checkKw("while") { return parseWhile() }
        if checkKw("for") { return parseFor() }
        if checkKw("return") {
            advance()
            if check(.semi) { advance(); return .returnStmt(nil, t.line) }
            let e = parseExpr(); expect(.semi); return .returnStmt(e, t.line)
        }
        if checkKw("break") { advance(); expect(.semi); return .breakStmt(t.line) }
        if checkKw("continue") { advance(); expect(.semi); return .continueStmt(t.line) }
        // assignment or expression statement
        if t.kind == .ident && toks[pos+1].kind == .assign {
            advance(); advance()
            let v = parseExpr(); expect(.semi)
            return .assignStmt(t.text, v, t.line)
        }
        // parse expression, check for index assignment
        let e = parseExpr()
        if check(.assign) {
            advance()
            let v = parseExpr(); expect(.semi)
            if case let .index(obj, idx, _) = e {
                return .indexAssign(obj, idx, v, t.line)
            }
            // shouldn't happen in valid programs
            expect(.semi)
            return .exprStmt(e, t.line)
        }
        expect(.semi)
        return .exprStmt(e, t.line)
    }

    func parseLet() -> Stmt {
        let t = advance() // let
        let name = advance().text
        expect(.assign)
        let v = parseExpr()
        expect(.semi)
        return .letStmt(name, v, t.line)
    }

    func parseFnStmt() -> Stmt {
        let t = advance() // fn
        let name = advance().text
        expect(.lparen)
        let params = parseParams()
        expect(.rparen)
        let body = parseBlock()
        return .fnStmt(name, params, body, t.line)
    }

    func parseParams() -> [String] {
        var ps: [String] = []
        if !check(.rparen) {
            ps.append(advance().text)
            while check(.comma) { advance(); ps.append(advance().text) }
        }
        return ps
    }

    func parseIf() -> Stmt {
        let t = advance() // if
        let cond = parseExpr()
        let thenB = parseBlock()
        var elseB: ElseClause? = nil
        if checkKw("else") {
            advance()
            if checkKw("if") { elseB = .ifStmt(parseIf()) }
            else { elseB = .block(parseBlock()) }
        }
        return .ifStmt(cond, thenB, elseB, t.line)
    }

    func parseWhile() -> Stmt {
        let t = advance() // while
        let cond = parseExpr()
        let body = parseBlock()
        return .whileStmt(cond, body, t.line)
    }

    func parseFor() -> Stmt {
        let t = advance() // for
        let name = advance().text
        expectKw("in")
        let iter = parseExpr()
        let body = parseBlock()
        return .forStmt(name, iter, body, t.line)
    }

    func parseExprStmt() -> Stmt {
        let t = peek()
        let e = parseExpr()
        expect(.semi)
        return .exprStmt(e, t.line)
    }

    // Expression parsing
    func parseExpr() -> Expr { return parseOr() }

    func parseOr() -> Expr {
        var l = parseAnd()
        while checkKw("or") { let t = advance(); let r = parseAnd(); l = .orE(l: l, r: r, line: t.line) }
        return l
    }

    func parseAnd() -> Expr {
        var l = parseNot()
        while checkKw("and") { let t = advance(); let r = parseNot(); l = .andE(l: l, r: r, line: t.line) }
        return l
    }

    func parseNot() -> Expr {
        if checkKw("not") { let t = advance(); let e = parseNot(); return .notE(e: e, line: t.line) }
        return parseComparison()
    }

    func parseComparison() -> Expr {
        var l = parseAdd()
        while check(.eqeq) || check(.neq) || check(.lt) || check(.le) || check(.gt) || check(.ge) {
            let t = advance()
            let r = parseAdd()
            l = .binary(op: t.text, l: l, r: r, line: t.line)
        }
        return l
    }

    func parseAdd() -> Expr {
        var l = parseMul()
        while check(.plus) || check(.minus) {
            let t = advance()
            let r = parseMul()
            l = .binary(op: t.text, l: l, r: r, line: t.line)
        }
        return l
    }

    func parseMul() -> Expr {
        var l = parseUnary()
        while check(.star) || check(.slash) || check(.pct) {
            let t = advance()
            let r = parseUnary()
            l = .binary(op: t.text, l: l, r: r, line: t.line)
        }
        return l
    }

    func parseUnary() -> Expr {
        if check(.minus) { let t = advance(); let e = parseUnary(); return .unary(op: "-", e: e, line: t.line) }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var e = parsePrimary()
        while true {
            if check(.lparen) {
                let t = advance()
                var args: [Expr] = []
                if !check(.rparen) {
                    args.append(parseExpr())
                    while check(.comma) { advance(); args.append(parseExpr()) }
                }
                expect(.rparen)
                e = .call(callee: e, args: args, line: t.line)
            } else if check(.lbracket) {
                let t = advance()
                let idx = parseExpr()
                expect(.rbracket)
                e = .index(obj: e, idx: idx, line: t.line)
            } else { break }
        }
        return e
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.kind {
        case .int: advance(); return .intLit(Int64(t.text)!, t.line)
        case .str: advance(); return .strLit(t.text, t.line)
        case .kw:
            switch t.text {
            case "true": advance(); return .boolLit(true, t.line)
            case "false": advance(); return .boolLit(false, t.line)
            case "nil": advance(); return .nilLit(t.line)
            case "fn":
                advance()
                expect(.lparen)
                let params = parseParams()
                expect(.rparen)
                let body = parseBlock()
                return .fnExpr(params: params, body: body, t.line)
            default:
                advance(); return .ident(t.text, t.line)
            }
        case .ident: advance(); return .ident(t.text, t.line)
        case .lparen:
            advance()
            let e = parseExpr()
            expect(.rparen)
            return e
        case .lbracket:
            advance()
            var elems: [Expr] = []
            if !check(.rbracket) {
                elems.append(parseExpr())
                while check(.comma) { advance(); elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        default:
            advance()
            return .nilLit(t.line)
        }
    }
}

// MARK: - Values

final class ListVal {
    var elements: [Val]
    init(_ e: [Val] = []) { elements = e }
}

final class FnVal {
    var params: [String]
    var body: [Stmt]
    var captured: Scope
    var builtin: BuiltinDef?
    init(params: [String], body: [Stmt], captured: Scope) {
        self.params = params; self.body = body; self.captured = captured; self.builtin = nil
    }
    init(builtin: BuiltinDef) {
        self.params = []; self.body = []; self.captured = Scope(parent: nil); self.builtin = builtin
    }
}

struct BuiltinDef {
    let name: String
    let arity: Int // -1 for variadic
    let impl: ([Val]) throws -> Val
}

enum Val {
    case int(Int64)
    case bool(Bool)
    case str(String)
    case list(ListVal)
    case fn(FnVal)
    case nilV
}

final class Scope {
    var vars: [String: Val]
    var parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func lookup(_ name: String) -> Scope? {
        var s: Scope? = self
        while let cur = s {
            if cur.vars[name] != nil { return cur }
            s = cur.parent
        }
        return nil
    }
}

// MARK: - Error

struct TernError: Error {
    let line: Int
    let message: String
}

// MARK: - Interpreter

enum CF { case normal, breakL, continueL, returnV(Val) }

func typeName(_ v: Val) -> String {
    switch v {
    case .int: return "int"
    case .bool: return "bool"
    case .str: return "string"
    case .list: return "list"
    case .fn: return "function"
    case .nilV: return "nil"
    }
}

func truthy(_ v: Val) -> Bool {
    switch v {
    case .int(let n): return n != 0
    case .bool(let b): return b
    case .str(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    case .fn: return true
    case .nilV: return false
    }
}

func valEqual(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.str(let x), .str(let y)): return x == y
    case (.nilV, .nilV): return true
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count {
            if !valEqual(x.elements[i], y.elements[i]) { return false }
        }
        return true
    case (.fn(let x), .fn(let y)): return x === y
    default: return false
    }
}

func escapeStr(_ s: String) -> String {
    var r = ""
    for c in s {
        switch c {
        case "\\": r += "\\\\"
        case "\"": r += "\\\""
        case "\n": r += "\\n"
        case "\t": r += "\\t"
        default: r.append(c)
        }
    }
    return r
}

func display(_ v: Val, inList: Bool, seen: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let n): return String(n)
    case .bool(let b): return b ? "true" : "false"
    case .nilV: return "nil"
    case .str(let s):
        if inList { return "\"" + escapeStr(s) + "\"" }
        return s
    case .list(let l):
        if seen.contains(ObjectIdentifier(l)) { return "[...]" }
        seen.insert(ObjectIdentifier(l))
        var parts: [String] = []
        for e in l.elements { parts.append(display(e, inList: true, seen: &seen)) }
        seen.remove(ObjectIdentifier(l))
        return "[" + parts.joined(separator: ", ") + "]"
    case .fn: return "<fn>"
    }
}

func displayTop(_ v: Val) -> String {
    var seen = Set<ObjectIdentifier>()
    return display(v, inList: false, seen: &seen)
}

func makeBuiltins() -> [String: Val] {
    var b: [String: Val] = [:]

    b["print"] = .fn(FnVal(builtin: BuiltinDef(name: "print", arity: -1) { args in
        var parts: [String] = []
        for a in args {
            var seen = Set<ObjectIdentifier>()
            parts.append(display(a, inList: false, seen: &seen))
        }
        print(parts.joined(separator: " "))
        return .nilV
    }))

    b["str"] = .fn(FnVal(builtin: BuiltinDef(name: "str", arity: 1) { args in
        var seen = Set<ObjectIdentifier>()
        return .str(display(args[0], inList: false, seen: &seen))
    }))

    b["type"] = .fn(FnVal(builtin: BuiltinDef(name: "type", arity: 1) { args in
        return .str(typeName(args[0]))
    }))

    b["len"] = .fn(FnVal(builtin: BuiltinDef(name: "len", arity: 1) { args in
        switch args[0] {
        case .str(let s): return .int(Int64(s.count))
        case .list(let l): return .int(Int64(l.elements.count))
        default: throw TernError(line: 0, message: "bad")
        }
    }))

    b["push"] = .fn(FnVal(builtin: BuiltinDef(name: "push", arity: 2) { args in
        guard case .list(let l) = args[0] else { throw TernError(line: 0, message: "bad") }
        l.elements.append(args[1])
        return .nilV
    }))

    b["pop"] = .fn(FnVal(builtin: BuiltinDef(name: "pop", arity: 1) { args in
        guard case .list(let l) = args[0] else { throw TernError(line: 0, message: "bad") }
        if l.elements.isEmpty { throw TernError(line: 0, message: "bad") }
        return l.elements.removeLast()
    }))

    b["range"] = .fn(FnVal(builtin: BuiltinDef(name: "range", arity: 2) { args in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else { throw TernError(line: 0, message: "bad") }
        if b <= a { return .list(ListVal()) }
        var elems: [Val] = []
        elems.reserveCapacity(Int(b - a))
        var i = a
        while i < b { elems.append(.int(i)); i += 1 }
        return .list(ListVal(elems))
    }))

    b["slice"] = .fn(FnVal(builtin: BuiltinDef(name: "slice", arity: 3) { args in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else { throw TernError(line: 0, message: "bad") }
        switch args[0] {
        case .list(let l):
            let n = l.elements.count
            if a < 0 || b > n || a > b { throw TernError(line: 0, message: "bad") }
            return .list(ListVal(Array(l.elements[Int(a)..<Int(b)])))
        case .str(let s):
            let chars = Array(s)
            let n = chars.count
            if a < 0 || b > n || a > b { throw TernError(line: 0, message: "bad") }
            return .str(String(chars[Int(a)..<Int(b)]))
        default: throw TernError(line: 0, message: "bad")
        }
    }))

    return b
}

func evalExpr(_ e: Expr, scope: Scope) throws -> Val {
    switch e {
    case .intLit(let n, _): return .int(n)
    case .strLit(let s, _): return .str(s)
    case .boolLit(let b, _): return .bool(b)
    case .nilLit: return .nilV
    case .ident(let name, let line):
        if let s = scope.lookup(name) { return s.vars[name]! }
        throw TernError(line: line, message: "undefined variable \(name)")
    case .notE(let operand, _):
        let v = try evalExpr(operand, scope: scope)
        return .bool(!truthy(v))
    case .andE(let l, let r, _):
        let lv = try evalExpr(l, scope: scope)
        if !truthy(lv) { return lv }
        return try evalExpr(r, scope: scope)
    case .orE(let l, let r, _):
        let lv = try evalExpr(l, scope: scope)
        if truthy(lv) { return lv }
        return try evalExpr(r, scope: scope)
    case .unary(op: "-", let operand, let line):
        let v = try evalExpr(operand, scope: scope)
        guard case .int(let n) = v else { throw TernError(line: line, message: "cannot apply - to \(typeName(v))") }
        if n == Int64.min { throw TernError(line: line, message: "integer overflow") }
        return .int(-n)
    case .binary(let op, let l, let r, let line):
        let lv = try evalExpr(l, scope: scope)
        let rv = try evalExpr(r, scope: scope)
        return try evalBinary(op, lv, rv, line)
    case .call(let callee, let args, let line):
        let fv = try evalExpr(callee, scope: scope)
        var argVals: [Val] = []
        for a in args { argVals.append(try evalExpr(a, scope: scope)) }
        return try callValue(fv, argVals, line)
    case .index(let obj, let idx, let line):
        let ov = try evalExpr(obj, scope: scope)
        let iv = try evalExpr(idx, scope: scope)
        return try indexRead(ov, iv, line)
    case .listLit(let elems, _):
        var vals: [Val] = []
        for e in elems { vals.append(try evalExpr(e, scope: scope)) }
        return .list(ListVal(vals))
    case .fnExpr(let params, let body, _):
        return .fn(FnVal(params: params, body: body, captured: scope))
    }
}

func evalBinary(_ op: String, _ lv: Val, _ rv: Val, _ line: Int) throws -> Val {
    switch op {
    case "==": return .bool(valEqual(lv, rv))
    case "!=": return .bool(!valEqual(lv, rv))
    case "+":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.addingReportingOverflow(b)
            if ov { throw TernError(line: line, message: "integer overflow") }
            return .int(r)
        }
        if case .str(let a) = lv, case .str(let b) = rv { return .str(a + b) }
        if case .list(let a) = lv, case .list(let b) = rv {
            return .list(ListVal(a.elements + b.elements))
        }
        throw TernError(line: line, message: "cannot apply + to \(typeName(lv)) and \(typeName(rv))")
    case "-":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.subtractingReportingOverflow(b)
            if ov { throw TernError(line: line, message: "integer overflow") }
            return .int(r)
        }
        throw TernError(line: line, message: "cannot apply - to \(typeName(lv)) and \(typeName(rv))")
    case "*":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.multipliedReportingOverflow(b)
            if ov { throw TernError(line: line, message: "integer overflow") }
            return .int(r)
        }
        throw TernError(line: line, message: "cannot apply * to \(typeName(lv)) and \(typeName(rv))")
    case "/":
        if case .int(let a) = lv, case .int(let b) = rv {
            if b == 0 { throw TernError(line: line, message: "division by zero") }
            if a == Int64.min && b == -1 { throw TernError(line: line, message: "integer overflow") }
            return .int(a / b)
        }
        throw TernError(line: line, message: "cannot apply / to \(typeName(lv)) and \(typeName(rv))")
    case "%":
        if case .int(let a) = lv, case .int(let b) = rv {
            if b == 0 { throw TernError(line: line, message: "division by zero") }
            if b == -1 { return .int(0) }
            return .int(a % b)
        }
        throw TernError(line: line, message: "cannot apply % to \(typeName(lv)) and \(typeName(rv))")
    case "<":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a < b) }
        if case .str(let a) = lv, case .str(let b) = rv { return .bool(a < b) }
        throw TernError(line: line, message: "cannot apply < to \(typeName(lv)) and \(typeName(rv))")
    case "<=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a <= b) }
        if case .str(let a) = lv, case .str(let b) = rv { return .bool(a <= b) }
        throw TernError(line: line, message: "cannot apply <= to \(typeName(lv)) and \(typeName(rv))")
    case ">":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a > b) }
        if case .str(let a) = lv, case .str(let b) = rv { return .bool(a > b) }
        throw TernError(line: line, message: "cannot apply > to \(typeName(lv)) and \(typeName(rv))")
    case ">=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a >= b) }
        if case .str(let a) = lv, case .str(let b) = rv { return .bool(a >= b) }
        throw TernError(line: line, message: "cannot apply >= to \(typeName(lv)) and \(typeName(rv))")
    default:
        throw TernError(line: line, message: "cannot apply \(op) to \(typeName(lv)) and \(typeName(rv))")
    }
}

func indexRead(_ obj: Val, _ idx: Val, _ line: Int) throws -> Val {
    switch obj {
    case .list(let l):
        guard case .int(let i) = idx else {
            throw TernError(line: line, message: "cannot index list with \(typeName(idx))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: line, message: "index \(i) out of range for length \(l.elements.count)")
        }
        return l.elements[Int(i)]
    case .str(let s):
        guard case .int(let i) = idx else {
            throw TernError(line: line, message: "cannot index string with \(typeName(idx))")
        }
        let chars = Array(s)
        if i < 0 || i >= chars.count {
            throw TernError(line: line, message: "index \(i) out of range for length \(chars.count)")
        }
        return .str(String(chars[Int(i)]))
    default:
        throw TernError(line: line, message: "cannot index \(typeName(obj)) with \(typeName(idx))")
    }
}

func callValue(_ fv: Val, _ args: [Val], _ line: Int) throws -> Val {
    guard case .fn(let f) = fv else {
        throw TernError(line: line, message: "cannot call \(typeName(fv))")
    }
    if let bi = f.builtin {
        if bi.arity >= 0 && args.count != bi.arity {
            throw TernError(line: line, message: "expected \(bi.arity) arguments, got \(args.count)")
        }
        do {
            return try bi.impl(args)
        } catch let e as TernError where e.message == "bad" {
            throw TernError(line: line, message: "bad argument to \(bi.name)")
        }
    }
    if args.count != f.params.count {
        throw TernError(line: line, message: "expected \(f.params.count) arguments, got \(args.count)")
    }
    let callScope = Scope(parent: f.captured)
    for (i, p) in f.params.enumerated() { callScope.vars[p] = args[i] }
    let cf = try execBlock(f.body, scope: callScope)
    if case .returnV(let v) = cf { return v }
    return .nilV
}

func execBlock(_ stmts: [Stmt], scope: Scope) throws -> CF {
    for s in stmts {
        let cf = try execStmt(s, scope: scope)
        if case .normal = cf { continue }
        return cf
    }
    return .normal
}

func execStmt(_ s: Stmt, scope: Scope) throws -> CF {
    switch s {
    case .letStmt(let name, let val, _):
        let v = try evalExpr(val, scope: scope)
        scope.vars[name] = v
        return .normal
    case .fnStmt(let name, let params, let body, _):
        let fv = FnVal(params: params, body: body, captured: scope)
        scope.vars[name] = .fn(fv)
        return .normal
    case .ifStmt(let cond, let thenB, let elseB, _):
        let cv = try evalExpr(cond, scope: scope)
        if truthy(cv) {
            let s2 = Scope(parent: scope)
            return try execBlock(thenB, scope: s2)
        } else if let eb = elseB {
            switch eb {
            case .block(let stmts):
                let s2 = Scope(parent: scope)
                return try execBlock(stmts, scope: s2)
            case .ifStmt(let stmt):
                return try execStmt(stmt, scope: scope)
            }
        }
        return .normal
    case .whileStmt(let cond, let body, _):
        while true {
            let cv = try evalExpr(cond, scope: scope)
            if !truthy(cv) { break }
            let s2 = Scope(parent: scope)
            let cf = try execBlock(body, scope: s2)
            switch cf {
            case .breakL: return .normal
            case .returnV(let v): return .returnV(v)
            default: break
            }
        }
        return .normal
    case .forStmt(let varName, let iter, let body, let line):
        let listVal = try evalExpr(iter, scope: scope)
        guard case .list(let lst) = listVal else {
            throw TernError(line: line, message: "cannot iterate \(typeName(listVal))")
        }
        var i = 0
        while i < lst.elements.count {
            let s2 = Scope(parent: scope)
            s2.vars[varName] = lst.elements[i]
            let cf = try execBlock(body, scope: s2)
            switch cf {
            case .breakL: return .normal
            case .returnV(let v): return .returnV(v)
            default: break
            }
            i += 1
        }
        return .normal
    case .returnStmt(let val, _):
        if let v = val { return .returnV(try evalExpr(v, scope: scope)) }
        return .returnV(.nilV)
    case .breakStmt: return .breakL
    case .continueStmt: return .continueL
    case .assignStmt(let name, let val, let line):
        let v = try evalExpr(val, scope: scope)
        if let s = scope.lookup(name) { s.vars[name] = v }
        else { throw TernError(line: line, message: "undefined variable \(name)") }
        return .normal
    case .indexAssign(let obj, let idx, let val, let line):
