                }
            }
            const litTree = buildTree(lens.slice(0, hlit));
            const distTree = buildTree(lens.slice(hlit, hlit + hdist));
            decodeBlock(r, out, litTree, distTree);
        }
    }
    return { data: new Uint8Array(out), stored, fixed, dynamic, endPos: r.pos, bitPos: r.bitPos };
}

function decodeBlock(r: BitReader, out: number[], litTree: HNode, distTree: HNode): void {
    while (true) {
        const s = decodeHuff(r, litTree);
        if (s < 256) { out.push(s); }
        else if (s === 256) { break; }
        else {
            const li = s - 257;
            const len = LEN_BASE[li] + r.readBits(LEN_EXTRA[li]);
            const ds = decodeHuff(r, distTree);
            const dist = DIST_BASE[ds] + r.readBits(DIST_EXTRA[ds]);
            for (let i = 0; i < len; i++) out.push(out[out.length - dist]);
        }
    }
}

// PNG filter paeth predictor
function paeth(a: number, b: number, c: number): number {
    const p = a + b - c;
    const pa = Math.abs(p - a);
    const pb = Math.abs(p - b);
    const pc = Math.abs(p - c);
    if (pa <= pb && pa <= pc) return a;
    if (pb <= pc) return b;
    return c;
}

function processFile(filePath: string, fileName: string): string {
    const data = fs.readFileSync(filePath);
    const lines: string[] = [];
    lines.push(`== ${fileName}`);

    // Parse chunks
    let pos = 8; // skip signature
    const chunkTypes: string[] = [];
    const chunkData: { type: string; dataStart: number; dataLen: number }[] = [];
    let chunkNum = 0;

    while (pos < data.length) {
        chunkNum++;
        if (pos + 8 > data.length) break;
        const length = ((data[pos] << 24) | (data[pos + 1] << 16) | (data[pos + 2] << 8) | data[pos + 3]) >>> 0;
        const type = String.fromCharCode(data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]);
        const dataStart = pos + 8;
        const crcPos = dataStart + length;
        const storedCrc = ((data[crcPos] << 24) | (data[crcPos + 1] << 16) | (data[crcPos + 2] << 8) | data[crcPos + 3]) >>> 0;
        const computedCrc = crc32(data, pos + 4, 4 + length);
        if (computedCrc !== storedCrc) {
            return lines.join('\n') + '\n' + `error: CRC mismatch in chunk ${chunkNum} ${type}`;
        }
        chunkTypes.push(type);
        chunkData.push({ type, dataStart, dataLen: length });
        pos = crcPos + 4;
        if (type === 'IEND') break;
    }

    // Parse IHDR
    const ihdr = chunkData[0];
    const width = ((data[ihdr.dataStart] << 24) | (data[ihdr.dataStart + 1] << 16) | (data[ihdr.dataStart + 2] << 8) | data[ihdr.dataStart + 3]) >>> 0;
    const height = ((data[ihdr.dataStart + 4] << 24) | (data[ihdr.dataStart + 5] << 16) | (data[ihdr.dataStart + 6] << 8) | data[ihdr.dataStart + 7]) >>> 0;
    const bitDepth = data[ihdr.dataStart + 8];
    const colorType = data[ihdr.dataStart + 9];

    // Parse PLTE
    let plte: Uint8Array | null = null;
    for (const c of chunkData) {
        if (c.type === 'PLTE') {
            plte = data.slice(c.dataStart, c.dataStart + c.dataLen);
            break;
        }
    }

    // Parse tRNS
    let trns: Uint8Array | null = null;
    for (const c of chunkData) {
        if (c.type === 'tRNS') {
            trns = data.slice(c.dataStart, c.dataStart + c.dataLen);
            break;
        }
    }

    // Concatenate IDAT data
    let idatData: number[] = [];
    for (const c of chunkData) {
        if (c.type === 'IDAT') {
            for (let i = 0; i < c.dataLen; i++) idatData.push(data[c.dataStart + i]);
        }
    }
    const zlibData = new Uint8Array(idatData);

    // Parse zlib header
    let deflateStart = 2; // skip CMF, FLG
    if ((zlibData[1] & 0x20) !== 0) deflateStart = 6; // skip DICTID

    // Inflate
    const result = inflate(zlibData, deflateStart);

    // Check Adler-32 - must align to byte boundary after DEFLATE stream
    let adlerPos = result.endPos;
    if (result.bitPos !== 0) adlerPos++;
    const storedAdler = ((zlibData[adlerPos] << 24) | (zlibData[adlerPos + 1] << 16) | (zlibData[adlerPos + 2] << 8) | zlibData[adlerPos + 3]) >>> 0;
    const computedAdler = adler32(result.data);
    if (storedAdler !== computedAdler) {
        return lines.join('\n') + '\n' + 'error: Adler-32 mismatch';
    }

    // Determine channels and bytes per pixel
    let channels: number;
    switch (colorType) {
        case 0: channels = 1; break;
        case 2: channels = 3; break;
        case 3: channels = 1; break;
        case 4: channels = 2; break;
        case 6: channels = 4; break;
        default: channels = 1;
    }
    const bitsPerPixel = channels * bitDepth;
    const bytesPerPixel = Math.max(1, Math.ceil(bitsPerPixel / 8));
    const bpp = bytesPerPixel;
    const rawRowBytes = Math.ceil(width * bitsPerPixel / 8);

    // Filter reversal
    const decompressed = result.data;
    const rawRows: Uint8Array[] = [];
    let offset = 0;
    const filterCounts = [0, 0, 0, 0, 0];

    for (let y = 0; y < height; y++) {
        const filterType = decompressed[offset++];
        filterCounts[filterType]++;
        const row = new Uint8Array(rawRowBytes);
        const prevRow = y > 0 ? rawRows[y - 1] : new Uint8Array(rawRowBytes);

        for (let x = 0; x < rawRowBytes; x++) {
            const raw = decompressed[offset + x];
            let a = 0, b = 0, c = 0;
            if (x >= bpp) a = row[x - bpp];
            b = prevRow[x];
            if (x >= bpp) c = prevRow[x - bpp];

            let val: number;
            switch (filterType) {
                case 0: val = raw; break;
                case 1: val = (raw + a) & 0xFF; break;
                case 2: val = (raw + b) & 0xFF; break;
                case 3: val = (raw + ((a + b) >> 1)) & 0xFF; break;
                case 4: val = (raw + paeth(a, b, c)) & 0xFF; break;
                default: val = raw;
            }
            row[x] = val;
        }
        offset += rawRowBytes;
        rawRows.push(row);
    }

    // Convert to RGBA
    const rgbaBuf = new Uint8Array(width * height * 4);
    let sumR = 0, sumG = 0, sumB = 0, sumA = 0;
    let rgbaIdx = 0;

    function getPixelValue(row: Uint8Array, x: number): number {
        if (bitDepth >= 8) {
            const byteIdx = x * (bitDepth / 8);
            if (bitDepth === 8) return row[byteIdx];
            else return (row[byteIdx] << 8) | row[byteIdx + 1]; // 16-bit big-endian
        } else {
            const bitPos = x * bitDepth;
            const byteIdx = bitPos >> 3;
            const bitOffset = 8 - (bitPos & 7) - bitDepth;
            return (row[byteIdx] >> bitOffset) & ((1 << bitDepth) - 1);
        }
    }

    function to8bit(val: number): number {
        if (bitDepth === 16) return val >> 8;
        if (bitDepth === 8) return val;
        return Math.round(val * 255 / ((1 << bitDepth) - 1));
    }

    // tRNS values for types 0 and 2 (stored as 16-bit big-endian)
    let trnsGray = -1, trnsR = -1, trnsG = -1, trnsB = -1;
    if (trns && (colorType === 0 || colorType === 2)) {
        if (colorType === 0) {
            trnsGray = (trns[0] << 8) | trns[1];
        } else {
            trnsR = (trns[0] << 8) | trns[1];
            trnsG = (trns[2] << 8) | trns[3];
            trnsB = (trns[4] << 8) | trns[5];
        }
    }

    for (let y = 0; y < height; y++) {
        const row = rawRows[y];
        for (let x = 0; x < width; x++) {
            let r = 0, g = 0, b = 0, a = 255;

            if (colorType === 0) {
                const gray = getPixelValue(row, x);
                const gray8 = to8bit(gray);
                r = g = b = gray8;
                if (trnsGray >= 0) {
                    const trnsVal = bitDepth === 16 ? trnsGray : (trnsGray & ((1 << bitDepth) - 1));
                    a = (gray === trnsVal) ? 0 : 255;
                }
            } else if (colorType === 2) {
                const rv = getPixelValue(row, x * 3);
                const gv = getPixelValue(row, x * 3 + 1);
                const bv = getPixelValue(row, x * 3 + 2);
                r = to8bit(rv); g = to8bit(gv); b = to8bit(bv);
                if (trnsR >= 0) {
                    const tr = bitDepth === 16 ? trnsR : (trnsR & ((1 << bitDepth) - 1));
                    const tg = bitDepth === 16 ? trnsG : (trnsG & ((1 << bitDepth) - 1));
                    const tb = bitDepth === 16 ? trnsB : (trnsB & ((1 << bitDepth) - 1));
                    a = (rv === tr && gv === tg && bv === tb) ? 0 : 255;
                }
            } else if (colorType === 3) {
                const idx = getPixelValue(row, x);
                if (plte) {
                    r = plte[idx * 3];
                    g = plte[idx * 3 + 1];
                    b = plte[idx * 3 + 2];
                }
                if (trns && idx < trns.length) {
                    a = trns[idx];
                }
            } else if (colorType === 4) {
                const gray = getPixelValue(row, x * 2);
                const alpha = getPixelValue(row, x * 2 + 1);
                r = g = b = to8bit(gray);
                a = to8bit(alpha);
            } else if (colorType === 6) {
                const rv = getPixelValue(row, x * 4);
                const gv = getPixelValue(row, x * 4 + 1);
                const bv = getPixelValue(row, x * 4 + 2);
                const av = getPixelValue(row, x * 4 + 3);
                r = to8bit(rv); g = to8bit(gv); b = to8bit(bv); a = to8bit(av);
            }

            rgbaBuf[rgbaIdx++] = r;
            rgbaBuf[rgbaIdx++] = g;
            rgbaBuf[rgbaIdx++] = b;
            rgbaBuf[rgbaIdx++] = a;
            sumR += r; sumG += g; sumB += b; sumA += a;
        }
    }

    // Format chunks line
    const chunkParts: string[] = [];
    let ci = 0;
    while (ci < chunkTypes.length) {
        let j = ci + 1;
        while (j < chunkTypes.length && chunkTypes[j] === chunkTypes[ci]) j++;
        const count = j - ci;
        if (count > 1) chunkParts.push(`${chunkTypes[ci]}*${count}`);
        else chunkParts.push(chunkTypes[ci]);
        ci = j;
    }

    const rgbaCrc = crc32(rgbaBuf, 0, rgbaBuf.length);
    const crcHex = rgbaCrc.toString(16).padStart(8, '0');

    lines.push(`IHDR ${width}x${height} depth=${bitDepth} color=${colorType}`);
    lines.push(`chunks ${chunkParts.join(' ')}`);
    lines.push(`deflate stored=${result.stored} fixed=${result.fixed} dynamic=${result.dynamic}`);
    lines.push(`filters none=${filterCounts[0]} sub=${filterCounts[1]} up=${filterCounts[2]} average=${filterCounts[3]} paeth=${filterCounts[4]}`);
    lines.push(`rgba sum=${sumR},${sumG},${sumB},${sumA} crc32=${crcHex}`);

    return lines.join('\n');
}

// Main
const dir = process.argv[2];
const files = fs.readdirSync(dir).filter(f => f.endsWith('.png'));
files.sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));

const outputs: string[] = [];
for (const f of files) {
    outputs.push(processFile(path.join(dir, f), f));
}
process.stdout.write(outputs.join('\n') + (outputs.length > 0 ? '\n' : ''));

import java.io.*;
import java.nio.file.*;
import java.awt.image.*;
import javax.imageio.*;
import java.util.*;

public class Main {
    static String json;
    static int pos;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        json = new String(Files.readAllBytes(Paths.get(dir, "scene.json")), "UTF-8");
        pos = 0;

        @SuppressWarnings("unchecked")
        Map<String, Object> scene = (Map<String, Object>) parseValue();

        int width = ((Number) scene.get("width")).intValue();
        int height = ((Number) scene.get("height")).intValue();
        @SuppressWarnings("unchecked")
        List<Object> bgList = (List<Object>) scene.get("background");
        int bgR = ((Number) bgList.get(0)).intValue();
        int bgG = ((Number) bgList.get(1)).intValue();
        int bgB = ((Number) bgList.get(2)).intValue();

        @SuppressWarnings("unchecked")
        List<Object> shapesList = (List<Object>) scene.get("shapes");

        // Canvas stored as int arrays
        int[][] canvasR = new int[height][width];
        int[][] canvasG = new int[height][width];
        int[][] canvasB = new int[height][width];
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++) {
                canvasR[y][x] = bgR;
                canvasG[y][x] = bgG;
                canvasB[y][x] = bgB;
            }

        StringBuilder output = new StringBuilder();

        for (int si = 0; si < shapesList.size(); si++) {
            @SuppressWarnings("unchecked")
            Map<String, Object> shape = (Map<String, Object>) shapesList.get(si);
            String type = (String) shape.get("type");
            @SuppressWarnings("unchecked")
            List<Object> colorList = (List<Object>) shape.get("color");
            int sR = ((Number) colorList.get(0)).intValue();
            int sG = ((Number) colorList.get(1)).intValue();
            int sB = ((Number) colorList.get(2)).intValue();
            int alpha = ((Number) colorList.get(3)).intValue();

            long covered = 0;

            if (type.equals("rect")) {
                long rx = ((Number) shape.get("x")).longValue();
                long ry = ((Number) shape.get("y")).longValue();
                long w = ((Number) shape.get("w")).longValue();
                long h = ((Number) shape.get("h")).longValue();

                int xStart = (int) Math.max(0, rx);
                int xEnd = (int) Math.min(width - 1, rx + w - 1);
                int yStart = (int) Math.max(0, ry);
                int yEnd = (int) Math.min(height - 1, ry + h - 1);

                for (int y = yStart; y <= yEnd; y++) {
                    for (int x = xStart; x <= xEnd; x++) {
                        covered++;
                        if (alpha > 0) {
                            canvasR[y][x] = (sR * alpha + canvasR[y][x] * (255 - alpha) + 127) / 255;
                            canvasG[y][x] = (sG * alpha + canvasG[y][x] * (255 - alpha) + 127) / 255;
                            canvasB[y][x] = (sB * alpha + canvasB[y][x] * (255 - alpha) + 127) / 255;
                        }
                    }
                }
            } else if (type.equals("circle")) {
                long cx = ((Number) shape.get("cx")).longValue();
                long cy = ((Number) shape.get("cy")).longValue();
                long r = ((Number) shape.get("r")).longValue();
                long r2 = r * r;

                for (int y = 0; y < height; y++) {
                    long dy = y - cy;
                    long dy2 = dy * dy;
                    for (int x = 0; x < width; x++) {
                        long dx = x - cx;
                        if (dx * dx + dy2 <= r2) {
                            covered++;
                            if (alpha > 0) {
                                canvasR[y][x] = (sR * alpha + canvasR[y][x] * (255 - alpha) + 127) / 255;
                                canvasG[y][x] = (sG * alpha + canvasG[y][x] * (255 - alpha) + 127) / 255;
                                canvasB[y][x] = (sB * alpha + canvasB[y][x] * (255 - alpha) + 127) / 255;
                            }
                        }
                    }
                }
            } else if (type.equals("triangle")) {
                @SuppressWarnings("unchecked")
                List<Object> pts = (List<Object>) shape.get("points");
                long[] px = new long[3], py = new long[3];
                for (int i = 0; i < 3; i++) {
                    @SuppressWarnings("unchecked")
                    List<Object> p = (List<Object>) pts.get(i);
                    px[i] = ((Number) p.get(0)).longValue();
                    py[i] = ((Number) p.get(1)).longValue();
                }

                for (int y = 0; y < height; y++) {
                    for (int x = 0; x < width; x++) {
                        long e0 = (px[1] - px[0]) * (y - py[0]) - (py[1] - py[0]) * (x - px[0]);
                        long e1 = (px[2] - px[1]) * (y - py[1]) - (py[2] - py[1]) * (x - px[1]);
                        long e2 = (px[0] - px[2]) * (y - py[2]) - (py[0] - py[2]) * (x - px[2]);

                        boolean allNonNeg = (e0 >= 0 && e1 >= 0 && e2 >= 0);
                        boolean allNonPos = (e0 <= 0 && e1 <= 0 && e2 <= 0);

                        if (allNonNeg || allNonPos) {
                            covered++;
                            if (alpha > 0) {
                                canvasR[y][x] = (sR * alpha + canvasR[y][x] * (255 - alpha) + 127) / 255;
                                canvasG[y][x] = (sG * alpha + canvasG[y][x] * (255 - alpha) + 127) / 255;
                                canvasB[y][x] = (sB * alpha + canvasB[y][x] * (255 - alpha) + 127) / 255;
                            }
                        }
                    }
                }
            } else if (type.equals("line")) {
                long x1 = ((Number) shape.get("x1")).longValue();
                long y1 = ((Number) shape.get("y1")).longValue();
                long x2 = ((Number) shape.get("x2")).longValue();
                long y2 = ((Number) shape.get("y2")).longValue();
                long r = ((Number) shape.get("r")).longValue();
                long r2 = r * r;
                long dx = x2 - x1;
                long dy = y2 - y1;
                long L = dx * dx + dy * dy;

                for (int y = 0; y < height; y++) {
                    long py1 = y - y1;
                    for (int x = 0; x < width; x++) {
                        long px1 = x - x1;
                        long t = px1 * dx + py1 * dy;
                        boolean covers;
                        if (t <= 0) {
                            covers = px1 * px1 + py1 * py1 <= r2;
                        } else if (t >= L) {
                            long px2 = x - x2;
                            long py2 = y - y2;
                            covers = px2 * px2 + py2 * py2 <= r2;
                        } else {
                            long c = px1 * dy - py1 * dx;
                            covers = c * c <= r2 * L;
                        }
                        if (covers) {
                            covered++;
                            if (alpha > 0) {
                                canvasR[y][x] = (sR * alpha + canvasR[y][x] * (255 - alpha) + 127) / 255;
                                canvasG[y][x] = (sG * alpha + canvasG[y][x] * (255 - alpha) + 127) / 255;
                                canvasB[y][x] = (sB * alpha + canvasB[y][x] * (255 - alpha) + 127) / 255;
                            }
                        }
                    }
                }
            }

            output.append(si + 1).append(" ").append(type).append(" ").append(covered).append("\n");
        }

        // Count distinct colors
        Set<Integer> colorSet = new HashSet<>();
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                colorSet.add(canvasR[y][x] * 65536 + canvasG[y][x] * 256 + canvasB[y][x]);
        output.append("colors ").append(colorSet.size()).append("\n");

        System.out.print(output.toString());

        // Write PNG
        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                img.setRGB(x, y, (canvasR[y][x] << 16) | (canvasG[y][x] << 8) | canvasB[y][x]);

        ImageIO.write(img, "PNG", new File("out.png"));
    }

    // --- JSON Parser ---
    static void skipWhitespace() {
        while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
    }

    static Object parseValue() {
        skipWhitespace();
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't' || c == 'f') return parseBoolean();
        if (c == 'n') { pos += 4; return null; }
        return parseNumber();
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++; // skip {
        skipWhitespace();
        if (json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWhitespace();
            String key = parseString();
            skipWhitespace();
            pos++; // skip :
            Object val = parseValue();
            map.put(key, val);
            skipWhitespace();
            if (json.charAt(pos) == ',') { pos++; }
            else break;
        }
        pos++; // skip }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++; // skip [
        skipWhitespace();
        if (json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            list.add(parseValue());
            skipWhitespace();
            if (json.charAt(pos) == ',') { pos++; }
            else break;
        }
        pos++; // skip ]
        return list;
    }

    static String parseString() {
        pos++; // skip opening "
        StringBuilder sb = new StringBuilder();
        while (json.charAt(pos) != '"') {
            if (json.charAt(pos) == '\\') {
                pos++;
                char esc = json.charAt(pos);
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        String hex = json.substring(pos + 1, pos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        pos += 4;
                        break;
                }
            } else {
                sb.append(json.charAt(pos));
            }
            pos++;
        }
        pos++; // skip closing "
        return sb.toString();
    }

    static Long parseNumber() {
        int start = pos;
        if (json.charAt(pos) == '-') pos++;
        while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
        if (pos < json.length() && json.charAt(pos) == '.') {
            pos++;
            while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
        }
        if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
            pos++;
            if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
            while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
        }
        String numStr = json.substring(start, pos);
        if (numStr.contains(".") || numStr.contains("e") || numStr.contains("E")) {
            return (long) Double.parseDouble(numStr);
        }
        return Long.parseLong(numStr);
    }

    static Boolean parseBoolean() {
        if (json.charAt(pos) == 't') { pos += 4; return true; }
        else { pos += 5; return false; }
    }
}

