                count = (x_end - x_start) * (y_end - y_start)
                if A == 255:
                    for y in range(y_start, y_end):
                        row = y * width
                        for x in range(x_start, x_end):
                            canvas[row + x] = [sR, sG, sB]
                elif A > 0:
                    inv = 255 - A
                    for y in range(y_start, y_end):
                        row = y * width
                        for x in range(x_start, x_end):
                            px = canvas[row + x]
                            px[0] = (sR * A + px[0] * inv + 127) // 255
                            px[1] = (sG * A + px[1] * inv + 127) // 255
                            px[2] = (sB * A + px[2] * inv + 127) // 255

        elif stype == 'circle':
            cx, cy, r = shape['cx'], shape['cy'], shape['r']
            r2 = r * r
            y_start = max(0, cy - r)
            y_end = min(height, cy + r + 1)

            if A == 255:
                for y in range(y_start, y_end):
                    dy = y - cy
                    rem = r2 - dy * dy
                    if rem < 0:
                        continue
                    dx_max = math.isqrt(rem)
                    x_lo = max(0, cx - dx_max)
                    x_hi = min(width, cx + dx_max + 1)
                    if x_lo >= x_hi:
                        continue
                    count += x_hi - x_lo
                    row = y * width
                    for x in range(x_lo, x_hi):
                        canvas[row + x] = [sR, sG, sB]
            elif A > 0:
                inv = 255 - A
                for y in range(y_start, y_end):
                    dy = y - cy
                    rem = r2 - dy * dy
                    if rem < 0:
                        continue
                    dx_max = math.isqrt(rem)
                    x_lo = max(0, cx - dx_max)
                    x_hi = min(width, cx + dx_max + 1)
                    if x_lo >= x_hi:
                        continue
                    count += x_hi - x_lo
                    row = y * width
                    for x in range(x_lo, x_hi):
                        px = canvas[row + x]
                        px[0] = (sR * A + px[0] * inv + 127) // 255
                        px[1] = (sG * A + px[1] * inv + 127) // 255
                        px[2] = (sB * A + px[2] * inv + 127) // 255
            else:
                for y in range(y_start, y_end):
                    dy = y - cy
                    rem = r2 - dy * dy
                    if rem < 0:
                        continue
                    dx_max = math.isqrt(rem)
                    x_lo = max(0, cx - dx_max)
                    x_hi = min(width, cx + dx_max + 1)
                    if x_lo < x_hi:
                        count += x_hi - x_lo

        elif stype == 'triangle':
            pts = shape['points']
            x0, y0 = pts[0]
            x1, y1 = pts[1]
            x2, y2 = pts[2]

            cross = (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0)
            ccw = cross > 0

            x_start = max(0, min(x0, x1, x2))
            x_end = min(width, max(x0, x1, x2) + 1)
            y_start = max(0, min(y0, y1, y2))
            y_end = min(height, max(y0, y1, y2) + 1)

            # Precompute edge parameters: (xi, yi, a, b) for edge from (xi,yi) to (xi+a, yi+b)
            edges = []
            for i in range(3):
                j = (i + 1) % 3
                xi, yi = pts[i]
                xj, yj = pts[j]
                edges.append((xi, yi, xj - xi, yj - yi))

            for y in range(y_start, y_end):
                x_lo = x_start
                x_hi = x_end
                valid = True
                for xi, yi, a, b in edges:
                    dy = y - yi
                    if b == 0:
                        # E = a * dy (constant, no x dependency)
                        if ccw:
                            if a * dy < 0:
                                valid = False
                                break
                        else:
                            if a * dy > 0:
                                valid = False
                                break
                    else:
                        # E = a*dy - b*(x - xi)
                        # ccw: E >= 0 => b*(x-xi) <= a*dy
                        # cw:  E <= 0 => b*(x-xi) >= a*dy
                        if ccw:
                            if b > 0:
                                # x <= xi + (a*dy)//b
                                val = xi + (a * dy) // b
                                if val + 1 < x_hi:
                                    x_hi = val + 1
                            else:
                                # x >= xi + ceil(a*dy / b)
                                val = xi + (-((-a * dy) // b))
                                if val > x_lo:
                                    x_lo = val
                        else:
                            if b > 0:
                                # x >= xi + ceil(a*dy / b)
                                val = xi + (-((-a * dy) // b))
                                if val > x_lo:
                                    x_lo = val
                            else:
                                # x <= xi + (a*dy)//b
                                val = xi + (a * dy) // b
                                if val + 1 < x_hi:
                                    x_hi = val + 1

                if not valid or x_lo >= x_hi:
                    continue

                if x_lo < x_start:
                    x_lo = x_start
                if x_hi > x_end:
                    x_hi = x_end
                if x_lo >= x_hi:
                    continue

                count += x_hi - x_lo

                if A == 255:
                    row = y * width
                    for x in range(x_lo, x_hi):
                        canvas[row + x] = [sR, sG, sB]
                elif A > 0:
                    inv = 255 - A
                    row = y * width
                    for x in range(x_lo, x_hi):
                        px = canvas[row + x]
                        px[0] = (sR * A + px[0] * inv + 127) // 255
                        px[1] = (sG * A + px[1] * inv + 127) // 255
                        px[2] = (sB * A + px[2] * inv + 127) // 255

        elif stype == 'line':
            x1l, y1l, x2l, y2l, r = shape['x1'], shape['y1'], shape['x2'], shape['y2'], shape['r']
            dx = x2l - x1l
            dy = y2l - y1l
            L = dx * dx + dy * dy
            r2 = r * r
            r2L = r2 * L

            x_start = max(0, min(x1l, x2l) - r)
            x_end = min(width, max(x1l, x2l) + r + 1)
            y_start = max(0, min(y1l, y2l) - r)
            y_end = min(height, max(y1l, y2l) + r + 1)

            if x_start < x_end and y_start < y_end:
                if A == 255:
                    for y in range(y_start, y_end):
                        row = y * width
                        for x in range(x_start, x_end):
                            t = (x - x1l) * dx + (y - y1l) * dy
                            if t <= 0:
                                covered = (x - x1l) * (x - x1l) + (y - y1l) * (y - y1l) <= r2
                            elif t >= L:
                                covered = (x - x2l) * (x - x2l) + (y - y2l) * (y - y2l) <= r2
                            else:
                                c = (x - x1l) * dy - (y - y1l) * dx
                                covered = c * c <= r2L
                            if covered:
                                canvas[row + x] = [sR, sG, sB]
                                count += 1
                elif A > 0:
                    inv = 255 - A
                    for y in range(y_start, y_end):
                        row = y * width
                        for x in range(x_start, x_end):
                            t = (x - x1l) * dx + (y - y1l) * dy
                            if t <= 0:
                                covered = (x - x1l) * (x - x1l) + (y - y1l) * (y - y1l) <= r2
                            elif t >= L:
                                covered = (x - x2l) * (x - x2l) + (y - y2l) * (y - y2l) <= r2
                            else:
                                c = (x - x1l) * dy - (y - y1l) * dx
                                covered = c * c <= r2L
                            if covered:
                                px = canvas[row + x]
                                px[0] = (sR * A + px[0] * inv + 127) // 255
                                px[1] = (sG * A + px[1] * inv + 127) // 255
                                px[2] = (sB * A + px[2] * inv + 127) // 255
                                count += 1
                else:
                    for y in range(y_start, y_end):
                        for x in range(x_start, x_end):
                            t = (x - x1l) * dx + (y - y1l) * dy
                            if t <= 0:
                                covered = (x - x1l) * (x - x1l) + (y - y1l) * (y - y1l) <= r2
                            elif t >= L:
                                covered = (x - x2l) * (x - x2l) + (y - y2l) * (y - y2l) <= r2
                            else:
                                c = (x - x1l) * dy - (y - y1l) * dx
                                covered = c * c <= r2L
                            if covered:
                                count += 1

        results.append((idx, stype, count))

    # Print summary
    for idx, stype, count in results:
        print(f"{idx} {stype} {count}")

    # Count distinct colors
    colors = set()
    for i in range(width * height):
        colors.add(tuple(canvas[i]))
    print(f"colors {len(colors)}")

    # Write PNG
    write_png('out.png', width, height, canvas)


def write_png(filename, width, height, canvas):
    sig = b'\x89PNG\r\n\x1a\n'

    ihdr_data = struct.pack('>IIBBBBB', width, height, 8, 2, 0, 0, 0)
    ihdr = make_chunk(b'IHDR', ihdr_data)

    raw = bytearray()
    for y in range(height):
        raw.append(0)  # filter type None
        row = y * width
        for x in range(width):
            px = canvas[row + x]
            raw.append(px[0])
            raw.append(px[1])
            raw.append(px[2])

    compressed = zlib.compress(bytes(raw))
    idat = make_chunk(b'IDAT', compressed)

    iend = make_chunk(b'IEND', b'')

    with open(filename, 'wb') as f:
        f.write(sig)
        f.write(ihdr)
        f.write(idat)
        f.write(iend)


def make_chunk(chunk_type, data):
    chunk = chunk_type + data
    return struct.pack('>I', len(data)) + chunk + struct.pack('>I', zlib.crc32(chunk) & 0xffffffff)


