func covers(_ shape: [String: Any], _ x: Int, _ y: Int) -> Bool {
    let type = shape["type"] as! String
    switch type {
    case "rect":
        let rx = shape["x"] as! Int
        let ry = shape["y"] as! Int
        let w = shape["w"] as! Int
        let h = shape["h"] as! Int
        return rx <= x && x < rx + w && ry <= y && y < ry + h
    case "circle":
        let cx = shape["cx"] as! Int
        let cy = shape["cy"] as! Int
        let r = shape["r"] as! Int
        let dx = x - cx
        let dy = y - cy
        return dx * dx + dy * dy <= r * r
    case "triangle":
        let pts = shape["points"] as! [[Int]]
        let x0 = pts[0][0], y0 = pts[0][1]
        let x1 = pts[1][0], y1 = pts[1][1]
        let x2 = pts[2][0], y2 = pts[2][1]
        let e0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0)
        let e1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1)
        let e2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2)
        return (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
    case "line":
        let x1 = shape["x1"] as! Int
        let y1 = shape["y1"] as! Int
        let x2 = shape["x2"] as! Int
        let y2 = shape["y2"] as! Int
        let r = shape["r"] as! Int
        let dx = x2 - x1
        let dy = y2 - y1
        let L = dx * dx + dy * dy
        let t = (x - x1) * dx + (y - y1) * dy
        if t <= 0 {
            let ddx = x - x1, ddy = y - y1
            return ddx * ddx + ddy * ddy <= r * r
        } else if t >= L {
            let ddx = x - x2, ddy = y - y2
            return ddx * ddx + ddy * ddy <= r * r
        } else {
            let c = (x - x1) * dy - (y - y1) * dx
            return c * c <= r * r * L
        }
    default:
        return false
    }
}

