/* ============ Growable buffer ============ */
typedef struct { char *data; size_t len, cap; } buf_t;
static void buf_init(buf_t *b) { b->data=NULL; b->len=0; b->cap=0; }
static void buf_append(buf_t *b, const char *s, size_t n) {
    if(b->len+n > b->cap){ b->cap=(b->len+n)*2; if(b->cap<256)b->cap=256; b->data=realloc(b->data,b->cap); }
    memcpy(b->data+b->len,s,n); b->len+=n;
}
static void buf_appendc(buf_t *b, char c){ buf_append(b,&c,1); }
static void buf_appends(buf_t *b, const char *s){ buf_append(b,s,strlen(s)); }

/* ============ Base64 ============ */
static const char b64_tab[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char *base64_encode(const unsigned char *data, size_t len){
    size_t olen=4*((len+2)/3);
    char *out=malloc(olen+1);
    size_t i,j;
    for(i=0,j=0;i<len;){
        unsigned int a=i<len?data[i++]:0;
        unsigned int b=i<len?data[i++]:0;
        unsigned int c=i<len?data[i++]:0;
        unsigned int t=(a<<16)|(b<<8)|c;
        out[j++]=b64_tab[(t>>18)&0x3F];
        out[j++]=b64_tab[(t>>12)&0x3F];
        out[j++]=b64_tab[(t>>6)&0x3F];
        out[j++]=b64_tab[t&0x3F];
    }
    if(len%3==1){out[olen-2]='=';out[olen-1]='=';}
    else if(len%3==2){out[olen-1]='=';}
    out[olen]='\0';
    return out;
}

/* ============ URL encoding ============ */
static char *url_encode_rfc6749(const char *s){
    buf_t b; buf_init(&b);
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if(isalnum(*p)||*p=='-'||*p=='.'||*p=='_'||*p=='*') buf_appendc(&b,*p);
        else if(*p==' ') buf_appends(&b,"+");
        else { char h[4]; snprintf(h,4,"%%%02X",*p); buf_appends(&b,h); }
    }
    buf_appendc(&b,'\0');
    return b.data;
}
static char *url_encode_query(const char *s){
    buf_t b; buf_init(&b);
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if(isalnum(*p)||*p=='-'||*p=='.'||*p=='_'||*p=='~') buf_appendc(&b,*p);
        else { char h[4]; snprintf(h,4,"%%%02X",*p); buf_appends(&b,h); }
    }
    buf_appendc(&b,'\0');
    return b.data;
}

/* ============ JSON Parser ============ */
typedef enum{JV_NULL,JV_TRUE,JV_FALSE,JV_NUMBER,JV_STRING,JV_ARRAY,JV_OBJECT}jtype;
typedef struct jval{
    jtype type;
    char *str;
    long long num;
    struct jval **arr; int arr_len;
    char **keys; struct jval **vals; int obj_len;
}jval;

static void skip_ws(const char **pp){ while(**pp==' '||**pp=='\t'||**pp=='\n'||**pp=='\r')(*pp)++; }
static int hex_val(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return 0; }

static void utf8_encode(int cp, buf_t *out){
    if(cp<0x80){ buf_appendc(out,cp); }
    else if(cp<0x800){ buf_appendc(out,0xC0|(cp>>6)); buf_appendc(out,0x80|(cp&0x3F)); }
    else if(cp<0x10000){ buf_appendc(out,0xE0|(cp>>12)); buf_appendc(out,0x80|((cp>>6)&0x3F)); buf_appendc(out,0x80|(cp&0x3F)); }
    else{ buf_appendc(out,0xF0|(cp>>18)); buf_appendc(out,0x80|((cp>>12)&0x3F)); buf_appendc(out,0x80|((cp>>6)&0x3F)); buf_appendc(out,0x80|(cp&0x3F)); }
}

static char *parse_json_string(const char **pp){
    (*pp)++;
    buf_t b; buf_init(&b);
    while(**pp!='"'){
        if(**pp=='\\'){
            (*pp)++;
            switch(**pp){
                case '"': buf_appendc(&b,'"'); break;
                case '\\':buf_appendc(&b,'\\');break;
                case '/': buf_appendc(&b,'/'); break;
                case 'b': buf_appendc(&b,'\b');break;
                case 'f': buf_appendc(&b,'\f');break;
                case 'n': buf_appendc(&b,'\n');break;
                case 'r': buf_appendc(&b,'\r');break;
                case 't': buf_appendc(&b,'\t');break;
                case 'u':{
                    (*pp)++;
                    int cp=0;
                    for(int i=0;i<4;i++) cp=(cp<<4)|hex_val(*(*pp)++);
                    (*pp)--;
                    if(cp>=0xD800&&cp<=0xDBFF){
                        (*pp)++;
                        if(**pp=='\\'&&(*pp)[1]=='u'){
                            *pp+=2;
                            int lo=0;
                            for(int i=0;i<4;i++) lo=(lo<<4)|hex_val(*(*pp)++);
                            (*pp)--;
                            cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                        }
                    }
                    utf8_encode(cp,&b);
                    break;
                }
                default: buf_appendc(&b,**pp); break;
            }
            (*pp)++;
        } else {
            buf_appendc(&b,**pp);
            (*pp)++;
        }
    }
    (*pp)++;
    buf_appendc(&b,'\0');
    return b.data;
}

static jval *parse_value(const char **pp);

static jval *parse_object(const char **pp){
    jval *v=calloc(1,sizeof(jval)); v->type=JV_OBJECT;
    (*pp)++; skip_ws(pp);
    if(**pp=='}'){(*pp)++;return v;}
    int cap=8;
    v->keys=malloc(cap*sizeof(char*)); v->vals=malloc(cap*sizeof(jval*));
    while(1){
        skip_ws(pp);
        char *key=parse_json_string(pp);
        skip_ws(pp); (*pp)++; skip_ws(pp);
        jval *val=parse_value(pp);
        if(v->obj_len>=cap){cap*=2;v->keys=realloc(v->keys,cap*sizeof(char*));v->vals=realloc(v->vals,cap*sizeof(jval*));}
        v->keys[v->obj_len]=key; v->vals[v->obj_len]=val; v->obj_len++;
        skip_ws(pp);
        if(**pp==','){(*pp)++;continue;}
        if(**pp=='}'){(*pp)++;break;}
        break;
    }
    return v;
}

static jval *parse_array(const char **pp){
    jval *v=calloc(1,sizeof(jval)); v->type=JV_ARRAY;
    (*pp)++; skip_ws(pp);
    if(**pp==']'){(*pp)++;return v;}
    int cap=8;
    v->arr=malloc(cap*sizeof(jval*));
    while(1){
        skip_ws(pp);
        jval *item=parse_value(pp);
        if(v->arr_len>=cap){cap*=2;v->arr=realloc(v->arr,cap*sizeof(jval*));}
        v->arr[v->arr_len++]=item;
        skip_ws(pp);
        if(**pp==','){(*pp)++;continue;}
        if(**pp==']'){(*pp)++;break;}
        break;
    }
    return v;
}

static jval *parse_value(const char **pp){
    skip_ws(pp);
    if(**pp=='"'){jval*v=calloc(1,sizeof(jval));v->type=JV_STRING;v->str=parse_json_string(pp);return v;}
    if(**pp=='{')return parse_object(pp);
    if(**pp=='[')return parse_array(pp);
    jval *v=calloc(1,sizeof(jval));
    if(!strncmp(*pp,"null",4)){v->type=JV_NULL;*pp+=4;}
    else if(!strncmp(*pp,"true",4)){v->type=JV_TRUE;*pp+=4;}
    else if(!strncmp(*pp,"false",5)){v->type=JV_FALSE;*pp+=5;}
    else{
        v->type=JV_NUMBER;
        char *end;
        v->num=strtoll(*pp,&end,10);
        *pp=end;
        if(**pp=='.'){(*pp)++;while(isdigit(**pp))(*pp)++;}
        if(**pp=='e'||**pp=='E'){(*pp)++;if(**pp=='+'||**pp=='-')(*pp)++;while(isdigit(**pp))(*pp)++;}
    }
    return v;
}

static jval *jget(jval *obj,const char *key){
    if(!obj||obj->type!=JV_OBJECT)return NULL;
    for(int i=0;i<obj->obj_len;i++) if(strcmp(obj->keys[i],key)==0)return obj->vals[i];
    return NULL;
}

/* ============ HTTP Client ============ */
typedef struct{
    int status;
    char *body; size_t body_len;
    char *hn[64]; char *hv[64]; int hc;
}http_resp;

static char *get_header(http_resp *r,const char *name){
    for(int i=0;i<r->hc;i++) if(strcasecmp(r->hn[i],name)==0)return r->hv[i];
    return NULL;
}

static http_resp *http_request(const char *host,int port,const char *method,
    const char *path,const char *extra_hdrs,const char *body,size_t body_len)
{
    int fd=socket(AF_INET,SOCK_STREAM,0);
    struct addrinfo hints={0},*res;
    hints.ai_family=AF_INET; hints.ai_socktype=SOCK_STREAM;
    char ps[16]; snprintf(ps,16,"%d",port);
    getaddrinfo(host,ps,&hints,&res);
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){perror("connect");exit(1);}
    freeaddrinfo(res);

    buf_t req; buf_init(&req);
    buf_appends(&req,method); buf_appendc(&req,' ');
    buf_appends(&req,path); buf_appends(&req," HTTP/1.1\r\n");
    buf_appends(&req,"Host: "); buf_appends(&req,host);
    if(port!=80){char p2[16];snprintf(p2,16,":%d",port);buf_appends(&req,p2);}
    buf_appends(&req,"\r\nConnection: close\r\n");
    if(extra_hdrs)buf_appends(&req,extra_hdrs);
    if(body&&body_len>0){char cl[64];snprintf(cl,64,"Content-Length: %zu\r\n",body_len);buf_appends(&req,cl);}
    buf_appends(&req,"\r\n");
    if(body&&body_len>0)buf_append(&req,body,body_len);

    write(fd,req.data,req.len);
    shutdown(fd,SHUT_WR);

    buf_t resp; buf_init(&resp);
    char tmp[8192]; ssize_t n;
    while((n=read(fd,tmp,sizeof(tmp)))>0) buf_append(&resp,tmp,n);
    close(fd);

    http_resp *r=calloc(1,sizeof(http_resp));
    char *data=resp.data;
    char *pos=data;

    if(strncmp(pos,"HTTP/1.1 ",9)==0||strncmp(pos,"HTTP/1.0 ",9)==0){pos+=9;r->status=atoi(pos);}
    char *eol=strstr(pos,"\r\n");
    if(eol)pos=eol+2;

    while(pos<data+resp.len){
        eol=strstr(pos,"\r\n");
        if(!eol||eol==pos){if(eol)pos=eol+2;break;}
        *eol='\0';
        char *colon=strchr(pos,':');
        if(colon){
            *colon='\0';
            char *val=colon+1;
            while(*val==' ')val++;
            if(r->hc<64){r->hn[r->hc]=strdup(pos);r->hv[r->hc]=strdup(val);r->hc++;}
        }
        pos=eol+2;
    }

    char *body_start=pos;
    size_t body_avail=(data+resp.len)-body_start;
    char *te=get_header(r,"Transfer-Encoding");
    char *cl_str=get_header(r,"Content-Length");

    if(te&&strcasestr(te,"chunked")){
        buf_t dec; buf_init(&dec);
        char *cp=body_start,*end=data+resp.len;
        while(cp<end){
            char *endptr;
            long cs=strtol(cp,&endptr,16);
            cp=endptr;
            while(cp<end&&*cp!='\n')cp++;
            if(cp<end)cp++;
            if(cs==0)break;
            if(cp+cs<=end){buf_append(&dec,cp,cs);cp+=cs;}
            if(cp<end&&*cp=='\r')cp++;
            if(cp<end&&*cp=='\n')cp++;
        }
        r->body=dec.data?dec.data:strdup("");
        r->body_len=dec.len;
    } else if(cl_str){
        size_t clen=(size_t)atol(cl_str);
        if(clen>body_avail)clen=body_avail;
        r->body=malloc(clen+1);
        memcpy(r->body,body_start,clen);
        r->body[clen]='\0';
        r->body_len=clen;
    } else {
        r->body=malloc(body_avail+1);
        memcpy(r->body,body_start,body_avail);
        r->body[body_avail]='\0';
        r->body_len=body_avail;
    }

    free(resp.data); free(req.data);
    return r;
}

/* ============ Amount ============ */
static long long parse_amount(const char *s){
    int neg=0;
    if(*s=='-'){neg=1;s++;}
    long long ip=0;
    while(isdigit(*s)){ip=ip*10+(*s-'0');s++;}
    long long cents=ip*100;
    if(*s=='.'){
        s++;
        int d1=-1,d2=-1;
        if(isdigit(*s)){d1=*s-'0';s++;}
        if(isdigit(*s)){d2=*s-'0';s++;}
        if(d1>=0&&d2>=0)cents+=d1*10+d2;
        else if(d1>=0)cents+=d1*10;
    }
    return neg?-cents:cents;
}

static void format_amount(long long cents,char *out,size_t sz){
    if(cents<0){cents=-cents;snprintf(out,sz,"-%lld.%02lld",cents/100,cents%100);}
    else snprintf(out,sz,"%lld.%02lld",cents/100,cents%100);
}

/* ============ Sorting ============ */
typedef struct{char *name;char *currency;long long cents;}total_entry;
static int cmp_total(const void *a,const void *b){
    total_entry *ta=(total_entry*)a,*tb=(total_entry*)b;
    int c=strcmp(ta->name,tb->name);
    if(c)return c;
    return strcmp(ta->currency,tb->currency);
}
static int cmp_strp(const void *a,const void *b){return strcmp(*(char**)a,*(char**)b);}

/* ============ Main ============ */
int main(int argc,char *argv[]){
    if(argc<3){fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char *data_dir=argv[1];
    const char *base_url=argv[2];

    /* Read client.json */
    char path[4096];
    snprintf(path,sizeof(path),"%s/client.json",data_dir);
    FILE *f=fopen(path,"rb");
    if(!f){perror("fopen");return 1;}
    buf_t jf; buf_init(&jf);
    char tmp[4096]; size_t n;
    while((n=fread(tmp,1,sizeof(tmp),f))>0)buf_append(&jf,tmp,n);
    fclose(f); buf_appendc(&jf,'\0');

    const char *jp=jf.data;
    jval *client=parse_value(&jp);
    char *client_id=jget(client,"client_id")->str;
    char *client_secret=jget(client,"client_secret")->str;
    char *scope=jget(client,"scope")->str;
    int page_size=(int)jget(client,"page_size")->num;

    /* Parse base URL */
    const char *url=base_url;
    if(!strncmp(url,"http://",7))url+=7;
    char host[256]={0}; int port=80;
    const char *slash=strchr(url,'/');
    const char *colon=strchr(url,':');
    if(colon&&(!slash||colon<slash)){
        int hl=colon-url; memcpy(host,url,hl); host[hl]='\0';
        port=atoi(colon+1);
    } else {
        if(slash){int hl=slash-url;memcpy(host,url,hl);host[hl]='\0';}
        else strcpy(host,url);
    }
    char *base_path=slash?strdup(slash):strdup("");

    /* Build auth header */
    char *enc_id=url_encode_rfc6749(client_id);
    char *enc_secret=url_encode_rfc6749(client_secret);
    buf_t cred; buf_init(&cred);
    buf_appends(&cred,enc_id); buf_appendc(&cred,':'); buf_appends(&cred,enc_secret);
    char *b64=base64_encode((unsigned char*)cred.data,cred.len);

    char token_path[4096];
    snprintf(token_path,sizeof(token_path),"%s/oauth/token",base_path);
    char *enc_scope=url_encode_rfc6749(scope);
    char tok_body[4096];
    snprintf(tok_body,sizeof(tok_body),"grant_type=client_credentials&scope=%s",enc_scope);
    char tok_hdrs[8192];
    snprintf(tok_hdrs,sizeof(tok_hdrs),"Content-Type: application/x-www-form-urlencoded\r\nAuthorization: Basic %s\r\n",b64);

    http_resp *resp=http_request(host,port,"POST",token_path,tok_hdrs,tok_body,strlen(tok_body));
    if(resp->status!=200){
        printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
        return 0;
    }
    jp=resp->body;
    jval *tok=parse_value(&jp);
    char *access_token=jget(tok,"access_token")->str;

    /* Fetch orders */
    int pages=0,retries=0,reauth=0,order_count=0;
    char *cursor=NULL;
    int token_fresh=1;

    typedef struct{char *name;char *currency;char *status;long long cents;}order_t;
    order_t *orders=NULL; int orders_cap=0,orders_len=0;

    while(1){
        char opath[8192];
        if(cursor){
            char *ec=url_encode_query(cursor);
            snprintf(opath,sizeof(opath),"%s/orders?limit=%d&cursor=%s",base_path,page_size,ec);
            free(ec);
        } else {
            snprintf(opath,sizeof(opath),"%s/orders?limit=%d",base_path,page_size);
        }
        char ahdr[8192];
        snprintf(ahdr,sizeof(ahdr),"Authorization: Bearer %s\r\n",access_token);

        resp=http_request(host,port,"GET",opath,ahdr,NULL,0);

        if(resp->status==429){
            retries++;
            char *ra=get_header(resp,"Retry-After");
            int w=ra?atoi(ra):1;
            sleep(w);
            continue;
        }
        if(resp->status==503){
            retries++;
            usleep(100000);
            continue;
        }
        if(resp->status==401){
            if(token_fresh){
                printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
                return 0;
            }
            reauth++;
            resp=http_request(host,port,"POST",token_path,tok_hdrs,tok_body,strlen(tok_body));
            if(resp->status!=200){
                printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
                return 0;
            }
            jp=resp->body;
            tok=parse_value(&jp);
            access_token=jget(tok,"access_token")->str;
            token_fresh=1;
            continue;
        }
        if(resp->status!=200){
            printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
            return 0;
        }

        pages++; token_fresh=0;

        jp=resp->body;
        jval *page=parse_value(&jp);
        jval *data=jget(page,"data");
        if(data&&data->type==JV_ARRAY){
            for(int i=0;i<data->arr_len;i++){
                jval *o=data->arr[i];
                jval *cust=jget(o,"customer");
                char *name=cust?jget(cust,"name")->str:"";
                char *currency=jget(o,"currency")->str;
                char *status=jget(o,"status")->str;
                char *amt=jget(o,"amount")->str;
                long long cents=parse_amount(amt);
                if(orders_len>=orders_cap){orders_cap=orders_cap?orders_cap*2:256;orders=realloc(orders,orders_cap*sizeof(order_t));}
                orders[orders_len].name=strdup(name);
                orders[orders_len].currency=strdup(currency);
                orders[orders_len].status=strdup(status);
                orders[orders_len].cents=cents;
                orders_len++; order_count++;
            }
        }
        jval *nc=jget(page,"next_cursor");
        if(!nc||nc->type==JV_NULL)break;
        free(cursor);
        cursor=strdup(nc->str);
    }

    /* Compute totals for non-cancelled */
    total_entry *totals=malloc((orders_len+1)*sizeof(total_entry));
    int tl=0;
    for(int i=0;i<orders_len;i++){
        if(strcmp(orders[i].status,"cancelled")==0)continue;
        totals[tl].name=orders[i].name;
        totals[tl].currency=orders[i].currency;
        totals[tl].cents=orders[i].cents;
        tl++;
    }
    qsort(totals,tl,sizeof(total_entry),cmp_total);

    for(int i=0;i<tl;){
        int j=i+1;
        while(j<tl&&strcmp(totals[j].name,totals[i].name)==0&&strcmp(totals[j].currency,totals[i].currency)==0)j++;
        long long sum=0;
        for(int k=i;k<j;k++)sum+=totals[k].cents;
        char amt[64]; format_amount(sum,amt,64);
        printf("total %s %s %s\n",totals[i].currency,amt,totals[i].name);
        i=j;
    }

    /* Status counts */
    if(orders_len>0){
        char **all_st=malloc(orders_len*sizeof(char*));
        for(int i=0;i<orders_len;i++)all_st[i]=orders[i].status;
        qsort(all_st,orders_len,sizeof(char*),cmp_strp);
        for(int i=0;i<orders_len;){
            int j=i+1;
            while(j<orders_len&&strcmp(all_st[j],all_st[i])==0)j++;
            printf("status %s %d\n",all_st[i],j-i);
            i=j;
        }
        free(all_st);
    }

    printf("orders %d pages %d retries %d reauth %d\n",order_count,pages,retries,reauth);
    return 0;
}

#!/usr/bin/env python3
import sys
import json
import http.client
from urllib.parse import urlparse
import codecs


def escape(s):
    result = []
    for ch in s:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        else:
            result.append(ch)
    return ''.join(result)


def read_stream(resp):
    while True:
        try:
            chunk = resp.read1(65536)
        except Exception:
            break
        if not chunk:
            break
        yield chunk


def parse_sse_lines(byte_chunks):
    """Decode bytes to lines, handling partial UTF-8 and CRLF."""
    decoder = codecs.getincrementaldecoder('utf-8')()
    buffer = ''

    for chunk in byte_chunks:
        buffer += decoder.decode(chunk)
        while True:
            nl = buffer.find('\n')
            if nl == -1:
                break
            line = buffer[:nl]
            buffer = buffer[nl + 1:]
            if line.endswith('\r'):
                line = line[:-1]
            yield line

    buffer += decoder.decode(b'', final=True)
    if buffer:
        line = buffer
        if line.endswith('\r'):
            line = line[:-1]
        yield line


def parse_sse_events(lines):
    """Parse SSE events from an iterator of lines."""
    event_type = None
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                yield (event_type or 'message', data)
            event_type = None
            data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('event:'):
            val = line[6:]
            if val.startswith(' '):
                val = val[1:]
            event_type = val
        elif line.startswith('data:'):
            val = line[5:]
            if val.startswith(' '):
                val = val[1:]
            data_lines.append(val)

    if data_lines:
        data = '\n'.join(data_lines)
        yield (event_type or 'message', data)


def process_stream(resp):
    """Process a streaming response. Returns (blocks, stop_reason, usage)."""
    lines = parse_sse_lines(read_stream(resp))
    events = parse_sse_events(lines)

    blocks = {}
    stop_reason = None
    usage = {'input_tokens': 0, 'output_tokens': 0, 'cache_read_input_tokens': 0}

    for event_type, data_str in events:
        if event_type == 'ping':
            continue

        try:
            data = json.loads(data_str)
        except (json.JSONDecodeError, ValueError):
            continue

        evt_type = data.get('type', event_type)

        if evt_type == 'message_start':
            msg = data.get('message', {})
            u = msg.get('usage', {})
            usage['input_tokens'] += u.get('input_tokens', 0)
            usage['cache_read_input_tokens'] += u.get('cache_read_input_tokens', 0)

        elif evt_type == 'content_block_start':
            idx = data['index']
            cb = data['content_block']
            blocks[idx] = {
                'type': cb['type'],
                'thinking': cb.get('thinking', ''),
                'signature': cb.get('signature', ''),
                'text': cb.get('text', ''),
                'id': cb.get('id', ''),
                'name': cb.get('name', ''),
                'input_json': '',
            }

        elif evt_type == 'content_block_delta':
            idx = data['index']
            delta = data['delta']
            dtype = delta['type']
            if dtype == 'thinking_delta':
                blocks[idx]['thinking'] += delta['thinking']
            elif dtype == 'signature_delta':
                blocks[idx]['signature'] += delta['signature']
            elif dtype == 'text_delta':
                blocks[idx]['text'] += delta['text']
            elif dtype == 'input_json_delta':
                blocks[idx]['input_json'] += delta['partial_json']

        elif evt_type == 'message_delta':
            d = data.get('delta', {})
            if 'stop_reason' in d:
                stop_reason = d['stop_reason']
            u = data.get('usage', {})
            usage['output_tokens'] += u.get('output_tokens', 0)

        elif evt_type == 'message_stop':
            pass

    sorted_blocks = [blocks[i] for i in sorted(blocks.keys())]
    return sorted_blocks, stop_reason, usage


def print_blocks(blocks):
    for b in blocks:
        if b['type'] == 'thinking':
            print(f'thinking {escape(b["thinking"])}')
            print(f'signature {escape(b["signature"])}')
        elif b['type'] == 'text':
            print(f'text {escape(b["text"])}')
        elif b['type'] == 'tool_use':
            print(f'tool_use {b["id"]} {b["name"]} {escape(b["input_json"])}')


def execute_tool(name, input_obj):
    if name == 'measure':
        text = input_obj.get('text', '')
        unit = input_obj.get('unit', '')
        if unit == 'code_points':
            return str(len(text)), False
        elif unit == 'utf8_bytes':
            return str(len(text.encode('utf-8'))), False
        elif unit == 'utf16_units':
            count = 0
            for ch in text:
                if ord(ch) > 0xFFFF:
                    count += 2
                else:
                    count += 1
            return str(count), False
        else:
            return f'unsupported unit: {unit}', True
    elif name == 'reverse':
        text = input_obj.get('text', '')
        return text[::-1], False
    else:
        return f'unknown tool: {name}', True


def make_request(base_url, api_key, body):
    parsed = urlparse(base_url)
    host = parsed.hostname
    port = parsed.port or 80
    path = parsed.path + '/v1/messages'

    conn = http.client.HTTPConnection(host, port)
    body_bytes = json.dumps(body).encode('utf-8')
    headers = {
        'Content-Length': str(len(body_bytes)),
        'x-api-key': api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
    }
    conn.request('POST', path, body_bytes, headers)
    return conn


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(f'{data_dir}/request.json', 'r') as f:
        req_data = json.load(f)

    api_key = req_data['api_key']
    model = req_data['model']
    max_tokens = req_data['max_tokens']
    thinking_budget = req_data['thinking_budget']
    system = req_data['system']
    prompt = req_data['prompt']
    tools = req_data['tools']

    # Request 1
    body1 = {
        'model': model,
        'max_tokens': max_tokens,
        'stream': True,
        'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
        'system': system,
        'tools': tools,
        'messages': [{'role': 'user', 'content': prompt}],
    }

    conn = make_request(base_url, api_key, body1)
    resp = conn.getresponse()

    if resp.status != 200:
        error_body = resp.read()
        try:
            err = json.loads(error_body)
            err_type = err['error']['type']
            err_msg = err['error']['message']
        except Exception:
            err_type = 'unknown'
            err_msg = error_body.decode('utf-8', errors='replace')
        print(f'ERROR {resp.status} {err_type}: {err_msg}')
        sys.exit(0)

    print('request 1')
    blocks1, stop_reason1, usage1 = process_stream(resp)
    print_blocks(blocks1)
    print(f'stop_reason {stop_reason1}')

    # Execute tools
    results = []
    for b in blocks1:
        if b['type'] == 'tool_use':
            try:
                input_obj = json.loads(b['input_json'])
            except Exception:
                input_obj = {}
            result, is_error = execute_tool(b['name'], input_obj)
            results.append((b['id'], result, is_error))

    for tool_id, result, is_error in results:
        if is_error:
            print(f'error {tool_id} {escape(result)}')
        else:
            print(f'result {tool_id} {escape(result)}')

    # Build request 2
    assistant_content = []
    for b in blocks1:
        if b['type'] == 'thinking':
            assistant_content.append({
                'type': 'thinking',
                'thinking': b['thinking'],
                'signature': b['signature'],
            })
        elif b['type'] == 'text':
            assistant_content.append({
                'type': 'text',
                'text': b['text'],
            })
        elif b['type'] == 'tool_use':
            input_obj = json.loads(b['input_json'])
            assistant_content.append({
                'type': 'tool_use',
                'id': b['id'],
                'name': b['name'],
                'input': input_obj,
            })

    tool_result_content = []
    for tool_id, result, is_error in results:
        block = {'type': 'tool_result', 'tool_use_id': tool_id, 'content': result}
        if is_error:
            block['is_error'] = True
        tool_result_content.append(block)

    body2 = {
        'model': model,
        'max_tokens': max_tokens,
        'stream': True,
        'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
        'system': system,
        'tools': tools,
        'messages': [
            {'role': 'user', 'content': prompt},
            {'role': 'assistant', 'content': assistant_content},
            {'role': 'user', 'content': tool_result_content},
        ],
    }

    conn2 = make_request(base_url, api_key, body2)
    resp2 = conn2.getresponse()

    if resp2.status != 200:
        error_body = resp2.read()
        try:
            err = json.loads(error_body)
            err_type = err['error']['type']
            err_msg = err['error']['message']
        except Exception:
            err_type = 'unknown'
            err_msg = error_body.decode('utf-8', errors='replace')
        print(f'ERROR {resp2.status} {err_type}: {err_msg}')
        sys.exit(0)

    print('request 2')
    blocks2, stop_reason2, usage2 = process_stream(resp2)
    print_blocks(blocks2)
    print(f'stop_reason {stop_reason2}')

    # Usage totals
    total_input = usage1['input_tokens'] + usage2['input_tokens']
    total_output = usage1['output_tokens'] + usage2['output_tokens']
    total_cache_read = usage1['cache_read_input_tokens'] + usage2['cache_read_input_tokens']

    print(f'usage input={total_input} output={total_output} cache_read={total_cache_read}')


if __name__ == '__main__':
    main()

import sys
import struct
import zlib
from decimal import Decimal


def read_varint(data, offset):
    result = 0
    for i in range(9):
        if offset + i >= len(data):
            break
        byte = data[offset + i]
        if i == 8:
            result = (result << 8) | byte
            return result, offset + 9
        result = (result << 7) | (byte & 0x7F)
        if byte < 0x80:
            return result, offset + i + 1
    return result, offset


def read_uint16(data, offset):
    return struct.unpack('>H', data[offset:offset + 2])[0]


def read_uint32(data, offset):
    return struct.unpack('>I', data[offset:offset + 4])[0]


def parse_serial_type(st):
    if st == 0:
        return 'NULL', 0
    elif st == 1:
        return 'INT', 1
    elif st == 2:
        return 'INT', 2
    elif st == 3:
        return 'INT', 3
    elif st == 4:
        return 'INT', 4
    elif st == 5:
        return 'INT', 6
    elif st == 6:
        return 'INT', 8
    elif st == 7:
        return 'REAL', 8
    elif st == 8:
        return 'ZERO', 0
    elif st == 9:
        return 'ONE', 0
    elif st >= 12 and st % 2 == 0:
        return 'BLOB', (st - 12) // 2
    elif st >= 13:
        return 'TEXT', (st - 13) // 2
    else:
        raise ValueError(f"Unknown serial type {st}")


def read_record(data, offset, end):
    record_start = offset
    header_size, offset = read_varint(data, offset)
    header_end = record_start + header_size
    serial_types = []
    while offset < header_end:
        st, offset = read_varint(data, offset)
        serial_types.append(st)
    values = []
    pos = header_end
    for st in serial_types:
        kind, size = parse_serial_type(st)
        if kind == 'NULL':
            values.append(('NULL', None))
        elif kind == 'ZERO':
            values.append(('INT', 0))
        elif kind == 'ONE':
            values.append(('INT', 1))
        elif kind == 'INT':
            val = int.from_bytes(data[pos:pos + size], 'big', signed=True)
            pos += size
            values.append(('INT', val))
        elif kind == 'REAL':
            val = struct.unpack('>d', data[pos:pos + 8])[0]
            pos += 8
            values.append(('REAL', val))
        elif kind == 'TEXT':
            val = data[pos:pos + size]
            pos += size
            values.append(('TEXT', val))
        elif kind == 'BLOB':
            val = data[pos:pos + size]
            pos += size
            values.append(('BLOB', val))
    return values


def read_payload(data, page_data, page_num, page_size, reserved, offset, total_payload_size):
    usable = page_size - reserved
    U = usable - 100 if page_num == 1 else usable
    X = U - 35
    if total_payload_size <= X:
        return page_data[offset:offset + total_payload_size]
    else:
        min_local = (U - 12) * 32 // 255 - 23
        max_local = (U - 12) * 64 // 255 - 23
        K = min_local + ((total_payload_size - min_local) % (U - 4))
        if K <= max_local:
            local_size = K
        else:
            local_size = min_local
        local_data = page_data[offset:offset + local_size]
        offset += local_size
        overflow_page = read_uint32(page_data, offset)
        result = local_data
        while overflow_page != 0:
            ovf_data = data[(overflow_page - 1) * page_size:overflow_page * page_size]
            next_page = read_uint32(ovf_data, 0)
            chunk_size = usable - 4
            result += ovf_data[4:4 + chunk_size]
            overflow_page = next_page
        return result[:total_payload_size]


def walk_btree(data, page_num, page_size, reserved):
    rows = []
    _walk(data, page_num, page_size, reserved, rows)
    return rows


def _walk(data, page_num, page_size, reserved, rows):
    page_data = data[(page_num - 1) * page_size:page_num * page_size]
    hdr_off = 100 if page_num == 1 else 0
    page_type = page_data[hdr_off]
    num_cells = read_uint16(page_data, hdr_off + 3)

    if page_type in (2, 5):
        header_size = 12
    else:
        header_size = 8

    cell_ptr_start = hdr_off + header_size

    if page_type == 13:  # leaf table b-tree
        for i in range(num_cells):
            cell_offset = read_uint16(page_data, cell_ptr_start + i * 2)
            pos = cell_offset
            total_payload, pos = read_varint(page_data, pos)
            rowid, pos = read_varint(page_data, pos)
            if rowid >= (1 << 63):
                rowid -= (1 << 64)
            payload = read_payload(data, page_data, page_num, page_size, reserved, pos, total_payload)
            rows.append((rowid, payload))
    elif page_type == 5:  # interior table b-tree
        right_child = read_uint32(page_data, hdr_off + 8)
        for i in range(num_cells):
            cell_offset = read_uint16(page_data, cell_ptr_start + i * 2)
            left_child = read_uint32(page_data, cell_offset)
            _walk(data, left_child, page_size, reserved, rows)
        _walk(data, right_child, page_size, reserved, rows)


def parse_sql_columns(sql):
    upper_sql = sql.upper()
    idx = upper_sql.find('CREATE')
    if idx == -1:
        return [], set()
    idx += 6
    while idx < len(sql) and sql[idx] in ' \t\n\r':
        idx += 1
    if upper_sql[idx:idx + 5] != 'TABLE':
        return [], set()
    idx += 5
    while idx < len(sql) and sql[idx] in ' \t\n\r':
        idx += 1
    # skip table name
    if idx < len(sql) and sql[idx] == '"':
        idx += 1
        while idx < len(sql) and sql[idx] != '"':
            idx += 1
        idx += 1
    else:
        while idx < len(sql) and sql[idx] not in ' \t\n\r(':
            idx += 1
    while idx < len(sql) and sql[idx] in ' \t\n\r':
        idx += 1
    if idx >= len(sql) or sql[idx] != '(':
        return [], set()
    idx += 1
    depth = 1
    start = idx
    while idx < len(sql) and depth > 0:
        if sql[idx] == '(':
            depth += 1
        elif sql[idx] == ')':
            depth -= 1
        idx += 1
    defs_str = sql[start:idx - 1]

    defs = []
    depth = 0
    current = []
    for ch in defs_str:
        if ch == '(':
            depth += 1
            current.append(ch)
        elif ch == ')':
            depth -= 1
            current.append(ch)
        elif ch == ',' and depth == 0:
            defs.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if current:
        defs.append(''.join(current))

    columns = []
    integer_pk_cols = set()

    for i, d in enumerate(defs):
        d = d.strip()
        if not d:
            continue
        j = 0
        if j < len(d) and d[j] == '"':
            j += 1
            name_start = j
            while j < len(d) and d[j] != '"':
                j += 1
            col_name = d[name_start:j]
            j += 1
        else:
            name_start = j
            while j < len(d) and d[j] not in ' \t\n\r(':
                j += 1
            col_name = d[name_start:j]

        columns.append(col_name)

        rest = d[j:].strip()
        type_end = 0
        while type_end < len(rest) and rest[type_end] not in ' \t\n\r(':
            type_end += 1
        type_name = rest[:type_end].upper()

        upper_d = d.upper()
        has_pk = 'PRIMARY' in upper_d and 'KEY' in upper_d
        if type_name == 'INTEGER' and has_pk:
            integer_pk_cols.add(i)

    return columns, integer_pk_cols


def format_real(val):
    import math
    if math.isinf(val) or math.isnan(val):
        return str(val)
    d = Decimal(val)
    s = format(d, 'f')
    if '.' not in s:
        s += '.0'
    else:
        s = s.rstrip('0')
        if s.endswith('.'):
            s += '0'
    return s


def format_text(data):
    if len(data) > 100:
        crc = zlib.crc32(data) & 0xFFFFFFFF
        return f'<TEXT len={len(data)} crc32={crc:08x}>'
    text = data.decode('utf-8')
    result = []
    for ch in text:
        o = ord(ch)
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        elif o < 0x20 or o == 0x7F:
            result.append(f'\\x{o:02X}')
        else:
            result.append(ch)
    return '"' + ''.join(result) + '"'


def format_blob(data):
    if len(data) > 100:
        crc = zlib.crc32(data) & 0xFFFFFFFF
        return f'<BLOB len={len(data)} crc32={crc:08x}>'
    return "X'" + data.hex().upper() + "'"


def format_value(kind, val):
    if kind == 'NULL':
        return 'NULL'
    elif kind == 'INT':
        return str(val)
    elif kind == 'REAL':
        return format_real(val)
    elif kind == 'TEXT':
        return format_text(val)
    elif kind == 'BLOB':
        return format_blob(val)
    return str(val)


def main():
    dir_path = sys.argv[1]
    db_path = dir_path + '/db.sqlite'

    with open(db_path, 'rb') as f:
        data = f.read()

    page_size = read_uint16(data, 16)
    if page_size == 1:
        page_size = 65536
    reserved = data[20]

    schema_rows = walk_btree(data, 1, page_size, reserved)

    tables = []
    for rowid, payload in schema_rows:
        values = read_record(payload, 0, len(payload))
        if len(values) < 5:
            continue
        type_val = values[0]
