import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;

public class Main {
    static byte[] data;
    static int pageSize;
    static int reservedBytes;
    static int usableSize;

    public static void main(String[] args) throws Exception {
        Path dbPath = Paths.get(args[0], "db.sqlite");
        data = Files.readAllBytes(dbPath);

        pageSize = readUint16(data, 16);
        if (pageSize == 1) pageSize = 65536;
        reservedBytes = data[20] & 0xFF;
        usableSize = pageSize - reservedBytes;

        List<SchemaEntry> schemas = new ArrayList<>();
        walkTableBTree(1, (rowid, values) -> {
            if (values.length < 5) return;
            String type = (String) values[0];
            String name = (String) values[1];
            Long rootpage = (Long) values[3];
            String sql = (String) values[4];
            if ("table".equals(type) && !name.startsWith("sqlite_") && rootpage != null && rootpage > 0) {
                schemas.add(new SchemaEntry(name, rootpage, sql));
            }
        });

        schemas.sort((a, b) -> {
            byte[] ab = a.name.getBytes(StandardCharsets.UTF_8);
            byte[] bb = b.name.getBytes(StandardCharsets.UTF_8);
            return compareBytes(ab, bb);
        });

        boolean first = true;
        for (SchemaEntry se : schemas) {
            if (!first) System.out.println();
            first = false;
            processTable(se);
        }
    }

    static void processTable(SchemaEntry se) {
        List<String> colNames = new ArrayList<>();
        List<Boolean> isAlias = new ArrayList<>();
        List<String> defs = parseColumnDefs(se.sql);
        for (String def : defs) {
            colNames.add(extractColumnName(def));
            isAlias.add(isRowidAlias(def));
        }

        List<long[]> rowids = new ArrayList<>();
        List<Object[]> allValues = new ArrayList<>();
        walkTableBTree((int) se.rootpage, (rowid, values) -> {
            rowids.add(new long[]{rowid});
            allValues.add(values);
        });

        System.out.println("TABLE " + se.name + " rows=" + rowids.size());
        System.out.println("COLUMNS " + String.join(", ", colNames));

        for (int i = 0; i < rowids.size(); i++) {
            long rowid = rowids.get(i)[0];
            Object[] values = allValues.get(i);
            StringBuilder sb = new StringBuilder();
            sb.append(rowid).append(": ");
            for (int c = 0; c < colNames.size(); c++) {
                if (c > 0) sb.append(", ");
                Object val;
                if (c < values.length) {
                    val = values[c];
                } else {
                    val = null;
                }
                if (c < isAlias.size() && isAlias.get(c) && val == null) {
                    val = rowid;
                }
                sb.append(formatValue(val));
            }
            System.out.println(sb.toString());
        }
    }

    static String formatValue(Object val) {
        if (val == null) return "NULL";
        if (val instanceof Long) {
            return Long.toString((Long) val);
        }
        if (val instanceof Double) {
            return formatReal((Double) val);
        }
        if (val instanceof String) {
            byte[] bytes = ((String) val).getBytes(StandardCharsets.UTF_8);
            if (bytes.length <= 100) {
                return escapeText(bytes);
            } else {
                CRC32 crc = new CRC32();
                crc.update(bytes);
                return String.format("<TEXT len=%d crc32=%08x>", bytes.length, crc.getValue());
            }
        }
        if (val instanceof byte[]) {
            byte[] bytes = (byte[]) val;
            if (bytes.length <= 100) {
                StringBuilder sb = new StringBuilder("X'");
                for (byte b : bytes) {
                    sb.append(String.format("%02X", b & 0xFF));
                }
                sb.append("'");
                return sb.toString();
            } else {
                CRC32 crc = new CRC32();
                crc.update(bytes);
                return String.format("<BLOB len=%d crc32=%08x>", bytes.length, crc.getValue());
            }
        }
        return "???";
    }

    static String formatReal(double value) {
        BigDecimal bd = new BigDecimal(value);
        bd = bd.setScale(8, RoundingMode.HALF_UP);
        String s = bd.toPlainString();
        int dot = s.indexOf('.');
        if (dot < 0) {
            s += ".0";
        } else {
            int end = s.length() - 1;
            while (end > dot + 1 && s.charAt(end) == '0') end--;
            s = s.substring(0, end + 1);
        }
        return s;
    }

    static String escapeText(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        int i = 0;
        while (i < bytes.length) {
            int v = bytes[i] & 0xFF;
            if (v == 0x5C) { sb.append("\\\\"); i++; }
            else if (v == 0x22) { sb.append("\\\""); i++; }
            else if (v == 0x0A) { sb.append("\\n"); i++; }
            else if (v == 0x0D) { sb.append("\\r"); i++; }
            else if (v == 0x09) { sb.append("\\t"); i++; }
            else if (v < 0x20 || v == 0x7F) {
                sb.append(String.format("\\x%02X", v));
                i++;
            } else if (v < 0x80) {
                sb.append((char) v);
                i++;
            } else {
                int seqLen;
                if ((v & 0xE0) == 0xC0) seqLen = 2;
                else if ((v & 0xF0) == 0xE0) seqLen = 3;
                else if ((v & 0xF8) == 0xF0) seqLen = 4;
                else seqLen = 1;
                if (i + seqLen <= bytes.length) {
                    sb.append(new String(bytes, i, seqLen, StandardCharsets.UTF_8));
                    i += seqLen;
                } else {
                    sb.append((char) v);
                    i++;
                }
            }
        }
        sb.append('"');
        return sb.toString();
    }

    interface RowVisitor {
        void visit(long rowid, Object[] values);
    }

    static void walkTableBTree(int page, RowVisitor visitor) {
        int pageBase = (page - 1) * pageSize;
        int headerOff = (page == 1) ? 100 : pageBase;

        int pageType = data[headerOff] & 0xFF;
        int numCells = readUint16(data, headerOff + 3);

        if (pageType == 13) {
            int cellPtrOff = headerOff + 8;
            for (int i = 0; i < numCells; i++) {
                int cellOff = readUint16(data, cellPtrOff + i * 2);
                int pos = pageBase + cellOff;
                long payloadSize = readVarint(data, pos);
                pos += varintSize(data, pos);
                long rowid = readVarint(data, pos);
                pos += varintSize(data, pos);

                int maxLocal = usableSize - 35;
                byte[] payload;
                if (payloadSize <= maxLocal) {
                    payload = Arrays.copyOfRange(data, pos, pos + (int) payloadSize);
                } else {
                    int local = (int) (((payloadSize - maxLocal) % (usableSize - 4)) + 4);
                    if (local > maxLocal) local = maxLocal;
                    byte[] localData = Arrays.copyOfRange(data, pos, pos + local);
                    pos += local;
                    long overflowPage = readUint32(data, pos) & 0xFFFFFFFFL;
                    byte[] overflowData = readOverflow(overflowPage, (int) (payloadSize - local));
                    payload = new byte[(int) payloadSize];
                    System.arraycopy(localData, 0, payload, 0, local);
                    System.arraycopy(overflowData, 0, payload, local, (int) (payloadSize - local));
                }

                Object[] values = parseRecord(payload);
                visitor.visit(rowid, values);
            }
        } else if (pageType == 5) {
            int cellPtrOff = headerOff + 12;
            for (int i = 0; i < numCells; i++) {
                int cellOff = readUint16(data, cellPtrOff + i * 2);
                int pos = pageBase + cellOff;
                int childPage = readUint32(data, pos);
                walkTableBTree(childPage, visitor);
            }
            int rightPage = readUint32(data, headerOff + 8);
            walkTableBTree(rightPage, visitor);
        }
    }

    static byte[] readOverflow(long page, int remaining) {
        byte[] result = new byte[remaining];
        int pos = 0;
        while (page != 0 && remaining > 0) {
            int offset = (int) ((page - 1) * pageSize);
            long nextPage = readUint32(data, offset) & 0xFFFFFFFFL;
            int chunk = Math.min(remaining, usableSize - 4);
            System.arraycopy(data, offset + 4, result, pos, chunk);
            pos += chunk;
            remaining -= chunk;
            page = nextPage;
        }
        return result;
    }

    static Object[] parseRecord(byte[] payload) {
        int pos = 0;
        long headerSize = readVarint(payload, pos);
        pos += varintSize(payload, pos);
        int headerEnd = (int) headerSize;

        List<Integer> serialTypes = new ArrayList<>();
        while (pos < headerEnd) {
            long st = readVarint(payload, pos);
            pos += varintSize(payload, pos);
            serialTypes.add((int) st);
        }

        Object[] values = new Object[serialTypes.size()];
        for (int i = 0; i < serialTypes.size(); i++) {
            int st = serialTypes.get(i);
            if (st == 0) {
                values[i] = null;
            } else if (st >= 1 && st <= 4) {
                values[i] = readSignedInt(payload, pos, st);
                pos += st;
            } else if (st == 5) {
                values[i] = readSignedInt(payload, pos, 6);
                pos += 6;
            } else if (st == 6) {
                values[i] = readSignedInt(payload, pos, 8);
                pos += 8;
            } else if (st == 7) {
                long bits = readUnsignedLong(payload, pos);
                values[i] = Double.longBitsToDouble(bits);
                pos += 8;
            } else if (st == 8) {
                values[i] = 0L;
            } else if (st == 9) {
                values[i] = 1L;
            } else if (st >= 12 && st % 2 == 0) {
                int len = (st - 12) / 2;
                values[i] = Arrays.copyOfRange(payload, pos, pos + len);
                pos += len;
            } else if (st >= 13 && st % 2 == 1) {
                int len = (st - 13) / 2;
                values[i] = new String(payload, pos, len, StandardCharsets.UTF_8);
                pos += len;
            }
        }
        return values;
    }

    static int readUint16(byte[] arr, int offset) {
        return ((arr[offset] & 0xFF) << 8) | (arr[offset + 1] & 0xFF);
    }

    static int readUint32(byte[] arr, int offset) {
        return ((arr[offset] & 0xFF) << 24) | ((arr[offset + 1] & 0xFF) << 16) |
               ((arr[offset + 2] & 0xFF) << 8) | (arr[offset + 3] & 0xFF);
    }

    static long readUnsignedLong(byte[] arr, int offset) {
        long result = 0;
        for (int i = 0; i < 8; i++) {
            result = (result << 8) | (arr[offset + i] & 0xFFL);
        }
        return result;
    }

    static long readSignedInt(byte[] arr, int offset, int len) {
        long result = 0;
        for (int i = 0; i < len; i++) {
            result = (result << 8) | (arr[offset + i] & 0xFFL);
        }
        if (len < 8 && (arr[offset] & 0x80) != 0) {
            result |= (-1L << (len * 8));
        }
        return result;
    }

    static long readVarint(byte[] arr, int offset) {
        long result = 0;
        for (int i = 0; i < 8; i++) {
            byte b = arr[offset + i];
            result = (result << 7) | (b & 0x7FL);
            if ((b & 0x80) == 0) return result;
        }
        result = (result << 8) | (arr[offset + 8] & 0xFFL);
        return result;
    }

    static int varintSize(byte[] arr, int offset) {
        for (int i = 0; i < 8; i++) {
            if ((arr[offset + i] & 0x80) == 0) return i + 1;
        }
        return 9;
    }

    static int compareBytes(byte[] a, byte[] b) {
        int min = Math.min(a.length, b.length);
        for (int i = 0; i < min; i++) {
            int diff = (a[i] & 0xFF) - (b[i] & 0xFF);
            if (diff != 0) return diff;
        }
        return a.length - b.length;
    }

    static List<String> parseColumnDefs(String sql) {
        int i = 0;
        i = skipWord(sql, i);
        i = skipWhitespace(sql, i);
        i = skipWord(sql, i);
        i = skipWhitespace(sql, i);
        if (i < sql.length() && matchWord(sql, i, "IF")) {
            i = skipWord(sql, i);
            i = skipWhitespace(sql, i);
            i = skipWord(sql, i);
            i = skipWhitespace(sql, i);
            i = skipWord(sql, i);
            i = skipWhitespace(sql, i);
        }
        if (i < sql.length() && sql.charAt(i) == '"') {
            i++;
            while (i < sql.length() && sql.charAt(i) != '"') i++;
            i++;
        } else {
            while (i < sql.length() && !Character.isWhitespace(sql.charAt(i)) && sql.charAt(i) != '(') i++;
        }
        i = skipWhitespace(sql, i);
        if (i >= sql.length() || sql.charAt(i) != '(') return new ArrayList<>();

        int open = i;
        int depth = 0;
        int close = open;
        for (int j = open; j < sql.length(); j++) {
            if (sql.charAt(j) == '(') depth++;
            else if (sql.charAt(j) == ')') {
                depth--;
                if (depth == 0) { close = j; break; }
            }
        }

        String defsStr = sql.substring(open + 1, close);
        List<String> defs = new ArrayList<>();
        int d = 0;
        int start = 0;
        for (int j = 0; j < defsStr.length(); j++) {
            char c = defsStr.charAt(j);
            if (c == '(') d++;
            else if (c == ')') d--;
            else if (c == ',' && d == 0) {
                String def = defsStr.substring(start, j).trim();
                if (!def.isEmpty()) defs.add(def);
                start = j + 1;
            }
        }
        String last = defsStr.substring(start).trim();
        if (!last.isEmpty()) defs.add(last);
        return defs;
    }

    static String extractColumnName(String def) {
        def = def.trim();
        if (def.startsWith("\"")) {
            int end = def.indexOf('"', 1);
            return def.substring(1, end);
        } else {
            int end = 0;
            while (end < def.length() && !Character.isWhitespace(def.charAt(end)) && def.charAt(end) != '(') end++;
            return def.substring(0, end);
        }
    }

    static boolean isRowidAlias(String def) {
        def = def.trim();
        String afterName;
        if (def.startsWith("\"")) {
            int end = def.indexOf('"', 1) + 1;
            afterName = def.substring(end).trim();
        } else {
            int end = 0;
            while (end < def.length() && !Character.isWhitespace(def.charAt(end)) && def.charAt(end) != '(') end++;
            afterName = def.substring(end).trim();
        }
        if (afterName.isEmpty()) return false;
        int j = 0;
        while (j < afterName.length() && !Character.isWhitespace(afterName.charAt(j)) && afterName.charAt(j) != '(') j++;
        String typeWord = afterName.substring(0, j);
        if (!typeWord.equalsIgnoreCase("INTEGER")) return false;
        String upper = afterName.toUpperCase();
        return upper.matches(".*\\bPRIMARY\\s+KEY\\b.*");
    }

    static int skipWord(String s, int i) {
        while (i < s.length() && !Character.isWhitespace(s.charAt(i))) i++;
        return i;
    }

    static int skipWhitespace(String s, int i) {
        while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
        return i;
    }

    static boolean matchWord(String s, int i, String word) {
        if (i + word.length() > s.length()) return false;
        return s.substring(i, i + word.length()).equalsIgnoreCase(word);
    }

    static class SchemaEntry {
        String name;
        long rootpage;
        String sql;
        SchemaEntry(String name, long rootpage, String sql) {
            this.name = name;
            this.rootpage = rootpage;
            this.sql = sql;
        }
    }
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

interface ContentBlock {
  type: 'thinking' | 'text' | 'tool_use';
  thinking?: string;
  signature?: string;
  text?: string;
  id?: string;
  name?: string;
  partialJson?: string;
}

interface StreamResult {
  status: number;
  errorType?: string;
  errorMessage?: string;
  blocks?: ContentBlock[];
  stopReason?: string;
  inputTokens?: number;
  outputTokens?: number;
  cacheReadTokens?: number;
}

function escapeString(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '\\') result += '\\\\';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\r') result += '\\r';
    else if (ch === '\t') result += '\\t';
    else result += ch;
  }
  return result;
}

function executeTool(name: string, input: Record<string, string>): { result: string; isError: boolean } {
  if (name === 'measure') {
    const text = input['text'] ?? '';
    const unit = input['unit'] ?? '';
    if (unit === 'code_points') {
      return { result: String(Array.from(text).length), isError: false };
    } else if (unit === 'utf8_bytes') {
      return { result: String(Buffer.byteLength(text, 'utf8')), isError: false };
    } else if (unit === 'utf16_units') {
      return { result: String(text.length), isError: false };
    } else {
      return { result: `unsupported unit: ${unit}`, isError: true };
    }
  } else if (name === 'reverse') {
    const text = input['text'] ?? '';
    return { result: Array.from(text).reverse().join(''), isError: false };
  } else {
    return { result: `unknown tool: ${name}`, isError: true };
  }
}

async function streamRequest(baseUrl: string, apiKey: string, body: object): Promise<StreamResult> {
  return new Promise((resolve, reject) => {
    const url = new URL(baseUrl + '/v1/messages');
    const bodyStr = JSON.stringify(body);

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: url.port ? parseInt(url.port) : 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Content-Length': String(Buffer.byteLength(bodyStr, 'utf8')),
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    };

    const req = http.request(options, (res) => {
      const statusCode = res.statusCode || 0;

      if (statusCode !== 200) {
        let bodyData = '';
        res.setEncoding('utf-8');
        res.on('data', (chunk: string) => { bodyData += chunk; });
        res.on('end', () => {
          try {
            const err = JSON.parse(bodyData);
            resolve({
              status: statusCode,
              errorType: err.error?.type ?? 'unknown',
              errorMessage: err.error?.message ?? ''
            });
          } catch {
            resolve({ status: statusCode, errorType: 'unknown', errorMessage: bodyData });
          }
        });
        res.on('error', reject);
        return;
      }

      // Parse SSE stream
      const decoder = new TextDecoder('utf-8');
      let buffer = '';
      let eventType = '';
      let dataLines: string[] = [];

      const blocks = new Map<number, ContentBlock>();
      let stopReason = '';
      let inputTokens = 0;
      let outputTokens = 0;
      let cacheReadTokens = 0;

      function processLine(line: string) {
        if (line === '') {
          if (dataLines.length > 0) {
            const data = dataLines.join('\n');
            handleEvent(eventType, data);
          }
          eventType = '';
          dataLines = [];
        } else if (line.startsWith(':')) {
          // comment, ignore
        } else if (line.startsWith('event:')) {
          let val = line.substring(6);
          if (val.startsWith(' ')) val = val.substring(1);
          eventType = val;
        } else if (line.startsWith('data:')) {
          let val = line.substring(5);
          if (val.startsWith(' ')) val = val.substring(1);
          dataLines.push(val);
        }
      }

      function handleEvent(event: string, data: string) {
        if (event === 'ping') return;

        let parsed: any;
        try {
          parsed = JSON.parse(data);
        } catch {
          return;
        }

        if (event === 'message_start') {
          const usage = parsed.message?.usage;
          if (usage) {
            inputTokens += usage.input_tokens || 0;
            cacheReadTokens += usage.cache_read_input_tokens || 0;
          }
        } else if (event === 'content_block_start') {
          const idx: number = parsed.index;
          const cb = parsed.content_block;
          if (cb.type === 'thinking') {
            blocks.set(idx, { type: 'thinking', thinking: '', signature: '' });
          } else if (cb.type === 'text') {
            blocks.set(idx, { type: 'text', text: '' });
          } else if (cb.type === 'tool_use') {
            blocks.set(idx, { type: 'tool_use', id: cb.id, name: cb.name, partialJson: '' });
          }
        } else if (event === 'content_block_delta') {
          const idx: number = parsed.index;
          const delta = parsed.delta;
          const block = blocks.get(idx);
          if (!block) return;

          if (delta.type === 'thinking_delta') {
            block.thinking = (block.thinking || '') + (delta.thinking || '');
          } else if (delta.type === 'signature_delta') {
            block.signature = (block.signature || '') + (delta.signature || '');
          } else if (delta.type === 'text_delta') {
            block.text = (block.text || '') + (delta.text || '');
          } else if (delta.type === 'input_json_delta') {
            block.partialJson = (block.partialJson || '') + (delta.partial_json || '');
          }
        } else if (event === 'message_delta') {
          if (parsed.delta?.stop_reason) {
            stopReason = parsed.delta.stop_reason;
          }
          if (parsed.usage?.output_tokens !== undefined) {
            outputTokens += parsed.usage.output_tokens;
          }
        } else if (event === 'message_stop') {
          // end of reply
        }
      }

      function processBuffer() {
        while (true) {
          const nlIndex = buffer.indexOf('\n');
          if (nlIndex === -1) break;
          let line = buffer.substring(0, nlIndex);
          if (line.endsWith('\r')) {
            line = line.substring(0, line.length - 1);
          }
          buffer = buffer.substring(nlIndex + 1);
          processLine(line);
        }
      }

      res.on('data', (chunk: Buffer) => {
        const text = decoder.decode(chunk, { stream: true });
        buffer += text;
        processBuffer();
      });

      res.on('end', () => {
        // Flush decoder
        const remaining = decoder.decode();
        if (remaining) {
          buffer += remaining;
        }
        processBuffer();

        // Process any remaining buffer as a final line (no trailing newline)
        if (buffer.length > 0) {
          let line = buffer;
          if (line.endsWith('\r')) line = line.substring(0, line.length - 1);
          processLine(line);
          buffer = '';
        }

        // Dispatch any pending event
        if (dataLines.length > 0) {
          const data = dataLines.join('\n');
          handleEvent(eventType, data);
          dataLines = [];
        }

        const orderedBlocks: ContentBlock[] = [];
        const sortedIndices = Array.from(blocks.keys()).sort((a, b) => a - b);
        for (const idx of sortedIndices) {
          orderedBlocks.push(blocks.get(idx)!);
        }

        resolve({
          status: 200,
          blocks: orderedBlocks,
          stopReason,
          inputTokens,
          outputTokens,
          cacheReadTokens
        });
      });

      res.on('error', reject);
    });

    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

