import Foundation

func escapeString(_ s: String) -> String {
    var result = ""
    for c in s.unicodeScalars {
        switch c {
        case "\\": result += "\\\\"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        default: result.unicodeScalars.append(c)
        }
    }
    return result
}

struct SSEEvent {
    var event: String = ""
    var data: String = ""
}

func parseSSE(_ data: Data) -> [SSEEvent] {
    let text = String(decoding: data, as: UTF8.self)
    var events: [SSEEvent] = []
    var currentEvent = SSEEvent()
    var dataLines: [String] = []
    var hasContent = false

    var lines: [String] = []
    var current = ""
    let chars = Array(text)
    var i = 0
    while i < chars.count {
        if chars[i] == "\r" {
            if i + 1 < chars.count && chars[i + 1] == "\n" {
                i += 1
            }
            lines.append(current)
            current = ""
        } else if chars[i] == "\n" {
            lines.append(current)
            current = ""
        } else {
            current.append(chars[i])
        }
        i += 1
    }
    if !current.isEmpty {
        lines.append(current)
    }

    for line in lines {
        if line.isEmpty {
            if hasContent {
                currentEvent.data = dataLines.joined(separator: "\n")
                events.append(currentEvent)
                currentEvent = SSEEvent()
                dataLines = []
                hasContent = false
            }
        } else if line.hasPrefix(":") {
            // comment, ignore
        } else if line.hasPrefix("event:") {
            var value = String(line.dropFirst(6))
            if value.hasPrefix(" ") { value = String(value.dropFirst()) }
            currentEvent.event = value
            hasContent = true
        } else if line.hasPrefix("data:") {
            var value = String(line.dropFirst(5))
            if value.hasPrefix(" ") { value = String(value.dropFirst()) }
            dataLines.append(value)
            hasContent = true
        }
    }
    if hasContent {
        currentEvent.data = dataLines.joined(separator: "\n")
        events.append(currentEvent)
    }
    return events
}

class ContentBlock {
    var type: String = ""
    var id: String = ""
    var name: String = ""
    var thinkingText: String = ""
    var signature: String = ""
    var text: String = ""
    var partialJson: String = ""
}

func executeTool(name: String, input: [String: Any]) -> (result: String, isError: Bool) {
    switch name {
    case "measure":
        let text = input["text"] as? String ?? ""
        let unit = input["unit"] as? String ?? ""
        switch unit {
        case "code_points":
            return (String(text.unicodeScalars.count), false)
        case "utf8_bytes":
            return (String(text.utf8.count), false)
        case "utf16_units":
            return (String(text.utf16.count), false)
        default:
            return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = input["text"] as? String ?? ""
        let reversed = String(String.UnicodeScalarView(text.unicodeScalars.reversed()))
        return (reversed, false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

// --- Main ---
let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dataDir = args[1]
let baseUrl = args[2]

let requestData = try! Data(contentsOf: URL(fileURLWithPath: "\(dataDir)/request.json"))
let requestJson = try! JSONSerialization.jsonObject(with: requestData) as! [String: Any]

let apiKey = requestJson["api_key"] as! String
let model = requestJson["model"] as! String
let maxTokens = requestJson["max_tokens"] as! Int
let thinkingBudget = requestJson["thinking_budget"] as! Int
let systemPrompt = requestJson["system"] as! String
let prompt = requestJson["prompt"] as! String
let tools = requestJson["tools"] as! [Any]

func makeRequest(messages: [[String: Any]]) -> (statusCode: Int, body: Data) {
    let body: [String: Any] = [
        "model": model,
        "max_tokens": maxTokens,
        "stream": true,
        "thinking": ["type": "enabled", "budget_tokens": thinkingBudget],
        "system": systemPrompt,
        "tools": tools,
        "messages": messages
    ]

    let url = URL(string: "\(baseUrl)/v1/messages")!
    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    request.setValue(apiKey, forHTTPHeaderField: "x-api-key")
    request.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
    request.setValue("application/json", forHTTPHeaderField: "content-type")

    let bodyData = try! JSONSerialization.data(withJSONObject: body)
    request.httpBody = bodyData

    let semaphore = DispatchSemaphore(value: 0)
    var statusCode = 0
    var responseBody = Data()

    let config = URLSessionConfiguration.default
    config.timeoutIntervalForRequest = 300
    config.timeoutIntervalForResource = 300
    let session = URLSession(configuration: config)

    let task = session.dataTask(with: request) { data, response, error in
        if let httpResponse = response as? HTTPURLResponse {
            statusCode = httpResponse.statusCode
        }
        if let data = data {
            responseBody = data
        }
        semaphore.signal()
    }
    task.resume()
    semaphore.wait()

    return (statusCode, responseBody)
}

func parseStreamResponse(_ data: Data) -> (blocks: [ContentBlock], stopReason: String, inputTokens: Int, outputTokens: Int, cacheReadTokens: Int) {
    let events = parseSSE(data)

    var blocks: [Int: ContentBlock] = [:]
    var blockOrder: [Int] = []
    var stopReason = ""
    var inputTokens = 0
    var outputTokens = 0
    var cacheReadTokens = 0

    for event in events {
        guard let jsonData = event.data.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: jsonData) as? [String: Any] else {
            continue
        }

        switch event.event {
        case "message_start":
            if let message = json["message"] as? [String: Any],
               let usage = message["usage"] as? [String: Any] {
                inputTokens += (usage["input_tokens"] as? Int) ?? 0
                cacheReadTokens += (usage["cache_read_input_tokens"] as? Int) ?? 0
            }
        case "content_block_start":
            let index = json["index"] as? Int ?? 0
            let block = ContentBlock()
            if let cb = json["content_block"] as? [String: Any] {
                block.type = cb["type"] as? String ?? ""
                block.id = cb["id"] as? String ?? ""
                block.name = cb["name"] as? String ?? ""
            }
            blocks[index] = block
            blockOrder.append(index)
        case "content_block_delta":
            let index = json["index"] as? Int ?? 0
            guard let block = blocks[index], let delta = json["delta"] as? [String: Any] else { continue }
            switch delta["type"] as? String ?? "" {
            case "thinking_delta":
                block.thinkingText += delta["thinking"] as? String ?? ""
            case "signature_delta":
                block.signature += delta["signature"] as? String ?? ""
            case "text_delta":
                block.text += delta["text"] as? String ?? ""
            case "input_json_delta":
                block.partialJson += delta["partial_json"] as? String ?? ""
            default:
                break
            }
        case "message_delta":
            if let delta = json["delta"] as? [String: Any] {
                stopReason = delta["stop_reason"] as? String ?? ""
            }
            if let usage = json["usage"] as? [String: Any] {
                outputTokens += (usage["output_tokens"] as? Int) ?? 0
            }
        default:
            break
        }
    }

    let orderedBlocks = blockOrder.compactMap { blocks[$0] }
    return (orderedBlocks, stopReason, inputTokens, outputTokens, cacheReadTokens)
}

func printBlockLines(_ blocks: [ContentBlock]) {
    for block in blocks {
        switch block.type {
        case "thinking":
            print("thinking \(escapeString(block.thinkingText))")
            print("signature \(escapeString(block.signature))")
        case "text":
            print("text \(escapeString(block.text))")
        case "tool_use":
            print("tool_use \(block.id) \(block.name) \(escapeString(block.partialJson))")
        default:
            break
        }
    }
}

// --- Execution ---
var totalInput = 0
var totalOutput = 0
var totalCacheRead = 0

print("request 1")

let messages1: [[String: Any]] = [["role": "user", "content": prompt]]
let (status1, body1) = makeRequest(messages: messages1)

if status1 != 200 {
    if let errorJson = try? JSONSerialization.jsonObject(with: body1) as? [String: Any],
       let error = errorJson["error"] as? [String: Any] {
