import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

function parseCsv(text: string): string[][] {
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  const rows: string[][] = [];
  let i = 0;
  const len = text.length;
  while (i < len) {
    const row: string[] = [];
    while (true) {
      if (i < len && text[i] === '"') {
        i++;
        let field = '';
        while (i < len) {
          if (text[i] === '"') {
            if (i + 1 < len && text[i + 1] === '"') {
              field += '"';
              i += 2;
            } else {
              i++;
              break;
            }
          } else {
            field += text[i];
            i++;
          }
        }
        row.push(field);
      } else {
        let field = '';
        while (i < len && text[i] !== ',' && text[i] !== '\r' && text[i] !== '\n') {
          field += text[i];
          i++;
        }
        row.push(field);
      }
      if (i < len && text[i] === ',') {
        i++;
      } else {
        if (i < len && text[i] === '\r') i++;
        if (i < len && text[i] === '\n') i++;
        break;
      }
    }
    if (row.length > 1 || row[0] !== '' || i < len) {
      rows.push(row);
    }
  }
  return rows;
}

function compactJsonString(s: string): string {
  let result = '"';
  for (let i = 0; i < s.length; i++) {
    const code = s.codePointAt(i)!;
    if (s[i] === '"') result += '\\"';
    else if (s[i] === '\\') result += '\\\\';
    else if (code === 0x08) result += '\\b';
    else if (code === 0x0C) result += '\\f';
    else if (code === 0x0A) result += '\\n';
    else if (code === 0x0D) result += '\\r';
    else if (code === 0x09) result += '\\t';
    else if (code < 0x20) result += '\\u00' + code.toString(16).padStart(2, '0');
    else result += s[i];
    if (code > 0xFFFF) i++;
  }
  result += '"';
  return result;
}

function compactJson(val: any): string {
  if (val === null || val === undefined) return 'null';
  if (typeof val === 'number') return String(val);
  if (typeof val === 'string') return compactJsonString(val);
  if (typeof val === 'boolean') return val ? 'true' : 'false';
  if (Array.isArray(val)) return '[' + val.map(compactJson).join(',') + ']';
  if (typeof val === 'object') {
    const parts: string[] = [];
    for (const k of Object.keys(val)) {
      parts.push(compactJsonString(k) + ':' + compactJson(val[k]));
    }
    return '{' + parts.join(',') + '}';
  }
  return String(val);
}

function executeTool(name: string, argsStr: string, inventory: Map<string, {sku:string,name:string,price_cents:number,currency:string,stock:number}>, rates: Record<string,number>): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku: string = args.sku;
    const row = inventory.get(sku);
    if (!row) {
      return compactJson({ error: 'unknown sku: ' + sku });
    }
    return compactJson({ sku: row.sku, name: row.name, price_cents: row.price_cents, currency: row.currency, stock: row.stock });
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rFrom = BigInt(rates[from]);
    const rTo = BigInt(rates[to]);
    const amount = BigInt(amountCents);
    const numerator = 2n * amount * rTo + rFrom;
    const denominator = 2n * rFrom;
    const converted = Number(numerator / denominator);
    return compactJson({ amount_cents: converted, currency: to });
  } else {
    return compactJson({ error: 'unknown tool: ' + name });
  }
}

function makeRequest(baseUrl: string, apiKey: string, body: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(baseUrl + '/chat/completions');
    const bodyBuf = Buffer.from(body, 'utf8');
    const req = http.request({
      hostname: urlObj.hostname,
      port: urlObj.port ? parseInt(urlObj.port) : 80,
      path: urlObj.pathname,
      method: 'POST',
      headers: {
        'Host': urlObj.host,
        'Authorization': 'Bearer ' + apiKey,
        'Content-Type': 'application/json',
        'Content-Length': bodyBuf.length,
      },
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        const data = Buffer.concat(chunks).toString('utf8');
        resolve({ status: res.statusCode!, body: data });
      });
    });
    req.on('error', reject);
    req.write(bodyBuf);
    req.end();
  });
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const taskRaw = fs.readFileSync(path.join(dataDir, 'task.json'), 'utf8');
  const task = JSON.parse(taskRaw);

  const csvRaw = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf8');
  const csvRows = parseCsv(csvRaw);

  const ratesRaw = fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf8');
  const ratesData = JSON.parse(ratesRaw);
  const rates: Record<string, number> = ratesData.rates;

  const inventory = new Map<string, { sku: string; name: string; price_cents: number; currency: string; stock: number }>();
  for (let i = 1; i < csvRows.length; i++) {
    const r = csvRows[i];
    if (r.length >= 5) {
      inventory.set(r[0], {
        sku: r[0],
        name: r[1],
        price_cents: parseInt(r[2], 10),
        currency: r[3],
        stock: parseInt(r[4], 10),
      });
    }
  }

  const messages: any[] = [
    { role: 'system', content: task.system },
    { role: 'user', content: task.user },
  ];

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requestCount = 0;
  const outputLines: string[] = [];

  while (true) {
    const reqBody = JSON.stringify({
      model: task.model,
      messages: messages,
      tools: task.tools,
      tool_choice: 'auto',
    });

    const resp = await makeRequest(baseUrl, task.api_key, reqBody);
    requestCount++;

    if (resp.status !== 200) {
      let errMsg = '';
      try {
        const errBody = JSON.parse(resp.body);
        errMsg = errBody.error ? errBody.error.message : '';
      } catch {
        errMsg = '';
      }
      for (const line of outputLines) console.log(line);
      console.log('ERROR ' + resp.status + ' ' + errMsg);
      process.exit(0);
    }

    const completion = JSON.parse(resp.body);
    if (completion.usage) {
      totalPrompt += completion.usage.prompt_tokens || 0;
      totalCompletion += completion.usage.completion_tokens || 0;
      totalTotal += completion.usage.total_tokens || 0;
    }

    const choice = completion.choices[0];
    const msg = choice.message;
    const finishReason = choice.finish_reason;

    if (finishReason === 'tool_calls') {
      const assistantMsg: any = { role: msg.role };
      assistantMsg.content = msg.content !== undefined ? msg.content : null;
      assistantMsg.tool_calls = msg.tool_calls;
      messages.push(assistantMsg);

      if (typeof msg.content === 'string') {
        outputLines.push('SAY ' + msg.content);
      }

      const toolCalls = msg.tool_calls || [];
      for (const tc of toolCalls) {
        outputLines.push('CALL ' + tc.id + ' ' + tc.function.name);
      }

      for (const tc of toolCalls) {
        const result = executeTool(tc.function.name, tc.function.arguments, inventory, rates);
        outputLines.push('RESULT ' + tc.id + ' ' + result);
        messages.push({ role: 'tool', tool_call_id: tc.id, content: result });
      }
    } else {
      outputLines.push('FINAL ' + (msg.content !== undefined && msg.content !== null ? msg.content : ''));
      break;
    }
  }

  for (const line of outputLines) console.log(line);
  console.log('USAGE prompt=' + totalPrompt + ' completion=' + totalCompletion + ' total=' + totalTotal + ' requests=' + requestCount);
}

main().catch((e) => {
  console.error(e);
  process.exit(0);
});

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

/* ============ String Buffer ============ */
typedef struct { char *d; size_t len, cap; } sb_t;
static void sb_init(sb_t *s){ s->cap=256; s->d=malloc(s->cap); s->len=0; s->d[0]=0; }
static void sb_free(sb_t *s){ free(s->d); }
static void sb_ens(sb_t *s, size_t n){ if(s->len+n+1>s->cap){ while(s->len+n+1>s->cap) s->cap*=2; s->d=realloc(s->d,s->cap);} }
static void sb_app(sb_t *s, const char *p, size_t n){ sb_ens(s,n); memcpy(s->d+s->len,p,n); s->len+=n; s->d[s->len]=0; }
static void sb_app_s(sb_t *s, const char *p){ sb_app(s,p,strlen(p)); }
static void sb_app_c(sb_t *s, char c){ sb_ens(s,1); s->d[s->len++]=c; s->d[s->len]=0; }

/* ============ JSON Value ============ */
typedef enum { JN, JB, JNUM, JSTR, JARR, JOBJ } jt_t;
typedef struct jv {
    jt_t t;
    union {
        int b;
        double num;
        char *str;
        struct { struct jv **a; int n, cap; } arr;
        struct { char **k; struct jv **v; int n, cap; } obj;
    };
} jv_t;

static jv_t *jv_new(jt_t t){ jv_t *v=calloc(1,sizeof(jv_t)); v->t=t; return v; }
static void jv_free(jv_t *v){
    if(!v) return;
    if(v->t==JSTR) free(v->str);
    else if(v->t==JARR){ for(int i=0;i<v->arr.n;i++) jv_free(v->arr.a[i]); free(v->arr.a); }
    else if(v->t==JOBJ){ for(int i=0;i<v->obj.n;i++){ free(v->obj.k[i]); jv_free(v->obj.v[i]); } free(v->obj.k); free(v->obj.v); }
    free(v);
}
static jv_t *jv_obj_get(jv_t *o, const char *k){
    if(!o||o->t!=JOBJ) return NULL;
    for(int i=0;i<o->obj.n;i++) if(strcmp(o->obj.k[i],k)==0) return o->obj.v[i];
    return NULL;
}
static const char *jv_str(jv_t *v){ return (v&&v->t==JSTR)?v->str:""; }
static int jv_int(jv_t *v){ return (v&&v->t==JNUM)?(int)v->num:0; }

/* ============ JSON Parser ============ */
static const char *skip_ws(const char *s){ while(*s&&(*s==' '||*s=='\t'||*s=='\n'||*s=='\r')) s++; return s; }
static jv_t *jparse(const char **pp);

static void encode_utf8(sb_t *s, uint32_t cp){
    if(cp<0x80) sb_app_c(s,(char)cp);
    else if(cp<0x800){ sb_app_c(s,0xC0|(cp>>6)); sb_app_c(s,0x80|(cp&0x3F)); }
    else if(cp<0x10000){ sb_app_c(s,0xE0|(cp>>12)); sb_app_c(s,0x80|((cp>>6)&0x3F)); sb_app_c(s,0x80|(cp&0x3F)); }
    else { sb_app_c(s,0xF0|(cp>>18)); sb_app_c(s,0x80|((cp>>12)&0x3F)); sb_app_c(s,0x80|((cp>>6)&0x3F)); sb_app_c(s,0x80|(cp&0x3F)); }
}

static uint32_t parse_hex4(const char *s){
    uint32_t v=0;
    for(int i=0;i<4;i++){ char c=s[i]; v<<=4; if(c>='0'&&c<='9') v|=c-'0'; else if(c>='a'&&c<='f') v|=c-'a'+10; else if(c>='A'&&c<='F') v|=c-'A'+10; }
    return v;
}

static char *parse_json_str(const char **pp){
    const char *s=*pp; sb_t sb; sb_init(&sb);
    s++; /* skip opening quote */
    while(*s && *s!='"'){
        if(*s=='\\'){
            s++;
            switch(*s){
                case '"': sb_app_c(&sb,'"'); s++; break;
                case '\\': sb_app_c(&sb,'\\'); s++; break;
                case '/': sb_app_c(&sb,'/'); s++; break;
                case 'b': sb_app_c(&sb,'\b'); s++; break;
                case 'f': sb_app_c(&sb,'\f'); s++; break;
                case 'n': sb_app_c(&sb,'\n'); s++; break;
                case 'r': sb_app_c(&sb,'\r'); s++; break;
                case 't': sb_app_c(&sb,'\t'); s++; break;
                case 'u': {
                    s++;
                    uint32_t cp=parse_hex4(s); s+=4;
                    if(cp>=0xD800&&cp<=0xDBFF&&*s=='\\'&&s[1]=='u'){
                        s+=2;
                        uint32_t lo=parse_hex4(s); s+=4;
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    encode_utf8(&sb,cp);
                    break;
                }
                default: sb_app_c(&sb,*s); s++; break;
            }
        } else {
            sb_app_c(&sb,*s); s++;
        }
    }
    if(*s=='"') s++;
    *pp=s;
    return sb.d;
}

static jv_t *jparse(const char **pp){
    const char *s=skip_ws(*pp);
    if(*s=='"'){
        jv_t *v=jv_new(JSTR); v->str=parse_json_str(&s); *pp=s; return v;
    } else if(*s=='{'){
        s++; jv_t *v=jv_new(JOBJ); v->obj.cap=8; v->obj.k=malloc(8*sizeof(char*)); v->obj.v=malloc(8*sizeof(jv_t*));
        s=skip_ws(s);
        if(*s=='}'){ s++; *pp=s; return v; }
        while(1){
            s=skip_ws(s);
            char *key=parse_json_str(&s);
            s=skip_ws(s); s++; /* colon */
            jv_t *val=jparse(&s);
            if(v->obj.n==v->obj.cap){ v->obj.cap*=2; v->obj.k=realloc(v->obj.k,v->obj.cap*sizeof(char*)); v->obj.v=realloc(v->obj.v,v->obj.cap*sizeof(jv_t*)); }
            v->obj.k[v->obj.n]=key; v->obj.v[v->obj.n]=val; v->obj.n++;
            s=skip_ws(s);
            if(*s==','){ s++; continue; }
            if(*s=='}'){ s++; break; }
            break;
        }
        *pp=s; return v;
    } else if(*s=='['){
        s++; jv_t *v=jv_new(JARR); v->arr.cap=8; v->arr.a=malloc(8*sizeof(jv_t*));
        s=skip_ws(s);
        if(*s==']'){ s++; *pp=s; return v; }
        while(1){
            jv_t *val=jparse(&s);
            if(v->arr.n==v->arr.cap){ v->arr.cap*=2; v->arr.a=realloc(v->arr.a,v->arr.cap*sizeof(jv_t*)); }
            v->arr.a[v->arr.n++]=val;
            s=skip_ws(s);
            if(*s==','){ s++; continue; }
            if(*s==']'){ s++; break; }
            break;
        }
        *pp=s; return v;
    } else if(*s=='t'){ *pp=s+4; jv_t *v=jv_new(JB); v->b=1; return v; }
    else if(*s=='f'){ *pp=s+5; jv_t *v=jv_new(JB); v->b=0; return v; }
    else if(*s=='n'){ *pp=s+4; return jv_new(JN); }
    else {
        const char *start=s;
        if(*s=='-') s++;
        while(isdigit(*s)) s++;
        if(*s=='.'){ s++; while(isdigit(*s)) s++; }
        if(*s=='e'||*s=='E'){ s++; if(*s=='+'||*s=='-') s++; while(isdigit(*s)) s++; }
        jv_t *v=jv_new(JNUM); v->num=strtod(start,NULL); *pp=s; return v;
    }
}

/* ============ JSON Serializer ============ */
static void jser_str(sb_t *s, const char *str){
    sb_app_c(s,'"');
    for(const char *p=str; *p; p++){
        unsigned char c=(unsigned char)*p;
        if(c=='"') sb_app_s(s,"\\\"");
        else if(c=='\\') sb_app_s(s,"\\\\");
        else if(c=='\n') sb_app_s(s,"\\n");
        else if(c=='\r') sb_app_s(s,"\\r");
        else if(c=='\t') sb_app_s(s,"\\t");
        else if(c<0x20){ char buf[8]; snprintf(buf,sizeof(buf),"\\u%04x",c); sb_app_s(s,buf); }
        else sb_app_c(s,(char)c);
    }
    sb_app_c(s,'"');
}

static void jser(sb_t *s, jv_t *v){
    if(!v){ sb_app_s(s,"null"); return; }
    switch(v->t){
        case JN: sb_app_s(s,"null"); break;
        case JB: sb_app_s(s,v->b?"true":"false"); break;
        case JNUM: {
            char buf[64];
            if(v->num==(long long)v->num && v->num>=-1e15 && v->num<=1e15)
                snprintf(buf,sizeof(buf),"%.0f",v->num);
            else snprintf(buf,sizeof(buf),"%.17g",v->num);
            sb_app_s(s,buf);
            break;
        }
        case JSTR: jser_str(s,v->str); break;
        case JARR:
            sb_app_c(s,'[');
            for(int i=0;i<v->arr.n;i++){ if(i) sb_app_c(s,','); jser(s,v->arr.a[i]); }
            sb_app_c(s,']');
            break;
        case JOBJ:
            sb_app_c(s,'{');
            for(int i=0;i<v->obj.n;i++){ if(i) sb_app_c(s,','); jser_str(s,v->obj.k[i]); sb_app_c(s,':'); jser(s,v->obj.v[i]); }
            sb_app_c(s,'}');
            break;
    }
}

/* ============ UTF-8 Utilities ============ */
static int utf8_decode(const char *s, uint32_t *cp){
    unsigned char c=(unsigned char)s[0];
    if(c<0x80){ *cp=c; return 1; }
    else if((c&0xE0)==0xC0){ *cp=((uint32_t)(c&0x1F)<<6)|(s[1]&0x3F); return 2; }
    else if((c&0xF0)==0xE0){ *cp=((uint32_t)(c&0x0F)<<12)|((uint32_t)(s[1]&0x3F)<<6)|(s[2]&0x3F); return 3; }
    else { *cp=((uint32_t)(c&0x07)<<18)|((uint32_t)(s[1]&0x3F)<<12)|((uint32_t)(s[2]&0x3F)<<6)|(s[3]&0x3F); return 4; }
}

static int count_codepoints(const char *s){
    int count=0;
    while(*s){ uint32_t cp; int n=utf8_decode(s,&cp); s+=n; count++; }
    return count;
}

static int count_utf16_units(const char *s){
    int count=0;
    while(*s){ uint32_t cp; int n=utf8_decode(s,&cp); s+=n; count+=(cp>0xFFFF)?2:1; }
    return count;
}

static char *reverse_utf8(const char *s){
    int cap=32, n=0;
    uint32_t *cps=malloc(cap*sizeof(uint32_t));
    while(*s){
        uint32_t cp; int len=utf8_decode(s,&cp); s+=len;
        if(n==cap){ cap*=2; cps=realloc(cps,cap*sizeof(uint32_t)); }
        cps[n++]=cp;
    }
    sb_t out; sb_init(&out);
    for(int i=n-1;i>=0;i--) encode_utf8(&out,cps[i]);
    free(cps);
    return out.d;
}

/* ============ HTTP Client ============ */
typedef struct {
    int status;
    char *body;
    size_t body_len;
} http_resp_t;

static char *read_file(const char *path, size_t *len){
    FILE *f=fopen(path,"rb");
    if(!f) return NULL;
    fseek(f,0,SEEK_END); *len=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=malloc(*len+1);
    fread(buf,1,*len,f); buf[*len]=0; fclose(f);
    return buf;
}

static void parse_url(const char *url, char *host, int *port, char *path){
    const char *p=url;
    if(strncmp(p,"http://",7)==0) p+=7;
    const char *slash=strchr(p,'/');
    const char *hostend=slash?slash:p+(strlen(p));
    const char *colon=memchr(p,':',hostend-p);
    if(colon){
        int hlen=colon-p;
        memcpy(host,p,hlen); host[hlen]=0;
        *port=atoi(colon+1);
    } else {
        int hlen=hostend-p;
        memcpy(host,p,hlen); host[hlen]=0;
        *port=80;
    }
    if(slash) strcpy(path,slash); else strcpy(path,"/");
}

static http_resp_t http_post(const char *host, int port, const char *path, const char *api_key, const char *body){
    http_resp_t resp={0,NULL,0};
    struct addrinfo hints={0}, *res;
    char portstr[16]; snprintf(portstr,sizeof(portstr),"%d",port);
    hints.ai_family=AF_INET; hints.ai_socktype=SOCK_STREAM;
    if(getaddrinfo(host,portstr,&hints,&res)!=0) return resp;
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    connect(fd,res->ai_addr,res->ai_addrlen);
    freeaddrinfo(res);

    sb_t req; sb_init(&req);
    sb_app_s(&req,"POST ");
    sb_app_s(&req,path);
    sb_app_s(&req," HTTP/1.1\r\n");
    sb_app_s(&req,"Host: "); sb_app_s(&req,host);
    char ps[16]; snprintf(ps,sizeof(ps),":%d",port); sb_app_s(&req,ps);
    sb_app_s(&req,"\r\n");
    sb_app_s(&req,"Content-Type: application/json\r\n");
    sb_app_s(&req,"x-api-key: "); sb_app_s(&req,api_key); sb_app_s(&req,"\r\n");
    sb_app_s(&req,"anthropic-version: 2023-06-01\r\n");
    char cl[32]; snprintf(cl,sizeof(cl),"Content-Length: %zu\r\n",strlen(body));
    sb_app_s(&req,cl);
    sb_app_s(&req,"\r\n");
    sb_app_s(&req,body);
    write(fd,req.d,req.len);
    sb_free(&req);

    /* Read all response */
    size_t rcap=65536, rlen=0;
    char *rb=malloc(rcap);
    while(1){
        if(rlen==rcap){ rcap*=2; rb=realloc(rb,rcap); }
        ssize_t n=read(fd,rb+rlen,rcap-rlen);
        if(n<=0) break;
        rlen+=n;
    }
    close(fd);

    /* Parse headers */
    char *hdr_end=strstr(rb,"\r\n\r\n");
    if(!hdr_end){ resp.body=rb; resp.body_len=rlen; return resp; }
    *hdr_end=0;
    sscanf(rb,"HTTP/%*d.%*d %d",&resp.status);

    /* Find transfer-encoding and content-length */
    int chunked=0;
    long clen=-1;
    char *line=rb;
    while(line&&*line){
        char *nl=strstr(line,"\r\n");
        if(!nl) break;
        *nl=0;
        if(strncasecmp(line,"Transfer-Encoding:",18)==0){
            if(strcasestr(line,"chunked")) chunked=1;
        }
        if(strncasecmp(line,"Content-Length:",15)==0){
            clen=atol(line+15);
        }
        line=nl+2;
    }

    char *body_start=hdr_end+4;
    size_t body_avail=rlen-(body_start-rb);

    if(chunked){
        /* Decode chunked body */
        sb_t out; sb_init(&out);
        char *p=body_start;
        char *end=rb+rlen;
        while(p<end){
            /* parse hex size */
            long sz=0;
            while(p<end&&isxdigit(*p)){
                char c=*p; sz=sz*16;
                if(c>='0'&&c<='9') sz+=c-'0';
                else if(c>='a'&&c<='f') sz+=c-'a'+10;
                else sz+=c-'A'+10;
                p++;
            }
            /* skip chunk extension */
            while(p<end&&*p!='\r'&&*p!='\n') p++;
            /* skip CRLF */
            if(p<end&&*p=='\r') p++;
            if(p<end&&*p=='\n') p++;
            if(sz==0) break;
            if(p+sz<=end) sb_app(&out,p,sz);
            p+=sz;
            if(p<end&&*p=='\r') p++;
            if(p<end&&*p=='\n') p++;
        }
        resp.body=out.d; resp.body_len=out.len;
        free(rb);
    } else {
        if(clen>=0 && (size_t)clen<=body_avail){
            resp.body=malloc(clen+1);
            memcpy(resp.body,body_start,clen);
            resp.body[clen]=0;
            resp.body_len=clen;
        } else {
            resp.body=malloc(body_avail+1);
            memcpy(resp.body,body_start,body_avail);
            resp.body[body_avail]=0;
            resp.body_len=body_avail;
        }
        free(rb);
    }
    return resp;
}

/* ============ SSE Parser ============ */
typedef void (*sse_cb_t)(const char *event, const char *data, void *ctx);

static void parse_sse(const char *body, size_t len, sse_cb_t cb, void *ctx){
    sb_t event_name; sb_init(&event_name);
    sb_t data_buf; sb_init(&data_buf);
    int have_data=0;
    size_t i=0;
    while(i<len){
        /* Read one line */
        size_t start=i;
        while(i<len && body[i]!='\n') i++;
        size_t line_end=i;
        if(i<len) i++; /* skip \n */
        /* Strip trailing \r */
        if(line_end>start && body[line_end-1]=='\r') line_end--;
        size_t line_len=line_end-start;

        if(line_len==0){
            /* Blank line: dispatch event */
            if(have_data||event_name.len>0){
                cb(event_name.len?event_name.d:"", data_buf.d?data_buf.d:"", ctx);
            }
            event_name.len=0; event_name.d[0]=0;
            data_buf.len=0; data_buf.d[0]=0;
            have_data=0;
        } else if(body[start]==':'){
            /* Comment, ignore */
        } else if(line_len>=6 && strncmp(body+start,"event:",6)==0){
            const char *v=body+start+6;
            size_t vl=line_len-6;
            if(vl>0&&*v==' '){ v++; vl--; }
            event_name.len=0;
            sb_app(&event_name,v,vl);
        } else if(line_len>=5 && strncmp(body+start,"data:",5)==0){
            const char *v=body+start+5;
            size_t vl=line_len-5;
            if(vl>0&&*v==' '){ v++; vl--; }
            if(have_data) sb_app_c(&data_buf,'\n');
            sb_app(&data_buf,v,vl);
            have_data=1;
        }
    }
    sb_free(&event_name);
    sb_free(&data_buf);
}

/* ============ Content Blocks ============ */
typedef struct {
    int type; /* 0=thinking, 1=text, 2=tool_use */
    sb_t thinking;
    sb_t signature;
    sb_t text;
    char *id;
    char *name;
    sb_t input_json;
} cblock_t;

typedef struct {
    cblock_t *blocks;
    int nblocks, cap_blocks;
    int stop_reason_set;
    char stop_reason[64];
    int input_tokens;
    int output_tokens;
    int cache_read;
} resp_data_t;

static void resp_init(resp_data_t *r){ memset(r,0,sizeof(*r)); }
static void resp_free(resp_data_t *r){
    for(int i=0;i<r->nblocks;i++){
        cblock_t *b=&r->blocks[i];
        sb_free(&b->thinking); sb_free(&b->signature); sb_free(&b->text); sb_free(&b->input_json);
        free(b->id); free(b->name);
    }
    free(r->blocks);
}

static cblock_t *get_block(resp_data_t *r, int idx){
    while(r->nblocks<=idx){
        if(r->nblocks==r->cap_blocks){ r->cap_blocks=r->cap_blocks?r->cap_blocks*2:8; r->blocks=realloc(r->blocks,r->cap_blocks*sizeof(cblock_t)); }
        cblock_t *b=&r->blocks[r->nblocks];
        memset(b,0,sizeof(*b));
        sb_init(&b->thinking); sb_init(&b->signature); sb_init(&b->text); sb_init(&b->input_json);
        r->nblocks++;
    }
    return &r->blocks[idx];
}

static void sse_handler(const char *event, const char *data, void *ctx){
    resp_data_t *r=(resp_data_t*)ctx;
    if(!data||!data[0]) return;
    const char *p=data;
    jv_t *ev=jparse(&p);
    if(!ev) return;

    if(strcmp(event,"message_start")==0){
        jv_t *msg=jv_obj_get(ev,"message");
        jv_t *usage=jv_obj_get(msg,"usage");
        if(usage){
            jv_t *it=jv_obj_get(usage,"input_tokens");
            if(it) r->input_tokens=jv_int(it);
            jv_t *cr=jv_obj_get(usage,"cache_read_input_tokens");
            if(cr) r->cache_read=jv_int(cr);
        }
    } else if(strcmp(event,"content_block_start")==0){
        jv_t *idx=jv_obj_get(ev,"index");
        int i=idx?jv_int(idx):0;
        jv_t *cb=jv_obj_get(ev,"content_block");
        cblock_t *b=get_block(r,i);
        const char *type=jv_str(jv_obj_get(cb,"type"));
        if(strcmp(type,"thinking")==0) b->type=0;
        else if(strcmp(type,"text")==0) b->type=1;
        else if(strcmp(type,"tool_use")==0){
            b->type=2;
            b->id=strdup(jv_str(jv_obj_get(cb,"id")));
            b->name=strdup(jv_str(jv_obj_get(cb,"name")));
        }
    } else if(strcmp(event,"content_block_delta")==0){
        jv_t *idx=jv_obj_get(ev,"index");
        int i=idx?jv_int(idx):0;
        jv_t *delta=jv_obj_get(ev,"delta");
        const char *dtype=jv_str(jv_obj_get(delta,"type"));
        cblock_t *b=get_block(r,i);
        if(strcmp(dtype,"thinking_delta")==0){
            sb_app_s(&b->thinking,jv_str(jv_obj_get(delta,"thinking")));
        } else if(strcmp(dtype,"signature_delta")==0){
            sb_app_s(&b->signature,jv_str(jv_obj_get(delta,"signature")));
        } else if(strcmp(dtype,"text_delta")==0){
            sb_app_s(&b->text,jv_str(jv_obj_get(delta,"text")));
        } else if(strcmp(dtype,"input_json_delta")==0){
            sb_app_s(&b->input_json,jv_str(jv_obj_get(delta,"partial_json")));
        }
    } else if(strcmp(event,"message_delta")==0){
        jv_t *delta=jv_obj_get(ev,"delta");
        if(delta){
            const char *sr=jv_str(jv_obj_get(delta,"stop_reason"));
            if(sr&&sr[0]){ strncpy(r->stop_reason,sr,63); r->stop_reason[63]=0; r->stop_reason_set=1; }
        }
        jv_t *usage=jv_obj_get(ev,"usage");
        if(usage){
            jv_t *ot=jv_obj_get(usage,"output_tokens");
            if(ot) r->output_tokens=jv_int(ot);
        }
    }
    jv_free(ev);
}

/* ============ Output ============ */
static void print_escaped(const char *s){
    for(const char *p=s; *p; p++){
        unsigned char c=(unsigned char)*p;
        if(c=='\\') printf("\\\\");
        else if(c=='\n') printf("\\n");
        else if(c=='\r') printf("\\r");
        else if(c=='\t') printf("\\t");
        else putchar(c);
    }
}

static void print_escaped_n(const char *s, size_t len){
    for(size_t i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='\\') printf("\\\\");
        else if(c=='\n') printf("\\n");
        else if(c=='\r') printf("\\r");
        else if(c=='\t') printf("\\t");
        else putchar(c);
    }
}

/* ============ Tool Execution ============ */
static char *execute_tool(const char *name, jv_t *input, int *is_error){
    *is_error=0;
    if(strcmp(name,"measure")==0){
        jv_t *text_v=jv_obj_get(input,"text");
        jv_t *unit_v=jv_obj_get(input,"unit");
        if(!text_v||text_v->t!=JSTR||!unit_v||unit_v->t!=JSTR){
            *is_error=1; return strdup("unknown tool: measure");
        }
        const char *text=text_v->str;
        const char *unit=unit_v->str;
        if(strcmp(unit,"code_points")==0){
            char buf[32]; snprintf(buf,sizeof(buf),"%d",count_codepoints(text)); return strdup(buf);
        } else if(strcmp(unit,"utf8_bytes")==0){
            char buf[32]; snprintf(buf,sizeof(buf),"%zu",strlen(text)); return strdup(buf);
        } else if(strcmp(unit,"utf16_units")==0){
            char buf[32]; snprintf(buf,sizeof(buf),"%d",count_utf16_units(text)); return strdup(buf);
        } else {
            *is_error=1;
            char buf[256]; snprintf(buf,sizeof(buf),"unsupported unit: %s",unit); return strdup(buf);
        }
    } else if(strcmp(name,"reverse")==0){
        jv_t *text_v=jv_obj_get(input,"text");
        if(!text_v||text_v->t!=JSTR){
            *is_error=1; return strdup("unknown tool: reverse");
        }
        return reverse_utf8(text_v->str);
    } else {
        *is_error=1;
        char buf[256]; snprintf(buf,sizeof(buf),"unknown tool: %s",name); return strdup(buf);
    }
}

/* ============ Build Request Body ============ */
static void build_request_body(sb_t *body, jv_t *model, jv_t *max_tokens, jv_t *thinking_budget,
                               jv_t *system, jv_t *tools, jv_t *messages){
    sb_app_s(body,"{\"model\":");
    jser(body,model);
    sb_app_s(body,",\"max_tokens\":");
    jser(body,max_tokens);
    sb_app_s(body,",\"stream\":true");
    sb_app_s(body,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    jser(body,thinking_budget);
    sb_app_s(body,"}");
    sb_app_s(body,",\"system\":");
    jser(body,system);
    sb_app_s(body,",\"tools\":");
    jser(body,tools);
    sb_app_s(body,",\"messages\":");
    jser(body,messages);
    sb_app_c(body,'}');
}

/* ============ Main ============ */
int main(int argc, char **argv){
    if(argc<3){ fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]); return 1; }
    const char *data_dir=argv[1];
    const char *base_url=argv[2];

    /* Parse URL */
    char host[256]={0}, path[512]={0}; int port=80;
    parse_url(base_url,host,&port,path);
    char req_path[512];
    snprintf(req_path,sizeof(req_path),"%s/v1/messages",path);

    /* Read request.json */
    char rpath[512];
    snprintf(rpath,sizeof(rpath),"%s/request.json",data_dir);
    size_t flen;
    char *fdata=read_file(rpath,&flen);
    if(!fdata){ fprintf(stderr,"Cannot read %s\n",rpath); return 1; }
    const char *fp=fdata;
    jv_t *req=jparse(&fp);

    jv_t *j_api_key=jv_obj_get(req,"api_key");
    jv_t *j_model=jv_obj_get(req,"model");
    jv_t *j_max_tokens=jv_obj_get(req,"max_tokens");
    jv_t *j_thinking_budget=jv_obj_get(req,"thinking_budget");
    jv_t *j_system=jv_obj_get(req,"system");
    jv_t *j_prompt=jv_obj_get(req,"prompt");
    jv_t *j_tools=jv_obj_get(req,"tools");

    const char *api_key=j_str(j_api_key);

    /* Build request 1 messages */
    /* messages: [{"role":"user","content":<prompt>}] */
    sb_t msgs1; sb_init(&msgs1);
    sb_app_s(&msgs1,"[{\"role\":\"user\",\"content\":");
    jser(&msgs1,j_prompt);
    sb_app_s(&msgs1,"}]");

    /* Build request 1 body */
    sb_t body1; sb_init(&body1);
    build_request_body(&body1,j_model,j_max_tokens,j_thinking_budget,j_system,j_tools,
                       /* We need to pass messages as a jv_t or raw string */
                       /* Let me restructure: build body manually */
                       NULL);
    sb_free(&body1);

    /* Actually let me build the body as a string directly */
    sb_init(&body1);
    sb_app_s(&body1,"{\"model\":");
    jser(&body1,j_model);
    sb_app_s(&body1,",\"max_tokens\":");
    jser(&body1,j_max_tokens);
    sb_app_s(&body1,",\"stream\":true");
    sb_app_s(&body1,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    jser(&body1,j_thinking_budget);
    sb_app_s(&body1,"}");
    sb_app_s(&body1,",\"system\":");
    jser(&body1,j_system);
    sb_app_s(&body1,",\"tools\":");
    jser(&body1,j_tools);
    sb_app_s(&body1,",\"messages\":");
    sb_app_s(&body1,"[{\"role\":\"user\",\"content\":");
    jser(&body1,j_prompt);
    sb_app_s(&body1,"}]");
    sb_app_c(&body1,'}');

    printf("request 1\n");
    fflush(stdout);

    /* Send request 1 */
    http_resp_t resp1=http_post(host,port,req_path,api_key,body1.d);
    if(resp1.status!=200){
        /* Parse error */
        const char *ep=resp1.body;
        jv_t *err=jparse(&ep);
        jv_t *err_obj=jv_obj_get(err,"error");
        const char *etype=jv_str(jv_obj_get(err_obj,"type"));
        const char *emsg=jv_str(jv_obj_get(err_obj,"message"));
        printf("ERROR %d %s: %s\n",resp1.status,etype,emsg);
        fflush(stdout);
        jv_free(err);
        return 0;
    }

    /* Parse SSE response 1 */
    resp_data_t rd1; resp_init(&rd1);
    parse_sse(resp1.body,resp1.body_len,sse_handler,&rd1);

    /* Print blocks */
    for(int i=0;i<rd1.nblocks;i++){
        cblock_t *b=&rd1.blocks[i];
        if(b->type==0){
            printf("thinking "); print_escaped(b->thinking.d); printf("\n");
            printf("signature "); print_escaped(b->signature.d); printf("\n");
        } else if(b->type==1){
            printf("text "); print_escaped(b->text.d); printf("\n");
        } else {
            printf("tool_use "); print_escaped(b->id); printf(" "); print_escaped(b->name); printf(" ");
            print_escaped(b->input_json.d); printf("\n");
        }
    }
    printf("stop_reason %s\n",rd1.stop_reason);
    fflush(stdout);

    /* Execute tools */
    /* Collect tool results */
    typedef struct { char *id; char *result; int is_error; } tool_result_t;
    tool_result_t *results=NULL;
    int nresults=0, cap_results=0;

    for(int i=0;i<rd1.nblocks;i++){
        cblock_t *b=&rd1.blocks[i];
        if(b->type!=2) continue;
        /* Parse input JSON */
        jv_t *input=NULL;
        if(b->input_json.len>0){
            const char *ip=b->input_json.d;
            input=jparse(&ip);
        }
        int is_err=0;
        char *result=execute_tool(b->name,input,&is_err);
        if(nresults==cap_results){ cap_results=cap_results?cap_results*2:8; results=realloc(results,cap_results*sizeof(tool_result_t)); }
        results[nresults].id=strdup(b->id);
        results[nresults].result=result;
        results[nresults].is_error=is_err;
        nresults++;
        printf("%s ",is_err?"error":"result");
        print_escaped(b->id); printf(" ");
        print_escaped(result); printf("\n");
        jv_free(input);
    }
    fflush(stdout);

    /* Build request 2 */
    /* messages: [user_msg, assistant_msg, tool_result_msg] */
    sb_t body2; sb_init(&body2);
    sb_app_s(&body2,"{\"model\":");
    jser(&body2,j_model);
    sb_app_s(&body2,",\"max_tokens\":");
    jser(&body2,j_max_tokens);
    sb_app_s(&body2,",\"stream\":true");
    sb_app_s(&body2,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    jser(&body2,j_thinking_budget);
    sb_app_s(&body2,"}");
    sb_app_s(&body2,",\"system\":");
    jser(&body2,j_system);
    sb_app_s(&body2,",\"tools\":");
    jser(&body2,j_tools);
    sb_app_s(&body2,",\"messages\":[");
    /* Message 1: user */
    sb_app_s(&body2,"{\"role\":\"user\",\"content\":");
    jser(&body2,j_prompt);
    sb_app_s(&body2,"}");
    /* Message 2: assistant */
    sb_app_s(&body2,",{\"role\":\"assistant\",\"content\":[");
    for(int i=0;i<rd1.nblocks;i++){
        if(i) sb_app_c(&body2,',');
        cblock_t *b=&rd1.blocks[i];
        if(b->type==0){
            sb_app_s(&body2,"{\"type\":\"thinking\",\"thinking\":");
            jser_str(&body2,b->thinking.d);
            sb_app_s(&body2,",\"signature\":");
            jser_str(&body2,b->signature.d);
            sb_app_c(&body2,'}');
        } else if(b->type==1){
            sb_app_s(&body2,"{\"type\":\"text\",\"text\":");
            jser_str(&body2,b->text.d);
            sb_app_c(&body2,'}');
        } else {
            sb_app_s(&body2,"{\"type\":\"tool_use\",\"id\":");
            jser_str(&body2,b->id);
            sb_app_s(&body2,",\"name\":");
            jser_str(&body2,b->name);
            sb_app_s(&body2,",\"input\":");
            /* Parse and re-serialize input */
            if(b->input_json.len>0){
                const char *ip=b->input_json.d;
                jv_t *inp=jparse(&ip);
                jser(&body2,inp);
                jv_free(inp);
            } else {
                sb_app_s(&body2,"{}");
            }
            sb_app_c(&body2,'}');
        }
    }
    sb_app_s(&body2,"]}");
    /* Message 3: tool results */
    sb_app_s(&body2,",{\"role\":\"user\",\"content\":[");
    for(int i=0;i<nresults;i++){
        if(i) sb_app_c(&body2,',');
        sb_app_s(&body2,"{\"type\":\"tool_result\",\"tool_use_id\":");
        jser_str(&body2,results[i].id);
        sb_app_s(&body2,",\"content\":");
        jser_str(&body2,results[i].result);
        if(results[i].is_error) sb_app_s(&body2,",\"is_error\":true");
        sb_app_c(&body2,'}');
    }
    sb_app_s(&body2,"]}");
    sb_app_s(&body2,"]}");
    sb_app_c(&body2,'}');

    printf("request 2\n");
    fflush(stdout);

    /* Send request 2 */
    http_resp_t resp2=http_post(host,port,req_path,api_key,body2.d);
    if(resp2.status!=200){
        const char *ep=resp2.body;
        jv_t *err=jparse(&ep);
        jv_t *err_obj=jv_obj_get(err,"error");
        const char *etype=jv_str(jv_obj_get(err_obj,"type"));
        const char *emsg=jv_str(jv_obj_get(err_obj,"message"));
        printf("ERROR %d %s: %s\n",resp2.status,etype,emsg);
        fflush(stdout);
        jv_free(err);
        return 0;
    }

    /* Parse SSE response 2 */
    resp_data_t rd2; resp_init(&rd2);
    parse_sse(resp2.body,resp2.body_len,sse_handler,&rd2);

    /* Print blocks */
    for(int i=0;i<rd2.nblocks;i++){
        cblock_t *b=&rd2.blocks[i];
        if(b->type==0){
            printf("thinking "); print_escaped(b->thinking.d); printf("\n");
            printf("signature "); print_escaped(b->signature.d); printf("\n");
        } else if(b->type==1){
            printf("text "); print_escaped(b->text.d); printf("\n");
        } else {
            printf("tool_use "); print_escaped(b->id); printf(" "); print_escaped(b->name); printf(" ");
            print_escaped(b->input_json.d); printf("\n");
        }
    }
    printf("stop_reason %s\n",rd2.stop_reason);

    /* Usage */
    int total_input=rd1.input_tokens+rd2.input_tokens;
    int total_output=rd1.output_tokens+rd2.output_tokens;
    int total_cache=rd1.cache_read+rd2.cache_read;
    printf("usage input=%d output=%d cache_read=%d\n",total_input,total_output,total_cache);
    fflush(stdout);

    /* Cleanup */
    resp_free(&rd1); resp_free(&rd2);
    for(int i=0;i<nresults;i++) free(results[i].id);
    free(results);
    sb_free(&body1); sb_free(&body2); sb_free(&msgs1);
    free(resp1.body); free(resp2.body);
    free(fdata);
    jv_free(req);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

/* ============ String Buffer ============ */
typedef struct { char *d; size_t len, cap; } sb_t;
static void sb_init(sb_t *s){ s->cap=256; s->d=malloc(s->cap); s->len=0; s->d[0]=0; }
static void sb_free(sb_t *s){ free(s->d); }
static void sb_ens(sb_t *s, size_t n){ if(s->len+n+1>s->cap){ while(s->len+n+1>s->cap) s->cap*=2; s->d=realloc(s->d,s->cap);} }
static void sb_app(sb_t *s, const char *p, size_t n){ sb_ens(s,n); memcpy(s->d+s->len,p,n); s->len+=n; s->d[s->len]=0; }
static void sb_app_s(sb_t *s, const char *p){ sb_app(s,p,strlen(p)); }
static void sb_app_c(sb_t *s, char c){ sb_ens(s,1); s->d[s->len++]=c; s->d[s->len]=0; }

/* ============ JSON Value ============ */
typedef enum { JN, JB, JNUM, JSTR, JARR, JOBJ } jt_t;
typedef struct jv {
    jt_t t;
    union {
        int b;
        double num;
        char *str;
        struct { struct jv **a; int n, cap; } arr;
        struct { char **k; struct jv **v; int n, cap; } obj;
    };
} jv_t;

static jv_t *jv_new(jt_t t){ jv_t *v=calloc(1,sizeof(jv_t)); v->t=t; return v; }
static void jv_free(jv_t *v){
    if(!v) return;
    if(v->t==JSTR) free(v->str);
    else if(v->t==JARR){ for(int i=0;i<v->arr.n;i++) jv_free(v->arr.a[i]); free(v->arr.a); }
    else if(v->t==JOBJ){ for(int i=0;i<v->obj.n;i++){ free(v->obj.k[i]); jv_free(v->obj.v[i]); } free(v->obj.k); free(v->obj.v); }
    free(v);
}
static jv_t *jv_obj_get(jv_t *o, const char *k){
    if(!o||o->t!=JOBJ) return NULL;
    for(int i=0;i<o->obj.n;i++) if(strcmp(o->obj.k[i],k)==0) return o->obj.v[i];
    return NULL;
}
static const char *jv_str(jv_t *v){ return (v&&v->t==JSTR)?v->str:""; }
static int jv_int(jv_t *v){ return (v&&v->t==JNUM)?(int)v->num:0; }

/* ============ JSON Parser ============ */
static const char *skip_ws(const char *s){ while(*s&&(*s==' '||*s=='\t'||*s=='\n'||*s=='\r')) s++; return s; }
static jv_t *jparse(const char **pp);

static void encode_utf8(sb_t *s, uint32_t cp){
    if(cp<0x80) sb_app_c(s,(char)cp);
    else if(cp<0x800){ sb_app_c(s,0xC0|(cp>>6)); sb_app_c(s,0x80|(cp&0x3F)); }
    else if(cp<0x10000){ sb_app_c(s,0xE0|(cp>>12)); sb_app_c(s,0x80|((cp>>6)&0x3F)); sb_app_c(s,0x80|(cp&0x3F)); }
    else { sb_app_c(s,0xF0|(cp>>18)); sb_app_c(s,0x80|((cp>>12)&0x3F)); sb_app_c(s,0x80|((cp>>6)&0x3F)); sb_app_c(s,0x80|(cp&0x3F)); }
}

static uint32_t parse_hex4(const char *s){
    uint32_t v=0;
    for(int i=0;i<4;i++){ char c=s[i]; v<<=4; if(c>='0'&&c<='9') v|=c-'0'; else if(c>='a'&&c<='f') v|=c-'a'+10; else if(c>='A'&&c<='F') v|=c-'A'+10; }
    return v;
}

static char *parse_json_str(const char **pp){
    const char *s=*pp; sb_t sb; sb_init(&sb);
    s++; /* skip opening quote */
    while(*s && *s!='"'){
        if(*s=='\\'){
            s++;
            switch(*s){
                case '"': sb_app_c(&sb,'"'); s++; break;
                case '\\': sb_app_c(&sb,'\\'); s++; break;
                case '/': sb_app_c(&sb,'/'); s++; break;
                case 'b': sb_app_c(&sb,'\b'); s++; break;
                case 'f': sb_app_c(&sb,'\f'); s++; break;
                case 'n': sb_app_c(&sb,'\n'); s++; break;
                case 'r': sb_app_c(&sb,'\r'); s++; break;
                case 't': sb_app_c(&sb,'\t'); s++; break;
                case 'u': {
                    s++;
                    uint32_t cp=parse_hex4(s); s+=4;
                    if(cp>=0xD800&&cp<=0xDBFF&&*s=='\\'&&s[1]=='u'){
                        s+=2;
                        uint32_t lo=parse_hex4(s); s+=4;
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    encode_utf8(&sb,cp);
                    break;
                }
                default: sb_app_c(&sb,*s); s++; break;
            }
        } else {
            sb_app_c(&sb,*s); s++;
        }
    }
    if(*s=='"') s++;
    *pp=s;
    return sb.d;
}

static jv_t *jparse(const char **pp){
    const char *s=skip_ws(*pp);
    if(*s=='"'){
        jv_t *v=jv_new(JSTR); v->str=parse_json_str(&s); *pp=s; return v;
    } else if(*s=='{'){
        s++; jv_t *v=jv_new(JOBJ); v->obj.cap=8; v->obj.k=malloc(8*sizeof(char*)); v->obj.v=malloc(8*sizeof(jv_t*));
        s=skip_ws(s);
        if(*s=='}'){ s++; *pp=s; return v; }
        while(1){
            s=skip_ws(s);
            char *key=parse_json_str(&s);
            s=skip_ws(s); s++; /* colon */
            jv_t *val=jparse(&s);
            if(v->obj.n==v->obj.cap){ v->obj.cap*=2; v->obj.k=realloc(v->obj.k,v->obj.cap*sizeof(char*)); v->obj.v=realloc(v->obj.v,v->obj.cap*sizeof(jv_t*)); }
            v->obj.k[v->obj.n]=key; v->obj.v[v->obj.n]=val; v->obj.n++;
            s=skip_ws(s);
            if(*s==','){ s++; continue; }
            if(*s=='}'){ s++; break; }
            break;
        }
        *pp=s; return v;
    } else if(*s=='['){
        s++; jv_t *v=jv_new(JARR); v->arr.cap=8; v->arr.a=malloc(8*sizeof(jv_t*));
        s=skip_ws(s);
        if(*s==']'){ s++; *pp=s; return v; }
        while(1){
            jv_t *val=jparse(&s);
            if(v->arr.n==v->arr.cap){ v->arr.cap*=2; v->arr.a=realloc(v->arr.a,v->arr.cap*sizeof(jv_t*)); }
            v->arr.a[v->arr.n++]=val;
            s=skip_ws(s);
            if(*s==','){ s++; continue; }
            if(*s==']'){ s++; break; }
            break;
        }
        *pp=s; return v;
    } else if(*s=='t'){ *pp=s+4; jv_t *v=jv_new(JB); v->b=1; return v; }
    else if(*s=='f'){ *pp=s+5; jv_t *v=jv_new(JB); v->b=0; return v; }
    else if(*s=='n'){ *pp=s+4; return jv_new(JN); }
    else {
        const char *start=s;
        if(*s=='-') s++;
        while(isdigit((unsigned char)*s)) s++;
        if(*s=='.'){ s++; while(isdigit((unsigned char)*s)) s++; }
        if(*s=='e'||*s=='E'){ s++; if(*s=='+'||*s=='-') s++; while(isdigit((unsigned char)*s)) s++; }
        jv_t *v=jv_new(JNUM); v->num=strtod(start,NULL); *pp=s; return v;
    }
}

/* ============ JSON Serializer ============ */
static void jser_str(sb_t *s, const char *str){
    sb_app_c(s,'"');
    for(const char *p=str; *p; p++){
        unsigned char c=(unsigned char)*p;
        if(c=='"') sb_app_s(s,"\\\"");
        else if(c=='\\') sb_app_s(s,"\\\\");
        else if(c=='\n') sb_app_s(s,"\\n");
        else if(c=='\r') sb_app_s(s,"\\r");
        else if(c=='\t') sb_app_s(s,"\\t");
        else if(c<0x20){ char buf[8]; snprintf(buf,sizeof(buf),"\\u%04x",c); sb_app_s(s,buf); }
        else sb_app_c(s,(char)c);
    }
    sb_app_c(s,'"');
}

static void jser(sb_t *s, jv_t *v){
    if(!v){ sb_app_s(s,"null"); return; }
    switch(v->t){
        case JN: sb_app_s(s,"null"); break;
        case JB: sb_app_s(s,v->b?"true":"false"); break;
        case JNUM: {
            char buf[64];
            if(v->num==(long long)v->num && v->num>=-1e15 && v->num<=1e15)
                snprintf(buf,sizeof(buf),"%.0f",v->num);
            else snprintf(buf,sizeof(buf),"%.17g",v->num);
            sb_app_s(s,buf);
            break;
        }
        case JSTR: jser_str(s,v->str); break;
        case JARR:
            sb_app_c(s,'[');
            for(int i=0;i<v->arr.n;i++){ if(i) sb_app_c(s,','); jser(s,v->arr.a[i]); }
            sb_app_c(s,']');
            break;
        case JOBJ:
            sb_app_c(s,'{');
            for(int i=0;i<v->obj.n;i++){ if(i) sb_app_c(s,','); jser_str(s,v->obj.k[i]); sb_app_c(s,':'); jser(s,v->obj.v[i]); }
            sb_app_c(s,'}');
            break;
    }
}

/* ============ UTF-8 Utilities ============ */
static int utf8_decode(const char *s, uint32_t *cp){
    unsigned char c=(unsigned char)s[0];
    if(c<0x80){ *cp=c; return 1; }
    else if((c&0xE0)==0xC0){ *cp=((uint32_t)(c&0x1F)<<6)|(s[1]&0x3F); return 2; }
    else if((c&0xF0)==0xE0){ *cp=((uint32_t)(c&0x0F)<<12)|((uint32_t)(s[1]&0x3F)<<6)|(s[2]&0x3F); return 3; }
    else { *cp=((uint32_t)(c&0x07)<<18)|((uint32_t)(s[1]&0x3F)<<12)|((uint32_t)(s[2]&0x3F)<<6)|(s[3]&0x3F); return 4; }
}

static int count_codepoints(const char *s){
    int count=0;
    while(*s){ uint32_t cp; int n=utf8_decode(s,&cp); s+=n; count++; }
    return count;
}

static int count_utf16_units(const char *s){
    int count=0;
    while(*s){ uint32_t cp; int n=utf8_decode(s,&cp); s+=n; count+=(cp>0xFFFF)?2:1; }
    return count;
}

static char *reverse_utf8(const char *s){
    int cap=32, n=0;
    uint32_t *cps=malloc(cap*sizeof(uint32_t));
    while(*s){
        uint32_t cp; int len=utf8_decode(s,&cp); s+=len;
        if(n==cap){ cap*=2; cps=realloc(cps,cap*sizeof(uint32_t)); }
        cps[n++]=cp;
    }
    sb_t out; sb_init(&out);
    for(int i=n-1;i>=0;i--) encode_utf8(&out,cps[i]);
    free(cps);
    return out.d;
}

/* ============ Case-insensitive substring ============ */
static int ci_contains(const char *haystack, const char *needle){
    size_t hlen=strlen(haystack), nlen=strlen(needle);
    for(size_t i=0;i+nlen<=hlen;i++){
        if(strncasecmp(haystack+i,needle,nlen)==0) return 1;
    }
    return 0;
}

/* ============ HTTP Client ============ */
typedef struct {
    int status;
    char *body;
    size_t body_len;
} http_resp_t;

static char *read_file(const char *path, size_t *len){
    FILE *f=fopen(path,"rb");
    if(!f) return NULL;
    fseek(f,0,SEEK_END); *len=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=malloc(*len+1);
    fread(buf,1,*len,f); buf[*len]=0; fclose(f);
    return buf;
}

static void parse_url(const char *url, char *host, int *port, char *path){
    const char *p=url;
    if(strncmp(p,"http://",7)==0) p+=7;
    const char *slash=strchr(p,'/');
    const char *hostend=slash?slash:p+strlen(p);
    const char *colon=memchr(p,':',hostend-p);
    if(colon){
        int hlen=(int)(colon-p);
        memcpy(host,p,hlen); host[hlen]=0;
        *port=atoi(colon+1);
    } else {
        int hlen=(int)(hostend-p);
        memcpy(host,p,hlen); host[hlen]=0;
        *port=80;
    }
    if(slash) strcpy(path,slash); else strcpy(path,"/");
}

static http_resp_t http_post(const char *host, int port, const char *path, const char *api_key, const char *body){
    http_resp_t resp={0,NULL,0};
    struct addrinfo hints={0}, *res;
    char portstr[16]; snprintf(portstr,sizeof(portstr),"%d",port);
    hints.ai_family=AF_INET; hints.ai_socktype=SOCK_STREAM;
    if(getaddrinfo(host,portstr,&hints,&res)!=0) return resp;
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    connect(fd,res->ai_addr,res->ai_addrlen);
    freeaddrinfo(res);

    sb_t req; sb_init(&req);
    sb_app_s(&req,"POST ");
    sb_app_s(&req,path);
    sb_app_s(&req," HTTP/1.1\r\n");
    sb_app_s(&req,"Host: "); sb_app_s(&req,host);
    char ps[16]; snprintf(ps,sizeof(ps),":%d",port); sb_app_s(&req,ps);
    sb_app_s(&req,"\r\n");
    sb_app_s(&req,"Content-Type: application/json\r\n");
    sb_app_s(&req,"x-api-key: "); sb_app_s(&req,api_key); sb_app_s(&req,"\r\n");
    sb_app_s(&req,"anthropic-version: 2023-06-01\r\n");
    char cl[32]; snprintf(cl,sizeof(cl),"Content-Length: %zu\r\n",strlen(body));
    sb_app_s(&req,cl);
    sb_app_s(&req,"\r\n");
    sb_app_s(&req,body);
    write(fd,req.d,req.len);
    sb_free(&req);

    /* Read all response */
    size_t rcap=65536, rlen=0;
    char *rb=malloc(rcap);
    while(1){
        if(rlen==rcap){ rcap*=2; rb=realloc(rb,rcap); }
        ssize_t n=read(fd,rb+rlen,rcap-rlen);
        if(n<=0) break;
        rlen+=n;
    }
    close(fd);

    /* Parse headers */
    char *hdr_end=strstr(rb,"\r\n\r\n");
    if(!hdr_end){ resp.body=rb; resp.body_len=rlen; return resp; }
    *hdr_end=0;
    sscanf(rb,"HTTP/%*d.%*d %d",&resp.status);

    /* Find transfer-encoding and content-length */
    int chunked=0;
    long clen=-1;
    char *line=rb;
    while(line&&*line){
        char *nl=strstr(line,"\r\n");
        if(!nl) break;
        *nl=0;
        if(strncasecmp(line,"Transfer-Encoding:",18)==0){
            if(ci_contains(line,"chunked")) chunked=1;
        }
        if(strncasecmp(line,"Content-Length:",15)==0){
            clen=atol(line+15);
        }
        line=nl+2;
    }

    char *body_start=hdr_end+4;
    size_t body_avail=rlen-(size_t)(body_start-rb);

    if(chunked){
        /* Decode chunked body */
        sb_t out; sb_init(&out);
        char *p=body_start;
        char *end=rb+rlen;
        while(p<end){
            /* parse hex size */
            long sz=0;
            while(p<end&&isxdigit((unsigned char)*p)){
                char c=*p; sz=sz*16;
                if(c>='0'&&c<='9') sz+=c-'0';
                else if(c>='a'&&c<='f') sz+=c-'a'+10;
                else sz+=c-'A'+10;
                p++;
            }
            /* skip chunk extension */
            while(p<end&&*p!='\r'&&*p!='\n') p++;
            /* skip CRLF */
            if(p<end&&*p=='\r') p++;
            if(p<end&&*p=='\n') p++;
            if(sz==0) break;
            if(p+sz<=end) sb_app(&out,p,(size_t)sz);
            p+=sz;
            if(p<end&&*p=='\r') p++;
            if(p<end&&*p=='\n') p++;
        }
        resp.body=out.d; resp.body_len=out.len;
        free(rb);
    } else {
        if(clen>=0 && (size_t)clen<=body_avail){
            resp.body=malloc((size_t)clen+1);
            memcpy(resp.body,body_start,(size_t)clen);
            resp.body[clen]=0;
            resp.body_len=(size_t)clen;
        } else {
            resp.body=malloc(body_avail+1);
            memcpy(resp.body,body_start,body_avail);
            resp.body[body_avail]=0;
            resp.body_len=body_avail;
        }
        free(rb);
    }
    return resp;
}

/* ============ SSE Parser ============ */
typedef void (*sse_cb_t)(const char *event, const char *data, void *ctx);

static void parse_sse(const char *body, size_t len, sse_cb_t cb, void *ctx){
    sb_t event_name; sb_init(&event_name);
    sb_t data_buf; sb_init(&data_buf);
    int have_data=0;
    size_t i=0;
    while(i<len){
        /* Read one line */
        size_t start=i;
        while(i<len && body[i]!='\n') i++;
        size_t line_end=i;
        if(i<len) i++; /* skip \n */
        /* Strip trailing \r */
        if(line_end>start && body[line_end-1]=='\r') line_end--;
        size_t line_len=line_end-start;

        if(line_len==0){
            /* Blank line: dispatch event */
            if(have_data||event_name.len>0){
                cb(event_name.len?event_name.d:"", data_buf.d?data_buf.d:"", ctx);
            }
            event_name.len=0; event_name.d[0]=0;
            data_buf.len=0; data_buf.d[0]=0;
            have_data=0;
        } else if(body[start]==':'){
            /* Comment, ignore */
        } else if(line_len>=6 && strncmp(body+start,"event:",6)==0){
            const char *v=body+start+6;
            size_t vl=line_len-6;
            if(vl>0&&*v==' '){ v++; vl--; }
            event_name.len=0;
            sb_app(&event_name,v,vl);
        } else if(line_len>=5 && strncmp(body+start,"data:",5)==0){
            const char *v=body+start+5;
            size_t vl=line_len-5;
            if(vl>0&&*v==' '){ v++; vl--; }
            if(have_data) sb_app_c(&data_buf,'\n');
            sb_app(&data_buf,v,vl);
            have_data=1;
        }
    }
    sb_free(&event_name);
    sb_free(&data_buf);
}

/* ============ Content Blocks ============ */
typedef struct {
    int type; /* 0=thinking, 1=text, 2=tool_use */
    sb_t thinking;
    sb_t signature;
    sb_t text;
    char *id;
    char *name;
    sb_t input_json;
} cblock_t;

typedef struct {
    cblock_t *blocks;
    int nblocks, cap_blocks;
    int stop_reason_set;
    char stop_reason[64];
    int input_tokens;
    int output_tokens;
    int cache_read;
} resp_data_t;

static void resp_init(resp_data_t *r){ memset(r,0,sizeof(*r)); }
static void resp_free(resp_data_t *r){
    for(int i=0;i<r->nblocks;i++){
        cblock_t *b=&r->blocks[i];
        sb_free(&b->thinking); sb_free(&b->signature); sb_free(&b->text); sb_free(&b->input_json);
        free(b->id); free(b->name);
    }
    free(r->blocks);
}

static cblock_t *get_block(resp_data_t *r, int idx){
    while(r->nblocks<=idx){
        if(r->nblocks==r->cap_blocks){ r->cap_blocks=r->cap_blocks?r->cap_blocks*2:8; r->blocks=realloc(r->blocks,r->cap_blocks*sizeof(cblock_t)); }
        cblock_t *b=&r->blocks[r->nblocks];
        memset(b,0,sizeof(*b));
        sb_init(&b->thinking); sb_init(&b->signature); sb_init(&b->text); sb_init(&b->input_json);
        r->nblocks++;
    }
    return &r->blocks[idx];
}

static void sse_handler(const char *event, const char *data, void *ctx){
    resp_data_t *r=(resp_data_t*)ctx;
    if(!data||!data[0]) return;
    const char *p=data;
    jv_t *ev=jparse(&p);
    if(!ev) return;

    if(strcmp(event,"message_start")==0){
        jv_t *msg=jv_obj_get(ev,"message");
        jv_t *usage=jv_obj_get(msg,"usage");
        if(usage){
            jv_t *it=jv_obj_get(usage,"input_tokens");
            if(it) r->input_tokens=jv_int(it);
            jv_t *cr=jv_obj_get(usage,"cache_read_input_tokens");
            if(cr) r->cache_read=jv_int(cr);
        }
    } else if(strcmp(event,"content_block_start")==0){
        jv_t *idx=jv_obj_get(ev,"index");
        int i=idx?jv_int(idx):0;
        jv_t *cb=jv_obj_get(ev,"content_block");
        cblock_t *b=get_block(r,i);
        const char *type=jv_str(jv_obj_get(cb,"type"));
        if(strcmp(type,"thinking")==0) b->type=0;
        else if(strcmp(type,"text")==0) b->type=1;
        else if(strcmp(type,"tool_use")==0){
            b->type=2;
            b->id=strdup(jv_str(jv_obj_get(cb,"id")));
            b->name=strdup(jv_str(jv_obj_get(cb,"name")));
        }
    } else if(strcmp(event,"content_block_delta")==0){
        jv_t *idx=jv_obj_get(ev,"index");
        int i=idx?jv_int(idx):0;
        jv_t *delta=jv_obj_get(ev,"delta");
        const char *dtype=jv_str(jv_obj_get(delta,"type"));
        cblock_t *b=get_block(r,i);
        if(strcmp(dtype,"thinking_delta")==0){
            sb_app_s(&b->thinking,jv_str(jv_obj_get(delta,"thinking")));
        } else if(strcmp(dtype,"signature_delta")==0){
            sb_app_s(&b->signature,jv_str(jv_obj_get(delta,"signature")));
        } else if(strcmp(dtype,"text_delta")==0){
            sb_app_s(&b->text,jv_str(jv_obj_get(delta,"text")));
        } else if(strcmp(dtype,"input_json_delta")==0){
            sb_app_s(&b->input_json,jv_str(jv_obj_get(delta,"partial_json")));
        }
    } else if(strcmp(event,"message_delta")==0){
        jv_t *delta=jv_obj_get(ev,"delta");
        if(delta){
            const char *sr=jv_str(jv_obj_get(delta,"stop_reason"));
            if(sr&&sr[0]){ strncpy(r->stop_reason,sr,63); r->stop_reason[63]=0; r->stop_reason_set=1; }
        }
        jv_t *usage=jv_obj_get(ev,"usage");
        if(usage){
            jv_t *ot=jv_obj_get(usage,"output_tokens");
            if(ot) r->output_tokens=jv_int(ot);
        }
    }
    jv_free(ev);
}

/* ============ Output ============ */
static void print_escaped(const char *s){
    for(const char *p=s; *p; p++){
        unsigned char c=(unsigned char)*p;
        if(c=='\\') printf("\\\\");
        else if(c=='\n') printf("\\n");
        else if(c=='\r') printf("\\r");
        else if(c=='\t') printf("\\t");
        else putchar(c);
    }
}

/* ============ Tool Execution ============ */
static char *execute_tool(const char *name, jv_t *input, int *is_error){
    *is_error=0;
    if(strcmp(name,"measure")==0){
        jv_t *text_v=jv_obj_get(input,"text");
        jv_t *unit_v=jv_obj_get(input,"unit");
        if(!text_v||text_v->t!=JSTR||!unit_v||unit_v->t!=JSTR){
            *is_error=1; return strdup("unknown tool: measure");
        }
        const char *text=text_v->str;
        const char *unit=unit_v->str;
        if(strcmp(unit,"code_points")==0){
            char buf[32]; snprintf(buf,sizeof(buf),"%d",count_codepoints(text)); return strdup(buf);
        } else if(strcmp(unit,"utf8_bytes")==0){
            char buf[32]; snprintf(buf,sizeof(buf),"%zu",strlen(text)); return strdup(buf);
        } else if(strcmp(unit,"utf16_units")==0){
            char buf[32]; snprintf(buf,sizeof(buf),"%d",count_utf16_units(text)); return strdup(buf);
        } else {
            *is_error=1;
            char buf[256]; snprintf(buf,sizeof(buf),"unsupported unit: %s",unit); return strdup(buf);
        }
    } else if(strcmp(name,"reverse")==0){
        jv_t *text_v=jv_obj_get(input,"text");
        if(!text_v||text_v->t!=JSTR){
            *is_error=1; return strdup("unknown tool: reverse");
        }
        return reverse_utf8(text_v->str);
    } else {
        *is_error=1;
        char buf[256]; snprintf(buf,sizeof(buf),"unknown tool: %s",name); return strdup(buf);
    }
}

/* ============ Main ============ */
int main(int argc, char **argv){
    if(argc<3){ fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]); return 1; }
    const char *data_dir=argv[1];
    const char *base_url=argv[2];

    /* Parse URL */
    char host[256]={0}, path[512]={0}; int port=80;
    parse_url(base_url,host,&port,path);
    char req_path[512];
    snprintf(req_path,sizeof(req_path),"%s/v1/messages",path);

    /* Read request.json */
    char rpath[512];
    snprintf(rpath,sizeof(rpath),"%s/request.json",data_dir);
    size_t flen;
    char *fdata=read_file(rpath,&flen);
    if(!fdata){ fprintf(stderr,"Cannot read %s\n",rpath); return 1; }
    const char *fp=fdata;
    jv_t *req=jparse(&fp);

    jv_t *j_api_key=jv_obj_get(req,"api_key");
    jv_t *j_model=jv_obj_get(req,"model");
    jv_t *j_max_tokens=jv_obj_get(req,"max_tokens");
    jv_t *j_thinking_budget=jv_obj_get(req,"thinking_budget");
    jv_t *j_system=jv_obj_get(req,"system");
    jv_t *j_prompt=jv_obj_get(req,"prompt");
    jv_t *j_tools=jv_obj_get(req,"tools");

    const char *api_key=jv_str(j_api_key);

    /* Build request 1 body */
    sb_t body1; sb_init(&body1);
    sb_app_s(&body1,"{\"model\":");
    jser(&body1,j_model);
    sb_app_s(&body1,",\"max_tokens\":");
    jser(&body1,j_max_tokens);
    sb_app_s(&body1,",\"stream\":true");
    sb_app_s(&body1,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    jser(&body1,j_thinking_budget);
    sb_app_s(&body1,"}");
    sb_app_s(&body1,",\"system\":");
    jser(&body1,j_system);
    sb_app_s(&body1,",\"tools\":");
    jser(&body1,j_tools);
    sb_app_s(&body1,",\"messages\":[{\"role\":\"user\",\"content\":");
    jser(&body1,j_prompt);
    sb_app_s(&body1,"}]}");

    printf("request 1\n");
    fflush(stdout);

    /* Send request 1 */
    http_resp_t resp1=http_post(host,port,req_path,api_key,body1.d);
    if(resp1.status!=200){
        const char *ep=resp1.body;
        jv_t *err=jparse(&ep);
        jv_t *err_obj=jv_obj_get(err,"error");
        const char *etype=jv_str(jv_obj_get(err_obj,"type"));
        const char *emsg=jv_str(jv_obj_get(err_obj,"message"));
        printf("ERROR %d %s: %s\n",resp1.status,etype,emsg);
        fflush(stdout);
        jv_free(err);
        return 0;
    }

    /* Parse SSE response 1 */
    resp_data_t rd1; resp_init(&rd1);
    parse_sse(resp1.body,resp1.body_len,sse_handler,&rd1);

    /* Print blocks */
    for(int i=0;i<rd1.nblocks;i++){
        cblock_t *b=&rd1.blocks[i];
        if(b->type==0){
            printf("thinking "); print_escaped(b->thinking.d); printf("\n");
            printf("signature "); print_escaped(b->signature.d); printf("\n");
        } else if(b->type==1){
            printf("text "); print_escaped(b->text.d); printf("\n");
        } else {
            printf("tool_use "); print_escaped(b->id); printf(" "); print_escaped(b->name); printf(" ");
            print_escaped(b->input_json.d); printf("\n");
        }
    }
    printf("stop_reason %s\n",rd1.stop_reason);
    fflush(stdout);

    /* Execute tools */
    typedef struct { char *id; char *result; int is_error; } tool_result_t;
    tool_result_t *results=NULL;
    int nresults=0, cap_results=0;

    for(int i=0;i<rd1.nblocks;i++){
        cblock_t *b=&rd1.blocks[i];
        if(b->type!=2) continue;
        /* Parse input JSON */
        jv_t *input=NULL;
        if(b->input_json.len>0){
            const char *ip=b->input_json.d;
            input=jparse(&ip);
        }
        int is_err=0;
        char *result=execute_tool(b->name,input,&is_err);
        if(nresults==cap_results){ cap_results=cap_results?cap_results*2:8; results=realloc(results,cap_results*sizeof(tool_result_t)); }
        results[nresults].id=strdup(b->id);
        results[nresults].result=result;
        results[nresults].is_error=is_err;
        nresults++;
        printf("%s ",is_err?"error":"result");
        print_escaped(b->id); printf(" ");
        print_escaped(result); printf("\n");
        jv_free(input);
    }
    fflush(stdout);

    /* Build request 2 */
    sb_t body2; sb_init(&body2);
    sb_app_s(&body2,"{\"model\":");
    jser(&body2,j_model);
    sb_app_s(&body2,",\"max_tokens\":");
    jser(&body2,j_max_tokens);
    sb_app_s(&body2,",\"stream\":true");
    sb_app_s(&body2,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    jser(&body2,j_thinking_budget);
    sb_app_s(&body2,"}");
    sb_app_s(&body2,",\"system\":");
    jser(&body2,j_system);
    sb_app_s(&body2,",\"tools\":");
    jser(&body2,j_tools);
    sb_app_s(&body2,",\"messages\":[");
    /* Message 1: user */
    sb_app_s(&body2,"{\"role\":\"user\",\"content\":");
    jser(&body2,j_prompt);
    sb_app_s(&body2,"}");
    /* Message 2: assistant */
    sb_app_s(&body2,",{\"role\":\"assistant\",\"content\":[");
    for(int i=0;i<rd1.nblocks;i++){
        if(i) sb_app_c(&body2,',');
        cblock_t *b=&rd1.blocks[i];
        if(b->type==0){
            sb_app_s(&body2,"{\"type\":\"thinking\",\"thinking\":");
            jser_str(&body2,b->thinking.d);
            sb_app_s(&body2,",\"signature\":");
            jser_str(&body2,b->signature.d);
            sb_app_c(&body2,'}');
        } else if(b->type==1){
            sb_app_s(&body2,"{\"type\":\"text\",\"text\":");
            jser_str(&body2,b->text.d);
            sb_app_c(&body2,'}');
        } else {
            sb_app_s(&body2,"{\"type\":\"tool_use\",\"id\":");
            jser_str(&body2,b->id);
            sb_app_s(&body2,",\"name\":");
            jser_str(&body2,b->name);
            sb_app_s(&body2,",\"input\":");
            if(b->input_json.len>0){
                const char *ip=b->input_json.d;
                jv_t *inp=jparse(&ip);
                jser(&body2,inp);
                jv_free(inp);
            } else {
                sb_app_s(&body2,"{}");
            }
            sb_app_c(&body2,'}');
        }
    }
    sb_app_s(&body2,"]}");
    /* Message 3: tool results */
    sb_app_s(&body2,",{\"role\":\"user\",\"content\":[");
    for(int i=0;i<nresults;i++){
        if(i) sb_app_c(&body2,',');
        sb_app_s(&body2,"{\"type\":\"tool_result\",\"tool_use_id\":");
        jser_str(&body2,results[i].id);
        sb_app_s(&body2,",\"content\":");
        jser_str(&body2,results[i].result);
        if(results[i].is_error) sb_app_s(&body2,",\"is_error\":true");
        sb_app_c(&body2,'}');
    }
    sb_app_s(&body2,"]}");
    sb_app_s(&body2,"]}");
    sb_app_c(&body2,'}');

    printf("request 2\n");
    fflush(stdout);

    /* Send request 2 */
    http_resp_t resp2=http_post(host,port,req_path,api_key,body2.d);
    if(resp2.status!=200){
        const char *ep=resp2.body;
        jv_t *err=jparse(&ep);
        jv_t *err_obj=jv_obj_get(err,"error");
        const char *etype=jv_str(jv_obj_get(err_obj,"type"));
        const char *emsg=jv_str(jv_obj_get(err_obj,"message"));
        printf("ERROR %d %s: %s\n",resp2.status,etype,emsg);
        fflush(stdout);
        jv_free(err);
        return 0;
    }

    /* Parse SSE response 2 */
    resp_data_t rd2; resp_init(&rd2);
    parse_sse(resp2.body,resp2.body_len,sse_handler,&rd2);

    /* Print blocks */
    for(int i=0;i<rd2.nblocks;i++){
        cblock_t *b=&rd2.blocks[i];
        if(b->type==0){
            printf("thinking "); print_escaped(b->thinking.d); printf("\n");
            printf("signature "); print_escaped(b->signature.d); printf("\n");
        } else if(b->type==1){
            printf("text "); print_escaped(b->text.d); printf("\n");
        } else {
            printf("tool_use "); print_escaped(b->id); printf(" "); print_escaped(b->name); printf(" ");
            print_escaped(b->input_json.d); printf("\n");
        }
    }
    printf("stop_reason %s\n",rd2.stop_reason);

    /* Usage */
    int total_input=rd1.input_tokens+rd2.input_tokens;
    int total_output=rd1.output_tokens+rd2.output_tokens;
    int total_cache=rd1.cache_read+rd2.cache_read;
    printf("usage input=%d output=%d cache_read=%d\n",total_input,total_output,total_cache);
    fflush(stdout);

    /* Cleanup */
    resp_free(&rd1); resp_free(&rd2);
    for(int i=0;i<nresults;i++) free(results[i].id);
    free(results);
    sb_free(&body1); sb_free(&body2);
    free(resp1.body); free(resp2.body);
    free(fdata);
    jv_free(req);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdint.h>
#include <ctype.h>
#include <math.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>

/* ============ String Buffer ============ */
typedef struct { char *d; int len, cap; } sbuf;
static void sb_init(sbuf *s) { s->d = NULL; s->len = 0; s->cap = 0; }
static void sb_grow(sbuf *s, int need) {
    if (s->len + need + 1 > s->cap) {
        int nc = s->cap ? s->cap * 2 : 256;
        while (nc < s->len + need + 1) nc *= 2;
        s->d = realloc(s->d, nc);
        s->cap = nc;
    }
}
static void sb_add(sbuf *s, const char *str, int len) {
    sb_grow(s, len);
    memcpy(s->d + s->len, str, len);
    s->len += len;
    s->d[s->len] = 0;
}
static void sb_puts(sbuf *s, const char *str) { sb_add(s, str, strlen(str)); }
static void sb_putc(sbuf *s, char c) { sb_add(s, &c, 1); }
static void sb_fmt(sbuf *s, const char *fmt, ...) {
    char buf[4096];
    va_list ap; va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n > 0) sb_add(s, buf, n);
}

/* ============ JSON Value ============ */
typedef enum { JNULL, JBOOL, JNUM, JSTR, JARR, JOBJ } jtype;
typedef struct jval {
    jtype type;
    union {
        int bval;
        double num;
        char *str;
        struct { struct jval **items; int count, cap; } arr;
        struct { char **keys; struct jval **vals; int count, cap; } obj;
    };
} jval;

static jval *jnull(void) { jval *v = calloc(1, sizeof(jval)); v->type = JNULL; return v; }
static jval *jstr(const char *s) { jval *v = calloc(1, sizeof(jval)); v->type = JSTR; v->str = strdup(s); return v; }
static jval *jstrn(const char *s, int len) { jval *v = calloc(1, sizeof(jval)); v->type = JSTR; v->str = malloc(len+1); memcpy(v->str,s,len); v->str[len]=0; return v; }
static jval *jnum(double n) { jval *v = calloc(1, sizeof(jval)); v->type = JNUM; v->num = n; return v; }
static jval *jobj_new(void) { jval *v = calloc(1, sizeof(jval)); v->type = JOBJ; return v; }
static jval *jarr_new(void) { jval *v = calloc(1, sizeof(jval)); v->type = JARR; return v; }

static void jobj_put(jval *o, const char *key, jval *val) {
    if (o->obj.count >= o->obj.cap) {
        o->obj.cap = o->obj.cap ? o->obj.cap * 2 : 8;
        o->obj.keys = realloc(o->obj.keys, o->obj.cap * sizeof(char*));
        o->obj.vals = realloc(o->obj.vals, o->obj.cap * sizeof(jval*));
    }
    o->obj.keys[o->obj.count] = strdup(key);
    o->obj.vals[o->obj.count] = val;
    o->obj.count++;
}
static void jarr_push(jval *a, jval *v) {
    if (a->arr.count >= a->arr.cap) {
        a->arr.cap = a->arr.cap ? a->arr.cap * 2 : 8;
        a->arr.items = realloc(a->arr.items, a->arr.cap * sizeof(jval*));
    }
    a->arr.items[a->arr.count++] = v;
}
static jval *jobj_get(jval *o, const char *key) {
    if (!o || o->type != JOBJ) return NULL;
    for (int i = 0; i < o->obj.count; i++)
        if (strcmp(o->obj.keys[i], key) == 0) return o->obj.vals[i];
    return NULL;
}

/* ============ JSON Parser ============ */
static const char *skip_ws(const char *p) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    return p;
}
static const char *parse_value(const char *p, jval **out);
static const char *parse_str(const char *p, char **out) {
    if (*p != '"') return NULL;
    p++;
    sbuf sb; sb_init(&sb);
    while (*p && *p != '"') {
        if (*p == '\\') {
            p++;
            switch (*p) {
                case '"': sb_putc(&sb, '"'); p++; break;
                case '\\': sb_putc(&sb, '\\'); p++; break;
                case '/': sb_putc(&sb, '/'); p++; break;
                case 'b': sb_putc(&sb, '\b'); p++; break;
                case 'f': sb_putc(&sb, '\f'); p++; break;
                case 'n': sb_putc(&sb, '\n'); p++; break;
                case 'r': sb_putc(&sb, '\r'); p++; break;
                case 't': sb_putc(&sb, '\t'); p++; break;
                case 'u': {
                    p++;
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) {
                        cp <<= 4;
                        if (*p >= '0' && *p <= '9') cp += *p - '0';
                        else if (*p >= 'a' && *p <= 'f') cp += *p - 'a' + 10;
                        else if (*p >= 'A' && *p <= 'F') cp += *p - 'A' + 10;
                        p++;
                    }
                    if (cp >= 0xD800 && cp <= 0xDBFF && p[0] == '\\' && p[1] == 'u') {
                        p += 2;
                        unsigned int lo = 0;
                        for (int i = 0; i < 4; i++) {
                            lo <<= 4;
                            if (*p >= '0' && *p <= '9') lo += *p - '0';
                            else if (*p >= 'a' && *p <= 'f') lo += *p - 'a' + 10;
                            else if (*p >= 'A' && *p <= 'F') lo += *p - 'A' + 10;
                            p++;
                        }
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    if (cp < 0x80) sb_putc(&sb, cp);
                    else if (cp < 0x800) { sb_putc(&sb, 0xC0|(cp>>6)); sb_putc(&sb, 0x80|(cp&0x3F)); }
                    else if (cp < 0x10000) { sb_putc(&sb, 0xE0|(cp>>12)); sb_putc(&sb, 0x80|((cp>>6)&0x3F)); sb_putc(&sb, 0x80|(cp&0x3F)); }
                    else { sb_putc(&sb, 0xF0|(cp>>18)); sb_putc(&sb, 0x80|((cp>>12)&0x3F)); sb_putc(&sb, 0x80|((cp>>6)&0x3F)); sb_putc(&sb, 0x80|(cp&0x3F)); }
                    break;
                }
                default: sb_putc(&sb, *p); p++; break;
            }
        } else {
            sb_putc(&sb, *p); p++;
        }
    }
    if (*p == '"') p++;
    *out = sb.d ? sb.d : strdup("");
    return p;
}
static const char *parse_value(const char *p, jval **out) {
    p = skip_ws(p);
    if (*p == '"') {
        char *s; p = parse_str(p, &s);
        *out = jstrn(s, strlen(s)); free(s);
        return p;
    }
    if (*p == '{') {
        p++; *out = jobj_new();
        p = skip_ws(p);
        if (*p == '}') { p++; return p; }
        while (1) {
            p = skip_ws(p);
            char *key; p = parse_str(p, &key);
            p = skip_ws(p); p++; /* colon */
            jval *val; p = parse_value(p, &val);
            jobj_put(*out, key, val); free(key);
            p = skip_ws(p);
            if (*p == ',') { p++; continue; }
            if (*p == '}') { p++; break; }
            break;
        }
        return p;
    }
    if (*p == '[') {
        p++; *out = jarr_new();
        p = skip_ws(p);
        if (*p == ']') { p++; return p; }
        while (1) {
            jval *val; p = parse_value(p, &val);
            jarr_push(*out, val);
            p = skip_ws(p);
            if (*p == ',') { p++; continue; }
            if (*p == ']') { p++; break; }
            break;
        }
        return p;
    }
    if (*p == 't') { *out = calloc(1, sizeof(jval)); (*out)->type = JBOOL; (*out)->bval = 1; return p+4; }
    if (*p == 'f') { *out = calloc(1, sizeof(jval)); (*out)->type = JBOOL; (*out)->bval = 0; return p+5; }
    if (*p == 'n') { *out = jnull(); return p+4; }
    /* number */
    char *end;
    double num = strtod(p, &end);
    *out = jnum(num);
    return end;
}
static jval *json_parse(const char *s) { jval *v = NULL; parse_value(s, &v); return v; }

/* ============ JSON Serializer ============ */
static void json_enc_str(sbuf *s, const char *str) {
    sb_putc(s, '"');
    for (const unsigned char *p = (const unsigned char*)str; *p; p++) {
        unsigned char c = *p;
        if (c == '"') sb_puts(s, "\\\"");
        else if (c == '\\') sb_puts(s, "\\\\");
        else if (c == '\b') sb_puts(s, "\\b");
        else if (c == '\f') sb_puts(s, "\\f");
        else if (c == '\n') sb_puts(s, "\\n");
        else if (c == '\r') sb_puts(s, "\\r");
        else if (c == '\t') sb_puts(s, "\\t");
        else if (c < 0x20) sb_fmt(s, "\\u%04x", c);
        else sb_putc(s, c);
    }
    sb_putc(s, '"');
}
static void json_enc_num(sbuf *s, double num) {
    if (num == floor(num) && fabs(num) < 9e15) {
        long long i = (long long)num;
        char buf[32]; sprintf(buf, "%lld", i);
        sb_puts(s, buf);
    } else {
        char buf[64]; sprintf(buf, "%.17g", num);
        char *dot = strchr(buf, '.');
        if (dot) {
            char *end = buf + strlen(buf) - 1;
            while (end > dot && *end == '0') *end-- = 0;
            if (*end == '.') *end = 0;
        }
        sb_puts(s, buf);
    }
}
static void json_enc(sbuf *s, jval *v) {
    if (!v) { sb_puts(s, "null"); return; }
    switch (v->type) {
        case JNULL: sb_puts(s, "null"); break;
        case JBOOL: sb_puts(s, v->bval ? "true" : "false"); break;
        case JNUM: json_enc_num(s, v->num); break;
        case JSTR: json_enc_str(s, v->str); break;
        case JARR:
            sb_putc(s, '[');
            for (int i = 0; i < v->arr.count; i++) {
                if (i) sb_putc(s, ',');
                json_enc(s, v->arr.items[i]);
            }
            sb_putc(s, ']');
            break;
        case JOBJ:
            sb_putc(s, '{');
            for (int i = 0; i < v->obj.count; i++) {
                if (i) sb_putc(s, ',');
                json_enc_str(s, v->obj.keys[i]);
                sb_putc(s, ':');
                json_enc(s, v->obj.vals[i]);
            }
            sb_putc(s, '}');
            break;
    }
}

/* ============ File I/O ============ */
static char *read_file(const char *path, int *len) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = 0;
    fclose(f);
    if (len) *len = sz;
    return buf;
}

/* ============ CSV Parser ============ */
typedef struct { char *sku, *name, *currency; long long price_cents, stock; } inv_row;
static inv_row *inventory = NULL;
static int inv_count = 0;

static char *csv_field(const char *data, int len, int *pos) {
    sbuf sb; sb_init(&sb);
    if (*pos < len && data[*pos] == '"') {
        (*pos)++;
        while (*pos < len) {
            if (data[*pos] == '"') {
                if (*pos + 1 < len && data[*pos + 1] == '"') {
                    sb_putc(&sb, '"'); *pos += 2;
                } else { (*pos)++; break; }
            } else { sb_putc(&sb, data[*pos]); (*pos)++; }
        }
    } else {
        while (*pos < len && data[*pos] != ',' && data[*pos] != '\r' && data[*pos] != '\n') {
            sb_putc(&sb, data[*pos]); (*pos)++;
        }
    }
    return sb.d ? sb.d : strdup("");
}

static void parse_inventory(const char *path) {
    int len; char *data = read_file(path, &len);
    int pos = 0;
    /* skip BOM */
    if (len >= 3 && (unsigned char)data[0]==0xEF && (unsigned char)data[1]==0xBB && (unsigned char)data[2]==0xBF) pos = 3;
    /* skip header */
    while (pos < len && data[pos] != '\n') pos++;
    if (pos < len) pos++; /* skip \n */
    while (pos < len) {
        char *fields[5]; int nf = 0;
        while (nf < 5) {
            fields[nf] = csv_field(data, len, &pos);
            nf++;
            if (pos < len && data[pos] == ',') { pos++; continue; }
            break;
        }
        /* skip line ending */
        if (pos < len && data[pos] == '\r') pos++;
        if (pos < len && data[pos] == '\n') pos++;
        if (nf < 5) break;
        inventory = realloc(inventory, (inv_count + 1) * sizeof(inv_row));
        inventory[inv_count].sku = fields[0];
        inventory[inv_count].name = fields[1];
        inventory[inv_count].price_cents = atoll(fields[2]);
        inventory[inv_count].currency = fields[3];
        inventory[inv_count].stock = atoll(fields[4]);
        inv_count++;
    }
}

/* ============ Rates ============ */
typedef struct { char *cur; long long rate; } rate_entry;
static rate_entry *rates = NULL;
static int rates_count = 0;
static long long get_rate(const char *cur) {
    for (int i = 0; i < rates_count; i++)
        if (strcmp(rates[i].cur, cur) == 0) return rates[i].rate;
    return 1000000;
}
static void parse_rates(const char *path) {
    int len; char *data = read_file(path, &len);
    jval *root = json_parse(data);
    jval *r = jobj_get(root, "rates");
    if (r && r->type == JOBJ) {
        rates = malloc(r->obj.count * sizeof(rate_entry));
        for (int i = 0; i < r->obj.count; i++) {
            rates[rates_count].cur = strdup(r->obj.keys[i]);
            rates[rates_count].rate = (long long)r->obj.vals[i]->num;
            rates_count++;
        }
    }
}

/* ============ HTTP Client ============ */
typedef struct { int status; char *body; int body_len; } http_resp;

static http_resp http_post(const char *host, int port, const char *path,
                           const char *auth, const char *body, int blen) {
    http_resp resp = {0, NULL, 0};
    char port_str[16]; sprintf(port_str, "%d", port);
    struct addrinfo hints = {0}, *res;
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(host, port_str, &hints, &res) != 0) { resp.status = -1; return resp; }
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) { close(fd); resp.status = -1; return resp; }

    /* Build request */
    sbuf req; sb_init(&req);
    sb_fmt(&req, "POST %s HTTP/1.1\r\n", path);
    sb_fmt(&req, "Host: %s:%s\r\n", host, port_str);
    sb_fmt(&req, "Authorization: Bearer %s\r\n", auth);
    sb_puts(&req, "Content-Type: application/json\r\n");
    sb_fmt(&req, "Content-Length: %d\r\n", blen);
    sb_puts(&req, "Connection: close\r\n");
    sb_puts(&req, "\r\n");
    sb_add(&req, body, blen);

    /* Send */
    int sent = 0;
    while (sent < req.len) {
        int n = write(fd, req.d + sent, req.len - sent);
        if (n <= 0) break;
        sent += n;
    }

    /* Receive */
    int bcap = 65536, blen2 = 0;
    char *buf = malloc(bcap);
    while (1) {
        if (blen2 >= bcap - 1) { bcap *= 2; buf = realloc(buf, bcap); }
        int n = read(fd, buf + blen2, bcap - blen2 - 1);
        if (n <= 0) break;
        blen2 += n;
    }
    close(fd);
    buf[blen2] = 0;

    /* Parse response */
    /* Find end of headers */
    char *hdr_end = NULL;
    for (int i = 0; i < blen2 - 3; i++) {
        if (buf[i]=='\r' && buf[i+1]=='\n' && buf[i+2]=='\r' && buf[i+3]=='\n') {
            hdr_end = buf + i + 4; break;
        }
    }
    if (!hdr_end) {
        for (int i = 0; i < blen2 - 1; i++) {
            if (buf[i]=='\n' && buf[i+1]=='\n') { hdr_end = buf + i + 2; break; }
        }
    }
    if (!hdr_end) { resp.status = -1; free(buf); return resp; }

    /* Parse status line */
    resp.status = atoi(buf + 9);

    /* Parse Content-Length */
    int content_len = -1;
    {
        char *h = buf;
        while (h < hdr_end - 2) {
            char *eol = strstr(h, "\r\n");
            if (!eol || eol >= hdr_end - 2) break;
            if (strncasecmp(h, "Content-Length:", 15) == 0) {
                content_len = atoi(h + 15);
            }
            h = eol + 2;
        }
    }

    int body_off = hdr_end - buf;
    if (content_len >= 0 && content_len <= blen2 - body_off) {
        resp.body = malloc(content_len + 1);
        memcpy(resp.body, hdr_end, content_len);
        resp.body[content_len] = 0;
        resp.body_len = content_len;
    } else {
        resp.body_len = blen2 - body_off;
        resp.body = malloc(resp.body_len + 1);
        memcpy(resp.body, hdr_end, resp.body_len);
        resp.body[resp.body_len] = 0;
    }
    free(buf);
    return resp;
}

/* ============ Tool Execution ============ */
static char *exec_tool(const char *name, const char *args_json) {
    sbuf sb; sb_init(&sb);
    if (strcmp(name, "inventory_lookup") == 0) {
        jval *args = json_parse(args_json);
        jval *sv = jobj_get(args, "sku");
        const char *sku = sv ? sv->str : "";
        for (int i = 0; i < inv_count; i++) {
            if (strcmp(inventory[i].sku, sku) == 0) {
                sb_puts(&sb, "{\"sku\":");
                json_enc_str(&sb, inventory[i].sku);
                sb_puts(&sb, ",\"name\":");
                json_enc_str(&sb, inventory[i].name);
                sb_fmt(&sb, ",\"price_cents\":%lld,\"currency\":", inventory[i].price_cents);
                json_enc_str(&sb, inventory[i].currency);
                sb_fmt(&sb, ",\"stock\":%lld}", inventory[i].stock);
                return sb.d;
            }
        }
        sb_puts(&sb, "{\"error\":\"unknown sku: ");
        json_enc_str(&sb, sku);
        sb_puts(&sb, "\"}");
        /* remove the extra quote we added */
        /* Actually let me redo this properly */
        sb_init(&sb);
        sb_puts(&sb, "{\"error\":");
        { sbuf msg; sb_init(&msg); sb_puts(&msg, "unknown sku: "); sb_puts(&msg, sku); json_enc_str(&sb, msg.d); }
        sb_putc(&sb, '}');
        return sb.d;
    } else if (strcmp(name, "convert_currency") == 0) {
        jval *args = json_parse(args_json);
        long long amount = (long long)jobj_get(args, "amount_cents")->num;
        const char *from = jobj_get(args, "from")->str;
        const char *to = jobj_get(args, "to")->str;
        long long rf = get_rate(from);
        long long rt = get_rate(to);
        long long result = (2 * amount * rt + rf) / (2 * rf);
        sb_puts(&sb, "{\"amount_cents\":");
        sb_fmt(&sb, "%lld", result);
        sb_puts(&sb, ",\"currency\":");
        json_enc_str(&sb, to);
        sb_putc(&sb, '}');
        return sb.d;
    } else {
        sb_puts(&sb, "{\"error\":");
        { sbuf msg; sb_init(&msg); sb_puts(&msg, "unknown tool: "); sb_puts(&msg, name); json_enc_str(&sb, msg.d); }
        sb_putc(&sb, '}');
        return sb.d;
    }
}

/* ============ Main ============ */
int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "Usage: %s <data_dir> <base_url>\n", argv[0]); return 1; }
    const char *data_dir = argv[1];
    const char *base_url = argv[2];

    /* Parse base_url: http://host:port/path */
    char host[256] = "", path[512] = "";
    int port = 80;
    {
        const char *p = base_url;
        if (strncmp(p, "http://", 7) == 0) p += 7;
        const char *slash = strchr(p, '/');
        const char *colon = strchr(p, ':');
        if (colon && (!slash || colon < slash)) {
            int hlen = colon - p;
            memcpy(host, p, hlen); host[hlen] = 0;
            port = atoi(colon + 1);
        } else {
            int hlen = slash ? slash - p : (int)strlen(p);
            memcpy(host, p, hlen); host[hlen] = 0;
        }
        if (slash) {
            strcpy(path, slash);
        } else {
            path[0] = '/'; path[1] = 0;
        }
        strcat(path, "/chat/completions");
    }

    /* Read task.json */
    char tpath[1024];
    sprintf(tpath, "%s/task.json", data_dir);
    int tlen; char *tdata = read_file(tpath, &tlen);
    jval *task = json_parse(tdata);
    const char *api_key = jobj_get(task, "api_key")->str;
    const char *model = jobj_get(task, "model")->str;
    const char *system_text = jobj_get(task, "system")->str;
    const char *user_text = jobj_get(task, "user")->str;
    jval *tools = jobj_get(task, "tools");

    /* Read inventory */
    sprintf(tpath, "%s/inventory.csv", data_dir);
    parse_inventory(tpath);

    /* Read rates */
    sprintf(tpath, "%s/rates.json", data_dir);
    parse_rates(tpath);

    /* Build conversation */
    jval *messages = jarr_new();
    {
        jval *m = jobj_new();
        jobj_put(m, "role", jstr("system"));
        jobj_put(m, "content", jstr(system_text));
        jarr_push(messages, m);
    }
    {
        jval *m = jobj_new();
        jobj_put(m, "role", jstr("user"));
        jobj_put(m, "content", jstr(user_text));
        jarr_push(messages, m);
    }

    int total_prompt = 0, total_completion = 0, total_total = 0;
    int num_requests = 0;

    /* Main loop */
    while (1) {
        /* Build request */
        jval *req = jobj_new();
        jobj_put(req, "model", jstr(model));
        jobj_put(req, "messages", messages);
        jobj_put(req, "tools", tools);
        jobj_put(req, "tool_choice", jstr("auto"));

        sbuf body; sb_init(&body);
        json_enc(&body, req);

        /* Send request */
        http_resp resp = http_post(host, port, path, api_key, body.d, body.len);
        num_requests++;

        if (resp.status != 200) {
            /* Print error */
            jval *err = resp.body ? json_parse(resp.body) : NULL;
            jval *err_obj = err ? jobj_get(err, "error") : NULL;
            jval *err_msg = err_obj ? jobj_get(err_obj, "message") : NULL;
            printf("ERROR %d %s\n", resp.status, err_msg ? err_msg->str : "");
            printf("USAGE prompt=%d completion=%d total=%d requests=%d\n",
                   total_prompt, total_completion, total_total, num_requests);
            return 0;
        }

        /* Parse response */
        jval *resp_json = json_parse(resp.body);

        /* Usage */
        jval *usage = jobj_get(resp_json, "usage");
        if (usage) {
            jval *pt = jobj_get(usage, "prompt_tokens");
            jval *ct = jobj_get(usage, "completion_tokens");
            jval *tt = jobj_get(usage, "total_tokens");
            if (pt) total_prompt += (int)pt->num;
            if (ct) total_completion += (int)ct->num;
            if (tt) total_total += (int)tt->num;
        }

        /* Choices */
        jval *choices = jobj_get(resp_json, "choices");
        jval *choice = choices->arr.items[0];
        jval *message = jobj_get(choice, "message");
        jval *fr = jobj_get(choice, "finish_reason");
        const char *finish = fr ? fr->str : "stop";

        if (strcmp(finish, "tool_calls") == 0) {
            jval *content = jobj_get(message, "content");
            if (content && content->type == JSTR) {
                printf("SAY %s\n", content->str);
            }

            jval *tool_calls = jobj_get(message, "tool_calls");
            int n = tool_calls->arr.count;

            /* Print CALL lines */
            for (int i = 0; i < n; i++) {
                jval *tc = tool_calls->arr.items[i];
                jval *id = jobj_get(tc, "id");
                jval *func = jobj_get(tc, "function");
                jval *name = jobj_get(func, "name");
                printf("CALL %s %s\n", id->str, name->str);
            }

            /* Build assistant message and add to conversation */
            jval *asst = jobj_new();
            jobj_put(asst, "role", jstr("assistant"));
            if (content && content->type == JSTR)
                jobj_put(asst, "content", jstr(content->str));
            else
                jobj_put(asst, "content", jnull());
            jobj_put(asst, "tool_calls", tool_calls);
            jarr_push(messages, asst);

            /* Execute tools and print RESULT lines */
            for (int i = 0; i < n; i++) {
                jval *tc = tool_calls->arr.items[i];
                jval *id = jobj_get(tc, "id");
                jval *func = jobj_get(tc, "function");
                jval *name = jobj_get(func, "name");
                jval *args_str = jobj_get(func, "arguments");
                const char *args_json = args_str ? args_str->str : "{}";
                char *result = exec_tool(name->str, args_json);
                printf("RESULT %s %s\n", id->str, result);

                /* Add tool result message */
                jval *tm = jobj_new();
                jobj_put(tm, "role", jstr("tool"));
                jobj_put(tm, "tool_call_id", jstr(id->str));
                jobj_put(tm, "content", jstr(result));
                jarr_push(messages, tm);
            }
        } else {
            /* stop */
            jval *content = jobj_get(message, "content");
            printf("FINAL %s\n", (content && content->type == JSTR) ? content->str : "");
            break;
        }
    }

    printf("USAGE prompt=%d completion=%d total=%d requests=%d\n",
           total_prompt, total_completion, total_total, num_requests);
    return 0;
}

