var rates: [String: Int] = [:]
for (key, value) in ratesDict {
    rates[key] = (value as! NSNumber).intValue
}

// MARK: - Tool Execution
func executeTool(name: String, arguments: String) -> String {
    guard let argsData = arguments.data(using: .utf8),
          let argsObj = (try? JSONSerialization.jsonObject(with: argsData)) as? [String: Any] else {
        return "{\"error\":\"unknown tool: \(escapeJSONString(name))\"}"
    }

    if name == "inventory_lookup" {
        let sku = argsObj["sku"] as! String
        if let item = inventory[sku] {
            return "{\"sku\":\"\(escapeJSONString(sku))\",\"name\":\"\(escapeJSONString(item.name))\",\"price_cents\":\(item.priceCents),\"currency\":\"\(escapeJSONString(item.currency))\",\"stock\":\(item.stock)}"
        } else {
            return "{\"error\":\"unknown sku: \(escapeJSONString(sku))\"}"
        }
    } else if name == "convert_currency" {
        let amountCents = (argsObj["amount_cents"] as! NSNumber).intValue
        let from = argsObj["from"] as! String
        let to = argsObj["to"] as! String
        let rateFrom = rates[from]!
        let rateTo = rates[to]!
        let converted = (2 * amountCents * rateTo + rateFrom) / (2 * rateFrom)
        return "{\"amount_cents\":\(converted),\"currency\":\"\(escapeJSONString(to))\"}"
    } else {
        return "{\"error\":\"unknown tool: \(escapeJSONString(name))\"}"
    }
}

// MARK: - HTTP Request
func makeRequest(url: URL, body: Data, apiKey: String) -> (Int, Data) {
    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.httpBody = body

    let semaphore = DispatchSemaphore(value: 0)
    var statusCode = 0
    var responseData = Data()

    let session = URLSession(configuration: URLSessionConfiguration.default)
    let sessionTask = session.dataTask(with: request) { data, response, error in
        if let httpResponse = response as? HTTPURLResponse {
            statusCode = httpResponse.statusCode
        }
        if let data = data {
            responseData = data
        }
        semaphore.signal()
    }
    sessionTask.resume()
    semaphore.wait()

    return (statusCode, responseData)
}

// MARK: - Main Loop
var messages: [[String: Any]] = [
    ["role": "system", "content": systemMsg],
    ["role": "user", "content": userMsg]
]

var totalPrompt = 0
var totalCompletion = 0
var totalTotal = 0
var requestCount = 0
var outputLines: [String] = []

let url = URL(string: baseUrl + "/chat/completions")!

while true {
    let body: [String: Any] = [
        "model": model,
        "messages": messages,
        "tools": tools,
        "tool_choice": "auto"
    ]

    let bodyData = try! JSONSerialization.data(withJSONObject: body)
    let (statusCode, responseData) = makeRequest(url: url, body: bodyData, apiKey: apiKey)
    requestCount += 1

    if statusCode != 200 {
        for line in outputLines {
            print(line)
        }
        var errorMsg = ""
        if let errorJSON = (try? JSONSerialization.jsonObject(with: responseData)) as? [String: Any],
           let errorObj = errorJSON["error"] as? [String: Any],
           let msg = errorObj["message"] as? String {
            errorMsg = msg
        }
        print("ERROR \(statusCode) \(errorMsg)")
        exit(0)
    }

    let response = try! JSONSerialization.jsonObject(with: responseData) as! [String: Any]

    // Accumulate usage
    if let usage = response["usage"] as? [String: Any] {
        totalPrompt += (usage["prompt_tokens"] as! NSNumber).intValue
        totalCompletion += (usage["completion_tokens"] as! NSNumber).intValue
        totalTotal += (usage["total_tokens"] as! NSNumber).intValue
    }

    let choices = response["choices"] as! [[String: Any]]
    let choice = choices[0]
    let finishReason = choice["finish_reason"] as! String
    let message = choice["message"] as! [String: Any]

    if finishReason == "tool_calls" {
        let content = message["content"]
        let contentStr = content as? String

        if let cs = contentStr {
            outputLines.append("SAY \(cs)")
        }

        let toolCalls = message["tool_calls"] as! [[String: Any]]

        // Build assistant message to append to conversation
        var assistantMsg: [String: Any] = ["role": "assistant"]
        if contentStr != nil {
            assistantMsg["content"] = contentStr!
        } else {
            assistantMsg["content"] = NSNull()
        }
        assistantMsg["tool_calls"] = toolCalls
        messages.append(assistantMsg)

        // Print CALL lines and execute tools
        for tc in toolCalls {
            let id = tc["id"] as! String
            let funcObj = tc["function"] as! [String: Any]
            let name = funcObj["name"] as! String
            outputLines.append("CALL \(id) \(name)")
        }

        for tc in toolCalls {
            let id = tc["id"] as! String
            let funcObj = tc["function"] as! [String: Any]
            let name = funcObj["name"] as! String
            let arguments = funcObj["arguments"] as! String

            let result = executeTool(name: name, arguments: arguments)
            outputLines.append("RESULT \(id) \(result)")

            messages.append(["role": "tool", "tool_call_id": id, "content": result])
        }
    } else {
        // finish_reason == "stop"
        let content = message["content"] as? String ?? ""
        outputLines.append("FINAL \(content)")

        for line in outputLines {
            print(line)
        }
        print("USAGE prompt=\(totalPrompt) completion=\(totalCompletion) total=\(totalTotal) requests=\(requestCount)")
        exit(0)
    }
}

import java.io.*;
import java.math.BigInteger;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    static String jsonStr;
    static int jsonPos;

    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // Read task.json
        byte[] taskBytes = Files.readAllBytes(Paths.get(dataDir, "task.json"));
        String taskContent = new String(taskBytes, StandardCharsets.UTF_8);
        if (taskContent.startsWith("\uFEFF")) taskContent = taskContent.substring(1);
        @SuppressWarnings("unchecked")
        Map<String, Object> task = (Map<String, Object>) parseJson(taskContent);

        String apiKey = (String) task.get("api_key");
        String model = (String) task.get("model");
        String systemMsg = (String) task.get("system");
        String userMsg = (String) task.get("user");
        @SuppressWarnings("unchecked")
        List<Object> tools = (List<Object>) task.get("tools");

        // Read inventory.csv
        byte[] csvBytes = Files.readAllBytes(Paths.get(dataDir, "inventory.csv"));
        int start = 0;
        if (csvBytes.length >= 3 && (csvBytes[0] & 0xFF) == 0xEF && (csvBytes[1] & 0xFF) == 0xBB && (csvBytes[2] & 0xFF) == 0xBF) {
            start = 3;
        }
        String csvContent = new String(csvBytes, start, csvBytes.length - start, StandardCharsets.UTF_8);
        List<String[]> inventory = parseCsv(csvContent);
        Map<String, String[]> skuMap = new HashMap<>();
        for (int i = 1; i < inventory.size(); i++) {
            String[] row = inventory.get(i);
            if (row.length >= 5) {
                skuMap.put(row[0], row);
            }
        }

        // Read rates.json
        byte[] ratesBytes = Files.readAllBytes(Paths.get(dataDir, "rates.json"));
        String ratesContent = new String(ratesBytes, StandardCharsets.UTF_8);
        if (ratesContent.startsWith("\uFEFF")) ratesContent = ratesContent.substring(1);
        @SuppressWarnings("unchecked")
        Map<String, Object> ratesData = (Map<String, Object>) parseJson(ratesContent);
        @SuppressWarnings("unchecked")
        Map<String, Object> rates = (Map<String, Object>) ratesData.get("rates");

        // Build conversation
        List<Object> messages = new ArrayList<>();
        Map<String, Object> sysMsg = new LinkedHashMap<>();
        sysMsg.put("role", "system");
        sysMsg.put("content", systemMsg);
        messages.add(sysMsg);

        Map<String, Object> usrMsg = new LinkedHashMap<>();
        usrMsg.put("role", "user");
        usrMsg.put("content", userMsg);
        messages.add(usrMsg);

        long totalPrompt = 0, totalCompletion = 0, totalTotal = 0;
        int numRequests = 0;
        StringBuilder output = new StringBuilder();

        while (true) {
            Map<String, Object> requestBody = new LinkedHashMap<>();
            requestBody.put("model", model);
            requestBody.put("messages", messages);
            requestBody.put("tools", tools);
            requestBody.put("tool_choice", "auto");

            String body = serializeJson(requestBody);

            int[] statusHolder = new int[1];
            String responseBody = sendPost(baseUrl, apiKey, body, statusHolder);
            int status = statusHolder[0];
            numRequests++;

            if (status != 200) {
                if (responseBody.startsWith("\uFEFF")) responseBody = responseBody.substring(1);
                @SuppressWarnings("unchecked")
                Map<String, Object> errBody = (Map<String, Object>) parseJson(responseBody);
                @SuppressWarnings("unchecked")
                Map<String, Object> error = (Map<String, Object>) errBody.get("error");
                String errMsg = (String) error.get("message");
                System.out.print(output.toString());
                System.out.println("ERROR " + status + " " + errMsg);
                return;
            }

            if (responseBody.startsWith("\uFEFF")) responseBody = responseBody.substring(1);
            @SuppressWarnings("unchecked")
            Map<String, Object> resp = (Map<String, Object>) parseJson(responseBody);

            @SuppressWarnings("unchecked")
            Map<String, Object> usage = (Map<String, Object>) resp.get("usage");
            if (usage != null) {
                totalPrompt += ((Number) usage.get("prompt_tokens")).longValue();
                totalCompletion += ((Number) usage.get("completion_tokens")).longValue();
                totalTotal += ((Number) usage.get("total_tokens")).longValue();
            }

            @SuppressWarnings("unchecked")
            List<Object> choices = (List<Object>) resp.get("choices");
            @SuppressWarnings("unchecked")
            Map<String, Object> choice = (Map<String, Object>) choices.get(0);
            String finishReason = (String) choice.get("finish_reason");
            @SuppressWarnings("unchecked")
            Map<String, Object> message = (Map<String, Object>) choice.get("message");

            if ("tool_calls".equals(finishReason)) {
                Object content = message.get("content");
                if (content != null) {
                    output.append("SAY ").append(content).append("\n");
                }

                @SuppressWarnings("unchecked")
                List<Object> toolCalls = (List<Object>) message.get("tool_calls");

                for (Object tc : toolCalls) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> tcMap = (Map<String, Object>) tc;
                    String id = (String) tcMap.get("id");
                    @SuppressWarnings("unchecked")
                    Map<String, Object> func = (Map<String, Object>) tcMap.get("function");
                    String name = (String) func.get("name");
                    output.append("CALL ").append(id).append(" ").append(name).append("\n");
                }

                // Append assistant message
                Map<String, Object> assistantMsg = new LinkedHashMap<>();
                assistantMsg.put("role", "assistant");
                assistantMsg.put("content", content);
                List<Object> tcList = new ArrayList<>();
                for (Object tc : toolCalls) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> tcMap = (Map<String, Object>) tc;
                    Map<String, Object> newTc = new LinkedHashMap<>();
                    newTc.put("id", tcMap.get("id"));
                    newTc.put("type", tcMap.get("type"));
                    @SuppressWarnings("unchecked")
                    Map<String, Object> func = (Map<String, Object>) tcMap.get("function");
                    Map<String, Object> newFunc = new LinkedHashMap<>();
                    newFunc.put("name", func.get("name"));
                    newFunc.put("arguments", func.get("arguments"));
                    newTc.put("function", newFunc);
                    tcList.add(newTc);
                }
                assistantMsg.put("tool_calls", tcList);
                messages.add(assistantMsg);

                // Execute tool calls
                for (Object tc : toolCalls) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> tcMap = (Map<String, Object>) tc;
                    String id = (String) tcMap.get("id");
                    @SuppressWarnings("unchecked")
                    Map<String, Object> func = (Map<String, Object>) tcMap.get("function");
                    String name = (String) func.get("name");
                    String arguments = (String) func.get("arguments");

                    String result = executeTool(name, arguments, skuMap, rates);
                    output.append("RESULT ").append(id).append(" ").append(result).append("\n");

                    Map<String, Object> toolMsg = new LinkedHashMap<>();
                    toolMsg.put("role", "tool");
                    toolMsg.put("tool_call_id", id);
                    toolMsg.put("content", result);
                    messages.add(toolMsg);
                }

            } else {
                String content = (String) message.get("content");
                output.append("FINAL ").append(content != null ? content : "").append("\n");
                break;
            }
        }

        System.out.print(output.toString());
        System.out.println("USAGE prompt=" + totalPrompt + " completion=" + totalCompletion + " total=" + totalTotal + " requests=" + numRequests);
    }

    static String executeTool(String name, String arguments, Map<String, String[]> skuMap, Map<String, Object> rates) {
        if ("inventory_lookup".equals(name)) {
            @SuppressWarnings("unchecked")
            Map<String, Object> args = (Map<String, Object>) parseJson(arguments);
            String sku = (String) args.get("sku");
            String[] row = skuMap.get(sku);
            if (row == null) {
                Map<String, Object> result = new LinkedHashMap<>();
                result.put("error", "unknown sku: " + sku);
                return serializeJson(result);
            }
            Map<String, Object> result = new LinkedHashMap<>();
            result.put("sku", row[0]);
            result.put("name", row[1]);
            result.put("price_cents", Long.parseLong(row[2]));
            result.put("currency", row[3]);
            result.put("stock", Long.parseLong(row[4]));
            return serializeJson(result);
        } else if ("convert_currency".equals(name)) {
            @SuppressWarnings("unchecked")
            Map<String, Object> args = (Map<String, Object>) parseJson(arguments);
            long amountCents = ((Number) args.get("amount_cents")).longValue();
            String from = (String) args.get("from");
            String to = (String) args.get("to");

            long rateFrom = ((Number) rates.get(from)).longValue();
            long rateTo = ((Number) rates.get(to)).longValue();

            BigInteger two = BigInteger.valueOf(2);
            BigInteger amount = BigInteger.valueOf(amountCents);
            BigInteger rTo = BigInteger.valueOf(rateTo);
            BigInteger rFrom = BigInteger.valueOf(rateFrom);

            BigInteger numerator = two.multiply(amount).multiply(rTo).add(rFrom);
            BigInteger denominator = two.multiply(rFrom);
            long converted = numerator.divide(denominator).longValue();

            Map<String, Object> result = new LinkedHashMap<>();
            result.put("amount_cents", converted);
            result.put("currency", to);
            return serializeJson(result);
        } else {
            Map<String, Object> result = new LinkedHashMap<>();
            result.put("error", "unknown tool: " + name);
            return serializeJson(result);
        }
    }

    // ==================== JSON Parser ====================

    static Object parseJson(String s) {
        jsonStr = s;
        jsonPos = 0;
        skipWs();
        Object result = parseValue();
        return result;
    }

    static void skipWs() {
        while (jsonPos < jsonStr.length()) {
            char c = jsonStr.charAt(jsonPos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                jsonPos++;
            } else {
                break;
            }
        }
    }

    static Object parseValue() {
        skipWs();
        char c = jsonStr.charAt(jsonPos);
        switch (c) {
            case '{': return parseObject();
            case '[': return parseArray();
            case '"': return parseString();
            case 't': jsonPos += 4; return Boolean.TRUE;
            case 'f': jsonPos += 5; return Boolean.FALSE;
            case 'n': jsonPos += 4; return null;
            default: return parseNumber();
        }
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        jsonPos++; // skip {
        skipWs();
        if (jsonPos < jsonStr.length() && jsonStr.charAt(jsonPos) == '}') { jsonPos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            jsonPos++; // skip :
            Object value = parseValue();
            map.put(key, value);
            skipWs();
            char c = jsonStr.charAt(jsonPos);
            if (c == '}') { jsonPos++; break; }
            if (c == ',') { jsonPos++; }
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        jsonPos++; // skip [
        skipWs();
        if (jsonPos < jsonStr.length() && jsonStr.charAt(jsonPos) == ']') { jsonPos++; return list; }
        while (true) {
            list.add(parseValue());
            skipWs();
            char c = jsonStr.charAt(jsonPos);
            if (c == ']') { jsonPos++; break; }
            if (c == ',') { jsonPos++; }
        }
        return list;
    }

    static String parseString() {
        jsonPos++; // skip opening "
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = jsonStr.charAt(jsonPos);
            if (c == '"') { jsonPos++; break; }
            if (c == '\\') {
                jsonPos++;
                char e = jsonStr.charAt(jsonPos);
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u': {
                        int cp = Integer.parseInt(jsonStr.substring(jsonPos + 1, jsonPos + 5), 16);
                        jsonPos += 4;
                        if (Character.isHighSurrogate((char) cp) && jsonPos + 1 < jsonStr.length()
                                && jsonStr.charAt(jsonPos + 1) == '\\' && jsonPos + 2 < jsonStr.length()
                                && jsonStr.charAt(jsonPos + 2) == 'u') {
                            jsonPos += 2; // skip \u
                            int cp2 = Integer.parseInt(jsonStr.substring(jsonPos + 1, jsonPos + 5), 16);
                            jsonPos += 4;
                            sb.append((char) cp);
                            sb.append((char) cp2);
                        } else {
                            sb.append((char) cp);
                        }
                        break;
                    }
                    default: sb.append(e); break;
                }
                jsonPos++;
            } else {
                sb.append(c);
                jsonPos++;
            }
        }
        return sb.toString();
    }

    static Object parseNumber() {
        int start = jsonPos;
        boolean isFloat = false;
        if (jsonPos < jsonStr.length() && jsonStr.charAt(jsonPos) == '-') jsonPos++;
        while (jsonPos < jsonStr.length() && Character.isDigit(jsonStr.charAt(jsonPos))) jsonPos++;
        if (jsonPos < jsonStr.length() && jsonStr.charAt(jsonPos) == '.') {
            isFloat = true;
            jsonPos++;
            while (jsonPos < jsonStr.length() && Character.isDigit(jsonStr.charAt(jsonPos))) jsonPos++;
        }
        if (jsonPos < jsonStr.length() && (jsonStr.charAt(jsonPos) == 'e' || jsonStr.charAt(jsonPos) == 'E')) {
            isFloat = true;
            jsonPos++;
            if (jsonPos < jsonStr.length() && (jsonStr.charAt(jsonPos) == '+' || jsonStr.charAt(jsonPos) == '-')) jsonPos++;
            while (jsonPos < jsonStr.length() && Character.isDigit(jsonStr.charAt(jsonPos))) jsonPos++;
        }
        String numStr = jsonStr.substring(start, jsonPos);
        if (isFloat) return Double.parseDouble(numStr);
        return Long.parseLong(numStr);
    }

    // ==================== JSON Serializer ====================

    static String serializeJson(Object obj) {
        StringBuilder sb = new StringBuilder();
        writeJson(obj, sb);
        return sb.toString();
    }

    @SuppressWarnings("unchecked")
    static void writeJson(Object obj, StringBuilder sb) {
        if (obj == null) {
            sb.append("null");
        } else if (obj instanceof String) {
            writeJsonString((String) obj, sb);
        } else if (obj instanceof Long || obj instanceof Integer) {
            sb.append(obj.toString());
        } else if (obj instanceof Number) {
            double d = ((Number) obj).doubleValue();
            if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 1e15) {
                sb.append(Long.toString((long) d));
            } else {
                sb.append(obj.toString());
            }
        } else if (obj instanceof Boolean) {
            sb.append(obj.toString());
        } else if (obj instanceof Map) {
            sb.append('{');
            boolean first = true;
            for (Map.Entry<String, Object> entry : ((Map<String, Object>) obj).entrySet()) {
                if (!first) sb.append(',');
                first = false;
                writeJsonString(entry.getKey(), sb);
                sb.append(':');
                writeJson(entry.getValue(), sb);
            }
            sb.append('}');
        } else if (obj instanceof List) {
            sb.append('[');
            boolean first = true;
            for (Object item : (List<Object>) obj) {
                if (!first) sb.append(',');
                first = false;
                writeJson(item, sb);
            }
            sb.append(']');
        }
    }

    static void writeJsonString(String s, StringBuilder sb) {
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
                    break;
            }
        }
        sb.append('"');
    }

    // ==================== CSV Parser ====================

    static List<String[]> parseCsv(String content) {
        List<String[]> records = new ArrayList<>();
        int pos = 0;
        int len = content.length();

        while (pos < len) {
            List<String> fields = new ArrayList<>();

            while (true) {
                StringBuilder field = new StringBuilder();

                if (pos < len && content.charAt(pos) == '"') {
                    pos++; // skip opening quote
                    while (pos < len) {
                        char c = content.charAt(pos);
                        if (c == '"') {
                            if (pos + 1 < len && content.charAt(pos + 1) == '"') {
                                field.append('"');
                                pos += 2;
                            } else {
                                pos++; // skip closing quote
                                break;
                            }
                        } else {
                            field.append(c);
                            pos++;
                        }
                    }
                } else {
                    while (pos < len) {
                        char c = content.charAt(pos);
                        if (c == ',' || c == '\r' || c == '\n') break;
                        field.append(c);
                        pos++;
                    }
                }

                fields.add(field.toString());

                if (pos < len && content.charAt(pos) == ',') {
                    pos++;
                } else {
                    // End of record
                    if (pos < len && content.charAt(pos) == '\r') pos++;
                    if (pos < len && content.charAt(pos) == '\n') pos++;
                    records.add(fields.toArray(new String[0]));
                    break;
                }
            }
        }

        return records;
    }

    // ==================== HTTP Client ====================

    static String sendPost(String baseUrl, String apiKey, String body, int[] statusHolder) throws Exception {
        URL url = new URL(baseUrl + "/chat/completions");
        String host = url.getHost();
        int port = url.getPort();
        if (port == -1) port = url.getDefaultPort();
        String path = url.getPath();
        if (url.getQuery() != null) path += "?" + url.getQuery();

        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);

        Socket socket = new Socket(host, port);
        socket.setSoTimeout(120000);
        OutputStream out = socket.getOutputStream();

        StringBuilder req = new StringBuilder();
        req.append("POST ").append(path).append(" HTTP/1.1\r\n");
        req.append("Host: ").append(host);
        if (url.getPort() != -1) req.append(":").append(url.getPort());
        req.append("\r\n");
        req.append("Authorization: Bearer ").append(apiKey).append("\r\n");
        req.append("Content-Type: application/json\r\n");
        req.append("Content-Length: ").append(bodyBytes.length).append("\r\n");
        req.append("Connection: close\r\n");
        req.append("\r\n");

        out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
        out.write(bodyBytes);
        out.flush();

        InputStream in = socket.getInputStream();

        // Read headers (until \r\n\r\n)
        ByteArrayOutputStream headerBuf = new ByteArrayOutputStream();
        int state = 0;
        while (true) {
            int b = in.read();
            if (b == -1) break;
            headerBuf.write(b);
            if (state == 0 && b == '\r') state = 1;
            else if (state == 1 && b == '\n') state = 2;
            else if (state == 2 && b == '\r') state = 3;
            else if (state == 3 && b == '\n') break;
            else state = 0;
        }

        String headers = headerBuf.toString("US-ASCII");
        String[] headerLines = headers.split("\r\n");

        // Parse status code
        String statusLine = headerLines[0];
        String[] parts = statusLine.split(" ", 3);
        int statusCode = Integer.parseInt(parts[1]);
        statusHolder[0] = statusCode;

        // Get Content-Length
        int contentLength = -1;
        for (int i = 1; i < headerLines.length; i++) {
            String h = headerLines[i];
            if (h.length() >= 15 && h.substring(0, 15).equalsIgnoreCase("Content-Length:")) {
                contentLength = Integer.parseInt(h.substring(15).trim());
            }
        }

        // Read body
        byte[] respBody;
        if (contentLength >= 0) {
            respBody = new byte[contentLength];
            int read = 0;
            while (read < contentLength) {
                int r = in.read(respBody, read, contentLength - read);
                if (r == -1) break;
                read += r;
            }
        } else {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int r;
            while ((r = in.read(buf)) != -1) {
                baos.write(buf, 0, r);
            }
            respBody = baos.toByteArray();
        }

        socket.close();
        return new String(respBody, StandardCharsets.UTF_8);
    }
}

use std::io::{Read, Write};
use std::net::TcpStream;
use std::process;

// ==================== JSON ====================

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> &str {
        if let Json::Str(s) = self { s } else { "" }
    }
    fn as_i64(&self) -> i64 {
        if let Json::Num(n) = self { *n as i64 } else { 0 }
    }
}

fn parse_json(s: &str) -> Json {
    let bytes = s.as_bytes();
    let mut pos = 0;
    skip_ws(bytes, &mut pos);
    if pos >= bytes.len() { return Json::Null; }
    parse_value(bytes, &mut pos)
}

fn skip_ws(b: &[u8], pos: &mut usize) {
    while *pos < b.len() && (b[*pos] == b' ' || b[*pos] == b'\t' || b[*pos] == b'\n' || b[*pos] == b'\r') {
        *pos += 1;
    }
}

fn parse_value(b: &[u8], pos: &mut usize) -> Json {
    skip_ws(b, pos);
    if *pos >= b.len() { return Json::Null; }
    match b[*pos] {
        b'"' => Json::Str(parse_string(b, pos)),
        b'{' => parse_object(b, pos),
        b'[' => parse_array(b, pos),
        b't' => { *pos += 4; Json::Bool(true) }
        b'f' => { *pos += 5; Json::Bool(false) }
        b'n' => { *pos += 4; Json::Null }
        _ => parse_number(b, pos),
    }
}

fn parse_string(b: &[u8], pos: &mut usize) -> String {
    *pos += 1; // skip opening "
    let mut result = String::new();
    while *pos < b.len() {
        match b[*pos] {
            b'"' => { *pos += 1; break; }
            b'\\' => {
                *pos += 1;
                if *pos >= b.len() { break; }
                match b[*pos] {
                    b'"' => { result.push('"'); *pos += 1; }
                    b'\\' => { result.push('\\'); *pos += 1; }
                    b'/' => { result.push('/'); *pos += 1; }
                    b'b' => { result.push('\u{08}'); *pos += 1; }
                    b'f' => { result.push('\u{0C}'); *pos += 1; }
                    b'n' => { result.push('\n'); *pos += 1; }
                    b'r' => { result.push('\r'); *pos += 1; }
                    b't' => { result.push('\t'); *pos += 1; }
                    b'u' => {
                        *pos += 1;
                        let cp = parse_hex4(b, pos);
                        *pos += 4;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if *pos + 1 < b.len() && b[*pos] == b'\\' && b[*pos + 1] == b'u' {
                                *pos += 2;
                                let lo = parse_hex4(b, pos);
                                *pos += 4;
                                let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                result.push(char::from_u32(full).unwrap_or('\u{FFFD}'));
                            } else {
                                result.push('\u{FFFD}');
                            }
                        } else {
                            result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => { result.push(b[*pos] as char); *pos += 1; }
                }
            }
            _ => {
                let start = *pos;
                *pos += 1;
                if b[start] >= 0x80 {
                    let extra = if b[start] >= 0xF0 { 3 } else if b[start] >= 0xE0 { 2 } else { 1 };
                    for _ in 0..extra {
                        if *pos < b.len() { *pos += 1; }
                    }
                }
                result.push_str(std::str::from_utf8(&b[start..*pos]).unwrap_or("\u{FFFD}"));
            }
        }
    }
    result
}

fn parse_hex4(b: &[u8], pos: &mut usize) -> u32 {
    let mut val = 0u32;
    for i in 0..4 {
        let c = b[*pos + i];
        val = val * 16 + match c {
            b'0'..=b'9' => (c - b'0') as u32,
            b'a'..=b'f' => (c - b'a' + 10) as u32,
            b'A'..=b'F' => (c - b'A' + 10) as u32,
            _ => 0,
        };
    }
    val
}

fn parse_number(b: &[u8], pos: &mut usize) -> Json {
    let start = *pos;
    if *pos < b.len() && b[*pos] == b'-' { *pos += 1; }
    while *pos < b.len() && b[*pos].is_ascii_digit() { *pos += 1; }
    if *pos < b.len() && b[*pos] == b'.' {
        *pos += 1;
        while *pos < b.len() && b[*pos].is_ascii_digit() { *pos += 1; }
    }
    if *pos < b.len() && (b[*pos] == b'e' || b[*pos] == b'E') {
        *pos += 1;
        if *pos < b.len() && (b[*pos] == b'+' || b[*pos] == b'-') { *pos += 1; }
        while *pos < b.len() && b[*pos].is_ascii_digit() { *pos += 1; }
    }
    let s = std::str::from_utf8(&b[start..*pos]).unwrap_or("0");
    Json::Num(s.parse::<f64>().unwrap_or(0.0))
}

fn parse_object(b: &[u8], pos: &mut usize) -> Json {
    *pos += 1;
    let mut pairs = Vec::new();
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == b'}' { *pos += 1; return Json::Obj(pairs); }
    loop {
        skip_ws(b, pos);
        let key = parse_string(b, pos);
        skip_ws(b, pos);
        if *pos < b.len() && b[*pos] == b':' { *pos += 1; }
        let val = parse_value(b, pos);
        pairs.push((key, val));
        skip_ws(b, pos);
        if *pos < b.len() && b[*pos] == b',' { *pos += 1; }
        else { break; }
    }
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == b'}' { *pos += 1; }
    Json::Obj(pairs)
}

fn parse_array(b: &[u8], pos: &mut usize) -> Json {
    *pos += 1;
    let mut items = Vec::new();
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == b']' { *pos += 1; return Json::Arr(items); }
    loop {
        items.push(parse_value(b, pos));
        skip_ws(b, pos);
        if *pos < b.len() && b[*pos] == b',' { *pos += 1; }
        else { break; }
    }
    skip_ws(b, pos);
    if *pos < b.len() && b[*pos] == b']' { *pos += 1; }
    Json::Arr(items)
}

fn serialize_json(val: &Json) -> String {
    match val {
        Json::Null => "null".to_string(),
        Json::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Json::Num(n) => {
            if *n == n.floor() && n.abs() < 1e15 {
                format!("{}", *n as i64)
            } else {
                format!("{}", n)
            }
        }
        Json::Str(s) => json_escape(s),
        Json::Arr(items) => {
            let parts: Vec<String> = items.iter().map(serialize_json).collect();
            format!("[{}]", parts.join(","))
        }
        Json::Obj(pairs) => {
            let parts: Vec<String> = pairs.iter().map(|(k, v)| {
                format!("{}:{}", json_escape(k), serialize_json(v))
            }).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn json_escape(s: &str) -> String {
    let mut result = String::from("\"");
    for ch in s.chars() {
        match ch {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{08}' => result.push_str("\\b"),
            '\u{0C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

// ==================== Output escaping ====================

fn output_escape(s: &str) -> String {
    let mut result = String::new();
    for ch in s.chars() {
        match ch {
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c => result.push(c),
        }
    }
    result
}

// ==================== HTTP ====================

fn read_line(stream: &mut TcpStream) -> Vec<u8> {
    let mut line = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        match stream.read(&mut byte) {
            Ok(0) => break,
            Ok(_) => {
                line.push(byte[0]);
                if byte[0] == b'\n' { break; }
            }
            Err(_) => break,
        }
    }
    line
}

fn read_exact(stream: &mut TcpStream, n: usize) -> Vec<u8> {
    let mut buf = vec![0u8; n];
    let mut read = 0;
    while read < n {
        match stream.read(&mut buf[read..]) {
            Ok(0) => break,
            Ok(k) => read += k,
            Err(_) => break,
        }
    }
    buf.truncate(read);
    buf
}

fn read_all(stream: &mut TcpStream) -> Vec<u8> {
    let mut buf = Vec::new();
    let mut tmp = [0u8; 65536];
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => break,
            Ok(k) => buf.extend_from_slice(&tmp[..k]),
            Err(_) => break,
        }
    }
    buf
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    loop {
        let line_start = pos;
        while pos < data.len() && data[pos] != b'\n' { pos += 1; }
        if pos >= data.len() { break; }
        let line_end = pos;
        pos += 1; // skip \n
        let mut line = &data[line_start..line_end];
        // strip trailing \r
        if line.last() == Some(&b'\r') { line = &line[..line.len()-1]; }
        let line_str = String::from_utf8_lossy(line).to_lowercase();
        let size_str = if let Some(semi) = line_str.find(';') {
            &line_str[..semi]
        } else {
            &line_str
        };
        let chunk_size = usize::from_str_radix(size_str.trim(), 16).unwrap_or(0);
        if chunk_size == 0 { break; }
        if pos + chunk_size <= data.len() {
            result.extend_from_slice(&data[pos..pos + chunk_size]);
        }
        pos += chunk_size;
        // skip trailing CRLF
        if pos < data.len() && data[pos] == b'\r' { pos += 1; }
        if pos < data.len() && data[pos] == b'\n' { pos += 1; }
    }
    result
}

// ==================== SSE ====================

struct SseEvent {
    event_type: String,
    data: String,
}

fn parse_sse(data: &[u8]) -> Vec<SseEvent> {
    let text = String::from_utf8_lossy(data);
    let mut events = Vec::new();
    let mut current_event_type = String::new();
    let mut current_data_lines: Vec<String> = Vec::new();

    for line in text.split('\n') {
        let line = if line.ends_with('\r') { &line[..line.len()-1] } else { line };

        if line.is_empty() {
            if !current_data_lines.is_empty() {
                events.push(SseEvent {
                    event_type: current_event_type.clone(),
                    data: current_data_lines.join("\n"),
                });
            }
            current_event_type.clear();
            current_data_lines.clear();
        } else if line.starts_with(':') {
            // comment
        } else if let Some(colon_pos) = line.find(':') {
            let field = &line[..colon_pos];
            let mut value = &line[colon_pos + 1..];
            if value.starts_with(' ') { value = &value[1..]; }
            match field {
                "event" => current_event_type = value.to_string(),
                "data" => current_data_lines.push(value.to_string()),
                _ => {}
            }
        } else {
            match line {
                "event" => current_event_type = String::new(),
                "data" => current_data_lines.push(String::new()),
                _ => {}
            }
        }
    }
    if !current_data_lines.is_empty() {
        events.push(SseEvent {
            event_type: current_event_type,
            data: current_data_lines.join("\n"),
        });
    }
    events
}

// ==================== Content blocks ====================

#[derive(Debug, Clone)]
enum ContentBlock {
    Thinking { thinking: String, signature: String },
    Text { text: String },
    ToolUse { id: String, name: String, input_json: String },
}

// ==================== Tools ====================

fn execute_tool(name: &str, input: &Json) -> (String, bool) {
    match name {
        "measure" => {
            let text = input.get("text").map(|v| v.as_str()).unwrap_or("");
            let unit = input.get("unit").map(|v| v.as_str()).unwrap_or("");
            match unit {
                "code_points" => (text.chars().count().to_string(), false),
                "utf8_bytes" => (text.len().to_string(), false),
                "utf16_units" => {
                    let count: usize = text.chars().map(|c| if (c as u32) > 0xFFFF { 2 } else { 1 }).sum();
                    (count.to_string(), false)
                }
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get("text").map(|v| v.as_str()).unwrap_or("");
            (text.chars().rev().collect::<String>(), false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ==================== URL parsing ====================

fn parse_url(url: &str) -> (String, String) {
    let without_scheme = if url.starts_with("http://") {
        &url[7..]
    } else if url.starts_with("https://") {
        &url[8..]
    } else {
        url
    };
    let slash_pos = without_scheme.find('/').unwrap_or(without_scheme.len());
    let host = &without_scheme[..slash_pos];
    let path = if slash_pos < without_scheme.len() {
        &without_scheme[slash_pos..]
    } else {
        "/"
    };
    (host.to_string(), path.to_string())
}

fn split_host_port(host_with_port: &str) -> (String, u16) {
    if let Some(colon_pos) = host_with_port.rfind(':') {
        let port_str = &host_with_port[colon_pos + 1..];
        if let Ok(port) = port_str.parse::<u16>() {
            return (host_with_port[..colon_pos].to_string(), port);
        }
    }
    (host_with_port.to_string(), 80)
}

// ==================== Main logic ====================

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <data_dir> <base_url>", args[0]);
        process::exit(1);
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    let path = format!("{}/request.json", data_dir);
    let json_str = std::fs::read_to_string(&path).expect("Failed to read request.json");
    let config = parse_json(&json_str);

    let api_key = config.get("api_key").unwrap().as_str().to_string();
    let model = config.get("model").unwrap().clone();
    let max_tokens = config.get("max_tokens").unwrap().clone();
    let thinking_budget = config.get("thinking_budget").unwrap().clone();
    let system = config.get("system").unwrap().clone();
    let prompt = config.get("prompt").unwrap().clone();
    let tools = config.get("tools").unwrap().clone();

    let (host_with_port, base_path) = parse_url(base_url);
    let request_path = format!("{}/v1/messages", base_path);
    let (host, port) = split_host_port(&host_with_port);

    // Request 1
    let messages1 = vec![
        Json::Obj(vec![
            ("role".to_string(), Json::Str("user".to_string())),
            ("content".to_string(), prompt.clone()),
        ])
    ];

    println!("request 1");

    let (blocks1, stop_reason1, usage1) = send_and_receive(
        &host, port, &request_path, &api_key, &model, &max_tokens,
        &thinking_budget, &system, &tools, &messages1,
    );

    print_blocks(&blocks1);
    println!("stop_reason {}", stop_reason1);

    // Execute tools
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();
    for block in &blocks1 {
        if let ContentBlock::ToolUse { id, name, input_json } = block {
            let input = if input_json.is_empty() {
                parse_json("{}")
            } else {
                parse_json(input_json)
            };
            let (result, is_error) = execute_tool(name, &input);
            tool_results.push((id.clone(), result.clone(), is_error));
            if is_error {
                println!("error {} {}", output_escape(id), output_escape(&result));
            } else {
                println!("result {} {}", output_escape(id), output_escape(&result));
            }
        }
    }

    // Build messages for request 2
    let mut assistant_content: Vec<Json> = Vec::new();
    let mut tool_result_content: Vec<Json> = Vec::new();

    for block in &blocks1 {
        match block {
            ContentBlock::Thinking { thinking, signature } => {
                assistant_content.push(Json::Obj(vec![
                    ("type".to_string(), Json::Str("thinking".to_string())),
                    ("thinking".to_string(), Json::Str(thinking.clone())),
                    ("signature".to_string(), Json::Str(signature.clone())),
                ]));
            }
            ContentBlock::Text { text } => {
                assistant_content.push(Json::Obj(vec![
                    ("type".to_string(), Json::Str("text".to_string())),
                    ("text".to_string(), Json::Str(text.clone())),
                ]));
            }
            ContentBlock::ToolUse { id, name, input_json } => {
                let input = if input_json.is_empty() {
                    parse_json("{}")
                } else {
                    parse_json(input_json)
                };
                assistant_content.push(Json::Obj(vec![
                    ("type".to_string(), Json::Str("tool_use".to_string())),
                    ("id".to_string(), Json::Str(id.clone())),
                    ("name".to_string(), Json::Str(name.clone())),
                    ("input".to_string(), input),
                ]));
            }
        }
    }

    for (id, result, is_error) in &tool_results {
        let mut block = vec![
            ("type".to_string(), Json::Str("tool_result".to_string())),
            ("tool_use_id".to_string(), Json::Str(id.clone())),
            ("content".to_string(), Json::Str(result.clone())),
        ];
        if *is_error {
            block.push(("is_error".to_string(), Json::Bool(true)));
        }
        tool_result_content.push(Json::Obj(block));
    }

    let messages2 = vec![
        Json::Obj(vec![
            ("role".to_string(), Json::Str("user".to_string())),
            ("content".to_string(), prompt.clone()),
        ]),
        Json::Obj(vec![
            ("role".to_string(), Json::Str("assistant".to_string())),
            ("content".to_string(), Json::Arr(assistant_content)),
        ]),
        Json::Obj(vec![
            ("role".to_string(), Json::Str("user".to_string())),
            ("content".to_string(), Json::Arr(tool_result_content)),
        ]),
    ];

    // Request 2
    println!("request 2");

    let (blocks2, stop_reason2, usage2) = send_and_receive(
        &host, port, &request_path, &api_key, &model, &max_tokens,
        &thinking_budget, &system, &tools, &messages2,
    );

    print_blocks(&blocks2);
    println!("stop_reason {}", stop_reason2);

    // Usage
    let total_input = usage1.0 + usage2.0;
    let total_output = usage1.1 + usage2.1;
    let total_cache_read = usage1.2 + usage2.2;
    println!("usage input={} output={} cache_read={}", total_input, total_output, total_cache_read);
}

fn print_blocks(blocks: &[ContentBlock]) {
    for block in blocks {
        match block {
            ContentBlock::Thinking { thinking, signature } => {
                println!("thinking {}", output_escape(thinking));
                println!("signature {}", output_escape(signature));
            }
            ContentBlock::Text { text } => {
                println!("text {}", output_escape(text));
            }
            ContentBlock::ToolUse { id, name, input_json } => {
                println!("tool_use {} {} {}", output_escape(id), output_escape(name), output_escape(input_json));
            }
        }
    }
}

fn send_and_receive(
    host: &str, port: u16, path: &str, api_key: &str,
    model: &Json, max_tokens: &Json, thinking_budget: &Json,
    system: &Json, tools: &Json, messages: &[Json],
) -> (Vec<ContentBlock>, String, (i64, i64, i64)) {
    let body_obj = Json::Obj(vec![
        ("model".to_string(), model.clone()),
        ("max_tokens".to_string(), max_tokens.clone()),
        ("stream".to_string(), Json::Bool(true)),
        ("thinking".to_string(), Json::Obj(vec![
            ("type".to_string(), Json::Str("enabled".to_string())),
            ("budget_tokens".to_string(), thinking_budget.clone()),
        ])),
        ("system".to_string(), system.clone()),
        ("tools".to_string(), tools.clone()),
        ("messages".to_string(), Json::Arr(messages.to_vec())),
    ]);
    let body = serialize_json(&body_obj);

    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("Failed to connect");
    stream.set_read_timeout(Some(std::time::Duration::from_secs(60))).ok();

    let request = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",
        path, host, body.len(), api_key, body
    );
    stream.write_all(request.as_bytes()).expect("Failed to send");
    stream.flush().expect("Failed to flush");

    // Read status line
    let status_line = read_line(&mut stream);
    let status_str = String::from_utf8_lossy(&status_line).trim().to_string();
    let status_code: u16 = status_str.split_whitespace().nth(1).unwrap_or("0").parse().unwrap_or(0);

