        let line = read_line(&mut stream);
        if line.is_empty() || line == b"\r\n" || line == b"\n" { break; }
        let line_lower = String::from_utf8_lossy(&line).to_lowercase();
        if line_lower.starts_with("content-length:") {
            content_length = line_lower["content-length:".len()..].trim().parse().unwrap_or(0);
        }
    }

    if status_code != 200 {
        let body_bytes = read_exact(&mut stream, content_length);
        let body_str = String::from_utf8_lossy(&body_bytes);
        let err_json = parse_json(&body_str);
        let err_type = err_json.get("error").and_then(|e| e.get("type")).map(|v| v.as_str()).unwrap_or("unknown");
        let err_msg = err_json.get("error").and_then(|e| e.get("message")).map(|v| v.as_str()).unwrap_or("unknown");
        println!("ERROR {} {}: {}", status_code, err_type, err_msg);
        std::io::stdout().flush().unwrap();
        process::exit(0);
    }

    // Read chunked body
    let raw = read_all(&mut stream);
    let sse_data = decode_chunked(&raw);
    let events = parse_sse(&sse_data);

    // Process events
    let mut blocks: Vec<ContentBlock> = Vec::new();
    let mut block_types: Vec<String> = Vec::new();
    let mut block_thinking: Vec<String> = Vec::new();
    let mut block_signature: Vec<String> = Vec::new();
