    let mut output_tokens: i64 = 0;
    let mut cache_read_tokens: i64 = 0;
    let mut stop_reason = String::new();

    for event in &events {
        let data = parse_json(&event.data);
        if let Json::Null = data { continue; }

        match event.event_type.as_str() {
            "message_start" => {
                if let Some(msg) = data.get("message") {
                    if let Some(usage) = msg.get("usage") {
                        input_tokens = usage.get("input_tokens").map(|v| v.as_i64()).unwrap_or(0);
                        cache_read_tokens = usage.get("cache_read_input_tokens").map(|v| v.as_i64()).unwrap_or(0);
                    }
                }
            }
            "content_block_start" => {
