                let btype = cb.get("type").map(|v| v.as_str()).unwrap_or("").to_string();
                while block_types.len() <= idx {
                    block_types.push(String::new());
                    block_thinking.push(String::new());
                    block_signature.push(String::new());
                    block_text.push(String::new());
                    block_tool_id.push(String::new());
                    block_tool_name.push(String::new());
                    block_tool_input.push(String::new());
                }
                block_types[idx] = btype.clone();
                if btype == "tool_use" {
                    block_tool_id[idx] = cb.get("id").map(|v| v.as_str()).unwrap_or("").to_string();
                    block_tool_name[idx] = cb.get("name").map(|v| v.as_str()).unwrap_or("").to_string();
                }
            }
            "content_block_delta" => {
                let idx = data.get("index").map(|v| v.as_i64()).unwrap_or(0) as usize;
                let delta = match data.get("delta") { Some(v) => v, None => continue };
                let dtype = delta.get("type").map(|v| v.as_str()).unwrap_or("");
                while block_types.len() <= idx {
                    block_types.push(String::new());
                    block_thinking.push(String::new());
                    block_signature.push(String::new());
                    block_text.push(String::new());
                    block_tool_id.push(String::new());
                    block_tool_name.push(String::new());
                    block_tool_input.push(String::new());
                }
                match dtype {
                    "thinking_delta" => {
                        block_thinking[idx].push_str(delta.get("thinking").map(|v| v.as_str()).unwrap_or(""));
                    }
                    "signature_delta" => {
                        block_signature[idx].push_str(delta.get("signature").map(|v| v.as_str()).unwrap_or(""));
                    }
                    "text_delta" => {
                        block_text[idx].push_str(delta.get("text").map(|v| v.as_str()).unwrap_or(""));
                    }
                    "input_json_delta" => {
                        block_tool_input[idx].push_str(delta.get("partial_json").map(|v| v.as_str()).unwrap_or(""));
                    }
                    _ => {}
                }
            }
            "content_block_stop" => {
                let idx = data.get("index").map(|v| v.as_i64()).unwrap_or(0) as usize;
                if idx < block_types.len() {
                    match block_types[idx].as_str() {
                        "thinking" => blocks.push(ContentBlock::Thinking {
                            thinking: block_thinking[idx].clone(),
                            signature: block_signature[idx].clone(),
                        }),
                        "text" => blocks.push(ContentBlock::Text {
                            text: block_text[idx].clone(),
                        }),
                        "tool_use" => blocks.push(ContentBlock::ToolUse {
                            id: block_tool_id[idx].clone(),
                            name: block_tool_name[idx].clone(),
                            input_json: block_tool_input[idx].clone(),
                        }),
                        _ => {}
                    }
                }
            }
            "message_delta" => {
                if let Some(delta) = data.get("delta") {
                    stop_reason = delta.get("stop_reason").map(|v| v.as_str()).unwrap_or("").to_string();
                }
                if let Some(usage) = data.get("usage") {
                    output_tokens = usage.get("output_tokens").map(|v| v.as_i64()).unwrap_or(0);
                }
            }
            _ => {}
        }
    }

    (blocks, stop_reason, (input_tokens, output_tokens, cache_read_tokens))
}

