#[derive(Clone, Debug)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self { Some(s) } else { None }
    }
    fn as_i64(&self) -> Option<i64> {
        if let Json::Num(n) = self { Some(*n as i64) } else { None }
    }
    fn as_arr(&self) -> Option<&Vec<Json>> {
        if let Json::Arr(a) = self { Some(a) } else { None }
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { bytes: s.as_bytes(), pos: 0 }
    }
    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() {
            match self.bytes[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        if self.pos >= self.bytes.len() { return Json::Null; }
        match self.bytes[self.pos] {
            b'"' => Json::Str(self.parse_string()),
            b'[' => self.parse_array(),
            b'{' => self.parse_object(),
            b't' => { self.pos += 4; Json::Bool(true) }
            b'f' => { self.pos += 5; Json::Bool(false) }
            b'n' => { self.pos += 4; Json::Null }
            _ => self.parse_number(),
        }
    }
    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let mut result = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c == b'"' { self.pos += 1; return result; }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.bytes.len() { break; }
                let esc = self.bytes[self.pos];
                match esc {
                    b'"' => { result.push('"'); self.pos += 1; }
                    b'\\' => { result.push('\\'); self.pos += 1; }
                    b'/' => { result.push('/'); self.pos += 1; }
                    b'b' => { result.push('\u{0008}'); self.pos += 1; }
                    b'f' => { result.push('\u{000C}'); self.pos += 1; }
                    b'n' => { result.push('\n'); self.pos += 1; }
                    b'r' => { result.push('\r'); self.pos += 1; }
                    b't' => { result.push('\t'); self.pos += 1; }
                    b'u' => {
                        self.pos += 1;
                        let cp = self.parse_hex4();
                        self.pos += 4;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.bytes.len() && self.bytes[self.pos] == b'\\' && self.bytes[self.pos + 1] == b'u' {
                                self.pos += 2;
                                let cp2 = self.parse_hex4();
                                self.pos += 4;
                                let full = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                if let Some(ch) = char::from_u32(full) { result.push(ch); }
                            } else {
                                result.push('\u{FFFD}');
                            }
                        } else {
                            if let Some(ch) = char::from_u32(cp) { result.push(ch); }
                        }
                    }
                    _ => { result.push(esc as char); self.pos += 1; }
                }
            } else {
                let start = self.pos;
                let len = if c < 0x80 { 1 } else if c < 0xE0 { 2 } else if c < 0xF0 { 3 } else { 4 };
                self.pos += len;
                if self.pos <= self.bytes.len() {
                    if let Ok(s) = std::str::from_utf8(&self.bytes[start..self.pos]) {
                        result.push_str(s);
                    }
                }
            }
        }
        result
    }
    fn parse_hex4(&self) -> u32 {
        let mut val = 0u32;
        for i in 0..4 {
            let c = self.bytes[self.pos + i];
            val <<= 4;
            if c >= b'0' && c <= b'9' { val |= (c - b'0') as u32; }
            else if c >= b'a' && c <= b'f' { val |= (c - b'a' + 10) as u32; }
            else if c >= b'A' && c <= b'F' { val |= (c - b'A' + 10) as u32; }
        }
        val
    }
    fn parse_array(&mut self) -> Json {
        self.pos += 1;
        let mut arr = Vec::new();
        self.skip_ws();
        if self.pos < self.bytes.len() && self.bytes[self.pos] == b']' { self.pos += 1; return Json::Arr(arr); }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            if self.pos >= self.bytes.len() { break; }
            if self.bytes[self.pos] == b',' { self.pos += 1; continue; }
            if self.bytes[self.pos] == b']' { self.pos += 1; break; }
        }
        Json::Arr(arr)
    }
    fn parse_object(&mut self) -> Json {
        self.pos += 1;
        let mut obj = Vec::new();
        self.skip_ws();
        if self.pos < self.bytes.len() && self.bytes[self.pos] == b'}' { self.pos += 1; return Json::Obj(obj); }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.pos += 1;
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            if self.pos >= self.bytes.len() { break; }
            if self.bytes[self.pos] == b',' { continue; }
            if self.bytes[self.pos] == b'}' { self.pos += 1; break; }
        }
        Json::Obj(obj)
    }
    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.pos < self.bytes.len() && self.bytes[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.bytes.len() && self.bytes[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.bytes.len() && (self.bytes[self.pos] == b'e' || self.bytes[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.bytes.len() && (self.bytes[self.pos] == b'+' || self.bytes[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.bytes[start..self.pos]).unwrap_or("0");
        Json::Num(s.parse::<f64>().unwrap_or(0.0))
    }
}

fn parse_json(s: &str) -> Json {
    let mut p = Parser::new(s);
    p.parse_value()
}

fn json_escape_str(s: &str) -> String {
    let mut result = String::new();
    for ch in s.chars() {
        match ch {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => result.push(ch),
        }
    }
    result
}

fn serialize_json(val: &Json) -> String {
    match val {
        Json::Null => "null".to_string(),
        Json::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Json::Num(n) => {
            if *n == (*n as i64) as f64 && n.abs() < 1e15 {
                format!("{}", *n as i64)
            } else {
                format!("{}", n)
            }
        }
        Json::Str(s) => format!("\"{}\"", json_escape_str(s)),
        Json::Arr(arr) => {
            let items: Vec<String> = arr.iter().map(|v| serialize_json(v)).collect();
            format!("[{}]", items.join(","))
        }
        Json::Obj(pairs) => {
            let items: Vec<String> = pairs.iter().map(|(k, v)| format!("\"{}\":{}", json_escape_str(k), serialize_json(v))).collect();
            format!("{{{}}}", items.join(","))
        }
    }
}

fn parse_csv(content: &str) -> Vec<Vec<String>> {
    let content = content.strip_prefix('\u{FEFF}').unwrap_or(content);
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut current_record: Vec<String> = Vec::new();
    let mut current_field = String::new();
    let mut in_quotes = false;
    let bytes = content.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if in_quotes {
            if bytes[i] == b'"' {
                if i + 1 < bytes.len() && bytes[i + 1] == b'"' {
                    current_field.push('"');
                    i += 2;
                } else {
                    in_quotes = false;
                    i += 1;
                }
            } else {
                let len = if bytes[i] < 0x80 { 1 } else if bytes[i] < 0xE0 { 2 } else if bytes[i] < 0xF0 { 3 } else { 4 };
                if i + len <= bytes.len() {
                    if let Ok(s) = std::str::from_utf8(&bytes[i..i+len]) {
                        current_field.push_str(s);
                    }
                }
                i += len;
            }
        } else {
            match bytes[i] {
                b'"' => { in_quotes = true; i += 1; }
                b',' => {
                    current_record.push(current_field.clone());
                    current_field.clear();
                    i += 1;
                }
                b'\r' => {
                    if i + 1 < bytes.len() && bytes[i + 1] == b'\n' { i += 2; } else { i += 1; }
                    current_record.push(current_field.clone());
                    current_field.clear();
                    records.push(current_record.clone());
                    current_record.clear();
                }
                b'\n' => {
                    i += 1;
                    current_record.push(current_field.clone());
                    current_field.clear();
                    records.push(current_record.clone());
                    current_record.clear();
                }
                _ => {
                    let len = if bytes[i] < 0x80 { 1 } else if bytes[i] < 0xE0 { 2 } else if bytes[i] < 0xF0 { 3 } else { 4 };
                    if i + len <= bytes.len() {
                        if let Ok(s) = std::str::from_utf8(&bytes[i..i+len]) {
                            current_field.push_str(s);
                        }
                    }
                    i += len;
                }
            }
        }
    }
    if !current_field.is_empty() || !current_record.is_empty() {
        current_record.push(current_field);
        records.push(current_record);
    }
    records
}

fn parse_url(url: &str) -> (String, u16, String) {
    let without_scheme = url.strip_prefix("http://").unwrap_or(url);
    let slash_pos = without_scheme.find('/').unwrap_or(without_scheme.len());
    let host_port = &without_scheme[..slash_pos];
    let path = if slash_pos < without_scheme.len() { &without_scheme[slash_pos..] } else { "" };
    let (host, port) = if let Some(colon_pos) = host_port.rfind(':') {
        let h = &host_port[..colon_pos];
        let p: u16 = host_port[colon_pos+1..].parse().unwrap_or(80);
        (h.to_string(), p)
    } else {
        (host_port.to_string(), 80)
    };
    (host, port, path.to_string())
}

fn http_post(host: &str, port: u16, path: &str, auth: &str, body: &str) -> (u16, String) {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    let mut request = format!("POST {} HTTP/1.1\r\n", path);
    request.push_str(&format!("Host: {}:{}\r\n", host, port));
    request.push_str(&format!("Authorization: Bearer {}\r\n", auth));
    request.push_str("Content-Type: application/json\r\n");
    request.push_str(&format!("Content-Length: {}\r\n", body.len()));
    request.push_str("Connection: close\r\n");
    request.push_str("\r\n");
    request.push_str(body);
    stream.write_all(request.as_bytes()).expect("write failed");
    stream.flush().expect("flush failed");
    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("read failed");
    let response_str = String::from_utf8_lossy(&response).to_string();
    let header_end = response_str.find("\r\n\r\n").unwrap_or(0);
    let headers_part = &response_str[..header_end];
    let body_part = &response_str[header_end + 4..];
    let first_line = headers_part.lines().next().unwrap_or("HTTP/1.1 500 Error");
    let status: u16 = first_line.split_whitespace().nth(1).unwrap_or("500").parse().unwrap_or(500);
    let content_length: usize = headers_part.lines()
        .find(|l| l.to_lowercase().starts_with("content-length:"))
        .map(|l| l.split(':').nth(1).unwrap_or("0").trim().parse().unwrap_or(0))
        .unwrap_or(body_part.len());
    let body_str = if content_length <= body_part.len() {
        body_part[..content_length].to_string()
    } else {
        body_part.to_string()
    };
    (status, body_str)
}

fn execute_tool(name: &str, arguments_str: &str, inventory: &HashMap<String, (String, i64, String, i64)>, rates: &Json) -> String {
    match name {
        "inventory_lookup" => {
            let args = parse_json(arguments_str);
            let sku = args.get("sku").and_then(|v| v.as_str()).unwrap_or("");
            match inventory.get(sku) {
                Some((nm, price_cents, currency, stock)) => {
                    format!("{{\"sku\":\"{}\",\"name\":\"{}\",\"price_cents\":{},\"currency\":\"{}\",\"stock\":{}}}",
                        json_escape_str(sku), json_escape_str(nm), price_cents, json_escape_str(currency), stock)
                }
                None => {
                    format!("{{\"error\":\"unknown sku: {}\"}}", json_escape_str(sku))
                }
            }
        }
        "convert_currency" => {
            let args = parse_json(arguments_str);
            let amount_cents = args.get("amount_cents").and_then(|v| v.as_i64()).unwrap_or(0);
            let from = args.get("from").and_then(|v| v.as_str()).unwrap_or("");
            let to = args.get("to").and_then(|v| v.as_str()).unwrap_or("");
            let rate_from = rates.get(from).and_then(|v| v.as_i64()).unwrap_or(1000000);
            let rate_to = rates.get(to).and_then(|v| v.as_i64()).unwrap_or(1000000);
            let numerator = 2i64.wrapping_mul(amount_cents).wrapping_mul(rate_to).wrapping_add(rate_from);
            let denominator = 2i64.wrapping_mul(rate_from);
            let converted = numerator / denominator;
            format!("{{\"amount_cents\":{},\"currency\":\"{}\"}}", converted, json_escape_str(to))
        }
        _ => {
            format!("{{\"error\":\"unknown tool: {}\"}}", json_escape_str(name))
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let task_content = std::fs::read_to_string(format!("{}/task.json", data_dir)).unwrap();
    let task = parse_json(&task_content);
    let api_key = task.get("api_key").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let model = task.get("model").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let system = task.get("system").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let user = task.get("user").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let tools = task.get("tools").cloned().unwrap_or(Json::Arr(vec![]));

    let csv_content = std::fs::read_to_string(format!("{}/inventory.csv", data_dir)).unwrap();
    let csv_records = parse_csv(&csv_content);
    let mut inventory: HashMap<String, (String, i64, String, i64)> = HashMap::new();
    for (i, record) in csv_records.iter().enumerate() {
        if i == 0 { continue; }
        if record.len() >= 5 {
            let sku = record[0].clone();
            let nm = record[1].clone();
            let price_cents: i64 = record[2].parse().unwrap_or(0);
            let currency = record[3].clone();
            let stock: i64 = record[4].parse().unwrap_or(0);
            inventory.insert(sku, (nm, price_cents, currency, stock));
        }
    }

    let rates_content = std::fs::read_to_string(format!("{}/rates.json", data_dir)).unwrap();
    let rates_json = parse_json(&rates_content);
    let rates = rates_json.get("rates").cloned().unwrap_or(Json::Obj(vec![]));

    let (host, port, path_prefix) = parse_url(base_url);
    let path = format!("{}/chat/completions", path_prefix);

    let mut messages: Vec<Json> = vec![
        Json::Obj(vec![
            ("role".to_string(), Json::Str("system".to_string())),
            ("content".to_string(), Json::Str(system)),
        ]),
        Json::Obj(vec![
            ("role".to_string(), Json::Str("user".to_string())),
            ("content".to_string(), Json::Str(user)),
        ]),
    ];

    let mut total_prompt = 0i64;
    let mut total_completion = 0i64;
    let mut total_total = 0i64;
    let mut num_requests = 0;

    loop {
        let body = Json::Obj(vec![
            ("model".to_string(), Json::Str(model.clone())),
            ("messages".to_string(), Json::Arr(messages.clone())),
            ("tools".to_string(), tools.clone()),
            ("tool_choice".to_string(), Json::Str("auto".to_string())),
        ]);
        let body_str = serialize_json(&body);
        num_requests += 1;

        let (status, resp_body) = http_post(&host, port, &path, &api_key, &body_str);

        if status != 200 {
            let err_json = parse_json(&resp_body);
            let msg = err_json.get("error")
                .and_then(|e| e.get("message"))
                .and_then(|m| m.as_str())
                .unwrap_or("unknown error");
            println!("ERROR {} {}", status, msg);
            process::exit(0);
        }

        let resp = parse_json(&resp_body);

        if let Some(usage) = resp.get("usage") {
            total_prompt += usage.get("prompt_tokens").and_then(|v| v.as_i64()).unwrap_or(0);
            total_completion += usage.get("completion_tokens").and_then(|v| v.as_i64()).unwrap_or(0);
            total_total += usage.get("total_tokens").and_then(|v| v.as_i64()).unwrap_or(0);
        }

        let choices = resp.get("choices").and_then(|c| c.as_arr()).cloned().unwrap_or_default();
        let choice = choices.first();
        let finish_reason = choice.and_then(|c| c.get("finish_reason")).and_then(|f| f.as_str()).unwrap_or("stop").to_string();
        let message = choice.and_then(|c| c.get("message"));

        if finish_reason == "tool_calls" {
            let content = message.and_then(|m| m.get("content"));
            if let Some(Json::Str(s)) = content {
                println!("SAY {}", s);
            }

            let tool_calls: Vec<Json> = message
                .and_then(|m| m.get("tool_calls"))
                .and_then(|tc| tc.as_arr())
                .cloned()
                .unwrap_or_default();

            for tc in &tool_calls {
                let id = tc.get("id").and_then(|v| v.as_str()).unwrap_or("");
                let nm = tc.get("function").and_then(|f| f.get("name")).and_then(|v| v.as_str()).unwrap_or("");
                println!("CALL {} {}", id, nm);
            }

            let content_val = match content {
                Some(Json::Str(s)) => Json::Str(s.clone()),
                _ => Json::Null,
            };
            let mut assistant_msg: Vec<(String, Json)> = vec![
                ("role".to_string(), Json::Str("assistant".to_string())),
                ("content".to_string(), content_val),
            ];
            if !tool_calls.is_empty() {
                assistant_msg.push(("tool_calls".to_string(), Json::Arr(tool_calls.clone())));
            }
            messages.push(Json::Obj(assistant_msg));

            for tc in &tool_calls {
                let id = tc.get("id").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let nm = tc.get("function").and_then(|f| f.get("name")).and_then(|v| v.as_str()).unwrap_or("").to_string();
                let arguments_str = tc.get("function").and_then(|f| f.get("arguments")).and_then(|v| v.as_str()).unwrap_or("{}");

                let result_str = execute_tool(&nm, arguments_str, &inventory, &rates);
                println!("RESULT {} {}", id, result_str);

                messages.push(Json::Obj(vec![
                    ("role".to_string(), Json::Str("tool".to_string())),
                    ("tool_call_id".to_string(), Json::Str(id)),
                    ("content".to_string(), Json::Str(result_str)),
                ]));
            }
        } else {
            let content = message.and_then(|m| m.get("content")).and_then(|c| c.as_str()).unwrap_or("");
            println!("FINAL {}", content);
            println!("USAGE prompt={} completion={} total={} requests={}", total_prompt, total_completion, total_total, num_requests);
            process::exit(0);
        }
    }
}

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles();
        if (files == null) return;

        List<File> wavFiles = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().endsWith(".wav")) {
                wavFiles.add(f);
            }
        }
        wavFiles.sort((a, b) -> {
            byte[] aBytes = a.getName().getBytes("UTF-8");
            byte[] bBytes = b.getName().getBytes("UTF-8");
            int minLen = Math.min(aBytes.length, bBytes.length);
            for (int i = 0; i < minLen; i++) {
                int cmp = (aBytes[i] & 0xFF) - (bBytes[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return aBytes.length - bBytes.length;
        });

        boolean first = true;
        for (File f : wavFiles) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File file) throws Exception {
        String name = file.getName();
        byte[] data = Files.readAllBytes(file.toPath());

        if (data.length < 12) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[0] != 'R' || data[1] != 'I' || data[2] != 'F' || data[3] != 'F') {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[8] != 'W' || data[9] != 'A' || data[10] != 'V' || data[11] != 'E') {
            System.out.println(name + ": unsupported");
            return;
        }

        int pos = 12;
        int formatTag = -1;
        int channels = -1;
        int sampleRate = -1;
        int bitsPerSample = -1;
        int effectiveFormat = -1;
        byte[] fmtBody = null;
        int fmtBodyLen = 0;
        byte[] dataBody = null;
        int dataBodyLen = 0;

        while (pos + 8 <= data.length) {
            String chunkId = new String(data, pos, 4, "US-ASCII");
            int chunkSize = readInt32LE(data, pos + 4);
            pos += 8;

            if (chunkId.equals("fmt ")) {
                fmtBodyLen = Math.min(chunkSize, data.length - pos);
                fmtBody = Arrays.copyOfRange(data, pos, pos + fmtBodyLen);
                if (fmtBodyLen >= 16) {
                    formatTag = readInt16LE(fmtBody, 0) & 0xFFFF;
                    channels = readInt16LE(fmtBody, 2) & 0xFFFF;
                    sampleRate = readInt32LE(fmtBody, 4);
                    bitsPerSample = readInt16LE(fmtBody, 14) & 0xFFFF;

                    if (formatTag == 0xFFFE && fmtBodyLen >= 26) {
                        effectiveFormat = readInt16LE(fmtBody, 24) & 0xFFFF;
                    } else {
                        effectiveFormat = formatTag;
                    }
                }
            } else if (chunkId.equals("data")) {
                dataBodyLen = Math.min(chunkSize, data.length - pos);
                dataBody = Arrays.copyOfRange(data, pos, pos + dataBodyLen);
            }

            pos += chunkSize;
            if (chunkSize % 2 != 0) pos++;
        }

        if (effectiveFormat != 1 || bitsPerSample != 16) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (channels < 1 || channels > 2) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (sampleRate != 8000 && sampleRate != 16000) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (dataBody == null) {
            System.out.println(name + ": unsupported");
            return;
        }

        int frameSize = 2 * channels;
        int numFrames = dataBodyLen / frameSize;
        short[] samples = new short[numFrames];
        for (int i = 0; i < numFrames; i++) {
            samples[i] = (short) readInt16LE(dataBody, i * frameSize);
        }

        int N = sampleRate / 50;
        int numBlocks = numFrames / N;

        double[] lowFreqs = {697, 770, 852, 941};
        double[] highFreqs = {1209, 1336, 1477, 1633};

        char[][] keypad = {
            {'1', '2', '3', 'A'},
            {'4', '5', '6', 'B'},
            {'7', '8', '9', 'C'},
            {'*', '0', '#', 'D'}
        };

        char[] labels = new char[numBlocks];
        Arrays.fill(labels, '\0');

        for (int i = 0; i < numBlocks; i++) {
            int offset = i * N;
            double E = 0;
            for (int n = 0; n < N; n++) {
                double x = samples[offset + n];
                E += x * x;
            }

            if (E < 1000000.0 * N) {
                continue;
            }

            double maxLowR = -1;
            int maxLowIdx = -1;
            double maxHighR = -1;
            int maxHighIdx = -1;

            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, offset, N, lowFreqs[fi], sampleRate, E);
                if (r > maxLowR) {
                    maxLowR = r;
                    maxLowIdx = fi;
                }
            }
            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, offset, N, highFreqs[fi], sampleRate, E);
                if (r > maxHighR) {
                    maxHighR = r;
                    maxHighIdx = fi;
                }
            }

            if (maxLowR >= 0.1 && maxHighR >= 0.1 && (maxLowR + maxHighR) >= 0.6) {
                labels[i] = keypad[maxLowIdx][maxHighIdx];
            }
        }

        // Bridging
        char[] bridged = Arrays.copyOf(labels, labels.length);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (labels[i] == '\0' && labels[i - 1] != '\0' && labels[i + 1] != '\0' && labels[i - 1] == labels[i + 1]) {
                bridged[i] = labels[i - 1];
            }
        }

        // Events: maximal runs of same digit >= 2 blocks
        List<int[]> events = new ArrayList<>();
        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] == '\0') {
                i++;
                continue;
            }
            char digit = bridged[i];
            int start = i;
            while (i < numBlocks && bridged[i] == digit) {
                i++;
            }
            int end = i - 1;
            if (end - start + 1 >= 2) {
                events.add(new int[]{start, end, digit});
            }
        }

        // Output
        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        for (int[] ev : events) {
            System.out.println((char) ev[2] + " " + (20 * ev[0]) + " " + (20 * (ev[1] + 1)));
        }
        StringBuilder digits = new StringBuilder();
        for (int[] ev : events) {
            digits.append((char) ev[2]);
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(short[] samples, int offset, int N, double freq, int rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[offset + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    static int readInt16LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }

    static int readInt32LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8) |
               ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }
}

