import Foundation

func readU16LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8)
}

func readU32LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8) | (Int(data[offset + 2]) << 16) | (Int(data[offset + 3]) << 24)
}

func readI16LE(_ data: [UInt8], _ offset: Int) -> Int {
    let val = Int(data[offset]) | (Int(data[offset + 1]) << 8)
    if val >= 32768 { return val - 65536 }
    return val
}

func processFile(path: String, name: String) -> String {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: path)) else {
        return "\(name): unsupported"
    }
    let bytes = [UInt8](data)

    // Check RIFF header
    guard bytes.count >= 12 else { return "\(name): unsupported" }
    guard bytes[0] == 0x52 && bytes[1] == 0x49 && bytes[2] == 0x46 && bytes[3] == 0x46 else {
        return "\(name): unsupported"
    }
    guard bytes[8] == 0x57 && bytes[9] == 0x41 && bytes[10] == 0x56 && bytes[11] == 0x45 else {
        return "\(name): unsupported"
    }

    // Parse chunks
    var fmtBody: [UInt8]? = nil
    var dataBody: [UInt8]? = nil
    var pos = 12

    while pos + 8 <= bytes.count {
        let chunkId = String(bytes: bytes[pos..<pos+4], encoding: .ascii) ?? ""
        let chunkSize = readU32LE(bytes, pos + 4)
        let bodyStart = pos + 8
        let bodyEnd = min(bodyStart + chunkSize, bytes.count)

        if chunkId == "fmt " {
            fmtBody = Array(bytes[bodyStart..<bodyEnd])
        } else if chunkId == "data" {
            dataBody = Array(bytes[bodyStart..<bodyEnd])
        }

        pos = bodyStart + chunkSize
        if chunkSize % 2 == 1 { pos += 1 }
    }

    guard let fmt = fmtBody, fmt.count >= 16 else { return "\(name): unsupported" }
    guard let dataBytes = dataBody else { return "\(name): unsupported" }

    let formatTag = readU16LE(fmt, 0)
    let channels = readU16LE(fmt, 2)
    let sampleRate = readU32LE(fmt, 4)
    let bitsPerSample = readU16LE(fmt, 14)

    var effectiveFormat = formatTag
    if formatTag == 0xFFFE {
        if fmt.count >= 26 {
            effectiveFormat = readU16LE(fmt, 24)
        } else {
            return "\(name): unsupported"
        }
    }

    guard effectiveFormat == 1 && bitsPerSample == 16 else {
        return "\(name): unsupported"
    }
    guard channels == 1 || channels == 2 else { return "\(name): unsupported" }
    guard sampleRate == 8000 || sampleRate == 16000 else { return "\(name): unsupported" }

    // Extract left channel samples
    let frameSize = 2 * channels
    let numFrames = dataBytes.count / frameSize
    var samples = [Int](repeating: 0, count: numFrames)
    for i in 0..<numFrames {
        samples[i] = readI16LE(dataBytes, i * frameSize)
    }

    // DTMF detection
    let N = sampleRate / 50
    let numBlocks = samples.count / N

    let lowFreqs: [Double] = [697, 770, 852, 941]
    let highFreqs: [Double] = [1209, 1336, 1477, 1633]

    let digitMap: [[String]] = [
        ["1", "2", "3", "A"],
        ["4", "5", "6", "B"],
        ["7", "8", "9", "C"],
        ["*", "0", "#", "D"]
    ]

    // Step 3: detect digits per block
    var labels = [String?](repeating: nil, count: numBlocks)

    for block in 0..<numBlocks {
        let start = block * N

        // Energy
        var E = 0.0
        for i in 0..<N {
            let v = Double(samples[start + i])
            E += v * v
        }

        if E < 1000000.0 * Double(N) { continue }

        // Goertzel for low frequencies
        var rLow = [Double](repeating: 0, count: 4)
        for fi in 0..<4 {
            let f = lowFreqs[fi]
            let c = 2.0 * cos(2.0 * Double.pi * f / Double(sampleRate))
            var s1 = 0.0, s2 = 0.0
            for n in 0..<N {
                let s = Double(samples[start + n]) + c * s1 - s2
                s2 = s1
                s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            rLow[fi] = 2.0 * P / (Double(N) * E)
        }

        // Goertzel for high frequencies
        var rHigh = [Double](repeating: 0, count: 4)
        for fi in 0..<4 {
            let f = highFreqs[fi]
            let c = 2.0 * cos(2.0 * Double.pi * f / Double(sampleRate))
            var s1 = 0.0, s2 = 0.0
            for n in 0..<N {
                let s = Double(samples[start + n]) + c * s1 - s2
                s2 = s1
                s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            rHigh[fi] = 2.0 * P / (Double(N) * E)
        }

        // Find max in each group
        var maxLowIdx = 0
        var maxHighIdx = 0
        for i in 1..<4 {
            if rLow[i] > rLow[maxLowIdx] { maxLowIdx = i }
            if rHigh[i] > rHigh[maxHighIdx] { maxHighIdx = i }
        }

        if rLow[maxLowIdx] >= 0.1 && rHigh[maxHighIdx] >= 0.1 && rLow[maxLowIdx] + rHigh[maxHighIdx] >= 0.6 {
            labels[block] = digitMap[maxLowIdx][maxHighIdx]
        }
    }

    // Step 4: Bridging
    var bridged = labels
    if numBlocks > 2 {
        for i in 1..<numBlocks-1 {
            if labels[i] == nil {
                if let prev = labels[i-1], let next = labels[i+1], prev == next {
                    bridged[i] = prev
                }
            }
        }
    }

    // Step 5: Events
    var events: [(digit: String, start: Int, end: Int)] = []
    var i = 0
    while i < numBlocks {
        if let d = bridged[i] {
            var j = i
            while j + 1 < numBlocks && bridged[j + 1] == d {
                j += 1
            }
            if j - i + 1 >= 2 {
                events.append((digit: d, start: 20 * i, end: 20 * (j + 1)))
            }
            i = j + 1
        } else {
            i += 1
        }
    }

    // Output
    var result = "\(name): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks\n"
    for e in events {
        result += "\(e.digit) \(e.start) \(e.end)\n"
    }
    let digitsStr = events.map { $0.digit }.joined()
    result += "digits: \(digitsStr)"

    return result
}

// Main
