import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];
const files = fs.readdirSync(dir)
  .filter(f => f.endsWith('.wav'))
  .sort((a, b) => Buffer.compare(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8')));

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];

const KEYPAD: string[][] = [
  ['1', '2', '3', 'A'],
  ['4', '5', '6', 'B'],
  ['7', '8', '9', 'C'],
  ['*', '0', '#', 'D'],
];

interface WavInfo {
  supported: boolean;
  rate: number;
  channels: number;
  samples: number[];
}

function parseWav(filepath: string): WavInfo {
  const buf = fs.readFileSync(filepath);

  if (buf.length < 12) return { supported: false, rate: 0, channels: 0, samples: [] };
  if (buf.toString('ascii', 0, 4) !== 'RIFF') return { supported: false, rate: 0, channels: 0, samples: [] };
  if (buf.toString('ascii', 8, 12) !== 'WAVE') return { supported: false, rate: 0, channels: 0, samples: [] };

  let offset = 12;
  let fmtBody: Buffer | null = null;
  let dataBody: Buffer | null = null;

  while (offset + 8 <= buf.length) {
    const id = buf.toString('ascii', offset, offset + 4);
    const size = buf.readUInt32LE(offset + 4);
    const bodyStart = offset + 8;

    if (id === 'fmt ') {
      fmtBody = buf.subarray(bodyStart, bodyStart + size);
    } else if (id === 'data') {
      dataBody = buf.subarray(bodyStart, bodyStart + size);
    }

    offset = bodyStart + size + (size % 2);
  }

  if (!fmtBody || !dataBody) return { supported: false, rate: 0, channels: 0, samples: [] };

  const formatTag = fmtBody.readUInt16LE(0);
  const channels = fmtBody.readUInt16LE(2);
  const rate = fmtBody.readUInt32LE(4);
  const bitsPerSample = fmtBody.readUInt16LE(14);

  let effectiveFormat = formatTag;
  if (formatTag === 0xFFFE) {
    if (fmtBody.length < 26) return { supported: false, rate, channels, samples: [] };
    effectiveFormat = fmtBody.readUInt16LE(24);
  }

  if (effectiveFormat !== 1 || bitsPerSample !== 16) {
    return { supported: false, rate, channels, samples: [] };
  }

  if ((channels !== 1 && channels !== 2) || (rate !== 8000 && rate !== 16000)) {
    return { supported: false, rate, channels, samples: [] };
  }

  const frameSize = 2 * channels;
  const numFrames = Math.floor(dataBody.length / frameSize);
  const samples: number[] = new Array(numFrames);

  for (let i = 0; i < numFrames; i++) {
    samples[i] = dataBody.readInt16LE(i * frameSize);
  }

  return { supported: true, rate, channels, samples };
}

function goertzelPower(samples: number[], start: number, N: number, freq: number, rate: number): number {
  const c = 2 * Math.cos(2 * Math.PI * freq / rate);
  let s1 = 0, s2 = 0;
  for (let n = 0; n < N; n++) {
    const s = samples[start + n] + c * s1 - s2;
    s2 = s1;
    s1 = s;
  }
  return s1 * s1 + s2 * s2 - c * s1 * s2;
}

function detectDigit(samples: number[], blockStart: number, N: number, rate: number): string | null {
  let E = 0;
  for (let n = 0; n < N; n++) {
    const v = samples[blockStart + n];
    E += v * v;
  }

  if (E < 1000000 * N) return null;

  let maxLowR = -1, maxLowIdx = 0;
  let maxHighR = -1, maxHighIdx = 0;

  for (let i = 0; i < 4; i++) {
    const P = goertzelPower(samples, blockStart, N, LOW_FREQS[i], rate);
    const r = 2 * P / (N * E);
    if (r > maxLowR) {
      maxLowR = r;
      maxLowIdx = i;
    }
  }

  for (let i = 0; i < 4; i++) {
    const P = goertzelPower(samples, blockStart, N, HIGH_FREQS[i], rate);
    const r = 2 * P / (N * E);
    if (r > maxHighR) {
      maxHighR = r;
      maxHighIdx = i;
    }
  }

  if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
    return KEYPAD[maxLowIdx][maxHighIdx];
  }

  return null;
}

const results: string[] = [];

for (const file of files) {
  const filepath = path.join(dir, file);
  const info = parseWav(filepath);

  if (!info.supported) {
    results.push(`${file}: unsupported`);
    continue;
  }

  const { rate, channels, samples } = info;
  const N = rate / 50;
  const numBlocks = Math.floor(samples.length / N);

  const labels: (string | null)[] = new Array(numBlocks);
  for (let i = 0; i < numBlocks; i++) {
    labels[i] = detectDigit(samples, i * N, N, rate);
  }

  // Bridging: use original labels for decision
  const bridged: (string | null)[] = [...labels];
  for (let i = 1; i < numBlocks - 1; i++) {
    if (labels[i] === null && labels[i - 1] !== null && labels[i + 1] !== null && labels[i - 1] === labels[i + 1]) {
      bridged[i] = labels[i - 1];
    }
  }

  // Events: maximal runs of same digit, length >= 2
  const events: { digit: string; start: number; end: number }[] = [];
  let i = 0;
  while (i < numBlocks) {
    if (bridged[i] !== null) {
      const digit = bridged[i]!;
      const startIdx = i;
      while (i < numBlocks && bridged[i] === digit) i++;
      const endIdx = i - 1;
      if (endIdx - startIdx + 1 >= 2) {
        events.push({ digit, start: 20 * startIdx, end: 20 * (endIdx + 1) });
      }
    } else {
      i++;
    }
  }

  const lines: string[] = [];
  lines.push(`${file}: ${rate} Hz, ${channels} ch, ${numBlocks} blocks`);
  for (const ev of events) {
    lines.push(`${ev.digit} ${ev.start} ${ev.end}`);
  }
  lines.push(`digits: ${events.map(e => e.digit).join('')}`);
  results.push(lines.join('\n'));
}

process.stdout.write(results.join('\n\n') + '\n');

use std::env;
use std::fs;
use std::io::Read;
use std::path::Path;

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    (data[offset] as u16) | ((data[offset + 1] as u16) << 8)
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    (data[offset] as u32)
        | ((data[offset + 1] as u32) << 8)
        | ((data[offset + 2] as u32) << 16)
        | ((data[offset + 3] as u32) << 24)
}

fn goertzel(block: &[f64], freq: f64, rate: f64, n: usize, e: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for i in 0..n {
        let s = block[i] + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n as f64 * e)
}

fn process_file(name: &str, data: &[u8]) {
    if data.len() < 12 || &data[0..4] != b"RIFF" || &data[8..12] != b"WAVE" {
        println!("{}: unsupported", name);
        return;
    }

    let mut pos = 12;
    let mut fmt_body: Option<Vec<u8>> = None;
    let mut data_body: Option<Vec<u8>> = None;

    while pos + 8 <= data.len() {
        let chunk_id = &data[pos..pos + 4];
        let chunk_size = read_u32_le(data, pos + 4) as usize;
        let body_start = pos + 8;
        let body_end = body_start + chunk_size;

        if body_end > data.len() {
            break;
        }

        if chunk_id == b"fmt " {
            fmt_body = Some(data[body_start..body_end].to_vec());
        } else if chunk_id == b"data" {
            data_body = Some(data[body_start..body_end].to_vec());
        }

        pos = body_end + if chunk_size % 2 == 1 { 1 } else { 0 };
    }

    let fmt = match fmt_body {
        Some(f) => f,
        None => {
            println!("{}: unsupported", name);
            return;
        }
    };
    let data_chunk = match data_body {
        Some(d) => d,
        None => {
            println!("{}: unsupported", name);
            return;
        }
    };

    if fmt.len() < 16 {
        println!("{}: unsupported", name);
        return;
    }

    let format_tag = read_u16_le(&fmt, 0);
    let channels = read_u16_le(&fmt, 2) as usize;
    let sample_rate = read_u32_le(&fmt, 4) as usize;
    let bits_per_sample = read_u16_le(&fmt, 14) as usize;

    let effective_format = if format_tag == 0xFFFE {
        if fmt.len() < 26 {
            println!("{}: unsupported", name);
            return;
        }
        read_u16_le(&fmt, 24)
    } else {
        format_tag
    };

    if effective_format != 1 || bits_per_sample != 16 {
        println!("{}: unsupported", name);
        return;
    }

    if (channels != 1 && channels != 2) || (sample_rate != 8000 && sample_rate != 16000) {
        println!("{}: unsupported", name);
        return;
    }

    // Extract left channel samples
    let bytes_per_frame = 2 * channels;
    let num_frames = data_chunk.len() / bytes_per_frame;

    let mut samples: Vec<f64> = Vec::with_capacity(num_frames);
    for i in 0..num_frames {
        let offset = i * bytes_per_frame;
        let raw = (data_chunk[offset] as u16) | ((data_chunk[offset + 1] as u16) << 8);
        samples.push(raw as i16 as f64);
    }

    // Detection
    let n = sample_rate / 50;
    let num_blocks = samples.len() / n;

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];
    let digit_map: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut labels: Vec<Option<char>> = vec![None; num_blocks];

    for i in 0..num_blocks {
        let block = &samples[i * n..(i + 1) * n];

        let e: f64 = block.iter().map(|x| x * x).sum();

        if e < 1000000.0 * n as f64 {
            continue;
        }

        let mut best_low_idx = 0usize;
        let mut best_low_r = -1.0f64;
        let mut best_high_idx = 0usize;
        let mut best_high_r = -1.0f64;

        for fi in 0..4 {
            let r = goertzel(block, low_freqs[fi], sample_rate as f64, n, e);
            if r > best_low_r {
                best_low_r = r;
                best_low_idx = fi;
            }
        }

        for fi in 0..4 {
            let r = goertzel(block, high_freqs[fi], sample_rate as f64, n, e);
            if r > best_high_r {
                best_high_r = r;
                best_high_idx = fi;
            }
        }

        if best_low_r >= 0.1 && best_high_r >= 0.1 && best_low_r + best_high_r >= 0.6 {
            labels[i] = Some(digit_map[best_low_idx][best_high_idx]);
        }
    }

    // Bridging
    let mut bridged = labels.clone();
    for i in 0..num_blocks {
        if labels[i].is_none() && i > 0 && i + 1 < num_blocks {
            if labels[i - 1].is_some() && labels[i - 1] == labels[i + 1] {
                bridged[i] = labels[i - 1];
            }
        }
    }

    // Events
    let mut events: Vec<(char, usize, usize)> = Vec::new();
    let mut i = 0;
    while i < num_blocks {
        if let Some(d) = bridged[i] {
            let start = i;
            while i < num_blocks && bridged[i] == Some(d) {
                i += 1;
            }
            let end = i; // exclusive
            if end - start >= 2 {
                events.push((d, 20 * start, 20 * end));
            }
        } else {
            i += 1;
        }
    }

    // Output
    println!("{}: {} Hz, {} ch, {} blocks", name, sample_rate, channels, num_blocks);
    for (d, start, end) in &events {
        println!("{} {} {}", d, start, end);
    }
    let digits: String = events.iter().map(|(d, _, _)| *d).collect();
    println!("digits: {}", digits);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    let entries = fs::read_dir(dir).unwrap();
    for entry in entries {
        let entry = entry.unwrap();
        let name = entry.file_name().to_string_lossy().to_string();
        if name.ends_with(".wav") {
            files.push(name);
        }
    }
    files.sort();

    let mut first = true;
    for name in &files {
        if !first {
            println!();
        }
        first = false;

        let path = Path::new(dir).join(name);
        let mut data = Vec::new();
        fs::File::open(&path)
            .unwrap()
            .read_to_end(&mut data)
            .unwrap();

        process_file(name, &data);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <math.h>
#include <stdint.h>

static uint16_t read_u16(const uint8_t *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t read_u32(const uint8_t *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24));
}

static int16_t read_i16(const uint8_t *p) {
    return (int16_t)(p[0] | (p[1] << 8));
}

static const double low_freqs[4] = {697, 770, 852, 941};
static const double high_freqs[4] = {1209, 1336, 1477, 1633};

static const char keypad[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

typedef struct {
    char *name;
} FileEntry;

static int cmp_files(const void *a, const void *b) {
    const FileEntry *fa = (const FileEntry *)a;
    const FileEntry *fb = (const FileEntry *)b;
    return strcmp(fa->name, fb->name);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    const char *dirpath = argv[1];

    DIR *dir = opendir(dirpath);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    FileEntry *files = NULL;
    int nfiles = 0, cap = 0;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        const char *name = ent->d_name;
        size_t len = strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            if (nfiles >= cap) {
                cap = cap ? cap * 2 : 16;
                files = realloc(files, cap * sizeof(FileEntry));
            }
            files[nfiles].name = strdup(name);
            nfiles++;
        }
    }
    closedir(dir);

    qsort(files, nfiles, sizeof(FileEntry), cmp_files);

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", dirpath, files[fi].name);

        FILE *fp = fopen(path, "rb");
        if (!fp) {
            printf("%s: unsupported\n", files[fi].name);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        uint8_t *buf = malloc(fsize > 0 ? fsize : 1);
        if (fsize > 0) {
            size_t rd = fread(buf, 1, fsize, fp);
            (void)rd;
        }
        fclose(fp);

        if (fsize < 12 || memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", files[fi].name);
            free(buf);
            continue;
        }

        const uint8_t *fmt_body = NULL;
        uint32_t fmt_size = 0;
        const uint8_t *data_body = NULL;
        uint32_t data_size = 0;

        uint32_t pos = 12;
        while (pos + 8 <= (uint32_t)fsize) {
            const uint8_t *chunk_id = buf + pos;
            uint32_t chunk_size = read_u32(buf + pos + 4);
            uint32_t body_start = pos + 8;

            if (body_start + chunk_size > (uint32_t)fsize)
                break;

            if (memcmp(chunk_id, "fmt ", 4) == 0) {
                fmt_body = buf + body_start;
                fmt_size = chunk_size;
            } else if (memcmp(chunk_id, "data", 4) == 0) {
                data_body = buf + body_start;
                data_size = chunk_size;
            }

            pos = body_start + chunk_size;
            if (chunk_size & 1) pos++;
        }

        if (!fmt_body || !data_body || fmt_size < 16) {
            printf("%s: unsupported\n", files[fi].name);
            free(buf);
            continue;
        }

        uint16_t format_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t sample_rate = read_u32(fmt_body + 4);
        uint16_t bits_per_sample = read_u16(fmt_body + 14);

        uint16_t effective_format = format_tag;
        if (format_tag == 0xFFFE) {
            if (fmt_size >= 26) {
                effective_format = read_u16(fmt_body + 24);
            } else {
                printf("%s: unsupported\n", files[fi].name);
                free(buf);
                continue;
            }
        }

        if (effective_format != 1 || bits_per_sample != 16 ||
            (channels != 1 && channels != 2) ||
            (sample_rate != 8000 && sample_rate != 16000)) {
            printf("%s: unsupported\n", files[fi].name);
            free(buf);
            continue;
        }

        int frames = (int)(data_size / (2 * channels));
        int16_t *samples = malloc(frames * sizeof(int16_t));
        for (int i = 0; i < frames; i++) {
            samples[i] = read_i16(data_body + (size_t)i * 2 * channels);
        }

        int N = (int)(sample_rate / 50);
        int nblocks = frames / N;

        printf("%s: %u Hz, %u ch, %d blocks\n", files[fi].name, sample_rate, channels, nblocks);

        char *labels = calloc(nblocks, 1);

        for (int b = 0; b < nblocks; b++) {
            int16_t *x = samples + (size_t)b * N;

            double E = 0;
            for (int n = 0; n < N; n++) {
                double v = (double)x[n];
                E += v * v;
            }

            if (E < 1000000.0 * N) {
                labels[b] = 0;
                continue;
            }

            double r_low[4], r_high[4];

            for (int i = 0; i < 4; i++) {
                double f = low_freqs[i];
                double c = 2.0 * cos(2.0 * M_PI * f / (double)sample_rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = (double)x[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[i] = 2.0 * P / ((double)N * E);
            }

            for (int i = 0; i < 4; i++) {
                double f = high_freqs[i];
                double c = 2.0 * cos(2.0 * M_PI * f / (double)sample_rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = (double)x[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[i] = 2.0 * P / ((double)N * E);
            }

            int best_low = 0, best_high = 0;
            for (int i = 1; i < 4; i++) {
                if (r_low[i] > r_low[best_low]) best_low = i;
                if (r_high[i] > r_high[best_high]) best_high = i;
            }

            if (r_low[best_low] >= 0.1 && r_high[best_high] >= 0.1 &&
                r_low[best_low] + r_high[best_high] >= 0.6) {
                labels[b] = keypad[best_low][best_high];
            } else {
                labels[b] = 0;
            }
        }

        /* Bridging */
        char *bridged = malloc(nblocks);
        memcpy(bridged, labels, nblocks);
        for (int b = 1; b < nblocks - 1; b++) {
            if (labels[b] == 0 && labels[b - 1] != 0 && labels[b - 1] == labels[b + 1]) {
                bridged[b] = labels[b - 1];
            }
        }

        /* Events */
        char *digits_str = malloc(nblocks + 1);
        int dpos = 0;

        int b = 0;
        while (b < nblocks) {
            if (bridged[b] == 0) { b++; continue; }
            int start = b;
            char digit = bridged[b];
            while (b < nblocks && bridged[b] == digit) b++;
            int end = b;
            if (end - start >= 2) {
                int start_ms = 20 * start;
                int end_ms = 20 * end;
                printf("%c %d %d\n", digit, start_ms, end_ms);
                digits_str[dpos++] = digit;
            }
        }
        digits_str[dpos] = '\0';
        printf("digits: %s\n", digits_str);

        free(digits_str);
        free(bridged);
        free(labels);
        free(samples);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i].name);
    free(files);

    return 0;
}

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;

public class Main {
    static class TypeRec {
        int offset;
        boolean isdst;
        String abbr;
    }

    static class TZData {
        long[] transTimes;
        int[] transTypes;
        TypeRec[] types;
        String stdName;
        int stdPosixOffset;
        int stdUtcOffset;
        String dstName;
        int dstPosixOffset;
        int dstUtcOffset;
        boolean hasDst;
        boolean hasRules;
        int startMonth, startWeek, startDay, startTimeSec;
        int endMonth, endWeek, endDay, endTimeSec;
    }

    static class Segment {
        long start, end;
        int offset;
        String abbr;
        Segment(long start, long end, int offset, String abbr) {
            this.start = start; this.end = end; this.offset = offset; this.abbr = abbr;
        }
    }

    static String pstr;
    static int ppos;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String content = Files.readString(Path.of(dir, "queries.txt"));
        String[] lines = content.split("\n");
        Map<String, List<Segment>> cache = new HashMap<>();
        StringBuilder sb = new StringBuilder();

        for (String line : lines) {
            if (line.isBlank()) continue;
            String[] parts = line.split(" ");
            String qtype = parts[0];
            String fname = parts[1];

            List<Segment> segs = cache.computeIfAbsent(fname, f -> {
                try {
                    return buildSegments(parseTZif(Path.of(dir, f)));
                } catch (Exception e) { throw new RuntimeException(e); }
            });

            if (qtype.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                sb.append(line).append(" -> ").append(utcToLocal(t, segs)).append("\n");
            } else {
                long wall = parseWallClock(parts[2]);
                sb.append(line).append(" -> ").append(localToUTC(wall, segs)).append("\n");
            }
        }
        System.out.print(sb);
    }

    static TZData parseTZif(Path path) throws Exception {
        byte[] data = Files.readAllBytes(path);
        ByteBuffer buf = ByteBuffer.wrap(data);
        buf.order(ByteOrder.BIG_ENDIAN);

        // First header
        buf.position(20);
        int isutcnt1 = buf.getInt();
        int isstdcnt1 = buf.getInt();
        int leapcnt1 = buf.getInt();
        int timecnt1 = buf.getInt();
        int typecnt1 = buf.getInt();
        int charcnt1 = buf.getInt();
        int block1Size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        buf.position(buf.position() + block1Size);

        // Second header
        buf.position(buf.position() + 4); // magic
        buf.position(buf.position() + 1); // version
        buf.position(buf.position() + 15); // unused
        int isutcnt = buf.getInt();
        int isstdcnt = buf.getInt();
        int leapcnt = buf.getInt();
        int timecnt = buf.getInt();
        int typecnt = buf.getInt();
        int charcnt = buf.getInt();

        // Second data block
        long[] transTimes = new long[timecnt];
        for (int i = 0; i < timecnt; i++) transTimes[i] = buf.getLong();

        int[] transTypes = new int[timecnt];
        for (int i = 0; i < timecnt; i++) transTypes[i] = buf.get() & 0xFF;

        int[] typeOffsets = new int[typecnt];
        boolean[] typeIsDst = new boolean[typecnt];
        int[] typeAbbrIdx = new int[typecnt];
        for (int i = 0; i < typecnt; i++) {
            typeOffsets[i] = buf.getInt();
            typeIsDst[i] = buf.get() != 0;
            typeAbbrIdx[i] = buf.get() & 0xFF;
        }

        byte[] charBytes = new byte[charcnt];
        buf.get(charBytes);
        buf.position(buf.position() + leapcnt * 12 + isstdcnt + isutcnt);

        // Footer
        buf.get(); // leading newline
        int footerStart = buf.position();
        int footerEnd = footerStart;
        while (footerEnd < data.length && data[footerEnd] != '\n') footerEnd++;
        String posixTZ = new String(data, footerStart, footerEnd - footerStart, java.nio.charset.StandardCharsets.US_ASCII).trim();

        TZData tz = new TZData();
        tz.transTimes = transTimes;
        tz.transTypes = transTypes;
        tz.types = new TypeRec[typecnt];
        for (int i = 0; i < typecnt; i++) {
            tz.types[i] = new TypeRec();
            tz.types[i].offset = typeOffsets[i];
            tz.types[i].isdst = typeIsDst[i];
            int s = typeAbbrIdx[i];
            int e = s;
            while (e < charBytes.length && charBytes[e] != 0) e++;
            tz.types[i].abbr = new String(charBytes, s, e - s, java.nio.charset.StandardCharsets.US_ASCII);
        }

        if (!posixTZ.isEmpty()) {
            parsePosixTZ(posixTZ, tz);
        } else {
            tz.hasDst = false;
            tz.hasRules = false;
            tz.stdName = tz.types.length > 0 ? tz.types[0].abbr : "UTC";
            tz.stdUtcOffset = tz.types.length > 0 ? tz.types[0].offset : 0;
            tz.stdPosixOffset = -tz.stdUtcOffset;
        }
        return tz;
    }

    static void parsePosixTZ(String s, TZData data) {
        pstr = s;
        ppos = 0;

        data.stdName = readName();
        data.hasDst = false;
        data.hasRules = false;

        if (ppos < pstr.length() && (Character.isDigit(pstr.charAt(ppos)) || pstr.charAt(ppos) == '+' || pstr.charAt(ppos) == '-')) {
            data.stdPosixOffset = readOffset();
        } else {
            data.stdPosixOffset = 0;
        }
        data.stdUtcOffset = -data.stdPosixOffset;

        if (ppos < pstr.length() && (Character.isLetter(pstr.charAt(ppos)) || pstr.charAt(ppos) == '<')) {
            data.dstName = readName();
            data.hasDst = true;

            if (ppos < pstr.length() && (Character.isDigit(pstr.charAt(ppos)) || pstr.charAt(ppos) == '+' || pstr.charAt(ppos) == '-')) {
                data.dstPosixOffset = readOffset();
            } else {
                data.dstUtcOffset = data.stdUtcOffset + 3600;
                data.dstPosixOffset = -data.dstUtcOffset;
            }
            if (data.dstUtcOffset == 0 && data.dstPosixOffset != 0) {
                // already set
            } else if (data.dstPosixOffset != 0 || data.dstUtcOffset != 0) {
                // already set above or below
            }
            if (ppos < pstr.length() && (Character.isDigit(pstr.charAt(ppos)) || pstr.charAt(ppos) == '+' || pstr.charAt(ppos) == '-')) {
                data.dstPosixOffset = readOffset();
            }
            data.dstUtcOffset = -data.dstPosixOffset;

            if (ppos < pstr.length() && pstr.charAt(ppos) == ',') {
                ppos++;
                parseRule(data, true);
                if (ppos < pstr.length() && pstr.charAt(ppos) == ',') ppos++;
                parseRule(data, false);
                data.hasRules = true;
            }
        }
    }

    static String readName() {
        if (pstr.charAt(ppos) == '<') {
            int end = pstr.indexOf('>', ppos);
            String name = pstr.substring(ppos + 1, end);
            ppos = end + 1;
            return name;
        } else {
            int start = ppos;
            while (ppos < pstr.length() && Character.isLetter(pstr.charAt(ppos))) ppos++;
            return pstr.substring(start, ppos);
        }
    }

    static int readOffset() {
        int sign = 1;
        if (ppos < pstr.length() && (pstr.charAt(ppos) == '+' || pstr.charAt(ppos) == '-')) {
            if (pstr.charAt(ppos) == '-') sign = -1;
            ppos++;
        }
        int h = readNumber();
        int m = 0, s = 0;
        if (ppos < pstr.length() && pstr.charAt(ppos) == ':') {
            ppos++;
            m = readNumber();
            if (ppos < pstr.length() && pstr.charAt(ppos) == ':') {
                ppos++;
                s = readNumber();
            }
        }
        return sign * (h * 3600 + m * 60 + s);
    }

    static int readNumber() {
        int start = ppos;
        while (ppos < pstr.length() && Character.isDigit(pstr.charAt(ppos))) ppos++;
        return Integer.parseInt(pstr.substring(start, ppos));
    }

    static void parseRule(TZData data, boolean isStart) {
        ppos++; // skip 'M'
        int m = readNumber();
        ppos++; // skip '.'
        int w = readNumber();
        ppos++; // skip '.'
        int d = readNumber();
        int timeSec = 2 * 3600;
        if (ppos < pstr.length() && pstr.charAt(ppos) == '/') {
            ppos++;
            timeSec = readOffset();
        }
        if (isStart) {
            data.startMonth = m; data.startWeek = w; data.startDay = d; data.startTimeSec = timeSec;
        } else {
            data.endMonth = m; data.endWeek = w; data.endDay = d; data.endTimeSec = timeSec;
        }
    }

    static List<Segment> buildSegments(TZData tz) {
        List<Segment> segments = new ArrayList<>();
        List<long[]> transList = new ArrayList<>();

        for (int i = 0; i < tz.transTimes.length; i++) {
            transList.add(new long[]{tz.transTimes[i], tz.transTypes[i]});
        }

        long lastTrans = tz.transTimes.length > 0 ? tz.transTimes[tz.transTimes.length - 1] : Long.MIN_VALUE;

        if (tz.hasDst && tz.hasRules) {
            for (int year = 1799; year <= 2401; year++) {
                long startUtc = posixTransUtc(year, tz.startMonth, tz.startWeek, tz.startDay, tz.startTimeSec, tz.stdUtcOffset);
                long endUtc = posixTransUtc(year, tz.endMonth, tz.endWeek, tz.endDay, tz.endTimeSec, tz.dstUtcOffset);
                if (startUtc > lastTrans) transList.add(new long[]{startUtc, -1});
                if (endUtc > lastTrans) transList.add(new long[]{endUtc, -2});
            }
        }

        transList.sort((a, b) -> Long.compare(a[0], b[0]));

        // Remove duplicates at same time, keeping first (file transitions come first due to sort stability)
        List<long[]> filtered = new ArrayList<>();
        for (int i = 0; i < transList.size(); i++) {
            if (i == 0 || transList.get(i)[0] != transList.get(i - 1)[0]) {
                filtered.add(transList.get(i));
            }
        }

        long prevTime = Long.MIN_VALUE;
        int prevType = 0;

        for (long[] tr : filtered) {
            long time = tr[0];
            int type = (int) tr[1];
            if (time > prevTime) {
                segments.add(makeSegment(prevTime, time, prevType, tz));
                prevTime = time;
                prevType = type;
            }
        }

        if (tz.hasDst && tz.hasRules) {
            segments.add(makeSegment(prevTime, Long.MAX_VALUE, prevType, tz));
        } else if (tz.stdName != null) {
            segments.add(makeSegment(prevTime, Long.MAX_VALUE, -2, tz));
        } else {
            segments.add(makeSegment(prevTime, Long.MAX_VALUE, prevType, tz));
        }

        return segments;
    }

    static Segment makeSegment(long start, long end, int type, TZData tz) {
        if (type == -1) return new Segment(start, end, tz.dstUtcOffset, tz.dstName);
        if (type == -2) return new Segment(start, end, tz.stdUtcOffset, tz.stdName);
        TypeRec tr = tz.types[type];
        return new Segment(start, end, tr.offset, tr.abbr);
    }

    static long posixTransUtc(int year, int month, int week, int day, int timeSec, int utcOffset) {
        int dom = nthWeekdayOfMonth(year, month, day, week);
        LocalDate date = LocalDate.of(year, month, dom);
        long epochSecs = date.toEpochDay() * 86400L + timeSec;
        return epochSecs - utcOffset;
    }

    static int nthWeekdayOfMonth(int year, int month, int weekday, int week) {
        LocalDate first = LocalDate.of(year, month, 1);
        int firstDow = first.getDayOfWeek().getValue(); // 1=Mon..7=Sun
        int firstDowSun = firstDow % 7; // 0=Sun,1=Mon,...,6=Sat
        int diff = (weekday - firstDowSun + 7) % 7;
        int firstDay = 1 + diff;
        if (week == 5) {
            int lastDayOfMonth = first.lengthOfMonth();
            int last = firstDay + 28;
            if (last > lastDayOfMonth) last -= 7;
            return last;
        } else {
            return firstDay + (week - 1) * 7;
        }
    }

    static String utcToLocal(long t, List<Segment> segs) {
        int lo = 0, hi = segs.size() - 1;
        while (lo < hi) {
            int mid = (lo + hi + 1) >>> 1;
            if (segs.get(mid).start <= t) lo = mid;
            else hi = mid - 1;
        }
        Segment seg = segs.get(lo);
        return formatLocalTime(t, seg.offset) + " " + seg.abbr;
    }

    static String localToUTC(long wall, List<Segment> segs) {
        List<long[]> results = new ArrayList<>();
        List<String> abbrs = new ArrayList<>();

        for (Segment seg : segs) {
            long t = wall - seg.offset;
            if (t >= seg.start && t < seg.end) {
                results.add(new long[]{t, seg.offset});
                abbrs.add(seg.abbr);
            }
        }

        if (results.size() == 1) {
            long t = results.get(0)[0];
            int offset = (int) results.get(0)[1];
            return t + " " + formatOffset(offset) + " " + abbrs.get(0);
        } else if (results.size() >= 2) {
            // Sort by t
            int n = results.size();
            for (int i = 0; i < n - 1; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (results.get(j)[0] < results.get(i)[0]) {
                        Collections.swap(results, i, j);
                        Collections.swap(abbrs, i, j);
                    }
                }
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if (i > 0) sb.append(" | ");
                sb.append(results.get(i)[0]).append(" ").append(formatOffset((int) results.get(i)[1])).append(" ").append(abbrs.get(i));
            }
            return sb.toString();
        } else {
            // Gap
            for (int i = 0; i < segs.size() - 1; i++) {
                Segment a = segs.get(i);
                Segment b = segs.get(i + 1);
                if (a.end != b.start) continue;
                long gapStart = a.end + a.offset;
                long gapEnd = b.start + b.offset;
                if (gapStart <= wall && wall < gapEnd) {
                    int offsetBefore = a.offset;
                    long t = wall - offsetBefore;
                    String localStr = formatLocalTime(t, b.offset);
                    return "GAP " + t + " " + localStr + " " + b.abbr;
                }
            }
            return "GAP 0 1970-01-01T00:00:00+00:00 UTC";
        }
    }

    static long parseWallClock(String s) {
        int year = Integer.parseInt(s.substring(0, 4));
        int month = Integer.parseInt(s.substring(5, 7));
        int day = Integer.parseInt(s.substring(8, 10));
        int hour = Integer.parseInt(s.substring(11, 13));
        int min = Integer.parseInt(s.substring(14, 16));
        int sec = Integer.parseInt(s.substring(17, 19));
        LocalDate date = LocalDate.of(year, month, day);
        return date.toEpochDay() * 86400L + hour * 3600L + min * 60L + sec;
    }

    static String formatLocalTime(long epochSec, int offsetSec) {
        long localSec = epochSec + offsetSec;
        long day = Math.floorDiv(localSec, 86400);
        long secOfDay = Math.floorMod(localSec, 86400);
        LocalDate date = LocalDate.ofEpochDay(day);
        int h = (int) (secOfDay / 3600);
        int m = (int) ((secOfDay % 3600) / 60);
        int s = (int) (secOfDay % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d%s",
                date.getYear(), date.getMonthValue(), date.getDayOfMonth(), h, m, s, formatOffset(offsetSec));
    }

    static String formatOffset(int offsetSec) {
        char sign = offsetSec >= 0 ? '+' : '-';
        int abs = Math.abs(offsetSec);
        int h = abs / 3600;
        int m = (abs % 3600) / 60;
        int s = abs % 60;
        if (s != 0) {
            return String.format("%c%02d:%02d:%02d", sign, h, m, s);
        } else {
            return String.format("%c%02d:%02d", sign, h, m);
        }
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    static final SecureRandom random = new SecureRandom();

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            handleSession(args[i]);
        }
    }

    static void handleSession(String url) throws Exception {
        String rest = url.substring(5);
        int slashIdx = rest.indexOf('/');
        String hostPort;
        String requestTarget;
        if (slashIdx == -1) {
            hostPort = rest;
            requestTarget = "/";
        } else {
            hostPort = rest.substring(0, slashIdx);
            requestTarget = rest.substring(slashIdx);
        }

        int colonIdx = hostPort.lastIndexOf(':');
        String host = hostPort.substring(0, colonIdx);
        int port = Integer.parseInt(hostPort.substring(colonIdx + 1));

        try (Socket socket = new Socket(host, port)) {
            socket.setTcpNoDelay(true);
            InputStream in = new BufferedInputStream(socket.getInputStream());
            OutputStream out = socket.getOutputStream();

            byte[] keyBytes = new byte[16];
            random.nextBytes(keyBytes);
            String key = Base64.getEncoder().encodeToString(keyBytes);

            String req = "GET " + requestTarget + " HTTP/1.1\r\n"
                    + "Host: " + hostPort + "\r\n"
                    + "Upgrade: websocket\r\n"
                    + "Connection: Upgrade\r\n"
                    + "Sec-WebSocket-Version: 13\r\n"
                    + "Sec-WebSocket-Key: " + key + "\r\n"
                    + "\r\n";
            out.write(req.getBytes(StandardCharsets.US_ASCII));
            out.flush();

            String statusLine = readLine(in);
            if (statusLine == null) return;

            String[] parts = statusLine.split(" ", 3);
            int statusCode = Integer.parseInt(parts[1]);
            String reasonPhrase = parts.length > 2 ? parts[2] : "";

            String acceptHeader = null;
            String line;
            while ((line = readLine(in)) != null && !line.isEmpty()) {
                int ci = line.indexOf(':');
                if (ci >= 0) {
                    String name = line.substring(0, ci).trim();
                    String value = line.substring(ci + 1).trim();
                    if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                        acceptHeader = value;
                    }
                }
            }

            if (statusCode != 101) {
                System.out.println("handshake failed: " + statusCode + " " + reasonPhrase);
                return;
            }

            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
            byte[] digest = sha1.digest((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII));
            String expectedAccept = Base64.getEncoder().encodeToString(digest);

            if (acceptHeader == null || !acceptHeader.equals(expectedAccept)) {
                System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                return;
            }

            processFrames(in, out);
        }
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int c2 = in.read();
                if (c2 == '\n') return sb.toString();
                sb.append('\r');
                if (c2 != -1) sb.append((char) c2);
            } else {
                sb.append((char) c);
            }
        }
        return sb.length() > 0 ? sb.toString() : null;
    }

    static void processFrames(InputStream in, OutputStream out) throws Exception {
        boolean closeSent = false;
        try {
            while (true) {
                Message msg = readMessage(in, out);

                if (msg.opcode == 8) {
                    handleClose(msg.payload, out, closeSent);
                    return;
                }

                if (msg.opcode == 1) {
                    String text = new String(msg.payload, StandardCharsets.UTF_8);

                    if (text.equals("BYE")) {
                        sendClose(out, 1000);
                        closeSent = true;
                        while (true) {
                            Message m = readMessage(in, out);
                            if (m.opcode == 8) {
                                handleClose(m.payload, out, closeSent);
                                return;
                            }
                        }
                    } else if (text.equals("SHA1")) {
                        Message next = readMessage(in, out);
                        if (next.opcode == 8) {
                            handleClose(next.payload, out, closeSent);
                            return;
                        }
                        byte[] hash = MessageDigest.getInstance("SHA-1").digest(next.payload);
                        String hex = bytesToHex(hash);
                        sendText(out, hex);
                        System.out.println("SHA1 " + next.payload.length + " -> " + hex);
                    } else if (text.startsWith("ADD ")) {
                        String nums = text.substring(4);
                        int sp = nums.indexOf(' ');
                        long a = Long.parseLong(nums.substring(0, sp));
                        long b = Long.parseLong(nums.substring(sp + 1));
                        long sum = a + b;
                        String reply = Long.toString(sum);
                        sendText(out, reply);
                        System.out.println(text + " -> " + reply);
                    } else if (text.startsWith("REV ")) {
                        String toRev = text.substring(4);
                        String reversed = reverseCodePoints(toRev);
                        sendText(out, reversed);
                        System.out.println(text + " -> " + reversed);
                    }
                }
            }
        } catch (EOFException e) {
            // connection closed unexpectedly
        }
    }

    static void handleClose(byte[] payload, OutputStream out, boolean closeSent) throws IOException {
        int code = 1005;
        String reason = "";
        if (payload.length >= 2) {
            code = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
            if (payload.length > 2) {
                reason = new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8);
            }
        }
        System.out.println("closed " + code + (reason.isEmpty() ? "" : " " + reason));
        if (!closeSent) {
            try {
                sendClose(out, code);
            } catch (IOException e) {
                // ignore
            }
        }
    }

    static Message readMessage(InputStream in, OutputStream out) throws IOException {
        ByteArrayOutputStream payload = new ByteArrayOutputStream();
        int msgOpcode = -1;

        while (true) {
            int b0 = in.read();
            if (b0 == -1) throw new EOFException();
            int b1 = in.read();
            if (b1 == -1) throw new EOFException();

            boolean fin = (b0 & 0x80) != 0;
            int opcode = b0 & 0x0F;
            boolean masked = (b1 & 0x80) != 0;
            int len = b1 & 0x7F;

            if (len == 126) {
                int hi = in.read();
                int lo = in.read();
                if (hi == -1 || lo == -1) throw new EOFException();
                len = (hi << 8) | lo;
            } else if (len == 127) {
                long longLen = 0;
                for (int i = 0; i < 8; i++) {
                    int b = in.read();
                    if (b == -1) throw new EOFException();
                    longLen = (longLen << 8) | b;
                }
                len = (int) longLen;
            }

            byte[] maskKey = null;
            if (masked) {
                maskKey = new byte[4];
                readFully(in, maskKey);
            }

            byte[] data = new byte[len];
            if (len > 0) readFully(in, data);

            if (masked && maskKey != null) {
                for (int i = 0; i < data.length; i++) {
                    data[i] ^= maskKey[i % 4];
                }
            }

            switch (opcode) {
                case 9:
                    sendPong(out, data);
                    break;
                case 10:
                    break;
                case 8:
                    return new Message(8, data);
                case 0:
                    payload.write(data);
                    if (fin) return new Message(msgOpcode, payload.toByteArray());
                    break;
                case 1:
                case 2:
                    if (msgOpcode == -1) msgOpcode = opcode;
                    payload.write(data);
                    if (fin) return new Message(msgOpcode, payload.toByteArray());
                    break;
                default:
                    break;
            }
        }
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        int len = payload.length;
        ByteArrayOutputStream buf = new ByteArrayOutputStream();

        buf.write(0x80 | opcode);

        if (len <= 125) {
            buf.write(0x80 | len);
        } else if (len <= 65535) {
            buf.write(0x80 | 126);
            buf.write((len >> 8) & 0xFF);
            buf.write(len & 0xFF);
        } else {
            buf.write(0x80 | 127);
            long longLen = len & 0xFFFFFFFFL;
            for (int i = 7; i >= 0; i--) {
                buf.write((int) ((longLen >>> (8 * i)) & 0xFF));
            }
        }

        byte[] mask = new byte[4];
        do {
            random.nextBytes(mask);
        } while (mask[0] == 0 && mask[1] == 0 && mask[2] == 0 && mask[3] == 0);
        buf.write(mask);

        byte[] masked = new byte[len];
        for (int i = 0; i < len; i++) {
            masked[i] = (byte) (payload[i] ^ mask[i % 4]);
        }
        buf.write(masked);

        out.write(buf.toByteArray());
        out.flush();
    }

    static void sendText(OutputStream out, String text) throws IOException {
        sendFrame(out, 1, text.getBytes(StandardCharsets.UTF_8));
    }

    static void sendPong(OutputStream out, byte[] data) throws IOException {
        sendFrame(out, 10, data);
    }

    static void sendClose(OutputStream out, int code) throws IOException {
        byte[] payload = new byte[2];
        payload[0] = (byte) ((code >> 8) & 0xFF);
        payload[1] = (byte) (code & 0xFF);
        sendFrame(out, 8, payload);
    }

    static void readFully(InputStream in, byte[] buf) throws IOException {
        int offset = 0;
        while (offset < buf.length) {
            int n = in.read(buf, offset, buf.length - offset);
            if (n == -1) throw new EOFException();
            offset += n;
        }
    }

    static String reverseCodePoints(String s) {
        int[] cps = s.codePoints().toArray();
        for (int i = 0, j = cps.length - 1; i < j; i++, j--) {
            int tmp = cps[i];
            cps[i] = cps[j];
            cps[j] = tmp;
        }
        return new String(cps, 0, cps.length);
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static class Message {
        int opcode;
        byte[] payload;
        Message(int opcode, byte[] payload) {
            this.opcode = opcode;
            this.payload = payload;
        }
    }
}

import * as net from 'net';
import * as crypto from 'crypto';

class BufferedReader {
  private buffer: Buffer = Buffer.alloc(0);
  private offset = 0;
  private ended = false;
  private error: Error | null = null;
  private waitingResolve: (() => void) | null = null;

  constructor(private socket: net.Socket) {
    this.socket.on('data', (chunk: Buffer) => {
      if (this.offset > 0) {
        this.buffer = Buffer.concat([this.buffer.subarray(this.offset), chunk]);
        this.offset = 0;
      } else {
        this.buffer = Buffer.concat([this.buffer, chunk]);
      }
      this.wake();
    });
    this.socket.on('end', () => { this.ended = true; this.wake(); });
    this.socket.on('close', () => { this.ended = true; this.wake(); });
    this.socket.on('error', (err) => { this.error = err; this.ended = true; this.wake(); });
  }

  private wake() {
    if (this.waitingResolve) {
      const r = this.waitingResolve;
      this.waitingResolve = null;
      r();
    }
  }

  private available(): number {
    return this.buffer.length - this.offset;
  }

  async readExactly(n: number): Promise<Buffer> {
    if (n === 0) return Buffer.alloc(0);
    while (this.available() < n) {
      if (this.ended || this.error) throw new Error('Connection closed');
      await new Promise<void>(resolve => { this.waitingResolve = resolve; });
    }
    const result = this.buffer.subarray(this.offset, this.offset + n);
    this.offset += n;
    return result;
  }

  async readHttpHeaders(): Promise<string> {
    while (true) {
      const data = this.buffer.subarray(this.offset);
      const idx = data.indexOf('\r\n\r\n');
      if (idx !== -1) {
        const headerBlock = data.subarray(0, idx + 4).toString('utf-8');
        this.offset += idx + 4;
        return headerBlock;
      }
      if (this.ended || this.error) throw new Error('Connection closed before headers complete');
      await new Promise<void>(resolve => { this.waitingResolve = resolve; });
    }
  }
}

function parseWsUrl(url: string): { host: string; port: number; path: string } {
  const rest = url.slice(5); // remove "ws://"
  const slashIdx = rest.indexOf('/');
  const hostPort = slashIdx === -1 ? rest : rest.slice(0, slashIdx);
  const path = slashIdx === -1 ? '/' : rest.slice(slashIdx);
  const colonIdx = hostPort.lastIndexOf(':');
  return { host: hostPort.slice(0, colonIdx), port: parseInt(hostPort.slice(colonIdx + 1)), path };
}

function encodeFrame(opcode: number, payload: Buffer): Buffer {
  const fin = 0x80;
  let header: Buffer;
  if (payload.length <= 125) {
    header = Buffer.alloc(2);
    header[0] = fin | opcode;
    header[1] = 0x80 | payload.length;
  } else if (payload.length <= 65535) {
    header = Buffer.alloc(4);
    header[0] = fin | opcode;
    header[1] = 0x80 | 126;
    header.writeUInt16BE(payload.length, 2);
  } else {
    header = Buffer.alloc(10);
    header[0] = fin | opcode;
    header[1] = 0x80 | 127;
    header.writeBigUInt64BE(BigInt(payload.length), 2);
  }
  let maskKey: Buffer;
  do { maskKey = crypto.randomBytes(4); } while (maskKey[0] === 0 && maskKey[1] === 0 && maskKey[2] === 0 && maskKey[3] === 0);
  const masked = Buffer.alloc(payload.length);
  for (let i = 0; i < payload.length; i++) masked[i] = payload[i] ^ maskKey[i & 3];
  return Buffer.concat([header, maskKey, masked]);
}

async function readFrame(reader: BufferedReader): Promise<{ fin: boolean; opcode: number; payload: Buffer }> {
  const h = await reader.readExactly(2);
  const fin = (h[0] & 0x80) !== 0;
  const opcode = h[0] & 0x0F;
  const masked = (h[1] & 0x80) !== 0;
  let payloadLen = h[1] & 0x7F;
  if (payloadLen === 126) {
    payloadLen = (await reader.readExactly(2)).readUInt16BE(0);
  } else if (payloadLen === 127) {
    payloadLen = Number((await reader.readExactly(8)).readBigUInt64BE(0));
  }
  let maskKey: Buffer | null = null;
  if (masked) maskKey = await reader.readExactly(4);
  let payload = await reader.readExactly(payloadLen);
  if (maskKey) {
    const unmasked = Buffer.alloc(payload.length);
    for (let i = 0; i < payload.length; i++) unmasked[i] = payload[i] ^ maskKey[i & 3];
    payload = unmasked;
  }
  return { fin, opcode, payload };
}

function connect(host: string, port: number): Promise<net.Socket> {
  return new Promise((resolve, reject) => {
    const s = net.createConnection({ host, port }, () => resolve(s));
    s.on('error', reject);
  });
}

async function processSession(url: string, sessionNum: number): Promise<void> {
  console.log(`session ${sessionNum}`);
  const { host, port, path } = parseWsUrl(url);

  let socket: net.Socket;
  try { socket = await connect(host, port); } catch { return; }

  const reader = new BufferedReader(socket);
  const key = crypto.randomBytes(16).toString('base64');

  socket.write(
    `GET ${path} HTTP/1.1\r\n` +
    `Host: ${host}:${port}\r\n` +
    `Upgrade: websocket\r\n` +
    `Connection: Upgrade\r\n` +
    `Sec-WebSocket-Version: 13\r\n` +
    `Sec-WebSocket-Key: ${key}\r\n` +
    `\r\n`
  );

  let headerBlock: string;
  try { headerBlock = await reader.readHttpHeaders(); } catch { socket.destroy(); return; }

  const lines = headerBlock.split('\r\n');
  const statusLine = lines[0];
  const sp1 = statusLine.indexOf(' ');
  const sp2 = statusLine.indexOf(' ', sp1 + 1);
  const statusCode = parseInt(statusLine.slice(sp1 + 1, sp2));
  const reasonPhrase = statusLine.slice(sp2 + 1);

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
    socket.destroy();
    return;
  }

  const expectedAccept = crypto.createHash('sha1')
    .update(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
    .digest('base64');

  let acceptValue: string | undefined;
  for (let i = 1; i < lines.length; i++) {
    const ci = lines[i].indexOf(':');
    if (ci !== -1 && lines[i].slice(0, ci).trim().toLowerCase() === 'sec-websocket-accept') {
      acceptValue = lines[i].slice(ci + 1).trim();
      break;
    }
  }

  if (acceptValue !== expectedAccept) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  let sentClose = false;
  let currentMessage: { opcode: number; fragments: Buffer[] } | null = null;
  let pendingSHA1 = false;

  function sendFrame(opcode: number, payload: Buffer) {
    socket.write(encodeFrame(opcode, payload));
  }

  function sendClose(code: number) {
    const p = Buffer.alloc(2);
    p.writeUInt16BE(code, 0);
    sendFrame(8, p);
    sentClose = true;
  }

  function handleClose(payload: Buffer) {
    let code: number, reason: string;
    if (payload.length >= 2) {
      code = payload.readUInt16BE(0);
      reason = payload.subarray(2).toString('utf-8');
    } else {
      code = 1005;
      reason = '';
    }
    console.log(reason.length > 0 ? `closed ${code} ${reason}` : `closed ${code}`);
    if (!sentClose) sendClose(code);
    socket.destroy();
  }

  function handleText(text: string) {
    if (text === 'SHA1') { pendingSHA1 = true; return; }
    if (text === 'BYE') { sendClose(1000); return; }
    if (text.startsWith('ADD ')) {
      const parts = text.slice(4).split(' ');
      const sum = parseInt(parts[0]) + parseInt(parts[1]);
      const reply = String(sum);
      sendFrame(1, Buffer.from(reply, 'utf-8'));
      console.log(`${text} -> ${reply}`);
      return;
    }
    if (text.startsWith('REV ')) {
      const t = text.slice(4);
      const reversed = Array.from(t).reverse().join('');
      sendFrame(1, Buffer.from(reversed, 'utf-8'));
      console.log(`${text} -> ${reversed}`);
      return;
    }
  }

  function handleBinary(payload: Buffer) {
    if (pendingSHA1) {
      const hash = crypto.createHash('sha1').update(payload).digest('hex');
      sendFrame(1, Buffer.from(hash, 'utf-8'));
      console.log(`SHA1 ${payload.length} -> ${hash}`);
      pendingSHA1 = false;
    }
  }

  function completeMessage(msg: { opcode: number; fragments: Buffer[] }) {
    const payload = Buffer.concat(msg.fragments);
    if (msg.opcode === 1) handleText(payload.toString('utf-8'));
    else if (msg.opcode === 2) handleBinary(payload);
  }

  try {
    while (true) {
      const frame = await readFrame(reader);
      if (frame.opcode === 9) { sendFrame(10, frame.payload); continue; }
      if (frame.opcode === 10) { continue; }
      if (frame.opcode === 8) { handleClose(frame.payload); return; }
      if (frame.opcode === 0) {
        if (currentMessage) {
          currentMessage.fragments.push(frame.payload);
          if (frame.fin) { completeMessage(currentMessage); currentMessage = null; }
        }
      } else {
        currentMessage = { opcode: frame.opcode, fragments: [frame.payload] };
        if (frame.fin) { completeMessage(currentMessage); currentMessage = null; }
      }
    }
  } catch {
    socket.destroy();
  }
}

async function main() {
  const urls = process.argv.slice(2);
  for (let i = 0; i < urls.length; i++) {
    await processSession(urls[i], i + 1);
  }
}

main().catch(() => {});

use std::io::{Read, Write};
use std::net::TcpStream;

// ============ SHA-1 ============
fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let ml = data.len() as u64 * 8;
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&ml.to_be_bytes());
    for chunk in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4], chunk[i*4+1], chunk[i*4+2], chunk[i*4+3]]);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }
        let mut a = h[0]; let mut b = h[1]; let mut c = h[2]; let mut d = h[3]; let mut e = h[4];
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999u32)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1u32)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32)
            } else {
                (b ^ c ^ d, 0xCA62C1D6u32)
            };
            let tmp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d; d = c; c = b.rotate_left(30); b = a; a = tmp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut out = [0u8; 20];
    for i in 0..5 { out[i*4..i*4+4].copy_from_slice(&h[i].to_be_bytes()); }
    out
}

fn sha1_hex(data: &[u8]) -> String {
    sha1(data).iter().map(|b| format!("{:02x}", b)).collect()
}

// ============ Base64 ============
fn base64_encode(data: &[u8]) -> String {
    const C: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    for ch in data.chunks(3) {
        let b0 = ch[0] as u32;
        let b1 = if ch.len() > 1 { ch[1] as u32 } else { 0 };
        let b2 = if ch.len() > 2 { ch[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        r.push(C[((n >> 18) & 63) as usize] as char);
        r.push(C[((n >> 12) & 63) as usize] as char);
        if ch.len() > 1 { r.push(C[((n >> 6) & 63) as usize] as char); } else { r.push('='); }
        if ch.len() > 2 { r.push(C[(n & 63) as usize] as char); } else { r.push('='); }
    }
    r
}

// ============ Random ============
fn random_bytes(n: usize) -> Vec<u8> {
    let mut f = std::fs::File::open("/dev/urandom").unwrap();
    let mut buf = vec![0u8; n];
    f.read_exact(&mut buf).unwrap();
    buf
}

// ============ WebSocket ============
struct Frame {
    fin: bool,
    opcode: u8,
    payload: Vec<u8>,
}

struct WsConn {
    stream: TcpStream,
    buf: Vec<u8>,
    pos: usize,
    sent_close: bool,
}

impl WsConn {
    fn fill(&mut self) {
        if self.pos >= self.buf.len() {
            self.buf.clear();
            self.pos = 0;
        }
        if self.buf.is_empty() {
            let mut tmp = vec![0u8; 65536];
            if let Ok(n) = self.stream.read(&mut tmp) {
                if n > 0 {
                    self.buf = tmp[..n].to_vec();
                    self.pos = 0;
                }
            }
        }
    }

    fn read_byte(&mut self) -> Option<u8> {
        self.fill();
        if self.pos < self.buf.len() {
            let b = self.buf[self.pos];
            self.pos += 1;
            Some(b)
        } else {
            None
        }
    }

    fn read_exact(&mut self, n: usize) -> Option<Vec<u8>> {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            match self.read_byte() {
                Some(b) => v.push(b),
                None => return None,
            }
        }
        Some(v)
    }

    fn read_frame(&mut self) -> Option<Frame> {
        let b0 = self.read_byte()?;
        let b1 = self.read_byte()?;
        let fin = (b0 & 0x80) != 0;
        let opcode = b0 & 0x0F;
        let masked = (b1 & 0x80) != 0;
        let mut plen = (b1 & 0x7F) as u64;
        if plen == 126 {
            let b = self.read_exact(2)?;
            plen = u16::from_be_bytes([b[0], b[1]]) as u64;
        } else if plen == 127 {
            let b = self.read_exact(8)?;
            plen = u64::from_be_bytes([b[0],b[1],b[2],b[3],b[4],b[5],b[6],b[7]]);
        }
        let mut mask = [0u8; 4];
        if masked {
            let m = self.read_exact(4)?;
            mask = [m[0], m[1], m[2], m[3]];
        }
        let mut payload = self.read_exact(plen as usize)?;
        if masked {
            for i in 0..payload.len() {
                payload[i] ^= mask[i % 4];
            }
        }
        Some(Frame { fin, opcode, payload })
    }

    fn write_frame(&mut self, opcode: u8, payload: &[u8]) {
        let mut frame = Vec::new();
        frame.push(0x80 | opcode);
        let mk = {
            let mut k = random_bytes(4);
            if k[0] == 0 && k[1] == 0 && k[2] == 0 && k[3] == 0 { k[0] = 1; }
            [k[0], k[1], k[2], k[3]]
        };
        let len = payload.len();
        if len <= 125 {
            frame.push(0x80 | len as u8);
        } else if len <= 65535 {
            frame.push(0x80 | 126);
            frame.extend_from_slice(&(len as u16).to_be_bytes());
        } else {
            frame.push(0x80 | 127);
            frame.extend_from_slice(&(len as u64).to_be_bytes());
        }
        frame.extend_from_slice(&mk);
        for (i, &b) in payload.iter().enumerate() {
            frame.push(b ^ mk[i % 4]);
        }
        self.stream.write_all(&frame).unwrap();
        self.stream.flush().unwrap();
    }

    fn send_close(&mut self, code: u16, reason: &str) {
        let mut p = code.to_be_bytes().to_vec();
        p.extend_from_slice(reason.as_bytes());
        self.write_frame(8, &p);
        self.sent_close = true;
    }

    /// Read a complete message (reassembling fragments, handling ping/pong).
    /// Returns the assembled message, or a close frame, or None on disconnect.
    fn read_message(&mut self) -> Option<Frame> {
        let mut msg_op = 0u8;
        let mut msg_data: Vec<u8> = Vec::new();
        loop {
            let f = self.read_frame()?;
            match f.opcode {
                8 => return Some(f),
                9 => { self.write_frame(10, &f.payload); }
                10 => {}
                0 => {
                    msg_data.extend_from_slice(&f.payload);
                    if f.fin {
                        return Some(Frame { fin: true, opcode: msg_op, payload: msg_data });
                    }
                }
                1 | 2 => {
                    msg_op = f.opcode;
                    msg_data.extend_from_slice(&f.payload);
                    if f.fin {
                        return Some(Frame { fin: true, opcode: msg_op, payload: msg_data });
                    }
                }
                _ => {
                    if f.fin { return Some(f); }
                }
            }
        }
    }
}

// ============ URL parsing ============
fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").unwrap();
    let slash = rest.find('/').unwrap_or(rest.len());
    let hp = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "/" };
    let colon = hp.rfind(':').unwrap();
    let host = hp[..colon].to_string();
    let port: u16 = hp[colon + 1..].parse().unwrap();
    (host, port, path.to_string())
}

// ============ Header reading ============
fn read_headers(conn: &mut WsConn) -> String {
    let mut buf: Vec<u8> = Vec::new();
    let mut tail = [0u8; 4];
    loop {
        match conn.read_byte() {
            Some(b) => {
                buf.push(b);
                tail[0] = tail[1]; tail[1] = tail[2]; tail[2] = tail[3]; tail[3] = b;
                if tail == [13, 10, 13, 10] { break; }
            }
            None => break,
        }
    }
    let hdr = if buf.len() >= 4 { &buf[..buf.len() - 4] } else { &buf[..] };
    String::from_utf8_lossy(hdr).to_string()
}

// ============ Close handling ============
fn handle_close(conn: &mut WsConn, payload: &[u8]) {
    if payload.len() >= 2 {
        let code = u16::from_be_bytes([payload[0], payload[1]]);
        let reason = String::from_utf8_lossy(&payload[2..]).to_string();
        if reason.is_empty() {
            println!("closed {}", code);
        } else {
            println!("closed {} {}", code, reason);
        }
        if !conn.sent_close {
            conn.send_close(code, "");
        }
    } else {
        if !conn.sent_close {
            conn.send_close(1005, "");
        }
    }
}

// ============ Session processing ============
fn process_messages(conn: &mut WsConn) {
    loop {
        let msg = match conn.read_message() {
            Some(m) => m,
            None => break,
        };
        match msg.opcode {
            8 => {
                handle_close(conn, &msg.payload);
                break;
            }
            1 => {
                let text = String::from_utf8_lossy(&msg.payload).to_string();
                if text == "BYE" {
                    conn.send_close(1000, "");
                    loop {
                        let m2 = match conn.read_message() {
                            Some(m) => m,
                            None => break,
                        };
                        if m2.opcode == 8 {
                            handle_close(conn, &m2.payload);
                            break;
                        }
                    }
                    break;
                } else if text.starts_with("ADD ") {
                    let rest = &text[4..];
                    let sp = rest.find(' ').unwrap_or(rest.len());
                    let a: i64 = rest[..sp].parse().unwrap_or(0);
                    let b: i64 = rest[sp + 1..].parse().unwrap_or(0);
                    let sum = a + b;
                    let reply = sum.to_string();
                    conn.write_frame(1, reply.as_bytes());
                    println!("{} -> {}", text, reply);
                } else if text.starts_with("REV ") {
                    let txt = &text[4..];
                    let rev: String = txt.chars().rev().collect();
                    conn.write_frame(1, rev.as_bytes());
                    println!("{} -> {}", text, rev);
                } else if text == "SHA1" {
                    let bin = match conn.read_message() {
                        Some(m) => m,
                        None => break,
                    };
                    if bin.opcode == 8 {
                        handle_close(conn, &bin.payload);
                        break;
                    }
                    let hex = sha1_hex(&bin.payload);
                    let len = bin.payload.len();
                    conn.write_frame(1, hex.as_bytes());
                    println!("SHA1 {} -> {}", len, hex);
                }
            }
            2 => {
                // unexpected binary outside SHA1 context; ignore
            }
            _ => {}
        }
    }
}

// ============ Session ============
fn process_session(url: &str) {
    let (host, port, path) = parse_url(url);
    let stream = match TcpStream::connect(format!("{}:{}", host, port)) {
        Ok(s) => s,
        Err(_) => return,
    };
    let key_bytes = random_bytes(16);
    let key = base64_encode(&key_bytes);
    let req = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, key
    );
    let mut conn = WsConn { stream, buf: Vec::new(), pos: 0, sent_close: false };
    conn.stream.write_all(req.as_bytes()).unwrap();
    conn.stream.flush().unwrap();

    let hdr_block = read_headers(&mut conn);
    let first_line = hdr_block.lines().next().unwrap_or("");
    let parts: Vec<&str> = first_line.splitn(3, ' ').collect();
    if parts.len() < 2 {
        println!("handshake failed: unknown");
        return;
    }
    let status: u16 = parts[1].parse().unwrap_or(0);
    let reason = if parts.len() > 2 { parts[2] } else { "" };
    if status != 101 {
        println!("handshake failed: {} {}", status, reason);
        return;
    }

    // Verify Sec-WebSocket-Accept
    let expected = {
        let mut s = key.clone();
        s.push_str("258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
        base64_encode(&sha1(s.as_bytes()))
    };
    let mut ok = false;
    for line in hdr_block.lines().skip(1) {
        if let Some(colon) = line.find(':') {
            if line[..colon].trim().eq_ignore_ascii_case("sec-websocket-accept") {
                if line[colon + 1..].trim() == expected {
                    ok = true;
                }
                break;
            }
        }
    }
    if !ok {
        println!("handshake failed: bad Sec-WebSocket-Accept");
        return;
    }

    process_messages(&mut conn);
}

// ============ Main ============
fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    for (i, url) in args.iter().enumerate() {
        println!("session {}", i + 1);
        process_session(url);
    }
}

use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead, Write};

fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 };
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn weekday_from_days(z: i64) -> i64 {
    ((z % 7) + 11) % 7
}

fn unix_to_civil(t: i64) -> (i64, i64, i64, i64, i64, i64) {
    let days = if t >= 0 { t / 86400 } else { (t - 86399) / 86400 };
    let rem = t - days * 86400;
    let (y, m, d) = civil_from_days(days);
    let h = rem / 3600;
    let mi = (rem % 3600) / 60;
    let s = rem % 60;
    (y, m, d, h, mi, s)
}

fn civil_to_unix(y: i64, mo: i64, d: i64, h: i64, mi: i64, s: i64) -> i64 {
    days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + s
}

fn parse_offset(s: &str) -> i64 {
    let mut chars = s.chars().peekable();
    let mut sign = 1i64;
    if let Some(c) = chars.peek() {
        if *c == '-' { sign = -1; chars.next(); }
        else if *c == '+' { chars.next(); }
    }
    let mut parts = Vec::new();
    let mut num = String::new();
    for c in chars {
        if c == ':' {
            parts.push(num.parse::<i64>().unwrap());
            num = String::new();
        } else {
            num.push(c);
        }
    }
    if !num.is_empty() {
        parts.push(num.parse::<i64>().unwrap());
    }
    let h = parts.get(0).copied().unwrap_or(0);
    let m = parts.get(1).copied().unwrap_or(0);
    let sec = parts.get(2).copied().unwrap_or(0);
    sign * (h * 3600 + m * 60 + sec)
}

fn parse_name(s: &str) -> (String, &str) {
    if s.starts_with('<') {
        let end = s.find('>').unwrap();
        (s[1..end].to_string(), &s[end + 1..])
    } else {
        let end = s.find(|c: char| !c.is_alphabetic()).unwrap_or(s.len());
        (s[..end].to_string(), &s[end..])
    }
}

fn parse_offset_str(s: &str) -> (String, &str) {
    let mut end = 0;
    let bytes = s.as_bytes();
    if end < bytes.len() && (bytes[end] == b'-' || bytes[end] == b'+') {
        end += 1;
    }
    while end < bytes.len() && bytes[end].is_ascii_digit() {
        end += 1;
    }
    if end < bytes.len() && bytes[end] == b':' {
        end += 1;
        while end < bytes.len() && bytes[end].is_ascii_digit() {
            end += 1;
        }
        if end < bytes.len() && bytes[end] == b':' {
            end += 1;
            while end < bytes.len() && bytes[end].is_ascii_digit() {
                end += 1;
            }
        }
    }
    (s[..end].to_string(), &s[end..])
}

fn parse_mwd(s: &str) -> (i64, i64, i64) {
    let parts: Vec<i64> = s.split('.').map(|x| x.parse().unwrap()).collect();
    (parts[0], parts[1], parts[2])
}

fn mwd_to_date(y: i64, m: i64, w: i64, d: i64) -> (i64, i64, i64) {
    let first_day = days_from_civil(y, m, 1);
    let first_dow = weekday_from_days(first_day);
    let mut diff = d - first_dow;
    if diff < 0 { diff += 7; }
    let first_occurrence = first_day + diff;
    if w <= 4 {
        let day = first_occurrence + (w - 1) * 7;
        civil_from_days(day)
    } else {
        let last_day = if m == 12 {
            days_from_civil(y + 1, 1, 1) - 1
        } else {
            days_from_civil(y, m + 1, 1) - 1
        };
        let last_dow = weekday_from_days(last_day);
        let mut diff2 = last_dow - d;
        if diff2 < 0 { diff2 += 7; }
        let last_occurrence = last_day - diff2;
        civil_from_days(last_occurrence)
    }
}

struct PosixRule {
    std_name: String,
    std_offset: i64,
    dst_name: Option<String>,
    dst_offset: Option<i64>,
    start: Option<(i64, i64, i64, i64)>,
    end: Option<(i64, i64, i64, i64)>,
}

fn parse_rule(s: &str) -> (i64, i64, i64, i64) {
    let (rule_part, time_part) = if let Some(slash) = s.find('/') {
        (&s[..slash], Some(&s[slash + 1..]))
    } else {
        (s, None)
    };
    let time = if let Some(t) = time_part {
        parse_offset(t)
    } else {
        2 * 3600
    };
    let mwd = &rule_part[1..];
    let (m, w, d) = parse_mwd(mwd);
    (m, w, d, time)
}

fn parse_posix_tz(s: &str) -> PosixRule {
    let s = s.trim();
    let (std_name, rest) = parse_name(s);
    let (std_offset_str, rest) = parse_offset_str(rest);
    let std_offset_val = parse_offset(&std_offset_str);
    let std_offset = -std_offset_val;

    if rest.is_empty() {
        return PosixRule {
            std_name, std_offset,
            dst_name: None, dst_offset: None,
            start: None, end: None,
        };
    }

    let (dst_name, rest) = parse_name(rest);

    let (dst_offset, rest) = if !rest.is_empty() &&
        (rest.starts_with('-') || rest.starts_with('+') ||
         rest.chars().next().map_or(false, |c| c.is_ascii_digit())) {
        let (off_str, rest) = parse_offset_str(rest);
        let val = parse_offset(&off_str);
        (-val, rest)
    } else {
        (std_offset + 3600, rest)
    };

    let mut start = None;
    let mut end = None;

    if rest.starts_with(',') {
        let rest = &rest[1..];
        let comma_pos = rest.find(',');
        let (start_str, rest) = if let Some(cp) = comma_pos {
            (&rest[..cp], &rest[cp..])
        } else {
            (rest, "")
        };
        start = Some(parse_rule(start_str));
        if rest.starts_with(',') {
            let rest = &rest[1..];
            end = Some(parse_rule(rest));
        }
    }

    PosixRule { std_name, std_offset, dst_name: Some(dst_name), dst_offset: Some(dst_offset), start, end }
}

struct TzifData {
    transitions: Vec<i64>,
    type_indices: Vec<u8>,
    types: Vec<(i64, bool, String)>,
    posix: Option<PosixRule>,
}

fn parse_tzif(data: &[u8]) -> TzifData {
    let read_u32_be = |data: &[u8], pos: usize| -> u32 {
        u32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]])
    };
    let read_i32_be = |data: &[u8], pos: usize| -> i32 {
        i32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]])
    };
    let read_i64_be = |data: &[u8], pos: usize| -> i64 {
        i64::from_be_bytes([
            data[pos], data[pos+1], data[pos+2], data[pos+3],
            data[pos+4], data[pos+5], data[pos+6], data[pos+7],
        ])
    };

    let mut pos = 20;
    let _isutcnt1 = read_u32_be(data, pos) as usize; pos += 4;
    let _isstdcnt1 = read_u32_be(data, pos) as usize; pos += 4;
    let _leapcnt1 = read_u32_be(data, pos) as usize; pos += 4;
    let timecnt1 = read_u32_be(data, pos) as usize; pos += 4;
    let typecnt1 = read_u32_be(data, pos) as usize; pos += 4;
    let charcnt1 = read_u32_be(data, pos) as usize; pos += 4;

    pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + _leapcnt1 * 8 + _isstdcnt1 + _isutcnt1;

    pos += 20;
    let isutcnt = read_u32_be(data, pos) as usize; pos += 4;
    let isstdcnt = read_u32_be(data, pos) as usize; pos += 4;
    let leapcnt = read_u32_be(data, pos) as usize; pos += 4;
    let timecnt = read_u32_be(data, pos) as usize; pos += 4;
    let typecnt = read_u32_be(data, pos) as usize; pos += 4;
    let charcnt = read_u32_be(data, pos) as usize; pos += 4;

    let mut transitions = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        transitions.push(read_i64_be(data, pos));
        pos += 8;
    }
    let mut type_indices = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        type_indices.push(data[pos]);
        pos += 1;
    }
    let mut type_records = Vec::with_capacity(typecnt);
    for _ in 0..typecnt {
        let gmtoff = read_i32_be(data, pos) as i64; pos += 4;
        let isdst = data[pos] != 0; pos += 1;
        let abbr_idx = data[pos] as usize; pos += 1;
        type_records.push((gmtoff, isdst, abbr_idx));
    }
    let abbr_chars = &data[pos..pos + charcnt];
    pos += charcnt;
    pos += leapcnt * 12 + isstdcnt + isutcnt;

    let mut types = Vec::with_capacity(typecnt);
    for &(gmtoff, isdst, abbr_idx) in &type_records {
        let mut abbr = String::new();
        let mut i = abbr_idx;
        while i < abbr_chars.len() && abbr_chars[i] != 0 {
            abbr.push(abbr_chars[i] as char);
            i += 1;
        }
        types.push((gmtoff, isdst, abbr));
    }

    let posix = if pos < data.len() && data[pos] == b'\n' {
        pos += 1;
        let start = pos;
        while pos < data.len() && data[pos] != b'\n' { pos += 1; }
        let tz_str = std::str::from_utf8(&data[start..pos]).unwrap_or("");
        if tz_str.is_empty() { None } else { Some(parse_posix_tz(tz_str)) }
    } else {
        None
    };

    TzifData { transitions, type_indices, types, posix }
}

fn get_type_from_posix(posix: &PosixRule, t: i64) -> (i64, bool, String) {
    if posix.dst_name.is_none() || posix.start.is_none() || posix.end.is_none() {
        return (posix.std_offset, false, posix.std_name.clone());
    }
    let dst_offset = posix.dst_offset.unwrap();
    let (sm, sw, sd, st) = posix.start.unwrap();
    let (em, ew, ed, et) = posix.end.unwrap();
    let (y, _, _, _, _, _) = unix_to_civil(t);

    let mut last_type_dst = false;
    let mut last_time = i64::MIN;

    for year in (y - 1)..=(y + 1) {
        let (sy, sm2, sd2) = mwd_to_date(year, sm, sw, sd);
        let t_start = civil_to_unix(sy, sm2, sd2, 0, 0, 0) + st - posix.std_offset;
        let (ey, em2, ed2) = mwd_to_date(year, em, ew, ed);
        let t_end = civil_to_unix(ey, em2, ed2, 0, 0, 0) + et - dst_offset;

        if t_start <= t && t_start > last_time {
            last_time = t_start;
            last_type_dst = true;
        }
        if t_end <= t && t_end > last_time {
            last_time = t_end;
            last_type_dst = false;
        }
    }

    if last_type_dst {
        (dst_offset, true, posix.dst_name.clone().unwrap())
    } else {
        (posix.std_offset, false, posix.std_name.clone())
    }
}

fn get_type_for_time(tz: &TzifData, t: i64) -> (i64, bool, String) {
    if tz.transitions.is_empty() {
        if let Some(ref posix) = tz.posix {
            return get_type_from_posix(posix, t);
        }
        return tz.types[0].clone();
    }
    if t < tz.transitions[0] {
        return tz.types[0].clone();
    }
    if t >= *tz.transitions.last().unwrap() {
        if let Some(ref posix) = tz.posix {
            return get_type_from_posix(posix, t);
        }
        let idx = tz.type_indices[tz.transitions.len() - 1] as usize;
        return tz.types[idx].clone();
    }
    let mut lo = 0usize;
    let mut hi = tz.transitions.len() - 1;
    while lo < hi {
        let mid = (lo + hi + 1) / 2;
        if tz.transitions[mid] <= t { lo = mid; } else { hi = mid - 1; }
    }
    let idx = tz.type_indices[lo] as usize;
    tz.types[idx].clone()
}

fn format_offset(offset: i64) -> String {
    let sign = if offset < 0 { '-' } else { '+' };
    let abs = offset.abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn format_datetime(t: i64, offset: i64) -> String {
    let local = t + offset;
    let (y, mo, d, h, mi, s) = unix_to_civil(local);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, mo, d, h, mi, s)
}

fn handle_utc_query(tz: &TzifData, t: i64) -> String {
    let (offset, _, abbr) = get_type_for_time(tz, t);
    let local = format_datetime(t, offset);
    let off_str = format_offset(offset);
    format!("{}{} {}", local, off_str, abbr)
}

fn find_gap_time(tz: &TzifData, wall: i64) -> i64 {
    for i in 0..tz.transitions.len() {
        let t_trans = tz.transitions[i];
        let idx_before = if i == 0 { 0usize } else { tz.type_indices[i - 1] as usize };
        let idx_after = tz.type_indices[i] as usize;
        let off_before = tz.types[idx_before].0;
        let off_after = tz.types[idx_after].0;
        if off_after > off_before {
            let gap_start = t_trans + off_before;
            let gap_end = t_trans + off_after;
            if wall >= gap_start && wall < gap_end {
                return wall - off_before;
            }
        }
    }
    if let Some(ref posix) = tz.posix {
        if let (Some(dst_off), Some((sm, sw, sd, st)), Some(_)) = (posix.dst_offset, posix.start, posix.end) {
            let std_off = posix.std_offset;
            if dst_off > std_off {
                let (y, _, _, _, _, _) = unix_to_civil(wall - std_off);
                for year in (y - 1)..=(y + 1) {
                    let (sy, sm2, sd2) = mwd_to_date(year, sm, sw, sd);
                    let t_start = civil_to_unix(sy, sm2, sd2, 0, 0, 0) + st - std_off;
                    let gap_start = t_start + std_off;
                    let gap_end = t_start + dst_off;
                    if wall >= gap_start && wall < gap_end {
                        return wall - std_off;
                    }
                }
            }
        }
    }
    wall
}

fn handle_local_query(tz: &TzifData, wall_str: &str) -> String {
    let (y, mo, d, h, mi, s) = parse_datetime(wall_str);
    let wall = civil_to_unix(y, mo, d, h, mi, s);

    let mut offsets: Vec<i64> = Vec::new();
    for t in &tz.types {
        if !offsets.contains(&t.0) {
            offsets.push(t.0);
        }
    }
    if let Some(ref posix) = tz.posix {
        if !offsets.contains(&posix.std_offset) {
            offsets.push(posix.std_offset);
        }
        if let Some(dst_off) = posix.dst_offset {
            if !offsets.contains(&dst_off) {
                offsets.push(dst_off);
            }
        }
    }

    let mut results: Vec<(i64, i64, String)> = Vec::new();
    for &off in &offsets {
        let t = wall - off;
        let (actual_off, _, actual_abbr) = get_type_for_time(tz, t);
        if actual_off == off {
            results.push((t, actual_off, actual_abbr));
        }
    }

    if results.len() == 1 {
        let (t, off, abbr) = &results[0];
        format!("{} {} {}", t, format_offset(*off), abbr)
    } else if results.len() >= 2 {
        results.sort_by_key(|(t, _, _)| *t);
        let (t1, o1, a1) = &results[0];
        let (t2, o2, a2) = &results[1];
        format!("{} {} {} | {} {} {}", t1, format_offset(*o1), a1, t2, format_offset(*o2), a2)
    } else {
        let t = find_gap_time(tz, wall);
        let (off, _, abbr) = get_type_for_time(tz, t);
        let local = format_datetime(t, off);
        let off_str = format_offset(off);
        format!("GAP {} {}{} {}", t, local, off_str, abbr)
    }
}

fn parse_datetime(s: &str) -> (i64, i64, i64, i64, i64, i64) {
    let y: i64 = s[0..4].parse().unwrap();
    let mo: i64 = s[5..7].parse().unwrap();
    let d: i64 = s[8..10].parse().unwrap();
    let h: i64 = s[11..13].parse().unwrap();
    let mi: i64 = s[14..16].parse().unwrap();
    let sec: i64 = s[17..19].parse().unwrap();
    (y, mo, d, h, mi, sec)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let queries_path = format!("{}/queries.txt", dir);
    let content = fs::read_to_string(&queries_path).unwrap();

    let mut cache: HashMap<String, TzifData> = HashMap::new();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for line in content.lines() {
        let line = line.trim_end();
