class Conn {
    let fd: Int32
    var buf: [UInt8] = []
    var pos: Int = 0

    init(fd: Int32) { self.fd = fd }

    func fill() -> Bool {
        if pos > 0 {
            buf.removeFirst(pos)
            pos = 0
        }
        var tmp = [UInt8](repeating: 0, count: 65536)
        let n = tmp.withUnsafeMutableBytes { ptr in
            Darwin.recv(fd, ptr.baseAddress!, ptr.count, 0)
        }
        if n <= 0 { return false }
        buf.append(contentsOf: tmp[0..<n])
        return true
    }

    func readByte() -> UInt8? {
        while pos >= buf.count {
            if !fill() { return nil }
        }
        let b = buf[pos]
        pos += 1
        return b
    }

    func readBytes(_ n: Int) -> [UInt8]? {
        if n == 0 { return [] }
        while buf.count - pos < n {
            if !fill() { return nil }
        }
        let result = Array(buf[pos..<pos+n])
        pos += n
        return result
    }

    func write(_ data: [UInt8]) {
        var offset = 0
        while offset < data.count {
            let n = data.withUnsafeBytes { ptr in
                Darwin.send(fd, ptr.baseAddress!.advanced(by: offset), data.count - offset, 0)
