/* ===== Buffered Reader ===== */
typedef struct {
    int fd;
    unsigned char *buf;
    size_t start, end, cap;
} BR;

static void br_init(BR *br, int fd) {
    br->fd = fd;
    br->cap = 65536;
    br->buf = malloc(br->cap);
    br->start = br->end = 0;
}

static int br_fill(BR *br) {
    if (br->start > 0) {
        memmove(br->buf, br->buf + br->start, br->end - br->start);
        br->end -= br->start;
        br->start = 0;
    }
    if (br->end >= br->cap) {
        br->cap *= 2;
        br->buf = realloc(br->buf, br->cap);
    }
    ssize_t r;
    do { r = read(br->fd, br->buf + br->end, br->cap - br->end); }
    while (r == -1 && errno == EINTR);
    if (r <= 0) return -1;
    br->end += (size_t)r;
    return 0;
}

static int br_ensure(BR *br, size_t n) {
    while (br->end - br->start < n) {
        if (br_fill(br) < 0) return -1;
    }
    return 0;
}

static int br_read_bytes(BR *br, unsigned char *out, size_t n) {
    if (br_ensure(br, n) < 0) return -1;
    memcpy(out, br->buf + br->start, n);
    br->start += n;
    return 0;
}

