        int fin, opcode;
        unsigned char *pl;
        size_t plen;
        if (ws_read_frame(br, &fin, &opcode, &pl, &plen) < 0) return -1;

        if (opcode == 9) { /* ping */
            ws_send_frame(br->fd, 10, pl, plen);
            free(pl);
            continue;
        }
        if (opcode == 10) { /* pong */
            free(pl);
            continue;
        }
        if (opcode == 8) { /* close */
            msg->is_close = 1;
            msg->close_code = 1005;
            msg->close_reason[0] = '\0';
            if (plen >= 2) {
                msg->close_code = (pl[0] << 8) | pl[1];
                size_t rlen = plen - 2;
                if (rlen > 4095) rlen = 4095;
                memcpy(msg->close_reason, pl + 2, rlen);
                msg->close_reason[rlen] = '\0';
            }
            free(pl);
            free(acc);
            return -1;
        }

        if (opcode == 0) { /* continuation */
            append(&acc, &acc_len, &acc_cap, pl, plen);
            free(pl);
            if (fin) {
                msg->opcode = msg_opcode;
                msg->payload = acc;
                msg->plen = acc_len;
                msg->is_close = 0;
                return 0;
            }
        } else { /* text or binary */
            msg_opcode = opcode;
            append(&acc, &acc_len, &acc_cap, pl, plen);
            free(pl);
            if (fin) {
                msg->opcode = msg_opcode;
                msg->payload = acc;
                msg->plen = acc_len;
                msg->is_close = 0;
                return 0;
            }
        }
    }
}

/* Read until close frame (for after BYE) */
static int read_until_close(BR *br, Msg *msg) {
    for (;;) {
        int fin, opcode;
        unsigned char *pl;
        size_t plen;
        if (ws_read_frame(br, &fin, &opcode, &pl, &plen) < 0) return -1;
        if (opcode == 9) { ws_send_frame(br->fd, 10, pl, plen); free(pl); continue; }
        if (opcode == 10) { free(pl); continue; }
        if (opcode == 8) {
            msg->is_close = 1;
            msg->close_code = 1005;
            msg->close_reason[0] = '\0';
            if (plen >= 2) {
                msg->close_code = (pl[0] << 8) | pl[1];
                size_t rlen = plen - 2;
                if (rlen > 4095) rlen = 4095;
                memcpy(msg->close_reason, pl + 2, rlen);
                msg->close_reason[rlen] = '\0';
            }
            free(pl);
            return 0;
        }
        free(pl);
    }
}

/* ===== URL parsing ===== */
static void parse_url(const char *url, char *host, int *port, char *path) {
    const char *p = url + 5; /* skip "ws://" */
    const char *colon = strchr(p, ':');
    const char *slash = strchr(p, '/');
    size_t hlen = (size_t)(colon - p);
    memcpy(host, p, hlen);
    host[hlen] = '\0';
    *port = atoi(colon + 1);
    strcpy(path, slash);
}

/* ===== Case-insensitive header compare ===== */
static int hdr_match(const char *line, const char *name) {
    size_t nl = strlen(name);
    return strncasecmp(line, name, nl) == 0 && line[nl] == ':';
}

/* ===== Main ===== */
int main(int argc, char *argv[]) {
    for (int sess = 1; sess < argc; sess++) {
        printf("session %d\n", sess);
        fflush(stdout);

        char host[256], path[4096];
        int port;
        parse_url(argv[sess], host, &port, path);

        /* Connect */
        int fd = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons((uint16_t)port);
        inet_pton(AF_INET, host, &addr.sin_addr);
        if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            close(fd);
            continue;
        }

        /* Generate key */
        unsigned char rawkey[16];
        arc4random_buf(rawkey, 16);
        char *wskey = b64_encode(rawkey, 16);

        /* Send handshake */
        char req[8192];
        int rlen = snprintf(req, sizeof(req),
            "GET %s HTTP/1.1\r\n"
            "Host: %s:%d\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Version: 13\r\n"
            "Sec-WebSocket-Key: %s\r\n"
            "\r\n",
            path, host, port, wskey);
        write_all(fd, req, (size_t)rlen);

        /* Read response */
        BR br;
        br_init(&br, fd);

        char line[8192];
        ssize_t ll = br_read_line(&br, line, sizeof(line));
        if (ll < 0) { close(fd); free(wskey); free(br.buf); continue; }

        /* Parse status line */
        int status_code = 0;
        char reason_phrase[256] = "";
        {
            char *sp1 = strchr(line, ' ');
            if (sp1) {
                status_code = atoi(sp1 + 1);
                char *sp2 = strchr(sp1 + 1, ' ');
                if (sp2) strcpy(reason_phrase, sp2 + 1);
            }
        }

        /* Read headers */
        char accept_hdr[256] = "";
        for (;;) {
            ll = br_read_line(&br, line, sizeof(line));
            if (ll <= 0) break;
            if (hdr_match(line, "Sec-WebSocket-Accept")) {
                char *v = strchr(line, ':') + 1;
                while (*v == ' ') v++;
                strncpy(accept_hdr, v, sizeof(accept_hdr)-1);
                accept_hdr[sizeof(accept_hdr)-1] = '\0';
            }
        }

        if (status_code != 101) {
            printf("handshake failed: %d %s\n", status_code, reason_phrase);
            fflush(stdout);
            close(fd); free(wskey); free(br.buf);
            continue;
        }

        /* Verify accept */
        {
            char concat[256];
            strcpy(concat, wskey);
            strcat(concat, "258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
            unsigned char sha[20];
            CC_SHA1((const unsigned char *)concat, (CC_LONG)strlen(concat), sha);
            char *expected = b64_encode(sha, 20);
            if (strcmp(accept_hdr, expected) != 0) {
                printf("handshake failed: bad Sec-WebSocket-Accept\n");
                fflush(stdout);
                free(expected); close(fd); free(wskey); free(br.buf);
                continue;
            }
            free(expected);
        }
        free(wskey);

        /* Message loop */
        int sent_close = 0;
        int done = 0;

        while (!done) {
            Msg msg;
            memset(&msg, 0, sizeof(msg));
            if (read_message(&br, &msg) < 0) {
                /* close or error */
                if (msg.is_close) {
                    if (msg.close_reason[0])
                        printf("closed %d %s\n", msg.close_code, msg.close_reason);
                    else
                        printf("closed %d\n", msg.close_code);
                    fflush(stdout);
                    if (!sent_close) {
                        unsigned char cp[2] = {(unsigned char)(msg.close_code >> 8), (unsigned char)(msg.close_code & 0xFF)};
                        ws_send_frame(fd, 8, cp, 2);
                    }
                }
                done = 1;
                break;
            }

            if (msg.opcode == 1) { /* text */
                /* Null-terminate for convenience */
                msg.payload = realloc(msg.payload, msg.plen + 1);
                msg.payload[msg.plen] = '\0';
                char *cmd = (char *)msg.payload;

                if (strncmp(cmd, "ADD ", 4) == 0) {
                    long long a, b;
                    sscanf(cmd + 4, "%lld %lld", &a, &b);
                    long long sum = a + b;
                    char reply[64];
                    snprintf(reply, sizeof(reply), "%lld", sum);
                    ws_send_frame(fd, 1, (unsigned char *)reply, strlen(reply));
                    printf("%s -> %s\n", cmd, reply);
                    fflush(stdout);
                } else if (strncmp(cmd, "REV ", 4) == 0) {
                    char *text = cmd + 4;
                    size_t tlen = strlen(text);
                    size_t rlen2;
                    char *rev = reverse_utf8((unsigned char *)text, tlen, &rlen2);
                    ws_send_frame(fd, 1, (unsigned char *)rev, rlen2);
                    printf("%s -> %s\n", cmd, rev);
                    fflush(stdout);
                    free(rev);
                } else if (strcmp(cmd, "SHA1") == 0) {
                    /* Read next data message (binary) */
                    Msg bmsg;
                    memset(&bmsg, 0, sizeof(bmsg));
                    if (read_message(&br, &bmsg) < 0) {
                        if (bmsg.is_close) {
                            if (bmsg.close_reason[0])
                                printf("closed %d %s\n", bmsg.close_code, bmsg.close_reason);
                            else
                                printf("closed %d\n", bmsg.close_code);
                            fflush(stdout);
                            if (!sent_close) {
                                unsigned char cp[2] = {(unsigned char)(bmsg.close_code >> 8), (unsigned char)(bmsg.close_code & 0xFF)};
                                ws_send_frame(fd, 8, cp, 2);
                            }
                        }
                        free(msg.payload);
                        done = 1;
                        break;
                    }
                    unsigned char sha[20];
                    CC_SHA1(bmsg.payload, (CC_LONG)bmsg.plen, sha);
                    char hex[41];
                    for (int i = 0; i < 20; i++) sprintf(hex + i*2, "%02x", sha[i]);
                    hex[40] = '\0';
                    char reply[64];
                    snprintf(reply, sizeof(reply), "%s", hex);
                    ws_send_frame(fd, 1, (unsigned char *)reply, 40);
                    printf("SHA1 %zu -> %s\n", bmsg.plen, hex);
                    fflush(stdout);
                    free(bmsg.payload);
                } else if (strcmp(cmd, "BYE") == 0) {
                    unsigned char cp[2] = {0x03, 0xE8};
                    ws_send_frame(fd, 8, cp, 2);
                    sent_close = 1;
                    Msg cmsg;
                    memset(&cmsg, 0, sizeof(cmsg));
                    if (read_until_close(&br, &cmsg) == 0) {
                        if (cmsg.close_reason[0])
                            printf("closed %d %s\n", cmsg.close_code, cmsg.close_reason);
                        else
                            printf("closed %d\n", cmsg.close_code);
                        fflush(stdout);
                    }
                    done = 1;
                }
                free(msg.payload);
            } else if (msg.opcode == 2) {
                /* Unexpected binary message outside SHA1 context - ignore */
                free(msg.payload);
            } else {
                free(msg.payload);
            }
        }

        close(fd);
        free(br.buf);
    }
    return 0;
}
